INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4606, 'zhTW', '超級清潔器5200型!', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4641, 'zhTW', '起點', '你終於長大啦，$N……你可以以部落的名義參加戰鬥了，為酋長的榮譽而戰吧!嗯……<卡爾圖克打量了你一番。>你會很出色的。毫無疑問，你的目標是找到一條巨龍或是一個惡魔，然後赤手空拳地打敗它，但是從比較弱的對手開始可能是個比較明智的選擇。<卡爾圖克笑了起來。>去向高內克報告吧，他可以為你這樣的年輕$c指派一項適合你的任務。你可以在西邊的大獸穴中找到高內克。', '與高內克談一談。卡爾圖克在你的地圖上標出了他的位置，並告訴你高內克居住在西邊的大獸穴中。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4722, 'zhTW', '擱淺的海龜', '你找到一具海龜的屍體，它顯然是不久之前擱淺在黑海岸的，而且早已被住在周圍的灰霧魚人吃得一乾二淨了。不過，剩下的殘骸也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去了。', '把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4723, 'zhTW', '擱淺的海洋生物', '一頭巨型蛇頸龍的屍體─它比你預想的還要大很多─躺在薄霧海的海岸上。這個生物是怎麼到這裡的，你無從得知。成群的魚人正在分食它的屍體，那些魚人看起來是如此渺小，它們完全是依靠數量才將這頭巨獸搞定的。$B$B雖然屍體已經被吃掉了大半，但是剩下的也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去了。', '把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4725, 'zhTW', '擱淺的海龜', '還有更多海龜的殘骸躺在海岸線上。這一具屍體的龜殼上還有個廢棄的車架。也許這個生物是被某種未知的力量趕到了海岸上，而不是像別的屍體那樣自己爬上海岸。強大的灰霧魚人正聚集在屍體附近並蠶食著它。$B$B你在車架中找到了一只有著奇怪標誌的箱子，也許奧伯丁的溫尼斯·布萊葛會對它有所瞭解。', '把有奇怪標記的箱子交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4727, 'zhTW', '擱淺的海龜', '一隻海龜的骸骨躺在黑海岸北部的沙灘上。也許灰霧魚人沒有發現它的屍體，或者由於某些特殊的原因而沒有去碰它。不管怎麼樣，這具屍體上有足夠的海龜肉，你可以採集一些作為樣本，並把它送到奧伯丁的溫尼斯·布萊葛那裡，供月神殿進行研究。', '把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4728, 'zhTW', '擱淺的海洋生物', '某種海中巨獸的屍體擱淺在了海灘上，一隻帶著輪子的木桶和其他一些雜七雜八的工具散佈在這頭巨獸旁邊，看來曾經有什麼人想要研究它。雖然這具屍體被魚人吃得差不多只剩骨頭了，但是剩下的殘骸也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去。', '把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4730, 'zhTW', '擱淺的海洋生物', '這具已經被吃掉一半的屍體看來是一頭海洋巨獸。屍體躺在海岸上，一群比奧伯丁那裡的同類更加強大的魚人聚在周圍大嚼大咽，不過殘留的屍體應該足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去了。', '把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4731, 'zhTW', '擱淺的海龜', '又一具海龜的殘骸躺在海岸線上，龜殼上還有個廢棄的車架。也許這個生物是被某種未知的力量趕到了海岸上，而不是像別的屍體那樣自己爬上海岸。強大的灰霧魚人正聚集在屍體附近並蠶食著它。$B$B你在車架中找到了一只有著奇怪標誌的箱子，也許奧伯丁的溫尼斯·布萊葛會對它有所瞭解。', '把有奇怪標記的箱子交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4732, 'zhTW', '擱淺的海龜', '你找到一具海龜的屍體，它顯然是不久之前擱淺在黑海岸的，而且早已被住在周圍的灰霧魚人吃得一乾二淨了。不過，剩下的殘骸也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去了。', '把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4733, 'zhTW', '擱淺的海洋生物', '這具巨型蛇頸龍的屍體被沖到了礁石遍佈的暮光海岸上。它比你見過的任何魚龍都要龐大蛇頸龍都要龐大，不管它是從哪裡來的，這頭巨獸原本顯然不是生活在黑海岸的。$B$B雖然這具屍體已經支離破碎了，但是殘留的屍體也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去。', '把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4761, 'zhTW', '桑迪斯·織風', '桑迪斯·織風應該已經對你在熊怪的營地那裡所進行的偵察行動有所了結了。他是奧伯丁的長者，在那裡負責處理村中的日常事務。請把你對熊怪的偵察結果彙報給他。我相信，他對熊怪墮落的原因有自己的解釋。或許你能與他一起制定出恢復自然平衡的計畫!', '與奧伯丁的桑迪斯·織風談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4813, 'zhTW', '水晶中的碎骨', '月井的水讓嵌在水晶裡的東西顯現了出來，那是一些細小的骨頭碎片，還有半塊下頜骨。這塊下頜骨似乎是人類的，但是你沒辦法打開水晶，所以還不能確定這一點─即使是最強大的魔法也幾乎不可能打碎這塊水晶。現在看來，你只能去向奧伯丁的哨兵哨兵戈琳達·納希恩彙報這個發現了。', '向奧伯丁的哨兵哨兵戈琳達·納希恩報告你的發現。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4971, 'zhTW', '時間問題', '一股邪惡的力量─很可能是天譴軍團─出現在安多哈爾，擾亂了時間的流動!我可以嘗試維持現有的時間進程，並修正它所遭到的破壞，但是我必須在一個安靜的環境中才能做這些事情，這就需要你的幫助。$B$B時光寄生蟲─以改變的時間流為能源的食腐蟲─在安多哈爾的倉庫中大量繁殖，扭曲的藍色脈搏是它們身體唯一可見的部分。它們阻撓了我的施法過程，所以，$N，請你使用時光置換器幫我除掉這些寄生蟲。', '在安多哈爾的一處倉庫附近使用時光置換器，使時光寄生蟲現身。$B$B殺掉10隻時光寄生蟲，然後將時光置換器還給西瘟疫之地安多哈爾旅店的克羅米。', '', '去西瘟疫之地找安多哈爾廢墟的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4972, 'zhTW', '找回時間', '我需要借助你的能力進入這間房間以外的世界，$N。請允許我稍後向你解釋。$B$B你發現這間房間與安多哈爾其他地方的不同了吧。我的龍族軍團成員以不同的方式在不同的時間線上工作著。要修復安多哈爾的損傷，我要從一個不同的時間線著手，避免過分污染它。要繼續進行這項工作的話，我需要一些時間飾品，其中一個是在瘟疫襲擊安多哈爾時產生的。在建築物殘骸中尋找時間飾品，這些建築都是這個曾經繁華的城市的一部分。', '在安多哈爾城中四處散落的帶鎖箱裡找到5個安多哈爾懷錶，然後把它們交給西瘟疫之地安多哈爾旅店裡的克羅米。', '', '去西瘟疫之地找安多哈爾廢墟的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4984, 'zhTW', '大自然的苦楚', '儘管我不可能以一己之力反抗天譴軍團，但我仍然來到了這裡，盡力治癒他們對大自然造成的傷害。這片土地上的生靈遭受著瘟疫所帶來的災難，這瘟疫使大地窒息。我想請你把我在這裡未完成的工作繼續下去。$B$B對那些正在忍受折磨的動物們來說，除了仁慈地解放它們，沒有什麼其他的解決辦法了。把附近生病的狼找出來，殺死它們。我請求你，$N，結束它們的痛苦吧……這樣做也會令我得到安寧。', '消滅8隻生病的狼，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。', '', '去西瘟疫之地找達隆米爾湖的穆格雷斯·深水。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4987, 'zhTW', '雕紋橡木樹枝', '牛頭人德魯伊那毫無生氣的手中緊緊地抓著一根看起來極為健康的橡木樹枝，樹皮上刻著一些德魯伊的自然雕紋。$B$B當你握著這根樹枝時，你發現原本應該冰冷的樹枝摸上去卻非常溫暖。莫高雷地區的雷霆崖畫面清晰地浮現在你的腦海裡，尤其是長者高地的景象。「塞納里奧議會」這幾個字從你的嘴中同時說了出來。顯然這根樹枝早就該被安排好帶到哪裡了。', '根據這枝雕紋橡木樹枝所附加的魔法，這個牛頭人德魯伊本來準備把它交給雷霆崖的塞納里奧議會。到那裡去尋求某個德魯伊的幫助吧。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5021, 'zhTW', '遲到總比不到好', '「在我被困在這裡之前，這個包裹一定得送……送出去!」一個驚恐的女人哭聲在這所房子裡穿梭回蕩。你看到一個女人的亡魂瑟縮在樓上的角落裡，看起來她並不完全熟悉周圍的環境，她只是隱約地感覺到了你的存在。「你是來幫我送包裹的嗎?趁事情還沒有變得更加糟糕……求你了，幫幫我!我本來是要騎馬離開這裡的，包裹應該還在我的馬旁邊……是不是已經太遲了?」', '這個女人的鬼魂告訴你她要送出一個包裹。她說那個包裹就在她的馬旁邊。至於馬在哪裡或者包裹要送到哪裡去，她卻根本沒有說。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5022, 'zhTW', '遲到總比不到好', '你撿起這個包裹，擦掉積在上面一層薄薄的塵土和泥垢。這個包裹上面草草地寫著要寄給暴風城裡一個名叫艾瑪·費爾斯通的人，而包裹的遞送日期已經是四年之前了。$B$B儘管你不清楚艾瑪·費爾斯通是否還活著，但暴風城的市政廳裡應該還保留著城市居民的記錄，你應該去找暴風城人口普查處的皇家代理人幫忙。', '向暴風城的皇家代理人確認艾瑪·費爾斯通的下落。通常在市政廳裡都有一個人口普查官。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5050 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5050, 'zhTW', '好運符咒', '看起來我錯怪你了，$N，為此我應向你道歉。我姐姐送給我許多東西，包括看起來很滑稽的費爾斯通農場地契，我想我一時半會是沒法收回它了。$B$B如果我姐姐的靈魂還被束縛在農場不能安息，請你幫幫忙……你能把這個還給她嗎?這是她的半個符咒，她的丈夫拿著另外一半。$B$B或許當她知道我拿到這些東西之後就可以安息了。', '把半個好運符咒還給西瘟疫之地的詹妮絲·費爾斯通。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5051, 'zhTW', '合二為一', '這個可憐的鬼魂繼續說道:$B$B「我好冷，約翰，把你的符咒帶給我，我們就可以在一起了!快點，約翰，在瘟疫把我們變成可惡的野獸之前!我看不到你，約翰……但是我知道你就在附近。我感覺你就在我身旁，」$B$B或許，找到另一半的符咒並組合起來，就能組成珍妮絲·菲爾斯通的靈魂所尋找的東西。', '在西瘟疫之地的費爾斯通農場的某個地方找尋另外半個好運符並組合起來。$B$B把好運符交給西瘟疫之地費爾斯通農場的珍妮絲·菲爾斯通。', '', '去找西瘟疫之地的詹妮絲·費爾斯通。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5058, 'zhTW', '達爾松夫人的日記', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5059, 'zhTW', '被鎖起來的農夫', '', '進度廁所的門幾乎被撐開了，裡面有什麼東西在瘋狂而執著地反復衝撞它。不過到目前為止這扇門還是從外面緊緊鎖住的。$B$B當你推擠這扇門時，你聽到從裡面傳出了混濁的咕嚕聲!不管那裡有什麼，它肯定不是個友善的傢伙。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5060 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5060, 'zhTW', '被鎖起來的農夫', '', '進度一個極其結實的櫃子立在你面前，櫃子的門被一個內建的鎖牢牢地鎖著。櫃子的前面有深深的劃痕與刻痕，看起來好像是在無數次想要解開其中秘密的粗暴失敗嘗試所導致的結果。$B$B如果你想要打開這個櫃子，就得先找到鑰匙。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5065, 'zhTW', '失落的摩沙魯石板', '那個食人妖沒有對你說出真相。你為他弄來的那兩塊石板提到了哈卡精華，但是那個傳說的內容應該還有更多才對。我已經研究很久了，而且我發現摩沙魯石板應該總共有六塊，並非兩塊!是六塊!$B$B我恐怕其他人所掌握的那些秘密會對我們不利……$B$B找到第三塊和第四塊摩沙魯石板。它們在東瘟疫之地，被居住在那裡的爛苔食人妖控制著。找到它們並把它們交給我。', '把第三塊和第四塊摩沙魯石板交給塔納利斯的勘察員鐵靴。', '', '去塔納利斯找熱砂港的勘察員鐵靴。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5066, 'zhTW', '戰鬥的號角:瘟疫之地!', '大家都聽著!大家都聽著!所有的英雄都應該聆聽這號召的聲音!暴風城已經發出了備戰的號召!所有勇士都應該拿起武器，一同面對來自東部王國北部地方天譴軍團的威脅!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，聯盟的安全岌岌可危!聯盟的英雄們-去向指揮官阿胥拉姆·瓦羅菲斯特報到吧，他的大本營就在奧特蘭克山脈北邊的冰風營地!', '找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5090, 'zhTW', '戰鬥的號角:瘟疫之地!', '大家都聽著!大家都聽著!所有的英雄都應該聆聽這號召的聲音!暴風城已經發出了備戰的號召!所有勇士都應該拿起武器，一同面對來自東部王國北部地方天譴軍團的威脅!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，聯盟的安全岌岌可危!聯盟的英雄們-去向指揮官阿胥拉姆·瓦羅菲斯特報到吧，他的大本營就在奧特蘭克山脈北邊的冰風營地!', '找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5092, 'zhTW', '掃清道路', '安多哈爾城西和城北的入口防守非常嚴密，我正在努力從防禦力較弱的東面入口尋找突破點。天譴軍團以佔據悔恨嶺的不死生物部隊所組成的第一道防線作為緩衝區，如果我們想要進攻安多哈爾的話，就必須穿過悔恨嶺。$B$B你的第一個任務是清除悔恨嶺一帶的障礙，掃除在這一地區出沒的骷髏和食屍鬼，任務完成之後就回來向我彙報!', '殺掉悔恨嶺中的10個骷髏撕掠者和10個被奴役的食屍鬼。$B$B然後向西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特覆命。', '', '去西瘟疫之地找冰風崗的指揮官阿胥拉姆·瓦羅菲斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5093, 'zhTW', '戰鬥的號角:瘟疫之地!', '部落的英雄們，請聆聽這召喚的聲音─部落召喚你們迅速行動起來!戰鬥的號角已經吹響，所有勇士都應拿起武器，準備與天譴軍團殊死作戰!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，部落的安全岌岌可危!部落的英雄們─去向高級執行官德靈頓報到吧，他的大本營就在提里斯法林地東部的亡靈壁壘!', '找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5094 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5094, 'zhTW', '戰鬥的號角:瘟疫之地!', '部落的英雄們，請聆聽這召喚的聲音─部落召喚你們迅速行動起來!戰鬥的號角已經吹響，所有勇士都應拿起武器，準備與天譴軍團殊死作戰!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，部落的安全岌岌可危!部落的英雄們─去向高級執行官德靈頓報到吧，他的大本營就在提里斯法林地東部的亡靈壁壘!', '找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5095, 'zhTW', '戰鬥的號角:瘟疫之地!', '部落的英雄們，請聆聽這召喚的聲音─部落召喚你們迅速行動起來!戰鬥的號角已經吹響，所有勇士都應拿起武器，準備與天譴軍團殊死作戰!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，部落的安全岌岌可危!部落的英雄們─去向高級執行官德靈頓報到吧，他的大本營就在提里斯法林地東部的亡靈壁壘!', '找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5096, 'zhTW', '誤導血色十字軍', '在進軍安多哈爾之前，我們必須解決來自壁爐谷的血色十字軍的威脅。他們已經在費爾斯通農場和達爾松之淚中間建立了營地，這使得我們在對天譴軍團和十字軍的作戰中處於劣勢，風險激增。$B$B我的計畫是挑起他們之間的戰爭，你要做的就是去摧毀十字軍的指揮帳篷，使用這只箱子裡的燃燒瓶就行了。在點燃了帳篷之後，把天譴軍團戰旗插在他們的營地中。如果我們運氣夠好的話，十字軍就會對天譴軍團進行報復。', '到血色十字軍建在費爾斯通農場和達爾松之淚之間的營地去，摧毀他們的指揮帳篷。$B$B將天譴軍團戰旗插在營地中，然後回到西瘟疫之地亡靈壁壘的高級執行官德靈頓那兒。', '摧毀指揮帳篷並在營地插上天災旗幟', '去找提裏斯法林地的高級執行官德靈頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5097 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5097, 'zhTW', '標記哨塔', '通過使用一種被稱作信號火炬的魔法物品，我們可以為軍隊即將展開的行動標識出目標。我們認為天譴軍團正在將安多哈爾的哨塔作為控制軍隊的手段。$B$B你的任務就是突破安多哈爾的防線，將信標放置在四座哨塔中。你必須將信標放在每座哨塔的門口才行。信號火炬僅可使用五次，可別浪費了!', '使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。$B$B在做完了標記之後，將信號火炬還給西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特。', '', '去西瘟疫之地找冰風崗的指揮官阿胥拉姆·瓦羅菲斯特。', '標記第一座塔', '標記第二座塔', '標記第三座塔', '標記第四座塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5098, 'zhTW', '標記哨塔', '通過使用一種被稱作信號火炬的魔法物品，我們可以為軍隊即將展開的行動標識出目標。我們認為天譴軍團正在將安多哈爾的哨塔作為控制軍隊的手段。$B$B你的任務就是突破安多哈爾的防線，將信標放置在四座哨塔中。你必須將信標放在每座哨塔的門口才行。信號火炬僅可使用五次，可別浪費了!', '使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。$B$B在做完了標記之後，將信號火炬還給西瘟疫之地亡靈壁壘的高級執行官德靈頓。', '', '去找提裏斯法林地的高級執行官德靈頓。', '標記第一座塔', '標記第二座塔', '標記第三座塔', '標記第四座塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5142, 'zhTW', '小帕米拉', '在達隆郡戰役中，我們犧牲了很多人。很多人死了……甚至更糟……戰爭一開始，我就把我的侄女帕米拉藏了起來，我不知道她現在到底怎麼樣了。我只是一個遊魂，但是我一直很想知道帕米拉的下落。求求你，好心的$c，你能去達隆郡找她嗎?往東邊走，過了蓋羅恩農場就到達隆郡了。', '找尋帕米拉·雷德帕斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5149, 'zhTW', '帕米拉的洋娃娃', '瑪萊恩姑媽讓我留在家裡，因為我的爸爸出去作戰了。爸爸是世界上最勇敢的人!$B$B但是我在這裡等了很長時間，他一直都沒有回來。有時候會有壞人來和我說話，我想讓爸爸把他們趕走，但是他不在這裡!$B$B有時候，天黑了以後，我會和我的洋娃娃玩，但是我把它丟在鎮子裡了。$B$B你能不能去幫我找到洋娃娃呢?', '找到帕米拉的洋娃娃。', '', '去找東瘟疫之地的帕米拉·雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5152, 'zhTW', '瑪萊恩姑媽', '啊，我感到好孤獨!我的家人在哪裡?瑪萊恩姑媽要我在這裡等，但是她就這樣一去不復返了!還有我的父親……你看到過他沒有?也許瑪萊恩姑媽知道他在哪裡。她住在安多哈爾附近，在靠南邊的一座房子裡。我想那房子是在一座小山上……她說過房子在山上。請你幫幫忙，$N。你是我的新朋友!你可以幫我去找我的姑媽嗎?', '與安多哈爾廢墟南邊的瑪萊恩談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5154, 'zhTW', '達隆郡的歷史', '要拯救約瑟夫·雷德帕斯，我們首先得找到他的過去。安多哈爾城鎮中心有一本書，名叫《達隆郡的歷史》，它可以告訴我們一些重要的事情。$B$B把書拿來給我，然後我們就可以了解約瑟夫的命運，如果運氣好的話……我們還能改變它!', '把《達隆郡的歷史》交給安多哈爾的克羅米。', '', '去西瘟疫之地找安多哈爾廢墟的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5168, 'zhTW', '達隆郡的英雄', '我永遠銘記著達隆郡的英雄，你帶給我的這本《達隆鎮的歷史》中就講述了他們的故事。$B$B書中提到了聖騎士達維·萊法爾，還提到了血色十字軍把他的聖契放在壁爐谷的城鎮大廳中。$B$B書中還提到了我的兄弟，雷德帕斯隊長。在他叛變之後，他的盾牌被擊碎並拋棄了，它就被扔在一個看起來最不可思議的地方─靠近蓋羅恩農場的穀倉那裡。$B$B收集那些被命運和悲劇籠罩的聖物，$N。', '把達維的聖契和雷德帕斯之盾交給卡林·雷德帕斯。', '', '去東瘟疫之地找聖光之願禮拜堂的卡林·雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5181, 'zhTW', '達隆郡的惡魔', '《達隆郡的歷史》講述了那場戰役中的幾個天譴軍團頭目。聯盟在這場戰役中如何殺死了食屍鬼之王，『劫毀者』霍古斯。他的屍體被扔到考林路口西北面的湖泊中，現在他的頭顱還在那兒呢。$B$B黑衣瑪杜克從未吃過敗仗，但是他的劍卻被擊落，留在了考林路口西面的山谷底部。$B$B去找回顱骨和寶劍吧，$N。我不清楚原因，但是我知道它們的命運是跟你有關聯的。', '將霍古斯的顱骨和馬杜克的破碎之劍交給聖光之願禮拜堂的卡林·雷德帕斯。', '', '去東瘟疫之地找聖光之願禮拜堂的卡林·雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5206, 'zhTW', '達隆郡的掠奪者', '克羅米說你所收集的那些聖物是施放一個強大的法術所必需的材料，此外還需要一樣東西:參加達隆郡戰役的天譴軍團士兵的顱骨。$B$B帶著這塊水晶去獵殺天譴軍團的士兵，並拿到他們的顱骨。這塊水晶已經被施了魔法，如果某個士兵曾參加過那場戰鬥，那麼當你把水晶球放在他的顱骨上時，它就會發出共鳴。把那些可以與水晶共鳴的顱骨交給我。$B$B快去，$N。你可以在北方的劇毒林地和西方的蘑菇林中找到天譴軍團的士兵。', '把5個共鳴顱骨和神秘水晶交給東瘟疫之地的卡林·雷德帕斯。', '', '去東瘟疫之地找聖光之願禮拜堂的卡林·雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5210, 'zhTW', '卡林弟兄', '借助我的魔法，《達隆郡的歷史》被增補了，現在它所記述的歷史已經包括戰爭之後的事情了。新增的章節裡有一部分講述了另一個雷德帕斯家族成員的下落，他在約瑟夫叛變後僥倖活了下來。卡林·雷德帕斯在東瘟疫之地的聖光之願禮拜堂裡。$B$B拿著這本書去找他吧。', '將《達隆鎮全史》交給東瘟疫之地的卡林·雷德帕斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5211, 'zhTW', '達隆郡的防衛者', '許多防衛者在達隆郡的戰役中倒下了。而他們之中許多人又成了天譴軍團的爪牙!找到這些可憐的靈魂並結束他們的痛苦!$B$B去獵殺吃人的食屍鬼、語無倫次的食屍鬼和生病的撕掠者。他們以前都是達隆郡的善良居民，現在毀滅他們的形體將會使他們的靈魂得到自由。$B$B你可以在病木林、考林的十字路口，還有東瘟疫之地的其他天譴軍團的據點裡找到他們。', '釋放15個達隆郡居民的靈魂，然後返回卡林·雷德帕斯身邊。', '', '去東瘟疫之地找聖光之願禮拜堂的卡林·雷德帕斯。', '解放達隆郡的靈魂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5215, 'zhTW', '瘟疫之鍋', '在羅德隆的土地上有八口瘟疫之鍋，其中四口在西瘟疫之地，另外四口在東瘟疫之地。這些瘟疫之鍋不斷向空中噴出毒氣，將天譴軍團的瘟疫傳播到整個大地。科爾蘇加德的力量太強大了，我們無法關掉這些瘟疫之鍋，但是我想我們可能有辦法利用它們。我的助手，高階牧師瑪多妮爾負責此項任務的執行，你去找她談談吧。', '與西瘟疫之地冰風崗的高階牧師瑪多妮爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5216, 'zhTW', '目標:費爾斯通農場', '在西瘟疫之地的四口瘟疫之鍋中，費爾斯通農場裡的那一口可能是最容易進入的了。天譴軍團在那邊駐紮的都是新兵，儘管他們也不是輕易可以擊敗的對手，但相對來說畢竟容易一些。$B$B到費爾斯通農場去，它就在這裡的正東方，安多哈爾的西北方，並與那裡的護鍋領主交戰。它身上有一把可以打開瘟疫之鍋的鑰匙。當你開啟那口鍋之後，用這個瓶子裝滿鍋裡的毒藥樣品，我們要對它進行研究以製造出一種解藥。', '到西瘟疫之地的費爾斯通農場去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶費爾斯通農場的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5217, 'zhTW', '返回冰風營地', '你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到冰風營地的高階牧師瑪多妮爾那裡去了。', '把費爾斯通農場的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5219, 'zhTW', '目標:達爾松之淚', '有一口瘟疫之鍋被放置在一座早已廢棄的農場上，現在這裡被稱為達爾松之淚。不過現在我們沒時間掉眼淚，$c。我們必須打開這口瘟疫之鍋!$B$B到安多哈爾正北方的達爾松之淚去，消滅那裡的護鍋領主。像上次一樣，護鍋領主身上應該有一把可以打開瘟疫之鍋的鑰匙。用這個瓶子從鍋裡裝一份樣品拿回來，每口鍋所使用的毒素配方都是截然不同的。', '到西瘟疫之地的達爾松之淚去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶達爾松之淚的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5220, 'zhTW', '返回冰風營地', '你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到冰風營地的高階牧師瑪多妮爾那裡去了。', '把達爾松之淚的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5222, 'zhTW', '目標:嚎哭鬼屋', '已經有兩口瘟疫之鍋被成功打開了，雖然並不確定你能否繼續前進，但我們仍然想要打開剩下的兩口瘟疫之鍋。這可以讓我們的解藥發揮更大的效果!$B$B這次你的目標是嚎哭鬼屋的瘟疫之鍋。那個地方在安多哈爾正東邊，相對來說比較靠近被毀壞的城牆。和以前一樣，消滅那裡的護鍋領主，拿到它的鑰匙。用這只瓶子從鍋裡取得樣品。$B$B祝一切順利，$N!', '到西瘟疫之地的嚎哭鬼屋去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶嚎哭鬼屋的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5223, 'zhTW', '返回冰風營地', '你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到冰風營地的高階牧師瑪多妮爾那裡去了。', '把嚎哭鬼屋的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5225, 'zhTW', '目標:蓋羅恩農場', '最後的一口瘟疫之鍋在一個被稱作蓋羅恩農場的地方，由天譴軍團中較為強大的爪牙守衛著─那裡的鬼魂和怨靈尤其危險。你可不能掉以輕心，$N。$B$B蓋羅恩農場在這裡的東北方向，靠近東瘟疫之地的邊界。和以前一樣，消滅那裡的護鍋領主以獲取他的鑰匙。拿著這個空樣品瓶，把它裝滿給我拿回來。願聖光護佑你平安完成這次危險的任務，$c。', '到西瘟疫之地的蓋羅恩農場去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶蓋羅恩農場的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5226, 'zhTW', '返回冰風營地', '你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到冰風營地的高階牧師瑪多妮爾那裡去了。', '把蓋羅恩農場的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5234, 'zhTW', '返回亡靈壁壘', '你小心地把瓶子裡裝滿了瘟疫之鍋中的毒液，一份從鍋子底部取出的毒液在這個易碎的玻璃瓶中不斷地翻騰著。$B$B現在該是帶著毒藥回到亡靈壁壘的暗影牧師范蒂絲那裡以完成這個任務的時候了。', '把裝滿了的瓶子交給西瘟疫之地的亡靈壁壘暗影牧師范蒂絲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5237, 'zhTW', '任務完成!', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5246, 'zhTW', '歷史的殘片', '我沒有意識到……請原諒我無情的話語，$c。$B$B我並不想回顧祖先犯下的錯誤，但是如果你的請求是真心的，那麼我會幫助你。$B$B<奧蘿拉查看了一下這些碎片>$B$B我相信這就是辛瑪洛水晶，一種具有強大的魔法力量並可以控制更強大力量的神器。它原本是用來做善事的，但那些偷走它的竊賊的邪惡力量使它破碎了。$B$B到艾薩拉的辛瑪洛神殿去─希望那本書還放在那裡。', '在艾薩拉的辛瑪洛神殿裡，找到神聖的精靈貴族筆跡。然後交給奧蘿拉，她就靠近東瘟疫之地的北地哨塔。', '', '去找東瘟疫之地的奧蘿拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5247, 'zhTW', '歷史的殘片', '如果你真的希望重塑神器，那我就可以幫助你。$B$B為了修復碎片，我需要一些具有強大魔法能量的物品。一塊附魔瑟銀錠和五塊恢復水晶……你還得從一個非常危險的地方搜集一些水……在菲拉斯地區的厄運之槌中，艾德雷斯區有一個厄運之池，用池中的水裝滿這只小瓶。$B$B在你去收集這些東西的時候，我會嘗試從書中找到復原神器所需的知識。', '給接近東瘟疫之地的奧蘿拉帶1塊附魔瑟銀錠、5塊恢復水晶，以及1小瓶恐怖之水。', '', '去找東瘟疫之地的奧蘿拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5248, 'zhTW', '記憶的折磨', '$N，我為過去所發生的事情哭泣。就像這塊水晶一樣，精靈這個種族已經破碎了。我不知道這些碎片是否還能被拼成一塊，但是能夠幫你完成這項小小的任務，這令我的悲痛減輕了許多。$B$B我們決不能忘記過去，$N……$B$B請把辛瑪洛水晶帶回凱斯利爾湖去，你必須尋找一個意識到這個錯誤的精靈貴族，讓他看到我們已經糾正了他們犯下的彌天大錯。', '把辛瑪洛水晶帶回冬泉谷的凱斯利爾湖，在那裡尋找一個會與你講話的精靈貴族。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5261, 'zhTW', '伊根·派特斯金納', '伊根·派特斯金納正在找人幫他獵捕狼。這是個好消息，因為現在北郡山谷裡的狼實在是太多了。如果你感興趣的話，那就去和伊根談談吧。他就在修道院的左邊。', '與伊根·派特斯金納談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5281, 'zhTW', '永不安息的靈魂', '在斯坦索姆淪陷的時候，許多人都悲慘地死去了。其中許多人是自殺的，他們寧願選擇葬身火海，也不願成為天譴軍團的一員。現在他們成了永遠也不得安息的幽靈，在斯坦索姆的街道上到處遊蕩。我們必須拯救他們，$N!我有一個名叫伊根的同伴，他多年來對鬼魂和幽靈進行了大量的研究，你可以去找他幫忙。伊根正在斯坦索姆附近的東瘟疫之地對他的新發明進行測試。', '找到伊根。你只知道他在斯坦索姆附近。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5342, 'zhTW', '巴羅夫的繼承人', '既然我的兄弟仍然活著，那麼自然就是家族財產的理所應當的繼承人。我絕不能讓他得到這筆財產。$B$B你這樣卑賤的流浪者除了當個冷血殺手之外還能幹什麼?$B$B這任務很簡單，我希望你能勝任。如果你想要得到報酬，就按我說的去做吧。$B$B維爾頓在東邊的冰風營地，他在那裡受到了聯盟的保護。殺死他，把他的腦袋給我帶回來。$B$B<阿萊克斯打了個哈欠。>$B$B趕快出發吧。', '到冰風營地─聯盟的領地─去暗殺維爾頓·巴羅夫。把他的腦袋交給阿萊克斯·巴羅夫。$B$B要多加小心，聯盟也許對維爾頓執行了嚴密的保護。', '', '去找提裏斯法林地的阿萊克斯·巴羅夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5344, 'zhTW', '巴羅夫的繼承人', '地契已經找到了，我們還剩下一件事要做─殺死阿萊克斯。只要他一死，我就用不著再擔心那些惟利是圖、肆無忌憚的強盜來取我的腦袋了。$B$B這任務很簡單。阿萊克斯在亡靈壁壘，他在那裡受到了部落的保護。$B$B不，只是殺死他還不行，我要你把他的腦袋拿回來!至於你怎麼做到這一點……呃，那是你的事情。這種行為可不是我這樣的貴族會做的。', '去亡靈壁壘─部落的領地─去暗殺阿萊克斯·巴羅夫。把他的腦袋交給維爾頓·巴羅夫。$B$B要小心，部落也許對阿萊克斯執行了嚴密的保護。', '', '去西瘟疫之地找冰風崗的維爾頓·巴羅夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5401 AND `locale` = 'zhTW';
