INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5660, 'zhTW', '虛弱之觸', '你已離家很遠了，$c。你的那座地下的城市需要你。你的女主人，那位召喚你回家的艾薩萊斯特需要你回到她身邊。有些東西你只能從她那兒學到，就像我的部落一樣。別在這兒待得太久了，你該迅速趕往幽暗城的軍事區。', '與幽暗城的艾薩萊斯特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5661, 'zhTW', '虛弱之觸', '血蹄村離你的家園很遠，$N。我來此是為了尋找自己部落的祭司，將他們帶回去同我們的領袖談談，但是這並不意味著我就沒法幫你了。我聽說你們的牧師領袖想要召集所有的被遺忘者─讓他們去跟她學點什麼。回到你的城市去，在軍事區跟艾薩萊斯特見一面吧。', '與幽暗城的艾薩萊斯特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5662, 'zhTW', '虛弱之觸', '我對你和你的族人表示尊重，$N。我一般只向我自己的同胞傳授技藝，你的課程開始於那座曾經被稱作羅德隆的城市中。如果你要學習那些只有你們才能掌握的技能，就回到幽暗城的軍事區裡去找艾薩萊斯特吧。', '與幽暗城的艾薩萊斯特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5663, 'zhTW', '虛弱之觸', '艾薩萊斯特正在召集她管轄的所有牧師，我們要指引那些較為年輕的成員到幽暗城去進行更多的訓練。如果你真的認為自己是我們中的一員，那麼你也應該回到那兒去。你可以在幽暗城深處的軍事區裡找到艾薩萊斯特。', '與幽暗城的艾薩萊斯特談話。', '', '', '', '', '', '', 0);
