INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5721, 'zhTW', '達隆郡的戰鬥', '現在，$N，你將參加達隆郡的戰鬥，並且拯救約瑟夫·雷德帕斯。$B$B把這個聖物包裹放到達隆郡的廣場中，達隆郡居民的靈魂將因此而被喚醒。參加他們的戰鬥，並確保你完成兩件事:在霍古斯死後，達維必須存活;雷德帕斯必須存活，直到他被腐化而墮落，此時再將其擊敗。$B$B在打敗了墮落的雷德帕斯之後，他的靈魂就將得到救贖。同他交談，然後再去找他的女兒帕米拉。', '將聖物包裹放在達隆郡的廣場中。$B$B在霍古斯死亡之前，達維必須存活。$B$B在雷德帕斯隊長墮落之前保證他存活。$B$B擊敗墮落的雷德帕斯。$B$B當約瑟夫·雷德帕斯出現在廣場中時，與他的靈魂進行交談，然後回到帕米拉的家中去找帕米拉。', '', '去找東瘟疫之地的帕米拉·雷德帕斯。', '接受雷德帕斯的寬恕', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5781, 'zhTW', '遺忘的記憶', '為了幫泰蘭找回他失去的東西，你必須收集他過去曾經使用過的物品。$B$B第一件是一個玩具，那是他7歲的時候我送給他的。這個玩具是他最珍愛的禮物:一隻小小的戰錘，那是我的戰錘的複製品。$B$B在我因叛國罪而被驅逐出去的時候，他媽媽告訴他我已經死了。他被帶到了我的「墳墓」前，就在南邊的墓室旁邊，把那隻小戰錘和對我的記憶永遠地埋在了那裡。$B$B你必須去一趟墓室，拿回泰蘭之錘。', '到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提里恩·弗丁那裡。', '', '去找東瘟疫之地的提里恩·弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5803, 'zhTW', '阿拉基的聖甲蟲', '『召喚者』阿拉基在城市廢墟的中心統治整個安多哈爾。我們知道在他占領了自己的城市之前，曾是通靈學院的領導者，為了完成鑰匙，我們就必須拿到他的那個被稱作聖甲蟲的圖章，用它來製作鑰匙的頭部。$B$B開一條路進入安多哈爾的中心，擊破他在城中空曠區域的守備。一旦將他摧毀，從他掉落的骨匣中奪取聖甲蟲!$B$B通靈學院的鑰匙在等著你，$N!', '殺掉『召喚者』阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地冰風崗的鍊金師阿爾比頓。', '', '去西瘟疫之地找冰風崗的鍊金師阿爾比頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5804, 'zhTW', '阿拉基的聖甲蟲', '『召喚者』阿拉基在城市廢墟的中心統治整個安多哈爾。我們知道在他占領了自己的城市之前，曾是通靈學院的領導者，為了完成鑰匙，我們就必須拿到他的那個被稱作聖甲蟲的圖章，用它來製作鑰匙的頭部。$B$B開一條路進入安多哈爾的中心，擊破他在城中空曠區域的守備。一旦將他摧毀，從他掉落的骨匣中奪取聖甲蟲!$B$B通靈學院的鑰匙在等著你，$N!', '殺掉『召喚者』阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。', '', '去找提裏斯法林地的藥劑師迪瑟斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5845, 'zhTW', '失落的榮耀', '當烏瑟被殺之後，白銀之手騎士團完全瓦解了。$B$B這孩子竭盡所能地堅持著。當他被逼入飽經戰亂的北谷中時，他做了最後的抵抗。$B$B騎士團是否還有別人活著，這還有什麼意義嗎?$B$B正是帶著這樣的想法，泰蘭拋棄了騎士團的戰旗，並否認了他所熟知的一切。他的榮譽被遺棄在了北谷那浸滿鮮血的土地上。$B$B你必須到北谷去，找回那面代表失落的榮耀的戰旗。', '到東瘟疫之地東北部的北谷去，找到失落榮耀的象徵。完成目標之後向提里奧·弗丁覆命。', '', '去找東瘟疫之地的提里恩·弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5846, 'zhTW', '愛與家庭', '當泰蘭還是孩子的時候，我們全家經常去凱爾達隆度假。我們最後一次去那裡時，一位名叫瑞弗蕾的藝術家為我們畫了一張在湖邊漫步的畫。這是最能讓我回想起與泰蘭和卡蘭德拉在一起時的美好時光的東西。那個時候我牽著我的妻子和兒子，心中充滿了無限的愛意。如果那幅畫還存在的話，你必須找到它。去凱爾達隆那座廢棄的島上看看那副畫或者那個畫家是不是還在吧。', '到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5861, 'zhTW', '尋找米蘭達', '$N，你完成了我交給你的所有任務，你的救贖任務只剩最後一步了。$B$B你必須把你收集到的東西交給泰蘭。不幸的是，泰蘭和他的血色十字軍一看見你就會立刻攻擊你。$B$B要傳遞我的信件只有一個辦法，那就是進行偽裝。$B$B往南走，你可以在那邊找到烏瑟之墓。我有個值得信賴的老朋友米蘭達住在那兒，找到她，把這些東西給她看看，她會幫助你的。', '到瘟疫之地南部的烏瑟之墓去，將提里恩的禮物交給巫女米蘭達。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5862, 'zhTW', '血色幻象', '我就是你們所說的……幻術師。雖然我可以創造一個幻影，讓你平安進入壁爐谷，但是你要知道，我的力量也不是無限的。$B$B如果你離開這個地區太遠的話，幻影會漸漸消失。這個法術需要花費大量的精力，即使這樣我也只能堅持很短的時間。$B$B當你準備好之後再和我說話吧。', '和巫女米蘭達交談以獲得血色幻影的效果。在血色幻影的掩護下深入壁爐谷，將提里恩的禮物交給大領主泰蘭·弗丁。$B$B壁爐谷在北方，泰蘭應該在瑪登霍爾德城堡裡面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5901, 'zhTW', '瘟疫與你', '為了削弱血色十字軍，我要拿下那座對他們來說至關重要的伐木場。我相信，如果他們損失了這麼重要的一個資源，定然會在構建防禦和重建城鎮的過程中捉襟見肘。你願意幫我的忙嗎，$N?$B$B把這個瓶子拿到東瘟疫之地的病木林去，在那裡的蟻丘上抓些白蟻，放進這個瓶子裡。當你收集到了足夠多的白蟻之後就回到我這裡來。', '在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100隻瘟疫白蟻之後，就回到提里斯法林地的亡靈壁壘去找米克·萊文。', '', '去找提裏斯法林地的米克·萊文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5903, 'zhTW', '瘟疫與你', '我試過很多方法來清除血色十字軍，但是從來都沒有成功過。好吧，我決定更換一下行事方法，我要讓他們吃吃苦頭。$B$B如果你願意幫我的話，我準備用最恐怖的白蟻來毀滅他們的伐木場。$B$B在靠近斯坦索姆的病木林裡有一種被瘟疫扭曲的白蟻。找到它們的巢穴，在瓶子裡裝滿白蟻，然後我們就把它們放到血色十字軍的伐木場裡!', '在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100隻瘟疫白蟻之後，就回到西瘟疫之地的冰風營地去找納薩尼爾·杜馬。', '', '去西瘟疫之地找冰風崗的納薩尼爾·杜馬。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5904, 'zhTW', '瘟疫與你', '現在我們有足夠的白蟻了，把這只鐵桶拿到壁爐谷南邊的北山伐木場去─就在那條通往鎮子的小路的西邊。$B$B當你到了那裡之後，就在伐木場的中間找個高一點的地方，比如一隻木箱或者別的什麼東西，把桶放在上面，然後打開桶蓋。這樣，白蟻就會開始它們的工作，然後讓那個伐木場徹底完蛋。', '到西瘟疫之地的北山伐木場去找個合適的地方，在那裡放下一桶瘟疫白蟻。$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5961, 'zhTW', '女妖之王的勇士', '我很高興地看到強大的勇士不斷加入我們的行列。隨著時間的推移，我們的軍隊數量和戰鬥力在不斷提升。也許現在已經到了考驗你的勇氣的時候了，$c。我手下最勇猛的大將是納薩諾斯·凋零者。我們之中很少有誰能比他更具有奉獻精神和活力了。到東瘟疫之地去找他。他就住在瑪瑞斯農場，偶爾也會在附近徘徊，殺死沿途所遇到的一切天譴軍團和聯盟成員。', '與東瘟疫之地的納薩諾斯·凋零者談一談。據說他居住在瑪瑞斯農場。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6003, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6004, 'zhTW', '未完成的任務', '我以間諜的身份來此暗中搞破壞，並負責偵察壁爐谷的防禦力量。聯盟中的一些人認為這座小鎮的重要性並不局限於其歷史意義，不過這與我的工作無關。但無論如何，我要好好休息一下才有精力繼續做事。$B$B如果你願意的話，我願意出大價錢換取你的幫助。沿著堡壘附近的營帳往南查看。如果你能證明自己的實力，或許你就能幫上我的大忙呢。', '殺死2個血色醫護員、2個血色獵人、2個血色魔法師和2個血色騎士，然後回到西瘟疫之地的科爾斯塔·迪普沙東那兒。', '', '去找西瘟疫之地的科爾斯塔·迪普沙東。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6021, 'zhTW', '『流亡者』塞達爾', '在經歷了瘟疫之地的一次次禍事之後……我們還得防著盜賊。你能相信嗎?他們不是普通的盜賊，而是食人妖盜賊。$B$B不是普通的食人妖盜賊。而是亡靈食人妖盜賊!$B$B統帥這夥盜賊的是一個身體魁梧的亡靈食人妖，『流亡者』塞達爾，他們趁著夜色來到這裡，從下面的坑裡盜取屍體，然後把屍體運到他們那邪惡的藏身之所─西邊的墓室中。$B$B到那兒去，幹掉塞達爾，$N。我對他深惡痛絕!', '將塞達爾的頭顱交給聖光之願禮拜堂的護理者奧林。', '', '去東瘟疫之地找聖光之願禮拜堂的護理者奧林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6022, 'zhTW', '殺戮的理由', '我的要求就是你殺戮的理由。$B$B你的第一個任務是餵養我的獵犬。$B$B拿著這個研缽和搗杵，然後到考林路口去。你可以在那裡發現很多可供你屠殺的不死生物，從他們身上取得生命腐質，把它們放在研缽裡搗爛，然後等待它凝固。把凝固腐質給我拿回來。$B$B記住，笨蛋，那些生命腐質不會長時間保持「活力」，你必須動作快一些!', '到東邊的考林路口去屠殺鎮裡的天譴軍團。在10分鐘內收集7塊生命腐質，使用研缽和搗杵將其研磨成凝固腐質。', '', '去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6024, 'zhTW', '哈米亞的請求', '殺了我。否則就太遲了。$B$B我是哈米亞。在穿越祖爾瑪夏的時候，我和我的兄弟吃了點壞掉的肉……我們已經變了。我們已經被感染了。$B$B現在我可以感覺到巫妖的話語，他要求我去祖爾瑪夏，並感染更多我的同胞。我無法抵抗他的命令，所以在我失去一切之前，我寫下了這張卷軸。$B$B我在這座地穴的後方埋了一隻箱子，就在貨車旁的土堆中。但是只有我的鑰匙可以打開它，鑰匙在我的手裡。如果你想要得到我的財寶，就來找到我。$B$B殺了我。否則就太遲了。', '殺了滲透者哈米亞，用他的鑰匙開啟墓室後的一堆泥土。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6026, 'zhTW', '獅子大開口', '銀色黎明的成員讓煙鬼給他們幹一些「爆炸性的」工作，煙鬼可不是小角色!只要你願意掏錢，我隨時為你效勞。這就是我的座右銘!$B$B如果你能為我做點跑腿之類的小事，那麼我也願意和你一起分享榮譽。具體來說是這樣的:我要去一趟病木林，然後給我們將要摧毀的建築物做上標記，而你就負責收集製造炸彈所需的材料。當你拿到所有東西之後就把它們交給我。你覺得怎麼樣?', '煙鬼拉魯恩要你拿來2塊瑟銀錠、1根金棒、8顆高爆爆裂物和8個不牢固的扳機。$B$B你需要找鐵匠和工程師幫忙製作這些東西。', '', '去東瘟疫之地找聖光之願禮拜堂的煙鬼拉魯恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6042 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6042, 'zhTW', '討厭的蝙蝠', '只要你離開農場兩步，就肯定可以撞見那些討厭的蝙蝠。我想帶著這些獵犬出去，在不驚動這些該死的傢伙的情況下剿滅天譴軍團。很明顯，與其讓我去沒日沒夜地砍殺蝙蝠，還不如做點更有意思的事情。但是你跟我不同。$B$B什麼?你的培訓?這就是培訓!出發吧，如果你不殺死一定數量的蝙蝠就別回來。不要讓我失望。', '殺掉20隻毒性瘟疫蝙蝠和10隻巨型瘟疫蝙蝠，然後回到納薩諾斯·凋零者那裡。', '', '去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6133, 'zhTW', '遊俠之王的命令', '奎爾林斯小屋裡的高等精靈拿著一件屬於我的東西，一本記錄著我生前的那些往事的日記。$B$B在你詢問之前，我要先明確地告訴你:你不得翻閱這些資料。照我說的做，你這條蟲子，去給我找到這份文件。$B$B另外，一定要讓他們飽嘗痛苦和悲傷，讓他們受盡苦難和折磨……', '到東瘟疫之地的北方邊界去找回奎爾薩拉斯名冊，這件物品在奎爾林斯小屋的某處。$B$B另外你還必須殺掉8個遊俠、8個巡路者和8個護林者。', '', '去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6141, 'zhTW', '安東修士', '我的好兄弟安東修士聽說在卡林多大陸的某處有不死生物出沒的傳聞─那個地方叫做淒涼之地。安東立即就決定要到那裡去消滅不死生物!他正在尋找有勇氣和決心幫助他的冒險者。如果你願意的話，就去找安東談談吧。他在淒涼之地的尼耶爾前哨站裡。', '與淒涼之地的安東修士談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6164, 'zhTW', '奧古斯圖斯的收據冊', '準備開張!你想要點什麼?$B$B啊，等等……沒有收據冊，我就不能開張。沒有收據冊的話，我怎麼能搞清楚帳目呢?$B$B我一定是把它丟在鎮裡了。我在旅店裡住過，一定是在那裡。$B$B把我的收據冊拿回來吧。請把它交給我!我要儘快開張營業，而你會看到我的價格完全出乎你的意料!', '把奧古斯圖斯的收據冊交給恐懼谷中精神失常的奧古斯圖斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6165, 'zhTW', '<NYI> <TXT> Archmage Timolain\'s Remains', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6182, 'zhTW', '第一個和最後一個', '納薩諾斯·瑪瑞斯是歷史上第一個也是最後一個人類遊俠領主，他是希瓦娜斯·風行者的學生。我們一直以為納薩諾斯在五年前的羅德隆保衛戰中犧牲了。儘管他的屍體從未被發現，但人們都認為他不大可能從東瘟疫之地逃出來。馬迪亞斯·肖爾一直在調查這起失蹤案，而且可能有了一些新的消息。立即去向他彙報。馬迪亞斯就住在舊城區的兵營裡。', '與暴風城的馬迪亞斯·肖爾談一談，他住在舊城區的兵營裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6321, 'zhTW', '瑟伯切爾的補給', '執行官哈德瑞克讓我清查我們在瑟伯切爾的裝備。由於森林中潛伏著的天譴軍團士兵的威脅，他不希望我們在裝備方面有所短缺。$B$B我發現，我們的武器裝備基本上庫存豐富，但是我們仍然需要更多的武器來替換那些在戰場上丟失的武器。$B$B這是一份武器訂單，把它交給幽暗城裡的武器供應商高頓·溫德哈姆。帶著訂單去找我們的蝙蝠管理員卡洛斯·拉佐克，跟他談談關於前往幽暗城的事兒吧。', '將博迪瑞格的訂單交給卡洛斯·拉佐克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6322, 'zhTW', '邁克爾·加勒特', '我已經將瑟伯切爾那邊要求的物資裝箱了。如果你已經拜訪過瑟伯切爾，並與他們那裡的蝙蝠管理員打過招呼，那麼你就可以乘坐蝙蝠回到那兒去。$B$B與幽暗城的蝙蝠飼養員邁克爾·加勒特談談吧，他可以為你提供一隻飛往瑟伯切爾的蝙蝠。', '將高頓的箱子交給邁克爾·加勒特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6323, 'zhTW', '飛往幽暗城', '只需一小筆費用，我的蝙蝠就可以把你帶到幽暗城去。當你準備就緒時再來找我，然後我會幫你安排剩下的事情。$B$B你可以在幽暗城的貿易區裡找到高頓·溫德哈姆，我的蝙蝠正好會降落在那個區域。', '從蝙蝠管理員卡洛斯·拉佐克那裡租一隻蝙蝠飛往幽暗城，然後將博迪瑞格的訂單交給幽暗城裡的高頓·溫德哈姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6324, 'zhTW', '向博迪瑞格回報', '瑟伯切爾的蝙蝠管理員是卡洛斯·拉佐克。如果你們已經見過面，那麼我可以為你提供一隻返回他那兒去的蝙蝠。$B$B這些蝙蝠都可以直飛幽暗城，但是如果你想要飛到更遙遠的地方去，就必須先拜訪那個區域的蝙蝠飼養員。$B$B你已經在瑟伯切爾跟卡洛斯碰過面了，現在你可以乘坐蝙蝠回到他那裡去。當你準備就緒時再來找我吧。', '從蝙蝠管理員邁克爾·加勒特那兒租一隻蝙蝠飛往瑟伯切爾，然後將高頓的箱子交給瑟伯切爾的亡靈衛兵博迪瑞格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6341, 'zhTW', '泰達希爾的漁業', '魯瑟蘭村周圍水域中的魚又大又肥，所以這裡的漁業很昌盛。我希望把從這裡捕獲的魚和卡林多的魚進行比較，研究一下它們有何不同。$B$B我收集了一些魚骨頭和鱗片，想要把它們帶到我在黑海岸的一個同事那裡去。他的名字叫做賴爾德，是奧伯丁的魚商。$B$B把我的東西拿到角鷹獸管理員維斯派塔斯那裡去，跟他談談關於去奧伯丁的事宜。', '將奈莎的貨物交給維斯派塔斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6342, 'zhTW', '飛往奧伯丁', '從魯瑟蘭村到奧伯丁去的方法有兩種:乘船或者騎角鷹獸。這兩種方式都很迅捷可靠，但是如果你沒有搭乘過角鷹獸的話，我建議你試一下。$B$B另外，你最好和各個城鎮中的角鷹獸管理員談談。一旦你和某地的角鷹獸飼養員打過了招呼，那麼以後你就可以從其他城鎮飛到那裡去了。$B$B這裡是奈莎的貨物。如果你準備好了的話，就再次和我對話，然後把這包東西送到賴爾德那裡。', '從角鷹獸管理員維斯派塔斯那裡乘一隻角鷹獸到奧伯丁，然後將奈莎的貨物交給賴爾德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6343, 'zhTW', '回去找奈莎', '我必須給奈莎回信，她應該會對這裡的魚跟泰達希爾沿岸的那些魚的差異感興趣。出現這種差異的原因……也許是世界之樹在影響其周圍的生物!$B$B請你幫我給奈莎捎個信。如果你想要乘坐角鷹獸回魯瑟蘭村的話，那就去跟角鷹獸管理員凱萊斯·月羽談談吧。如果你要搭船回去，西北面的碼頭那裡有定時的航班。', '將賴爾德的回信交給奈莎·影歌。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6344, 'zhTW', '奈莎·影歌', '我的朋友奈莎·影歌是魯瑟蘭村的一個漁業商人，她要送一個包裹到黑海岸去，所以她正在找人幫忙。如果你感興趣的話，那就去找奈莎吧。從達納蘇斯到魯瑟蘭村去的傳送門就在神殿花園的西邊。', '與奈莎·影歌談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6361, 'zhTW', '一捆獸皮', '我有一捆從貧瘠之地採集的獸皮，必須要把它們送到雷霆崖去。我在那兒的同伴安哈努需要用這些獸皮來製作皮件。$B$B你能幫我把這些獸皮交給他嗎?$B$B前往雷霆崖最為快捷的方法就是乘坐雙足飛龍。帶著這捆獸皮去十字路口找雙足飛龍管理員迪弗拉克，跟他談談到雷霆崖去的事兒。', '帶著獸皮去找十字路口的雙足飛龍管理員迪弗拉克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6362, 'zhTW', '飛往雷霆崖', '只需一小筆費用，我就可以為你提供飛往雷霆崖的雙足飛龍。沒有比這更方便快捷的旅行方式了!$B$B如果你願意的話，準備一下就來找我吧。$B$B如果你要把這些獸皮交給安哈努，就到雷霆崖雙足飛龍高塔底層的海瓦的武器店裡去找他吧，就是你降落的地方!', '從雙足飛龍管理員迪弗拉克那裡租一隻馭風者飛往雷霆崖，然後將這捆獸皮交給雷霆崖的安哈努。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6363, 'zhTW', '雙足飛龍管理員塔爾', '我已經為加翰準備好了供他在十字路口出售的皮件。請你把這些交給他好嗎?$B$B如果你已經拜訪過了十字路口的雙足飛龍管理員，那麼你就可以乘坐雷霆崖的雙足飛龍返回他那兒了。$B$B將皮件交給雷霆崖的雙足飛龍管理員塔爾，然後和他談談前往十字路口的行程安排。', '將安哈努的皮貨交給雷霆崖的塔爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6364, 'zhTW', '向加翰回覆', '想要飛回某座城鎮的話，你必須已經徒步到達過那裡，並且和那裡的雙足飛龍管理員打過招呼。如果你去過十字路口並和他們的雙足飛龍管理員迪弗拉克談過話，那麼你就可以從這裡搭乘雙足飛龍直接飛過去了。$B$B如果你準備好了，就再次和我談談。一旦到了十字路口，你就可以把這些皮貨交給加翰·鷹翼了。', '從雙足飛龍管理員塔爾那裡租用一頭飛往十字路口的雙足飛龍，並把安哈努的皮貨交給加翰·鷹翼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6662, 'zhTW', '我的兄弟，尼普希', '我的兄弟尼普希在地鐵的另一端經營一家烤老鼠肉。你必須在這箱老鼠壞掉之前把它們交給他。趕快!$B$B你以前坐過地鐵，對吧?很簡單，只要等車停下來，走上去，然後就享受你的旅程吧。在車子行進時可別把頭手伸出車外，免得你下半輩子得靠義肢過日子。', '把裝著神秘肉品的紙箱交給在暴風城礦道地鐵倉庫的尼普希。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6721, 'zhTW', '獵人之道', '你好，年輕的獵人。看起來你已經準備好要馴服一頭野獸，並將其訓練成自己的同伴了。你必須去見一見多蘭納爾的達札拉，他可以幫助你馴服自己的第一頭寵物。', '與多蘭納爾的達札拉談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6841, 'zhTW', '<UNUSED>', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6961, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在奧格瑪燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6962, 'zhTW', '招待冬天爺爺', '嘿，你能幫冬天爺爺一個忙嗎，小<男孩/女孩>？$B$B不用我說你也看得出來，冬天爺爺一天到晚都在這裡忙碌，所以他想吃些東西。一些薑餅搭配一杯冰牛奶將會非常正點 。你是冬天爺爺的朋友吧，可以帶些給我嗎？', '把5塊薑餅和一杯冰牛奶帶給奧格瑪的冬天爺爺。', '', '去找奧格瑪的冬天爺爺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6963, 'zhTW', '被偷的冬幕節', '聽著……並不是我們的神奇力量不夠，但是燻木牧場需要一些幫助——一種你們這些冒險者知道該如何給予的幫助。我們遺失了一批為了這個季節而儲存的貨物，而且現在連我們派去找這批貨物的燻木牧場特派員也不見了！拜託——最後一次出見那批貨是在奧特蘭克山脈，我們的人也是到那裡去了。請你去那裡看看人跟貨是不是都在那裡，是否一切安好！', '去奧特蘭克山脈的雪地找到失蹤的燻木牧場調查員。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6964, 'zhTW', '冬幕節的意義', '禮物，款待，獎品……我要說，呸！那些哥布林玷污了這個季節的真正意義——冬幕節。這是個萬物復甦的時刻，整個大地安靜的覆蓋在冬天爺爺所帶來的薄雪之下，冬天爺爺可不是那個穿著紅色外套的笨蛋！如果你想要瞭解更多關於冬幕節的事情，就去問問薩格尼吧。它肯定會因為有人對禮物不感興趣而是對冬幕節的歷史感興趣而感到驚奇的。', '和奧格瑪智慧谷裡的薩格尼談談關於冬幕節的事情。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6983, 'zhTW', '天寒地凍', '一個叫做「可惡的格林奇」的生-生-生物偷走了我們的貨-貨-貨物，$N。小-小-小心！$B$B如果你要-要-要面-面-面對他的話。我看見他總是在雪-雪-雪怪出沒的地方晃-晃-晃悠；他一-一-一定在那-那-那裡！找-找-找到我們的貨物，$N，把他帶回-回-回給奧格瑪的燻木牧場，並告-告-告訴他們我需-需-需要解凍！', '找到並把被偷走的禮品帶給奧格瑪的凱瑪德·考伯賓奇。它被可惡的格林奇拿走了，去奧特蘭克雪地中去找它。', '', '去找奧格瑪的凱瑪德·考伯賓奇。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6984, 'zhTW', '', '', '[Speak with Great-father Winter in Orgrimmar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7021, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去跟現在正在奧格瑪的冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在奧格瑪燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7022, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在鐵爐堡燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
