INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7023, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去跟現在正在鐵爐堡的冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在鐵爐堡燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
