INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8428, 'zhTW', '峽谷之戰', '我們在戰歌峽谷對銀翼哨兵的戰役非常重要。聯盟以保護這片不屬於他們的森林為由，妄圖從部落手中奪取我們最大的伐木場。$B$B別讓他們的妄想成為事實，$N！為了部落，證明你的價值！成功之後再回到我這兒來。', '將3枚戰歌榮譽獎章交給戰場外的部落戰爭使者。', '', '去找部落戰爭使者。', '', '', '', '', 0);
