INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8438, 'zhTW', '資源競賽', '我們和聯盟的衝突已擴大為一場真正的戰爭，不久之後戰爭就將全面開戰。$B$B對於阿拉希盆地的爭奪就是一個很好的開戰理由。不是聯盟取得資源並將它們拿來對抗我們；就是我們取得資源並拿來支援我們的戰爭。幫助污染者保持這場資源競賽上的優勢吧，$N！', '將3枚阿拉希盆地榮譽獎章交給戰場外的部落戰爭使者。', '', '去找部落戰爭使者。', '', '', '', '', 0);
