INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8746, 'zhTW', '麋鹿梅特森', '出大事了！麋鹿梅特森被綁架了！$B$B梅特森是冬天爺爺的八頭麋鹿之一－－也是燻木牧場的財產。我們已經收到不只一封，而是兩封聲稱他們擁有梅特森的集團的勒索信。因為節日的季節馬上就要到了！拜託－－找到梅特森並把牠帶回來給我們！$B$B你可以從這些勒索信上找尋線索，並且把這個麋鹿粉末灑在牠的身上－－這會讓牠擺脫任何拘束他的東西！$B$B拜託了，事不宜遲！', '找到馴鹿梅特森。在你手上的筆記中查尋有關梅特森下落的線索。$B$B當你找到它之後，往它身上灑一些糜鹿粉末，這樣就可以讓它擺脫任何束縛。$B$B解救梅特森之後，把糜鹿粉末還給奧格瑪的凱瑪德·考伯賓奇。', '', '去找奧格瑪的凱瑪德·考伯賓奇。', '尋找麋鹿梅特森並且解救牠', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8762, 'zhTW', '麋鹿梅特森', '出大事了！麋鹿梅特森被綁架了！$B$B梅特森是冬天爺爺的八頭麋鹿之一－－也是燻木牧場的財產。我們已經收到不只一封，而是兩封聲稱他們擁有梅特森的集團勒索信。因為節日即將來臨！拜託－－找到梅特森並把牠帶回來給我們！$B$B你可以從這些勒索信上找尋線索，並且把這個麋鹿粉末灑在牠的身上－－這會讓牠擺脫任何拘束他的東西！$B$B拜託了，事不宜遲！', '找到馴鹿梅特森。在你手上的筆記中查尋有關梅特森下落的線索。$B$B當你找到它之後，往它身上灑一些糜鹿粉末，這樣就可以讓它擺脫任何束縛。$B$B解救梅特森之後，把糜鹿粉末還給鐵爐堡的烏爾莫特。', '', '去找鐵爐堡的烏爾莫特。', '尋找麋鹿梅特森並且解救牠', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8767 AND `locale` = 'zhTW';
