INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9207, 'zhTW', '光底礦物樣本', '我從太陽聖所被派來這裡收集一些光底礦物樣本，但是豺狼人已經橫行於這個地方了!如果我不快點將那些樣本交給博學者，我就要人頭落地了。或許你可以幫我，$c?$B$B你可以在礦物節點找到樣本，而豺狼人身上也有攜帶它們。等你收集到足夠的數量請將它們交給太陽聖所的博學者奎壘司提斯。就在東邊，過了死亡之痕，日傷山峰的南邊。', '收集6個光底礦物帶到鬼魂之地的太陽聖所交給博學者奎壘司提斯。', '', '去找幽魂之地的博學者奎壘司提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9211, 'zhTW', '冰霜守護者', '啊，冰霜守護者 。冰霜守護者是一層薄薄的魔法屏障，只要附魔在護具上就可以產生額外的冰霜防護效果，在與冰霜系的怪物纏鬥時額外的好用。$B$B不過只要是我 ，施怒者麥特斯，所製造的東西，它都有它應有的價格而這個價格可是無法討價還價的。有興趣嗎?', '東瘟疫之地聖光之願禮拜堂的『施怒者』麥特斯需要10個十字軍徽記和30金。', '', '去東瘟疫之地找聖光之願禮拜堂的『施怒者』麥特斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9212, 'zhTW', '逃出地下墓穴', '這些食人妖襲擊我還把我關在這籠子裡。我想他們打算犧牲我!救我出去!$B$B籠子上的鎖看起來不是很複雜……只是我從裡面沒辦法打開。如果你讓我離開這裡並護送我回到遠行者營地，我相信希里歐斯隊長一定會獎勵你，而且我也一定會感激你!', '護送遊俠莉娜薩回到鬼魂之地的遠行者營地找希里歐斯隊長。', '護送遊俠莉拉薩返回遠行者禁地', '去找幽魂之地的希里歐斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9213, 'zhTW', '暗影守護者', '這真是天才的傑作阿!就像冰霜守衛者一樣，暗影守衛者可以附魔在護具上產生額外的暗影防護效果。但別高興的太早，暗影守護者也跟冰霜守護者一樣需要一筆不小的收費。$B$B<麥特斯貪婪的伸出手>$B$B有興趣嗎?', '東瘟疫之地聖光之願禮拜堂的『施怒者』麥特斯需要10個十字軍徽記和30金。', '', '去東瘟疫之地找聖光之願禮拜堂的『施怒者』麥特斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9214, 'zhTW', '影松食人妖的軍備', '$C，我要你盡可能的殺死影松食人妖，越多越好。我們需要大幅削弱他們的實力，如此才能將我們的目標轉移對付死亡之域。既然你要去對付他們，乾脆幫我取回他們的武器。最好不要浪費這些武器，我們還可以拿來對抗天譴軍團。$B$B猛力地攻擊他們的營地吧，就在東邊的札布泰拉和南邊的札布諾瓦。', '收集3個獵頭者之斧、3個暗影施法者之錘、3個馭貓者之爪和3個妖術師之棍，並且回到鬼魂之地的遠行者營地交給希里歐斯隊長。', '', '去找幽魂之地的希里歐斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9215, 'zhTW', '把卡爾喀旭的頭顱帶來!', '懸賞:把影松食人妖的頭目，『邪惡者』卡爾喀旭的頭顱帶給希里歐斯隊長。不准發問。據說卡爾喀旭住在札布諾瓦南邊。$B$B獎勵:有，但不預付!', '將『邪惡者』卡爾喀旭的頭顱帶到鬼魂之地交給遠行者營地的希里歐斯隊長。', '', '去找幽魂之地的希里歐斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9216, 'zhTW', '腐爛之心', '我聽說阿曼尼食人妖以吃掉敵人的心臟來竊取他們的力量。他們一定對某種事物很熟悉，$N。經過適當的處理，無生命體的心臟能夠製造出強效的菁華。$B$B獵殺在死亡之痕流連的殭屍並將他們的心臟帶來給我。我會讓你見識一下這類能夠運用在身體上的強化以對抗不死生物。', '把10顆腐爛之心交給安寧地的博學者艾米諾。', '', '去找幽魂之地的博學者艾米諾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9217, 'zhTW', '更多的腐爛之心', '', '', '', '去找幽魂之地的博學者艾米諾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9218, 'zhTW', '脊骨之塵', '復活的骷髏體內流著的黑暗力量主要會累積在他們的脊椎裡。我發現了一個方法可以將這股能量注入藥水裡，增強我們的魔法能力對抗不死族。$B$B幫我帶來一些脊骨之塵我就會樂意提供你一個樣本。你會在西邊的死亡之痕找到一堆遊走的骷髏。', '把10份脊骨之塵交給安寧地的博學者艾米諾。', '', '去找幽魂之地的博學者艾米諾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9219, 'zhTW', '更多脊骨之塵', '', '', '', '去找幽魂之地的博學者艾米諾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9220, 'zhTW', '死亡之域戰爭', '如果你想要幫忙的話，此時此地就是最佳良機。$B$B重建太陽聖所，我們早已在敵方權力中心:死亡之域，高舉反抗的消息。$B$B去與這群居住在這個邪惡天譴軍堡壘的不死生物們對戰。', '在死亡之域殺掉5名死亡之域通靈師，6名奈幽碧斯百夫長和6名哀嚎者，並回到鬼魂之地向太陽聖所的博學者艾度尼斯回報。', '', '去找幽魂之地的博學者艾度尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9223, 'zhTW', '精良級軍備之戰-銀色黎明聲望尊敬', '你好，朋友。你想要用點黎明徽記或是十字軍徽記來換取一些強大的物品嗎?$B$B不過我必須要警告你，雖然你是的銀色黎明所尊敬的朋友，但是想要購買這些物品還需要一些額外的收費，我建議你去提升更高的聲望後再來考慮這些物品吧。', '付出20個黎明徽記和20個十字軍徽記就能換取銀色黎明藏寶庫裡的一樣強大的物品。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9224, 'zhTW', '史詩級軍備之戰-銀色黎明聲望尊敬', '你好，朋友。你想要用點黎明徽記或是十字軍徽記來換取一些史詩級的物品嗎?$B$B不過我必須要警告你，雖然你是銀色黎明所尊敬的朋友，但是想要購買這些物品可是還須付出一筆非常龐大的額外費用，我建議你去提升更高的聲望後再來考慮這些物品吧。', '付出75個黎明徽記和75個十字軍徽記就能換取銀色黎明藏寶庫裡的一樣史詩級的物品。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9252, 'zhTW', '保衛晴風村', '我們已感覺到天譴軍團明顯提高攻擊行動，$N。我們快抵抗不住了，而且銀月城好像也沒有增援的跡象。協助我們削弱死亡之痕不死生物的數目，一起來保護這村莊。', '殺掉4個腐肢掠奪者、4個黑暗怨靈。然後回到遊俠塞瑞覆命，他在永歌森林的晴風村。', '', '去找永歌森林的遊俠塞瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9253, 'zhTW', '符文守護者德蘭', '天譴軍團有增無減的攻擊行動讓我相信，鬼魂之地邊界那裡的某個防禦符文石一定發生故障。我們用這些古老的石頭來保護我們不受不死族傷害。它們大部分都在太陽之井的攻擊後被摧毀或不見了。朝著鬼魂之地的方向沿著路往南走，往西邊看就會發現一條小徑。你會在附近的一個符文石看到符文守護者德蘭;他會知道發生了什麼問題。', '與永歌森林的符文守護者德蘭談話，他在鬼魂之地邊界附近。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9254, 'zhTW', '遊蕩者學徒', '感謝你的幫忙，$N。當我整頓好這裡的事情時，我想請你幫個忙。我之前的一個學徒捲入了危險的研究調查。她前往了東部聖所，就在死亡之痕中間。我擔心她的安危。你能不能幫我把她找回來，並說服她找回自己。', '與東部聖所的學徒莫維達談話，位置在永歌森林。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9255, 'zhTW', '研究報告', '雖然我的研究結果令人沮喪，這份資料還是有可取之處。我要在這份報告被正視之前，先讓博學者檢視一下我的成果。拜託你，把這些報告拿給西邊晴風村的博學者蘭德拉·晨行者。', '把研究報告帶到永歌森林交給晴風村的博學者蘭德拉·晨行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9256, 'zhTW', '晴風村', '我有另一個任務要給你，$N。遊俠迪哥里恩被派去晴風村找尋更多有關鄙惡者攻擊附近船廠的線索。他正尋求增援，可是我們還不能幫忙。去找到他，然後盡你全力去幫助他吧。沿著內精靈之門這條路一直往南走就能找到晴風村了。祝你好運，$N。', '到永歌森林與晴風村的遊俠迪哥里恩談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9258, 'zhTW', '烈焰邊境', '天譴軍團的污土持續進攻新的區域。為此，我們在鬼魂之地邊界建造了防護符石，以防止污染繼續蔓延。某次天譴軍團的攻擊行動中，他們摧毀了西邊的符石，迫使我們必須燒掉四周的土地來遏止污穢擴散。我的姐妹，拉瑞安娜·河風，看管著烈焰邊境。去找她，她可能有工作要給你。', '去烈焰邊境附近找拉瑞安娜·河風，位置就在永歌森林的西南方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9274, 'zhTW', '溺死者的靈魂', '就我有印象以來北邊的湖就充斥著我祖先的靈魂，$N。那些可憐的鬼魂都是在一場悲慘的意外中溺死在湖底的受害者。$B$B事情的來龍去脈我已忘得差不多了，但是他們揮之不去的哭喊聲一直提醒著我他們的詛咒。$B$B如果你能勝任這個任務，我要你去湖那裡結束他們的苦難，$N。我和他們都會感謝你的……我保證。', '鬼魂之地，遠行者營地的遊俠克羅南，要你去附近的湖裡殺死8個復仇的亡魂和8個貪婪的亡魂。', '', '去找幽魂之地的遊俠克羅南。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9275, 'zhTW', '一點小佐料', '讓我先自我介紹。我是皇家藥劑師學會的藥劑師范衲斯特。我是來幫助遠行者解決他們的食人妖麻煩。我想我有辦法解決這個問題。$B$B我手上有一堆強而有力的毒藥。食人妖也是活的生物，他們也要吃。如果我們把他們的食物加入我的毒藥……那麼，我相信結果會非常有趣。$B$B你願意幫助我們擺脫南邊札布諾瓦的影松食人妖嗎?', '到札布諾瓦營地在食人妖的食物裡下毒，再回到鬼魂之地的遠行者營地，將剩下的藥劑師之毒交給藥劑師范衲斯特。', '', '去找幽魂之地的藥劑師范衲斯特。', '對鮮肉架下毒', '對燻肉架子下毒', '對鮮魚架子下毒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9276, 'zhTW', '攻擊札布泰拉', '我很高興你來這裡幫忙，$c。我們的資源已經減少許多，所以你的幫忙對我們而言是相當珍貴的。隊長已派我追查當地影松食人妖營地的騷擾事件。我們的策略就是讓他們失去平衡直到有天能一舉殲滅他們。$B$B到那時候，我們就需要所有能找到的志願者，這樣那些影松食人妖的數量才不會增加。$B$B你覺得你能前往東方的札布泰拉給他們點顏色瞧瞧嗎?', '殺死8名影松暗影施法者和8名影松獵頭者，再回到鬼魂之地找遠行者營地的遠行者索安娜。', '', '去找幽魂之地的遠行者索安娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9277, 'zhTW', '攻擊札布諾瓦', '是來點比較有挑戰性任務的時候了。南邊的札布諾瓦是較強大的影松食人妖的家。為了持續將食人妖的數量削減至最小，我要派你去那裡攻擊他們，不論你用什麼手段。$B$B你覺得這方法如何，$N?準備好對付更多的食人妖了嗎?', '殺死10名影松馭貓者和10名影松妖術師，再回到鬼魂之地找遠行者營地的遠行者索安娜。', '', '去找幽魂之地的遠行者索安娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9281, 'zhTW', '清除道路', '博學者坎德立斯派我來這清除任何有敵意的野生生物。等這個區域安全了，博學者打算把這裡變成對抗天譴軍團的前哨。$B$B如果要我說當學生時學到的一件事就是負起責任 - 尤其是悠關性命的事!$B$B如果你有興趣，我要你去殺死西邊和南邊的巨型細網蜘蛛和鬼爪劫毀者，我會給你豐厚的報酬。', '鬼魂之地安狄里安莊園的學徒瓦瑞爾要你去殺10隻巨型細網蜘蛛和10個鬼爪劫毀者。', '', '去找幽魂之地的學徒瓦瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9282, 'zhTW', '遠行者營地', '博學者和遠行者永遠都不會有意見一致的時候，$N。不過，說到達克汗，我們全都同意一定要想出個辦法來擊敗他和他的軍團。東北邊的遠行者營地有個叫薇娜的遊俠，她對我們的敵人有了一些重要的發現。和她談談看是否你能幫得上忙。', '太陽聖所的博學者坎德立斯要你去鬼魂之地和遠行者營地的遊俠薇娜談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9309, 'zhTW', '調查暗影山脊', '我們手上有幾個不同來源的證據指出暗影山脊有不尋常的活動正在進行中。這很麻煩;我們以為先前進行的偵察任務已經做得很徹底了。有一個斥候尚未跟我回報。$C，我要你前往西南方到銀線湖的另一邊，找到托蘭，看他為什麼被耽擱了。', '到安曼谷的暗影山脊找到托蘭並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9312, 'zhTW', '發射器', '$N，你去外面調查暗影山脊時，薩那已經在這裡展開關於全像攝影發射器的研究。你應該會想和她談談。', '和安曼谷失事地點的技師·薩那談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9313, 'zhTW', '前往藍色守望', '謝天謝地，$N，你一定要立刻到藍色守望和戴伏恩談談!有一條路通往這小島的西邊。沿著它走並穿過水晶河川到達島的較大區域。再沿著路走你就會來到藍色守望。看看你能否說服他們給我們一些補給和援助。我們會盡量跟上你。謝謝你，沒有你我們辦不到這些的!', '到藍謎島和藍色守望的技師戴伏恩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9314, 'zhTW', '藍色守望的字條', '$C!有一群突變的野獸撲向我，害我的腿受了傷。我們收到薩那的命令後就從藍色守望出發派去進行偵察任務。拜託你，代替我去和照顧者查倫談談好嗎?她需要知道會有多少人前去藍色守望。越過水晶河川再沿著路走，你就可以到達藍色守望。記得請她給你一個地方休息。', '去藍謎島和藍色守望的照顧者查倫談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9315, 'zhTW', '安羅科舒頓', '靠近一點，我快……死了。$B$B我被派來這裡……殺這些奈幽蟲族，但是范德隆不……知道他們有個領導者。$B$B<垂死的血精靈咳出了大量的鮮血。>$B$B你一定要找到……並殺死安羅科舒頓。找人幫忙。她在日冠村……附近遊蕩。', '殺死安羅科舒頓再回到鬼魂之地的安寧地找秘法師范德隆。', '', '去找幽魂之地的秘法師范德隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9319, 'zhTW', '暗處之光', '我們不是唯一慶祝這個節日的人，$n。所有的生物，所有的文化，都被這火焰所感動。就連在最黑暗的地方，也點著這些火焰。$B$B如果你想親自看看它們就到深處去。找到在斯坦索姆，通靈學院，厄運之槌，和黑石塔大廳燃燒的營火;我會等著你回來。', '找到並觸碰位在黑石塔，厄運之槌，通靈學院，和斯坦索姆的營火。', '', '去找陶土議會長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9322, 'zhTW', '卡林多的藍色火焰', '艾澤拉斯到處都在慶祝仲夏火焰節慶，而卡林多這塊多變的土地也不例外。你看起來很適合旅行 - 或許已經安排好一個旅程了。$B$B如果你沒有看過世界各處猛烈的藍色火焰就不算真的體驗了仲夏。主持者們在冷颼颼的西冬泉谷，艾薩拉東北邊，希利蘇斯荒地的勇士之墓附近，和通往繁茂安戈洛的入口都點燃了火焰。等你的旅行完成了再回來。', '拜訪艾薩拉，希利蘇斯，安戈洛環形山，和冬泉谷的仲夏營地，再回去找節慶營火管理者。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9323, 'zhTW', '東部王國的藍色火焰', '我們的火焰慶典遍布整個大陸，$c。每一個地方都感受到這個節日的熱情，最旺盛的火焰燃燒著明亮的藍色。去找它們吧。你會在黑石塔北邊就發現一個。其他有的在東瘟疫之地一個老舊的城鎮附近，有的在沿著路到多山的辛特蘭懸崖邊，還有詛咒之地通往黑暗之門的路上。$B$B完成之後再回來這裡。', '拜訪詛咒之地，東瘟疫之地，辛特蘭和灼熱峽谷的火焰節慶營地。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9324, 'zhTW', '偷取奧格瑪之焰', '這個從奧格瑪中心偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但博學大師或許知道更多……', '將奧格瑪之焰交給節慶博學大師。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9326, 'zhTW', '偷取幽暗城之焰', '這個從幽暗城廢墟偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但博學大師或許知道更多……', '將幽暗城之焰交給節慶博學大師。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9327, 'zhTW', '被遺忘者', '我知道這聽起來很奇怪，但被遺忘者竟來這裡幫忙。你應該和他們的領導者高階執行官瑪弗倫談談。他就在城西邊的塔裡。還有，$c，等你和他談完後再來找我;我有些緊急的事要立刻處理!', '到鬼魂之地的安寧地和高階執行官瑪弗倫談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9328, 'zhTW', '辛多雷的英雄', '這是我們種族歷史中新的一章，$N。我們將會奪回我們的領土，並且鞏固和希瓦娜斯及其盟友的關係。$B$B把背叛者的頭顱帶給銀月城的地區統治者，洛索瑪·塞隆。他會非常渴望聽到這個消息。', '把達克汗的頭顱帶給銀月城的洛索瑪·塞隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9329, 'zhTW', '被遺忘者', '我知道這聽起來很奇怪，但被遺忘者竟來這裡幫忙。你應該和他們的領導者高階執行官瑪弗倫談談。他就在城西邊的塔裡。還有，$c，等你和他談完後再來找我;我有些緊急的事要立刻處理!', '到鬼魂之地的安寧地和高階執行官瑪弗倫談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9330, 'zhTW', '偷取暴風城之火', '這個從暴風城中心偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但故事使者或許知道更多……', '將暴風城之火帶給節慶故事使者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9331 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9331, 'zhTW', '偷取鐵爐堡之火', '這個從鐵爐堡中心偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但故事使者或許知道更多……', '將鐵爐堡之火帶給節慶故事使者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9332, 'zhTW', '偷取達納蘇斯之火', '這個從泰達希爾陸地偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但故事使者或許知道更多……', '將達納蘇斯之火帶給節慶故事使者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9339, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9352, 'zhTW', '達納蘇斯的入侵', '除了鄙惡者不斷帶來的威脅外，我還要處理各種謊報目睹夜精靈的狀況。$B$B雖然大部份的報導都是沒有根據的，但是，最近有個事件需要進一步的調查。我們的主要能量來源之一，西部聖所，而且關於達納蘇斯破壞的傳言一直很猖獗。$B$B前往那裡對付任何可疑的人。再向看守聖所的牧地看守者維蘭妮雅回報。', '前往西部聖所，就在獵鷹之翼廣場的西南邊，擊敗那裡所有的入侵者。將你的發現向牧地看守者維蘭妮雅報告。', '', '去找永歌森林的牧地看守者維蘭妮雅。', '擊敗入侵者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9357 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9357, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9358, 'zhTW', '遊俠塞瑞', '別以為這個村子的安全是與生俱來的。我們被東邊的天譴軍團和西邊的鄙惡者包圍。遊俠塞瑞保護我們的邊界，不讓死亡之痕湧入的不死族侵擾我們。沿著出城後往東邊的路走，看看你能否幫她一把。', '向永歌森林晴風村外的遊俠塞瑞報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9359, 'zhTW', '遠行者居所', '你對壓制鄙惡者的幫助是無價的。遠行者在對抗阿曼尼食人妖時如果能有像你這樣的人一定會很有用。去東北方的遠行者營地和晨奔中尉談談，看看他需要怎樣的幫助。', '向永歌森林遠行者營地的晨奔中尉報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9360, 'zhTW', '阿曼尼入侵', '雖然你不了解這些作戰計劃的語言，你還是能清楚地辨別出一個標記著遠行者居所和晴風村的地圖。$B$B你最好讓遠行者居所的晨奔中尉知道這點。', '將阿曼尼攻擊計畫送給遠行者居所的晨奔中尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9363, 'zhTW', '警告晴風村', '前往晴風村警告遊俠迪哥里恩關於阿曼尼的計劃。即使祖瑪羅什已死，晴風村還是要準備好對抗食人妖的攻擊。告訴迪哥里恩我們會盡快派遣援軍給他。', '前往永歌森林的晴風村和遊俠迪哥里恩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9365, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9367, 'zhTW', '火焰節慶', '仲夏又來了!$B$B每一年，按照傳統，雀屏中選的營火管理者要負責看管我們城市裡的營火。當整個艾澤拉斯都是燃燒的火焰時，我們的火苗一定要是最熱烈、最明亮的，才能恰當地表現出對季節的尊敬。$B$B事實上，我有個任務要給你，如果你不介意的話。我還沒聽說所有主城裡的火焰都燃燒的恰如其分。前往那裡讓火焰為你取取暖 -- 確定它們是燙的!', '觸摸暴風城，鐵爐堡和達納蘇斯裡的營火，再和任何一個節慶傳說大師談談。', '', '去找節慶傳說大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9368, 'zhTW', '火焰節慶', '仲夏又來了!$B$B每一年，按照傳統，雀屏中選的營火管理者要負責看管我們城市裡的營火。當整個艾澤拉斯都是燃燒的火焰時，我們的火苗一定要是最熱烈、最明亮的，才能恰當地表現出對季節的尊敬。$B$B事實上，我有個任務要給你，如果你不介意的話。我還沒聽說所有主城裡的火焰都燃燒的恰如其分。前往那裡讓火焰為你取取暖 -- 確定它們是燙的!', '觸摸奧格瑪，雷霆崖和幽暗城裡的營火，再和任何一個節慶故事使者談談。', '', '去找節慶故事使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9371, 'zhTW', '植物學家泰瑞茲', '$N，植物學家泰瑞茲需要你的幫助。你可以在西邊找到她和她的學徒，就在船外面。', '和安曼谷失事地點的植物學家泰瑞茲談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9378, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9386, 'zhTW', '[A Light in Dark Places]', '[An eager one, aren\'t you? If you\'re willing to enter the depths once more, I\'ll gladly reward you.$B$BSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, $n.]', '[Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper.]', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9388, 'zhTW', '卡林多的閃爍火焰', '世界各地都有許多的火焰在燃燒著，$n。最難處理的火焰就是那些發著綠光的;沒有管理的話它們不會長久燃燒。為我們的火焰管理者確認那些翠綠色的火焰仍在卡林多燃燒著，聽到了嗎?$B$B你可以在貧瘠之地的棘齒城，黑海岸的主宰之劍附近找到它們，還有從銀翼哨站旁的橋邊進入梣谷的森林裡，和沿著石爪山脈的幹道走到通往狂風峭壁的路上都能找到。', '探勘梣谷，貧瘠之地，黑海岸，和石爪山脈的營火，再和節慶火焰管理者談談。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9389, 'zhTW', '東部王國的閃爍火焰', '仲夏火焰節慶傳統上會在整個土地上點燃無數的火焰。有些人說綠色的火焰是最美的，因為它們是最難維持的而且又有獨特的色澤。為我們的火焰管理者確認它們仍在東部王國燃燒著。它們座落在濕地的丹莫德附近，銀松森林內的焚木村那裡也有，眺望濕地燈塔的峭壁上，和希爾斯布萊德丘陵廢棄的哨塔旁。', '探勘希爾斯布萊德丘陵，銀松森林，西部荒野，和濕地的營火，再和節慶火焰管理者談談。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9394, 'zhTW', '威利坦在哪裡?', '暗木的地面守衛者不見了!一定是博學者和大家離開時忘了叫他一起走了。我知道他還在營地附近，但我不敢自己去找他，有太多魔法生物在那裡閒晃了。你能幫我去找他嗎，$c，確定他還安然無恙?', '到永歌森林的暗木營地尋找地面守衛者威利坦。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9395, 'zhTW', '薩瑟里的避風港', '我發誓如果再讓我收到跟薩瑟里領主的舞會物資相關的請求我就要用火球殺了某人!我看起來像舞會策劃人嗎?!再偷偷告訴你，那個白痴和他的食客們根本就不相信我們這裡正遭受攻擊!我們有些人正忙著，呃，我不知道，防守奎爾薩拉斯剩下的土地!$C，可以請你前往薩瑟里的避風港看看能不能讓他閉上嘴嗎?那地方就在往西邊的路上。', '到永歌森林和薩瑟里的避風港的薩瑟里領主談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9409, 'zhTW', '緊急送件!', '既然你已收集了所有我們需要的東西來補充我們的治療水晶，我要你送些瓶子給我們的牧師，薩度恩。他就在船中央的房間裡照料我們的傷者。', '將一捆瓶子送到安曼谷給失事地點的薩度恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9443, 'zhTW', '所謂的光明使者的印記', '我曾是烏瑟·光明使者的一個學生，他是白銀之手騎士團的創立者。我看過他如何粗暴地對待阿薩斯王子的訓練。那導致了我的家園，奎爾薩拉斯的毀滅，我把一切都歸因於烏瑟和他的無能!而現在他竟然還有自己光榮的墓碑 - 真是美好。$B$B我的資訊告訴我那些血色笨蛋把他的一個\'神聖\'的聖物放在他們壁爐谷附近的守衛哨塔頂端。$B$B去西瘟疫之地把它拿回來給我。', '取得光明使者記號再帶回西瘟疫之地的亡靈壁壘給瑪拉·曦刃。', '', '去找提裏斯法林地的瑪拉·曦刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9452, 'zhTW', '紅鯛魚 - 非常美味!', '我發現這些水裡充滿了活躍的紅鯛魚，一種非常美味的魚。只要有個捕魚網，我就能抓到足夠的魚來餵飽許多的德萊尼!不幸的是，我最近在河裡捕魚時被一種叫做魚人的生物攻擊，受了點傷無法進行我的工作。我需要幫忙!$B$B到東邊的水晶河川捕捉這種魚，記得在成群的紅鯛魚旁使用這個捕魚網。$B$B你說怎麼樣?完成後記得把魚網帶回來。', '使用德萊尼捕魚網捕捉10隻紅鯛魚。完成任務後將魚和網子帶回藍謎島給狄克泰納。', '', '去找蔚藍海岸島的狄克泰納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9453, 'zhTW', '找到艾克緹昂!', '你完成了一件很棒的工作，$N。我們的人民會很感激這次的餽贈。說到這，你可否將這些紅鯛魚送給藍色守望的艾克緹昂呢?$B$B他應該不難找因為他正在等著這批貨。', '送紅鯛魚木箱給藍色守望的艾克緹昂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9454, 'zhTW', '牧月大獵殺', '你將讓自己成名了，$N。要不要試試打獵呢?$B$B從前在德拉諾，我們最厲害的獵人能獵捕一種稱為塔巴克的野獸，類似這裡的牧月成鹿。$B$B如果你認為自己夠德萊尼，就回去野外殺死夠多的成鹿，把你的背包裝滿肉塊。$B$B你可以在藍色守望南邊找到在吃草的他們。小心他們的角!', '帶6塊牧月成鹿嫩腰肉給藍色守望的艾克緹昂。', '', '去找蔚藍海岸島的艾克緹昂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9455, 'zhTW', '奇怪的發現', '你在小型夜間潛伏者身上發現的水晶看來是來自艾克索達的。這或許能解釋這區域某些動物不尋常的外表和行為。$B$B帶著水晶回到藍色守望。主教一定會想知道這個發現的。', '將微光水晶送給藍色守望的主教米奈奧斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9456, 'zhTW', '下一步……清除夜間潛伏者', '我不會為你的發現找任何的理由。這明顯的是我們的錯。我們獲報在東邊的河川裡有粉碎的水晶碎片但卻選擇忽視它的牽連。現在我們不是要坐著哭喊這座島上降臨的悲劇，就是要做點什麼來阻止它擴散。$B$B如果你有興趣的話，我要你回到野外殺死越多被感染的小型夜間潛伏者越好。', '藍色守望的主教米奈奧斯要你殺死8隻被感染的小型夜間潛伏者。', '', '去找蔚藍海岸島的主教米奈奧斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9463, 'zhTW', '醫療用途', '我發現島上亂竄的鞭笞者藤蔓裡有一種復原的藥效特性。透過適宜的處理，藤蔓可以做成一種強大的治療藥膏。不幸的是，有那麼多受傷的德萊尼路過藍色守望，我們總是物資不足。$B$B我們嬌弱的客人昨天在水晶河川旁被發現，受了傷又意識不清。如果你可以幫我把藤蔓帶來，我們就能救她。$B$B你可以在藍色守望的南方和東方找到根鬚捕獸者。', '藍色守望的隱士·法禔瑪要你幫她帶來8個根鬚捕獸者藤蔓。', '', '去找蔚藍海岸島的隱士‧法禔瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9473 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9473, 'zhTW', '替代的選擇', '這女孩為了讓藥膏發揮效用已做了太多努力。或許有別的辦法……$B$B藍謎島森林有許多秘密，其中一個就是一種叫藍色金魚藻的稀有植物，有些人說它是萬靈丹 - 治療所有疾病的解藥。$B$B你可以從它和藍謎島其他植物明顯的對比以及它需要藍色松樹為基底來生長的特性辨視它。動作快!$B$B還有$N，小心那裡的盤根痛擊者因為它們以食用金魚藻維生。', '藍色守望的爹達歐要你幫他帶來5個藍色金魚藻球莖。', '', '去找蔚藍海岸島的狄戴爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9505, 'zhTW', '費倫的預言', '預言提到了今天:在這座島上，在這個新世界裡，我們的盟友會找到我們。「我們會被測試。他們會要求我們為我們的父親贖罪……」那時候，我並不了解他字句背後的意思，但看到這個生物和她對我們的反應，現在一切都逐漸明朗了。我們族人的腐敗被認為是對等的。前往南方。我們是在那裡找到這個生物的。找到它的族人並告訴他們關於我們族人的事。', '爹達歐要你前往南方找到受傷的生物提到的人們。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9506, 'zhTW', '一個小開始', '我是聯盟海軍指揮的艦隊司令·奧迪席斯。我們的船被迫停靠在你們島旁是因為碰到了某種族對我們的侵擾。要開口談這件事真尷尬，但哥布林不知怎地躲藏在我的兩艘船上偷渡來此。$B$B昨天夜裡，當大部分船員都在船艙裡睡覺時，我們就遭到突擊了!$B$B更奇怪的是，他們拿走了我們的航海工具就跳船了!$B$B他們消失在東邊的樹叢中。你可以去幫我們找回工具嗎?這對我們而言很重要。', '奧迪席斯平臺的艦隊司令·奧迪席斯要你取回被風險投資公司偷走的航海指南針和航海地圖。', '', '去找蔚藍海岸島的艦隊司令‧奧迪席斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9512, 'zhTW', '廚師的特大燴肉', '艦長是對的，你是個聰明的傢伙。也許你可以幫廚師的忙?$B$B要是我再讓船員吃雞肉，我一定會被送到禁閉室的。$B$B我注意到沿著海岸線一路都有爬行者 - 多著呢!幫我帶點爬行者的肉來，我會永遠感激不盡的。$B$B幫改過自新的海賊一個忙吧?', '奧迪席斯平臺的『小廚』麥克威醬要你幫他帶來6塊滑膩的爬行者肉。', '', '去找蔚藍海岸島的『小廚』麥克威醬。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9513, 'zhTW', '奪回廢墟', '雖然有些人認為我們現在的處境是不幸的事，但我感覺我們來到這裡是有原因的。命運無形的手把我們推向這個方向。原因會隨著時間而明朗。$B$B西邊是古老的夜精靈城市，現在是個佈滿納迦的廢墟。如果納迦汙染了我的先祖之地，而我只是閒坐在一旁，那就是我的疏失了。 $B$B你已證明你是個能幹的$c了。讓我的族人感到光榮，清除掉廢墟裡他們不歡迎的居民。', '藍謎島，奧迪席斯平臺的女牧師凱玲·伊丹奈爾要你殺死5個怒鱗侍從、5個怒鱗納迦和5個怒鱗海妖。', '', '去找蔚藍海岸島的女牧師凱玲‧伊丹奈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9514, 'zhTW', '符文雕飾石板', '你辨別不出這石板上的任何符號。或許女祭司可以解讀這些神秘的符文。', '把符文雕飾石板帶到藍謎島給奧迪席斯平臺的女牧師凱玲·伊丹奈爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9515, 'zhTW', '督軍司瑞史提斯', '納迦入侵會是一場災難，$N。我見過納迦的本事，我不想見到這樣的大災難降臨在任何生物身上。如果要我猜，這個督軍司瑞史提斯會躲在洞穴裡 - 或許是在西邊的海岸上。$B$B找到督軍司瑞史提斯並結束他的統治。', '藍謎島，奧迪席斯平臺的女牧師凱玲·伊丹奈爾要你殺了督軍司瑞史提斯。', '', '去找蔚藍海岸島的女牧師凱玲‧伊丹奈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9521, 'zhTW', '北方前線的報告', '對抗戰歌伐木營地的戰役不單是從林歌神殿展開，$N。西南邊的銀翼樹林還有更多的銀翼哨兵，靠近貧瘠之地的邊界。在樹林那，哨兵輕歌指揮我們抵抗那些想摧毀我們土地的人。$B$B我現在把最新的報告送過去給哨兵輕歌已經有點太晚了，而且也猶豫是否要獨自離開林歌神殿。如果你的旅程會經過銀翼樹林附近，你願意幫我遞送報告嗎?', '將哨兵露西歐·星語的報告送給銀翼樹林的哨兵輕歌。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9523, 'zhTW', '小心輕放', '女祭司告訴我西邊的廢墟是夜精靈文明唯一遺留下來的產物。那讓我想起我爸爸總是這樣說夜精靈廢墟，「兒子，當你看見夜精靈廢墟時，夜精靈的聖物肯定就在附近。」$B$B如果我不僱用我第一個看到的人去挖出夜精靈聖物給我，那我還算是什麼矮人?現在快去吧!', '藍謎島，奧迪席斯平臺的考古學家阿達曼·鐵心要你幫他帶來8個古代聖物。', '', '去找蔚藍海岸島的考古學家阿達曼‧鐵心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9527, 'zhTW', '剩下的一切', '我們和島上的野獸和平共處了許多年。你可以想像當他們襲取海濱攻擊我們時我有多驚訝。$B$B我拼了命的奮戰但還是輕易地被擊敗。當我因為受到劇烈的一擊而昏了過去時，我祈禱我的家人不會遭殃。$B$B當我醒來時，一切是如此平靜。沙子被血浸濕 - 那是他們的血。他們全都被毀滅了。$B$B我不想報仇，$N。我只想要回我家人的遺體好好埋葬。', '藍謎島的科倫要你找到科倫家族遺骨。', '', '去找蔚藍海岸島的科倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9528, 'zhTW', '求救', '我們家幾個禮拜前遭到島上的魚人和梟獸攻擊。我設法逃了出來但我想我的父母已慘遭毒手了。我不知道現在該怎麼辦，但我一定要試著回到我的家 - 或是說它還沒被摧毀的部份……你會幫我通過森林嗎?', '護送麥格文穿過島嶼回到她的家。', '瑪格溫已護送至安全處', '去找蔚藍海岸島的科倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9530, 'zhTW', '我要一棵樹', '我已經懷疑這件事好一陣子了，但這證明了它是真的。$B$B我們之中有個叛徒。$B$B哥布林留下的計畫裡證明了陰謀的存在。既然我不知道他是誰，我就要你幫助找到叛徒。我的手下沒有一個可信。$B$B如果這要起作用，我就需要一顆挖空的樹和樹葉。搜尋我們北邊樵木工附近的樹。你要自己找到樹葉。看看森林裡有沒有。', '藍謎島，奧迪席斯平臺的艦隊司令·奧迪席斯要你幫他帶回中空樹和5堆樹葉。', '', '去找蔚藍海岸島的艦隊司令‧奧迪席斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9531 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9531, 'zhTW', '樹的偽裝', '根據計畫，背叛者和哥布林的領導者，吉索，將要在西部半島上的一個海灣相見。我要你出現在那場會面，$N。$B$B記得那些樹和葉子嗎?你要穿戴上它們!那是完美的偽裝。$B$B去海灣那裡尋找一面納迦旗幟。如果旗子在那，就表示安排了一場會面。當你看到旗幟後就使用偽裝工具，然後等待。最後背叛者會現身。讓密會結束再回來告訴我那背叛者的是誰。帶著那個壞蛋的身份回來找我。', '藍謎島，奧迪席斯平臺的艦隊司令·奧迪席斯要你去觀察吉索和背叛者的會議。$B$B等你知道了背叛者的身份就回去找他。', '', '去找蔚藍海岸島的艦隊司令‧奧迪席斯。', '背叛者揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9533 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9533, 'zhTW', '伸出援手', '有卡多雷的支持和合作，我的族人在梣谷東邊了付出了重要的努力。在建築師尼莫斯和復仇者維達的監督下，他們正在復興一個老舊的夜精靈前哨。建築的工作不簡單，$N，因為他們面對的挑戰和敵人很多。 我知道建築師尼莫斯和他在林歌神殿的同伴會感激任何能獲得的幫忙，而他也請我派任何有興趣的<男人/女人>去他那裡。', '前往林歌神殿和建築師尼莫斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9537, 'zhTW', '別對地精仁慈', '一定要讓火花·歐爾滾知道什麼叫正義!$B$B我要你去海邊那找到這個騙人的地精。一旦你找到他，就要他抖出所有的事情!$B$B如果連一個聯盟的高階官員都有不忠的行為，誰知道還有多少其他人也墮落了?$B$B還有$N，必要時你可以使用武力……', '奧迪席斯平臺的艦隊司令·奧迪席斯要你從工程師火花·歐爾滾那裡取回背叛者的信件。', '', '去找蔚藍海岸島的艦隊司令‧奧迪席斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9538, 'zhTW', '學習語言', '我想我破解了它，$N!$B$B<奧蘭指向圖騰。>$B$B我們所需要知道的靜松熊怪語言都銘刻在他們的圖騰上了。只要知道他們文字符號的基本意義，我們就能研究圖騰並試著和熊怪溝通。$B$B我在羊皮紙上寫下了他們基本的文字符號。研究它並檢驗圖騰。它會引導你至下一個語言圖騰。$B$B等你學會他們的語言之後再回來和阿魯古談談!$r!', '閱讀奧蘭給你的靜松熊怪語言入門書並和藍色守望的阿契達的圖騰互動。', '已閱讀寧松熊怪語言入門', '去找蔚藍海岸島的阿契達的圖騰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9539, 'zhTW', '庫的圖騰', '你開始閱讀圖騰，僅能唸出一些奇怪的字和片語。慢慢地，文字開始在你腦袋裡形成。你認為圖騰告訴你要去附近東北邊的山丘上。', '使用提供給你的線索找到庫的圖騰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9540, 'zhTW', '堤克悌的圖騰', '你開始閱讀圖騰，較能發出字和片語的音。文字開始在你的腦袋裡形成。你認為圖騰告訴你要走到東邊的水晶河川對面。或許你的目的地就在河的另一邊。', '使用提供給你的線索找到堤克悌的圖騰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9541, 'zhTW', '優兒的圖騰', '這圖騰的象徵似乎翻譯的更快一些。這些圖形和畫像都交融成熟悉的字。你相當確定這圖騰要你去南方，河流之下。在河底有個東西。', '使用提供給你的線索找到優兒的圖騰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9542, 'zhTW', '瓦克的圖騰', '圖騰裡不再有你無法辨視的象徵了。優兒的圖騰讀起來就像在看你自己的語言一樣。印記辨識出另一個熊怪巢穴，就在西邊。你可以熟練地解讀圖騰上的語言知道你的目的地是鬚肢村。優兒會引導你，但如果你迷路了，你知道你可以走森林裡往西的古老精靈之路來到達你的目的地。', '使用提供給你的線索找到瓦克的圖騰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9544, 'zhTW', '阿契達的預言', '圖騰上的圖像是描述靜松熊怪及鬚肢熊怪兩族的戰爭。上面的蝕刻顯示鬚肢熊怪對靜松熊怪做了不合理的事。$B$B在這場混亂中，一則預言開始實現:將會出現一位英雄 - 非熊怪族群 -拯救了靜松熊怪。$B$B殺了鬚肢村裡的鬚肢熊怪，取得鑰匙，用這把鑰匙釋放被俘虜的靜松熊怪。完成後回到靜松要塞找阿魯古!', '釋放8個在鬚肢村裡發現的靜松俘虜。完成後回到藍色守望找靜松要塞的阿魯古。', '', '去找蔚藍海岸島的靜松要塞的阿魯古。', '釋放靜松俘虜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9548, 'zhTW', '被偷走的裝備', '噓!小聲一點別讓我被發現。$B$B如果魚人察覺我的存在，實驗就毀了!危機已經逼近到足以毀掉我的研究數據。$B$B我昨天在搜索糧食的時候，他們其中一個一定是晃的太近發現了我的營地。我回來的時候剛好看見兩個魚人拿走一個木箱裝滿了我大部分的裝備!它一定在他們附近的營地之一裡，但我不能冒險現身。你願意幫忙嗎?', '把克羅波的裝備帶回來給克羅波·維茲班，他藏在海邊的一個龜殼裡面。', '', '去找鮮血島的克羅波‧維茲班恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9549, 'zhTW', '黑沙的手工藝品', '我對黑沙魚人的觀察和描寫是相當輝煌的，$N，但它們只是開始。我打算帶著黑沙的早期製作技術產物回到鐵爐堡。$B$B問題是黑沙總是帶著這些物品在身上，我不能背著良心去殺他們。如果你願意幫我收集黑沙先知帶著的塑像，和黑沙戰士及巡岸者帶著的粗糙小刀，我不會問你是怎麼弄到它們的。', '帶3個粗糙的魚人塑像和6把粗糙的魚人小刀給克羅波·維茲班，他藏在海邊的一個龜殼裡面。', '', '去找鮮血島的克羅波‧維茲班恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9550 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9550, 'zhTW', '模糊的地圖?', '這個繪畫粗糙的地圖並未透露出任何關於繪圖者的線索，但看來是隻很不穩的手畫的。顫抖的線條和符號描繪出一個有著破損圓柱的小亭子，在一個部分淹沒在水中的哨塔附近。$B$B如果這地圖可信的話，這些廢墟似乎位在島的東邊海岸。你不知道你可以在那邊找到什麼，但這一定夠重要繪圖者才會記錄下來。', '找到地圖中描繪的亭子並尋找製圖者想記錄下來的東西。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9557, 'zhTW', '解讀這本書', '沒有辦法閱讀這本書的內容，你思考著誰能幫你從製圖師的潦草字跡中辨別出原著的字句。$B$B想起無數文化中隱士裴薩斯的手工藝品收藏，你懷疑他老練的雙眼是否能幫你解讀這本書的內容。', '把古老的日記帶給血色守望的隱士裴薩斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9559, 'zhTW', '靜松要塞', '允諾者，你一定要去北方我族人的家園 - 靜松要塞。你會在那裡遇上最令人怯步的挑戰。去吧，大酋長靜松在等著你。', '和靜松要塞的大酋長靜松談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9560, 'zhTW', '天啟的野獸!', '我和我哥哥在東邊的樹林裡打獵時遭到奇怪的，像昆蟲一樣的野獸突擊。我們從沒在藍謎島見過這樣的畸型生物!他們會是即將來臨的天啟徵象嗎?你命中注定要阻止的天啟?$B$B如果你真的是允諾者，你就要擊敗那些天啟的生物……把他們的皮革帶來給我。利用它們的皮革，我可以製作強大力量的護甲!$B$B去東邊找到它們，就在路的那一邊。', '藍謎島，靜松要塞的墨爾多要你幫他帶來8塊劫毀者皮。', '', '去找蔚藍海岸島的墨爾多。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9561, 'zhTW', '諾凱的話', '翻譯已經準備好了，$N。<隱士裴薩斯指著他翻譯尾段的一塊文字。>\'敵人離我們不遠了。我們聚集了所有的生還者撤退到東方的神廟。這是我們在島上真正掌握的最後一塊土地，生還者也都有默契的認為這裡是我們最後的一站。我已將我最後的一些財產埋在神廟的土裡，希望有人會找到它們並知道這裡發生了什麼事。', '找到諾凱的日記中描述的地點及那裡埋藏已久的財產。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9562, 'zhTW', '魚人……為何此時?為何此地?', '這些日子很黑暗，允諾者。就連魚人都對我們窮追不捨 - 一點也不誇張。不幸地，不只我的自尊受挫。$B$B雖然我們和沙鰭魚人的關係一直都很不好，但我們怎麼也沒想到他們會有膽攻擊我們還偷取我們的食物存貨!到西邊的淤塞海岸取回我們被偷的糧食!$B$B還有如果你看見一隻黑皮膚的魚人蹼指間卡著一塊白色的毛皮……', '藍謎島，靜松要塞的克夫要你取回5袋靜松穀物。', '', '去找蔚藍海岸島的克夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9564, 'zhTW', '克夫的尊嚴', '你取回克夫跟魚人奮鬥時「丟失」的毛皮。將毛皮還給克夫並讓他知道可怕的莫爾古爾古拉已經被殺了。', '將克夫的尊嚴帶到藍謎島的靜松要塞還給克夫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9565, 'zhTW', '搜索靜松要塞', '身為大酋長，我最擔心的就是靜松要塞的腐敗根源。為什麼梟獸 - 曾經是我們的盟友 - 會攻擊我們?他們為什麼會居住在靜松要塞?或許裡面的某個東西會有答案。搜索靜松要塞尋找腐敗源頭的線索。', '搜索靜松要塞找到線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9566, 'zhTW', '血水晶', '表面上看來，水晶似乎只是艾克索達的一部分。但這水晶出了些可怕的錯誤，它是血紅色的而且迅速地溶解在洞穴的給水系統中。這或許解釋了藍謎島生物不尋常的侵略性行為。帶著這個消息去找大酋長靜松。', '和靜松要塞的大酋長靜松談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9567, 'zhTW', '了解敵人', '在血色守望見到新面孔真好，$c。雖然血精靈是最緊迫的威脅，但還有其他以血謎島為家的邪惡生物。$B$B納茲維斯薩特是特別令人擔心的。他們是骯髒，惡魔的生物，掌握黑暗魔法，以艾克索達失事產生的汙染物為食物。$B$B我們一定要阻擋他們，但首先要先了解他們。去西南邊的納茲維恩，從他們奇形怪狀的紀念碑來認識他們。', '找到納茲維恩的納茲維斯紀念碑並取得納茲維斯紀念碑雕紋。拿到一個雕紋後回到血色守望的復仇者艾樂希雅那裡。', '', '去找鮮血島的復仇者艾樂希雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9569, 'zhTW', '遏制威脅', '既然已讓薩特知道了我們的存在，我們就一定要放出消息讓他們知道我們不會容忍燃燒軍團的爛人出現在這些土地。$B$B德萊尼已經躲避燃燒軍團和它的爪牙太久了，$N。他們不管在哪裡找到我們都毫不留情。$B$B我們一定不能讓薩特利用艾克索達的失事，把腐敗的水晶當做武器。去北邊，他們領導者居住的艾克薩瑞安，殺了他，取回他一直在收集的被汙染的水晶!', '殺死5個艾克薩瑞安巡影者，5個艾克薩瑞安地獄呼喚者，和澤伏瑞斯，再收集5個被汙染的水晶交給血色守望的復仇者艾樂希雅。', '', '去找鮮血島的復仇者艾樂希雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9570, 'zhTW', '潛伏的克爾肯', '在水晶風暴平息後，一隻神秘的野獸出現在我們村子裡。這隻野獸，克爾肯，是被入侵的梟獸帶來這裡的，他對我們的村子造成許多毀壞。許多靜松的人都為了防禦我們的土地而被殺，還有許多人嘗試制服這隻野獸，從此失去了他們的性命。$B$B在我的幻境中我看見一個人擊敗了克爾肯。那個人一定就是你，$N。你是我們唯一的希望。進入靜松要塞殺死克爾肯。把他的皮革帶回來給我做為證據。', '藍謎島，靜松要塞的『啟示者』克茲要你殺死克爾肯再帶回克爾肯的皮。', '', '去找蔚藍海岸島的『啟示者』克茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9571, 'zhTW', '克爾肯的皮', '把克爾肯的皮帶給墨爾多，在村子的另一邊。他會把皮革做成你要的物品。', '將克爾肯的皮送給靜松要塞的墨爾多。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9573 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9573, 'zhTW', '歐沐魯酋長', '我是靜松年少者，靜松遺產的繼承人。如你所見，我的防衛者對靜松要塞裡攻擊我們的瘋狂梟獸設了一個死亡陷阱。我們雖然能阻止他們進到這裡，但我的防衛者卻沒有一人能滲入要塞。如果你可以進到裡面並殺了他們的領導者，那就能給我們機會襲擊!$B$B找到歐沐魯酋長並殺了他。也殺死任何你在裡面遇到的瘋狂梟獸。', '藍謎島，靜松要塞的靜松年少者要你殺死歐沐魯酋長和9個瘋狂的梟獸。', '', '去找蔚藍海岸島的靜松之子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9574 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9574, 'zhTW', '腐敗的受害者', '血謎島在我們到達之後已經被徹底的改變了。艾克索達的失事讓殘骸散落在整座島上，我想它開始對野生生物產生了負面的影響。$B$B在我確定我的推論之前，我需要更仔細的檢視一番。水晶似乎對樹木的影響最快，所以樹人應該是最容易出現症狀的。如果你幫我從墮落的樹人身上帶回樹皮的樣本，我就能開始我的深入研究。', '帶6塊晶化樹皮給血色守望的莫瑞伊。', '', '去找鮮血島的莫瑞伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9576, 'zhTW', '酷鰭的項鍊', '檢視這個製作粗糙的墜飾，你發現水晶正輕柔地搏動著。雖然它的光線很微弱，但你幾乎可以感覺水晶散發出一種錯誤的訊息。$B$B你不太確定是什麼支配著酷鰭製作出這樣的墜飾，但這發現實在是太重要無法忽略。你或許該把它拿給血色守望的人看看。', '將紅色水晶綴飾帶給血色守望的莫瑞伊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9578, 'zhTW', '尋找高拉恩', '你常想到你的家人嗎，$N?有許多家庭都坐上了艾克索達，但我很少聽到有人能團圓的。我自己也在尋找我丈夫高拉恩的消息，他是冬眠核心的技師。那個殘骸在西邊，那裡充滿了血精靈!我一定要知道高拉恩的下落!就算是他的死訊也比永遠都不知道來的好。我的丈夫會戴著一個和我一樣的墜飾;它們是我姐姐送的禮物。', '尋找莫瑞伊的丈夫高拉恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9579, 'zhTW', '高拉恩的命運', '你無法利用莫瑞伊給你的資訊來鑑別高拉恩的屍體，但他的衣服看來被人搜括過而撕裂。$B$B這區域的血精靈會拿走殘骸身上所有有價值的東西，包括高拉恩的寶石護符。$B$B雖然她的丈夫未從失事中生還，你相信莫瑞伊會很感激你從血精靈那裡取回她丈夫的護符。', '將高拉恩的護符帶給血色守望的莫瑞伊。', '', '去找鮮血島的莫瑞伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9580, 'zhTW', '熊的必需品', '我相信你在血謎島的這段時間也看到了，很少遺物未因我們的到來而改變。我的訓練和經驗讓我知道就算是像這樣的環境產物也可以拿來利用。$B$B資源這麼少，我們一定要依賴我們的足智多謀。我用閒晃在島上的熊肉補充我們的存貨。有適當的處理，我們就能安全的吃熊肉。如果你要去外面晃晃，何不幫忙補充一些存貨呢?', '帶8塊老棕熊腰肉給血色守望的追蹤者萊希安。', '', '去找鮮血島的追蹤者萊希安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9581, 'zhTW', '水晶的學問', '歡迎來到血色守望，$c。監督前哨的防禦是我首要關心的事，但我也被艾克索達的領導者指派了很多其他的職務。$B$B問題是在島嶼這樣危險的時候派出大量的研究員是很危險的。我需要某人去島上不同地點收集一連串的水晶樣本。$B$B我需要的第一個樣本一定要來自鎮南方過了橋的地方，劫毀者寄生的船隻殘骸。', '對衝擊遺址水晶使用水晶採礦鎬以取得衝擊遺址水晶樣本然後交給血色守望的通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9584, 'zhTW', '第二個樣本', '既然我們有了基線水晶，我們就需要更多危險區域的樣本來完成這套送到艾克索達的水晶。$B$B下一個樣本一定要來自劍木林的血精靈控制的水晶，就在血色守望的西北邊。我獲悉他們改變並取得水晶用在一些魔法儀器上。看看你能否找到一個未被合併在他們儀器裡的水晶並採下一個樣本。', '對變質的血謎水晶使用水晶採礦鎬以取得變質的水晶樣本然後交給血色守望的通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9585, 'zhTW', '最後的樣本', '在我把這些水晶送到艾克索達前還有一個樣本要收集，$n。最後的樣本一定要來自西北邊艾克薩瑞安的薩特要塞。$B$B我不確定這個水晶樣本能說明什麼，但我肯定一定會有一些汙染的徵象。記得從水晶上開採下你的裂片，就是看起來像你取得之前樣本的那種水晶，否則我們的研究員就無法做出有根據的對照。', '對艾克薩瑞安水晶使用水晶採礦鎬以取得艾克薩瑞安水晶樣本然後交給血色守望的通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9594, 'zhTW', '燃燒軍團的徵象', '護甲碎塊是由一種好像會吸收光線的深黑色金屬鑄造而成。雖然它不像被附魔的樣子，但它絕對有不對勁的地方。$B$B這種護甲只有一種軍隊會使用 - 燃燒軍團。軍團出現在這裡就是因為他們要動員島上的薩特對抗德萊尼。$B$B對當地薩特採取行動，再回到血色守望把這個護甲碎塊拿給復仇者艾樂希雅看。', '殺死8個納茲維斯薩特和8個納茲維斯魔語，然後帶著泰斯拉克的鎧甲到血色守望找復仇者艾樂希雅。', '', '去找鮮血島的復仇者艾樂希雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9602, 'zhTW', '傳遞不幸的消息……', '你一定要將這個消息告訴你的族人，$N。雖然你英勇的行為的確有讓凱爾薩斯和他黑暗主人的計畫慢下來，但攻擊絕對會持續下去。$B$B把背叛者的信件帶給你的領導者。他們一定要親自看看。或許他們能更清楚了解裡面寫的東西。', '將背叛者的信件帶給藍色守望的主教米奈奧斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9603, 'zhTW', '床，繃帶，和很多很多', '歡迎來到血色守望，$c。請不要介意四周的凌亂。把簡單的事情視為理所當然是很容易的，就像建造一間有著完整裝潢和存貨的旅店，直到你被迫無中生有才知道它的困難。$B$B我們已利用這個分離艙做為建築物，但沒有適當的家具和急救補給品，這旅店也不過是個美麗的帳篷而已。艾克索達的魯古尼已表示會給我們一個包裹來解決我們最迫切的需要，但我還需要某人幫我把這個單子送給他。', '把塔伏爾的單子交給血色守望的角鷹獸管理員勒藍度。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9604, 'zhTW', '飛快的角鷹獸', '只要一點錢，你就能租一隻角鷹獸載你到艾克索達。$B$B搭乘角鷹獸是既快又安全的方式，提供給攜帶重要訊息的人選擇。如果你要乘坐，再跟我說，我會安排的。', '向勒藍度那租借一隻角鷹獸飛往艾克索達，抵達後，將塔伏爾的單子交給那魯之座的魯古尼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9605, 'zhTW', '角鷹獸管理員史丹樊那斯', '箱子在這，$N。這應該夠塔伏爾經營旅店了。讓他知道有需要的話他可以繼續訂貨。血色守望急切地需要一個地方來照料傷者及供給旅人住宿。$B$B等你準備好前往血色守望，就去找艾克索達入口旁的史丹樊那斯。', '到艾克索達外去找史丹樊那斯，並乘坐角鷹獸回到血色守望。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9606, 'zhTW', '回到塔伏爾·羅歐那裡', '如果我沒記錯，血色守望的角鷹獸管理員是勒藍度。要是你之前已經跟他說過話了，就能從我這租一隻角鷹獸到他那去。$B$B這是個很好的學習:角鷹獸一直接受訓練飛往他們的主要城市，但它們只能送你前往所在地之外的角鷹獸管理員那。$B$B因為你已經去過勒藍度的其中一處鳥點，就能使用這條路線帶著補充品回到血色守望去。', '與史丹樊那斯租借一隻角鷹獸回到血色守望。一旦抵達後，運送魯古尼的補給品給照顧者塔伏爾·羅歐', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9611, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9616, 'zhTW', '土匪!', '這看起來是一個賞金帳本。你不了解血精靈的語言，但你注意到有一個圖片描繪一個死去的德萊尼，一個微笑的血精靈站在屍體旁，和一個你認為是某種血精靈貨幣的符號。$B$B他們已經對德萊尼發動攻擊了!你一定要通知主教。', '將血精靈情報帶給藍色守望的主教米奈奧斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9620, 'zhTW', '失蹤的調查小組', '隨著我們在血色守望安置下來，我也派出了調查小組去製作更多可靠的島嶼地圖。大部分的情況來說，他們都會帶著我們需要的資料毫髮未傷的回來，但我派去東邊廢墟的小組卻未向我們回報。我擔心他們會發生什麼事，但我沒有人手可以接下另一個任務去找他們。找到他們，$N，給予他們任何需要的協助帶回他們的調查資料。', '通報者米可拉斯要你找到他派去羅薩倫廢墟的調查小組並盡力幫助他們。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9621, 'zhTW', '部落的使者', '我們潛在的新盟友對我們的能力有些懷疑。被認為連自己家的問題都無法解決那我們對他們而言還有什麼用?$B$B這會改變一切。我們的能力不再會被質疑。我們會以同等的姿態加入部落。$B$B把這封信交給希瓦娜斯，被遺忘者的統治者。她已經和我們站在同一陣線了，但達克汗的死訊對她而言沒有影響力。準備好長途跋涉吧，$N。如果一切進行順利她會送你到奧格瑪的。', '將來自洛索瑪·塞隆的信帶到幽暗城，提里斯法林地的被遺忘者首都給希瓦娜斯·風行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9622, 'zhTW', '警告你的族人', '要塞保住了，很快的我的族人會回到先祖的家。預言成真了，一個新的繁榮時代就要在靜松展開了。但我擔心黑暗就在你自己的族人前方逼近。還有問題未被解答 - 預言的幻象未被目睹。回到你的領導者那裡告訴他們你在這看見了什麼。還有允諾者，如果你需要靜松的幫助，請隨時開口。', '和藍色守望的主教米奈奧斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9623, 'zhTW', '是時候了', '你在我們新家的荒野裡活了下來，並展現你的過人之處。我相信你可以協助那些血謎島前線的戰役了。阿古斯之手會需要像你這樣的$r。$B$B向『獸群管理者』托拉利斯回報。他在艾克索達外面照顧著伊萊克。把這些命令交給他，這樣他就會指示你在血謎島上的新任務。', '藍色守望的主教米奈奧斯要你將主教的命令送給『獸群管理者』托拉利斯，他就在艾克索達外面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9624, 'zhTW', '最愛的一道菜', '我發現了一件很棒的事，$c。在未受汙染的島上生長著一種超棒的水果叫沙梨。它們長在樹底下。$B$B我準備用它們來做派，但如果我一不小心，伊萊克就會開始四處遊蕩偷取我的水果。我已採集夠多水果和這些動物分享，但我的儲存量已不夠而我對派的渴望又不斷上揚。你願意幫我收集這些水果讓我做另一批派嗎?我保證會分你的!', '凱索十字路的艾昂爾要你幫他帶來10顆沙梨。', '', '去找鮮血島的艾昂爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9625, 'zhTW', '伊萊克是嚴肅的職責', '他瘋了嗎?委託這樣的事情給一個不知名的年輕$r!記住這點孩子:你永遠也無法成為一個阿古斯之手的!你沒那個本事!我想我這次得遷就他了。到血謎島和凱索十字路的渥卡恩談談。沿著往北方的路走，到了岔路時繼續往北走就對了。', '和血謎島的『伊萊克牧者』渥卡恩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9627, 'zhTW', '效忠部落', '你的人民被聯盟狠狠的背叛。你已成功抵擋達納蘇斯和鐵爐堡間諜的攻擊。現在你又在家門前擊敗了一個強大的天譴軍團領導者。你的實力已不再值得懷疑。現在很明顯的你需要我們而我們也需要你。回到洛索瑪那裡。告訴他我清楚的收到了他的訊息。<大酋長將信在手中揉爛。>歡迎來到部落，精靈。', '回到銀月城向洛索瑪·塞隆回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9628, 'zhTW', '搶回資料', '現在幫製圖師完成他們的任務已經太遲了，但看來他們收集了通報者米可拉斯想要的資料。儲存他們調查資料的水晶不在他們的背包裡，所以它一定是在怒鱗納迦的手中。$B$B你知道通報者米可拉斯若失去了調查小組會很難過，但他還是會搶救調查資料吧。', '從死亡的製圖師附近的怒鱗身上取得勘察資料水晶，再帶回血色守望給通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9629, 'zhTW', '標記魚人', '西南方海岸上的黑沙魚人是很好奇的生物。在某些方面來說，他們只是敏銳的哨兵，但其他時候，他們又展現了非凡的組織程度。$B$B我對此有一些理論，但直接最近才有真正試探他們的方法。我想出了一個辦法讓我可以追蹤我有興趣的魚人，而不會對他們造成一點傷害或干擾他們自然的行為。如果你願意幫我做標記，我會很樂意酬謝你的協助。', '血色守望的莫瑞伊要你使用魚人標示器「標記」6個黑沙斥候。', '', '去找鮮血島的莫瑞伊。', '標記黑沙斥候', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9632, 'zhTW', '新找到的盟友', '通報者米可拉斯保衛血色守望的工作做的相當不錯，$c，但我們的敵人有許多，而我們的資源卻很少。$B$B敵人很清楚我們的弱點，但你和聯盟軍隊的聯繫卻是他們料想不到的。我準備了一封介紹信給奧伯丁的人民，最近的聯盟殖民地，提出合作對抗我們敵人的建議。帶著它去找艾克索達西邊碼頭附近的女獵人凱拉·夜弓。', '將介紹信交給女獵人凱拉·夜弓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9633, 'zhTW', '去奧伯丁的路', '如果你在碼頭外等著，你就會看到從黑海岸的奧伯丁來的船抵達。等到它的乘客都下船後，你就能上船。$B$B在一小段旅程之後，船就會在奧伯丁停下，你就能遞送你的訊息了。$B$B你最好將這個交給桑迪斯·織風，我的一個老朋友也是那個鎮上很受尊敬的市民。', '從靠近女獵人凱拉·夜弓的碼頭上搭船前往奧伯丁。等你到了奧伯丁，將介紹信拿給桑迪斯·織風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9634, 'zhTW', '外來掠奪者', '我們在旅途中學到的一件事就是當你將一個世界的野生動物帶到另一個世界時一定要格外小心。當艾克索達失事時，它裝載著各種外域的物種樣本，包括一個叫劫毀者的昆蟲掠食者。$B$B有些樣本不見了，但許多其他的還活著並開始喜歡荒地。如果我們不持續觀察它們，它們會擾亂島上的自然平衡。$B$B你可以在凱索十字路西邊找到這些劫毀者，靠近海岸的地方。', '殺死10隻血謎幼蟲後回到血謎島的凱索十字路找『伊萊克牧者』渥卡恩。', '', '去找鮮血島的『伊萊克牧者』渥卡恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9641, 'zhTW', '受到輻射的水晶裂片', '艾克索達失事的邪惡水晶裂片散落在整個血謎島，汙染了水源和景色。$B$B我們甚至開始在動物的肉體裡找到水晶裂片。我已找到一個方法可以淨化裂片，將它們轉變為有用的水晶，所以如果你幫我帶來足夠的裂片，我就會用一個完整的水晶和你交換。目前為止我已在熊，劫毀者，翼蛾，和樹人的身體裡找到裂片，他們都住在島上受汙染的地方。', '血色守望的復仇者波羅斯要你幫他帶來10個受到輻射的水晶裂片。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9642, 'zhTW', '更多受到輻射的水晶裂片', '', '進度如果你有更多受到輻射的水晶裂片，我很樂意和你交換。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9643, 'zhTW', '蟒藤', '一個好木匠會善用所有可利用的資源，$c。就連最奇怪的生物所擁有的特性我們都能利用。$B$B血色守望不斷遭受太陽之鷹的攻擊，我們要尋求各種天然的防禦包括陷阱。鞭笞者多刺的藤蔓很適合建造我想的陷阱。銳利的刺和致命的毒素結合會讓粗心的攻擊者落入陷阱。幫我把突變的蟒藤帶來這樣我就能開始動工。', '血色守望的追蹤者萊希安要你幫他帶來6個多刺的蟒藤。', '', '去找鮮血島的追蹤者萊希安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9646, 'zhTW', '懸賞:死亡之爪', '通報者米可拉斯的命令:以18銀懸賞帶著死亡之爪，一隻潛行捕食的熊已死的證據回來的勇敢靈魂。$B$B死亡之爪是極為危險的生物，在血色守望西北方的海岸殺死了一批調查小組。旅人最好都避開那個區域。', '將死亡之爪的爪子帶給血色守望的通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9647, 'zhTW', '撲殺翼蛾', '當我們第一次碰到翼蛾時，他們沒有什麼突變的跡象。隨著汙染日益嚴重，飛蛾和其他物種便開始出現受汙染的跡象。$B$B現在已經進展到和他們接觸的所有生物幾乎都遭到損害了。他們正在擴大艾克索達失事後散落的水晶裂片所造成的傷害。我們別無選擇只能開始削減他們在血色守望北邊的數量。', '血色守望的追蹤者萊希安要你殺死10隻皇家藍翼蛾。', '', '去找鮮血島的追蹤者萊希安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9648, 'zhTW', '麥克艾瑞野生蘑菇', '你知道採集蘑菇比消耗蘑菇更危險嗎?蘑菇採收者置身於許多未知 - 不包括潛在 - 的野生生物危機中。$B$B如果沒有危險會是什麼樣子?我需要收集蘑菇。你會在這些未探勘的荒野中找到四個不同的品種:水生惡菌菇，血色蘑菇，有害的孢子群，和魔錐果真菌。它們都是血謎島上獨特的品種。把它們帶來給我。', '血色守望的潔希拉·麥克艾瑞要1個水生惡菌菇，1個血色蘑菇，1個有害的孢子群，和1個魔錐果真菌。', '', '去找鮮血島的潔希拉·麥克艾瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9649, 'zhTW', '伊瑟拉之淚', '再見到你真好，$N!你在完成我給你的最後一個任務時真是異常地有效率。或許你對另一個任務有興趣?$B$B東北方有個龍痕島，一種名罕見蘑菇生長在那邊，伊瑟拉之淚 - 以住在那座島上的綠龍軍團為名。我只需要一個蘑菇小樣本，但我一定要警告你島上的居民不歡迎訪客。步步為營。', '血色守望的潔希拉·麥克艾瑞要2個伊瑟拉之淚。', '', '去找鮮血島的潔希拉·麥克艾瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9663, 'zhTW', '幫凱索的忙', '你來的正好，$N。這區域的血精靈活動在過去一個禮拜已經加倍了。我們的密探告訴我們自稱為太陽之鷹的血精靈計畫要對藍謎島發動攻擊。我要你去警告一下我們的盟友和同伴。$B$B警告靜松要塞的大酋長靜松，藍色守望的主教米奈奧斯，和奧迪席斯平臺的艦隊司令·奧迪席斯。$B$B時間緊迫所以我借你我的伊萊克。記得不能讓它碰到水。', '凱索十字路的凱索要你去警告靜松要塞的大酋長靜松，藍色守望的主教米奈奧斯，和奧迪席斯平臺的艦隊司令·奧迪席斯關於血精靈即將發動的攻擊。完成任務後回到凱索那裡。你只有15分鐘。', '', '去找鮮血島的凱索。', '已警告大酋長靜松', '已警告主教米奈奧斯', '警告艦隊司令·奧迪席斯', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9665, 'zhTW', '增強防禦', '被遺忘者密探揭發了聯盟的秘密計畫，他們要在東瘟疫之地被廢棄的哨塔上建立新基地。$B$B現在要緊的是我們不能讓他們在東部邊界建立重要的據點，所以我們一定要趕走這批聯盟入侵者。我們目前的計畫是把他們可能已攻佔的所有哨塔中趕走，並佔據控制那些哨塔不受進一步的攻擊。', '佔領東瘟疫之地的皇冠哨塔，東牆之塔，北地哨塔和病木林哨塔，再回到聖光之願禮拜堂的密使·戈馬克那裡。', '', '去東瘟疫之地找聖光之願禮拜堂的密使·戈馬克。', '已奪得皇冠哨塔', '已奪得東牆之塔', '奪得北地哨塔', '奪得病木林哨塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9666, 'zhTW', '宣示力量', '你有看過毒蛇人嗎?就是自稱納迦的那些人?$B$B<凱索吐了一口口水。>$B$B他們竟敢在三天前趁著夜色的掩護向這營地進軍。你相信那些原始野獸的膽大妄為嗎?$B$B我要你送一個訊息給他們的領導者，$N。東北方的怒鱗巢穴是希司領主的家。找到他，殺了他，把這支旗幟插在他的屍體上。$B$B讓他們知道每當看見我們的軍旗，就是該害怕的時候!', '血謎島，凱索十字路的凱索要你殺了怒鱗巢穴的希司領主，並將德萊尼旗幟插入他的屍體。', '力量的宣言', '去找鮮血島的凱索。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9667, 'zhTW', '拯救靜松公主', '救救我，$N!鬚肢熊怪把我抓來並且打算將我獻祭給他們骯髒的神祇!$B$B大酋長鬚肢握有開啟籠子的鑰匙。要逼他現身，你必須殺死邪惡的鬚肢熊怪，位置就在這座營地西邊的兩座鬚肢熊怪營地。如果你殺了夠多熊怪，他就會出來報仇!當他出現的時候，殺了他並拿到鑰匙!$B$B如果你救了我，我的父親會重重答謝你的!', '釋放囚禁在籠子裡的靜松公主後與血色守望的靜松大使歐洛格談談。$B$B你得殺掉大酋長鬚肢才能得到籠子的鑰匙。', '', '去找鮮血島的靜松大使法薩布。', '已拯救靜松公主', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9668, 'zhTW', '向主教阿德密特斯回報', '一個阿古斯之手的士兵代表了很多意義:服從，勇敢，智慧，和最重要的，高尚。你或許還沒展現出這些特質，$c。如果你還對加入阿古斯之手有興趣，就向血色守望的主教阿德密特斯回報吧。他和他的部屬會進一步的以德萊尼士兵的方式訓練你。還有記住，$N:高尚的人不會永遠都做高尚的事，有時候他們身不由己。沿著這條路往北走你就可以找到血色守望。', '和血色守望的主教阿德密特斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9669, 'zhTW', '失蹤的遠征隊', '大概一個禮拜前，當我和我的研究小組在血謎島西邊的荒野探勘時，遭到嗜血的蜘蛛攻擊。水晶汙染的效果非常明顯，因為這些蜘蛛體型變得既龐大又極具攻擊性。$B$B我設法逃了出來，但我的組員就沒這麼幸運。我們不能讓同樣的命運降臨在其他人身上。去西邊的琥珀網小徑殺死蜘蛛和他們的女王，沙拉克。', '殺死8隻謎霧紡紗者，8隻謎霧吸血者和他們的領導者，沙拉克。任務完成後回到血色守望找阿奇拉斯。', '', '去找鮮血島的阿奇拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9670, 'zhTW', '他們還活著!或許吧……', '那真是一場血戰啊，$N。我們被一大群蜘蛛給突襲。他們的祖先用不可思議的速度向我們蜂擁而上並把我們包在繭裡。$B$B在我們被纏住後，她開始在我們附近產卵。我們就要成為她幼蟲的食物了!是食物!$B$B我設法逃了出來，但我沒辦法丟下其他人不管。目前為止我都無法成功接近那裡。你可以伸出援手嗎?$B$B摧毀那些繭!希望我們的隊員還有人活著!', '研究員卡尼勒斯要你救出5個遠征隊研究員。', '', '去找鮮血島的研究員卡尼勒斯。', '已釋放遠征隊研究員', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9671, 'zhTW', '緊急送件', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9672, 'zhTW', '血咒遺產', '親愛的朋友，我顫抖著手寫下這封信。我希望它能及時送到你手中。昨天夜裡，「失望」號的船長，艾德華·漢尼斯出現在我帳篷前面。和20年前因壞血病而死的艾德華·漢尼斯一模一樣。這個亡魂告訴我一個讓我的心不停顫抖的故事。一個我要你聽的故事和一個我要你完成的任務。你願意接受嗎?你願意去基地東北方的龍痕島找艾德華嗎?艦隊司令·奧迪席斯，敬上', '艦隊司令·奧迪席斯要你找到隊長艾德華·漢尼斯並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9674, 'zhTW', '血咒納迦', '他們說當世界分裂的時候，這座島是最悲情的。數千條夜精靈性命在這裡犧牲而被世人遺忘，原本屬於夜精靈的土地如今興起了為仇恨而生的可怕生物 - 納迦。$B$B他們效忠於他們瘋狂的女王艾薩拉，誓要殺光任何膽敢穿越他們海洋的人。這種情形將會持續數千年，但是現在將要改變。$B$B任務的第一個命令就是解決掉沙洲的血咒納迦。', '龍痕島的隊長艾德華·漢尼斯要你殺死10個血咒納迦。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9676, 'zhTW', '聖騎士訓練', '當你在職業中不斷進步，你會想從職業訓練師所能提供你的訓練中獲得助益。對逐日者之島這裡的年輕聖騎士而言，你們的訓練師是傑斯賽尼斯·擊日者。和傑斯賽尼斯談談，看他能提供什麼訓練給你。他的訓練需要收費，所以帶一些錢在身上。你的訓練師 - 和逐日者之島上所有的訓練師一樣 - 都在日尖塔的較低層。', '和傑斯賽尼斯·擊日者 - 聖騎士職業訓練師 - 談談，他就在逐日者之島的日尖塔裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9682, 'zhTW', '絕望者……', '在沙洲的突出處，比你發現血咒納迦再深入一點的地方，可以找到絕望者:血咒航海者，那些被血咒抓去的鬼魂。$B$B我現在要你做的事，讓人感到不忍心……但他們一定要被消滅並把他們被詛咒的軀殼帶回來給我。$B$B他們的靈魂一定要得到安息。等你完成了我要求的事情再回來找我，我就會給你最後的一個任務。', '龍痕島的隊長艾德華·漢尼斯要你帶回4個血咒靈魂。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9683, 'zhTW', '終止血咒', '你會在南方找到血咒島。在島的頂端你會找到一座獻給摯愛的納迦女王，艾薩拉的神殿。摧毀那個雕像 - 把它燒毀!這一定會引起阿托夫，血咒領導者的憤怒。$B$B殺了阿托夫再回來找我!', '龍痕島的隊長艾德華·漢尼斯要你摧毀艾薩拉女王雕像並殺了血咒的阿托夫。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9687, 'zhTW', '恢復聖潔', '不久以前，區域裡曾經平靜的梟獸出現在島的海岸。他們會一個接一個來偷取陣亡的龍骨。我不知道是什麼讓這些生物這樣苦惱，或是他們為什麼會想要死者的骨頭，但那些後裔的靈魂因為這樣悖理逆天的行為無法安息。$B$B到西邊去，穿過赤紅地帶，你會找到怒羽山脊。進入梟獸營地取回被偷走的龍骨。', '龍痕島的托瑞斯王子要你取回8根龍骨。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9688, 'zhTW', '進入夢境', '你在這島上看到的幼龍都是綠龍軍團被激怒的靈魂。就像我一樣，他們都被束縛在這塊土地上，無法回到他們在夢境之國的最後安息之地。$B$B取得亡者的骨頭會暫時讓他們平息下來，但你一定要採取進一步的行動。$B$B解放他們永恆的束縛。在完成之前我不能離開這裡。他們一定要被釋放!', '龍痕島的托瑞斯王子要你殺死5隻翠綠色幼龍和5隻翠綠色小龍。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9689, 'zhTW', '瑞索默', '許多黑龍軍團的成員都在攻擊中被殺了。這些亡魂中有一名死亡之翼的副官，他的靈魂現在還出沒在這個地方。如果你望著天空，你會看見他的鬼靈面容在空中環繞。他的仇恨心太重以致於連死後都還心懷憤恨。$B$B帶著你先前為我收集的骨頭到這座島的山頂上，將它們放在永不熄滅的柴堆裡。此舉會發出一種訊息使瑞索默降下來查看究竟。到時候就殺死他的不死身驅。', '龍痕島的托瑞斯王子要你殺了瑞索默。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9693, 'zhTW', '阿古斯對我的意義', '阿古斯對你而言有什麼意義，$N?你大概和許多德萊尼一樣不知道或不記得我們的家園。我們在那裡和曼那瑞分開:那是薩格拉斯『賦予』我們一族的扭曲惡魔形態，或是如他們所自稱的，埃雷達爾。埃雷達爾……這個字曾經有它的意義。<阿德密特斯好像在品嚐這個字一樣。>真噁心。不要再浪費時間了。找到復仇者波羅斯展開你的訓練。', '血色守望的主教阿德密特斯要你去和復仇者波羅斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9694, 'zhTW', '血色守望', '你知道，血色守望是阿古斯之手運作的兩個前鋒基地之一。你已經去過另一個基地藍色守望了;血謎島的情形是完全不同的。當我們第一次到這裡，這片土地是和藍謎島一樣美麗的。我們甚至還稱它為銀色歡地，但是現在疾病散播大地，而更糟的是，我們在艾克索達對抗的血精靈從失事中生還了。這讓我想到你的第一個任務:前往西北方的劍木林除掉所有你見到的血精靈。', '血色守望的復仇者波羅斯要你殺死10個太陽之鷹間諜。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9696, 'zhTW', '翻譯……', '我們的首席審問者伊萊希雅會說流利的薩拉斯語。把文件帶給她，看看她怎麼說。', '將太陽之鷹書信帶給血色守望的審問者伊萊希雅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9698, 'zhTW', '覲見預言者', '我要你把翻譯的文件親自交給費倫，$N。我不信任那個笨手笨腳的信差。$B$B向預言者解釋血精靈正在從外域接收援軍，他們在艾克索達的德萊尼之中有個間諜。費倫住在艾克索達的聖光地窖。$B$B動作快!', '將翻譯太陽之鷹的書信帶給艾克索達的預言者費倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9699, 'zhTW', '是真是假', '謝謝你及時的送達，$N。你將要成為阿格斯之手優秀的密探之一了。$B$B要是我們能知道他們在血謎島向誰報告那就好了，還有更重要的，太陽之門在什麼地方……他們似乎有重重戒備 - 不管它是在什麼地方。$B$B你有興趣接一些勘察的工作嗎?$B$B如果可以，請帶著這些命令回到復仇者波羅斯那裡。他會給你下一個任務。', '將費倫的命令帶給血色守望的復仇者波羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9700 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9700, 'zhTW', '向黑暗中發射魔法', '費倫表示如果血精靈已在這座島和外域間開啟了裂縫，傳送門開啟的地方就會有召喚儀式的殘餘物或異常者出現。你一定要搜索島上有顯現出這些異象的地方。$B$B小心，$N;有些異象是從虛無本身來的生物。如果你發現虛無反常者，就殺了他們!帶著你找到的新資訊回來向我報告。從北邊開始你的搜索，靠近星移活塞的地方。', '血色守望的復仇者波羅斯要你找到太陽之門地點並殺死5個虛無反常者。', '已確認太陽傳送門地點', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9703, 'zhTW', '冬眠核心', '我們還有其他人在尋找太陽之門的線索，$N。我要你先專注於手上的工作。$B$B波羅斯收到一則新報告指出有另一個失事地點。我們發現那個失事地點就是艾克索達的冬眠核心。這是覆蓋船艙的支撐區域，就和我們德萊尼從安曼谷爬出來的那個船艙一樣。$B$B這個區域也有醫療補給。前往冬眠核心，就在血色守望正西邊。尋找物資及生還者。', '血色守望的復仇者庫羅斯要你取得12箱醫療補給。', '', '去找鮮血島的復仇者庫羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9706, 'zhTW', '高拉恩的日誌 - 復仇者薩魯安的命運', '你的手顫抖著撿起書。庫羅斯一定知道這個悲劇了。將書還給他。', '將高拉恩的日誌帶給血色守望的復仇者庫羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9711, 'zhTW', '殘忍的馬帝斯', '馬帝斯會得到正義的，$N;我要你找到他並把他帶回三頭政治。$B$B搜索島嶼找到這個混蛋。如果你找到他，就使用這把信號槍。我的追蹤者看到閃光就會前去協助逮捕馬帝斯。抓到他後再來找我。', '血色守望的復仇者庫羅斯要你抓到殘忍的馬帝斯。', '殘酷的馬提斯已捕獲', '去找鮮血島的復仇者庫羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9740, 'zhTW', '太陽之門', '多虧了你和你做的努力，我的斥候才能找到太陽之門。精靈讓傳送門的位置保持活動，這樣他們才能瞬間移動它。這是為什麼你調查到的地點是空的。$B$B這個系統的優點也是它最大的缺點。太陽之門由傳送門控制器來穩定。如果我們可以擊敗控制器，我們就能摧毀傳送門。目前太陽之門的位置在西邊，旋繞導航器的南方。找到並摧毀它!', '血色守望的復仇者艾伊森要你摧毀太陽之門。', '', '去找鮮血島的復仇者艾伊森。', '摧毀太陽之門', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9741, 'zhTW', '虛無異常者', '幾天前艾伊森派我的小組去進行一個勘察任務，搜索太陽之門。不用說，我們發現了……$B$B<羅莉指著喬爾力。>$B$B不管那些蠢精靈透過傳送門在傳送什麼，這讓虛無能量不斷被釋放。那個區域到處都是虛無異常者。$B$B我們一定要在他們有機會變成虛無反常者前毀了他們。你可以在西南方靠近太陽之門的地方找到這些生物的發源地。殺了他們，完成後向艾伊森報告。', '殺死12個虛無異常者再向血色守望的復仇者艾伊森回報。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9746, 'zhTW', '體能極限', '勝利就只差臨門一腳，$N。發現了太陽之門，他們的補給線不久後就會被完全封鎖了。現在是襲擊他們部隊的時候。$B$B你可以在西邊找到許多的太陽之鷹營地。太陽之鷹控火者和太陽之鷹防衛者佔據了大部分的區域。找到他們，殺了他們，再回來找我。', '血色守望的復仇者艾伊森要你殺死10個太陽之鷹控火者和10個太陽之鷹防衛者。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9748, 'zhTW', '別喝那裡的水', '我們的薩滿聲稱水元素因為水源的污染受到很大的影響。我們知道艾克索達的能量核心位在西邊的山裡。它一定是正滲漏出揮發性的液體到水供給裡!我要你去幫我收集更多資訊。$B$B<艾伊森指向一個瓶子並點點頭。>$B$B你要帶著這個瓶子沿著海邊北方走，直到你到達血謎島的河流匯入海洋的區域。採集那裡的樣本並帶回來給我。', '血色守望的復仇者艾伊森要你使用水樣本瓶取得血謎水樣本。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9751 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9751, 'zhTW', '血咒遺產', '昨天夜裡，「失望」號的船長，艾德華·漢尼斯出現在我帳篷前面。和20年前因壞血病而死的艾德華·漢尼斯一模一樣。這個亡魂告訴我了一個讓我的心顫抖的故事。一個我要你聽的故事和一個我要你完成的任務。你會去做嗎?你會去找血色守望東北方的龍痕島找艾德華嗎?', '艦隊司令·奧迪席斯要你去找隊長艾德華·漢尼斯並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9753, 'zhTW', '我們所知道的事……', '我們最近幾天了解了很多敵人的事。血精靈由一個叫賽羅娜斯的人領導並密謀要摧毀我們。最後，他們要征服歐蘿絲並重拾對艾克索達的控制。$B$B讚美聖光，我們摧毀了太陽之門，阻止了他們的補給線。不幸的是，他們持續使用旋繞導航器的污染物來毒害大地，使用幅射性落塵的突變物質來利己。$B$B有了這樣的認識，阿德密特斯便想出個計畫。快去找他。', '和血色守望的主教阿德密特斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9754 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9754, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9756, 'zhTW', '我們不知道的事……', '我們嘗試審問的企圖已悲慘地失敗了，$N。折磨 - 當然 - 是絕對會有的。我們需要的是一個在裡面的德萊尼。$B$B我可以對你施放一個法術讓你變成血精靈並調整你的語言。透過一些藉口，我們或許可以獲得被俘虜的密探的消息。$B$B在這樣的偽裝下，我要你盡可能的從囚犯那裡取得資訊。$B$B還有$N，偽裝的時候不可以離開血色守望否則法術就會失效。', '和血色守望被俘虜的太陽之鷹密探談談並取得太陽之鷹情報。完成任務後回報主教阿德密特斯。', '', '去找鮮血島的主教阿德密特斯。', '取得太陽之鷹情報', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9758, 'zhTW', '回到秘法師范德隆那裡', '我的朋友，希望你可以好心的回到秘法師范德隆那裡，我知道他非常渴望派你來鬼魂之地這裡進行你的第一個任務。我們都靠你了，$N。別讓我們失望。', '回到鬼魂之地的安寧地找秘法師范德隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9759, 'zhTW', '結束他們的世界', '如果你珍惜你的生命就不要接下這個任務。你看到遠處那個從山邊突起的巨大能量核心嗎?任何接下這個重擔的人都需要一路戰鬥到那座山上，在保護我的同時要和太陽之鷹軍隊作戰，而我要切斷那個核心以破壞它。賽羅娜斯也在那裡某處。$B$B如果你就此離去我也不會輕視你的，$N。$B$B但或許你就是那個能摧毀旋繞導航器和擊敗賽羅娜斯的人。那麼，你是嗎?', '在破壞者勒茍索嘗試摧毀旋繞導航器並殺死賽羅娜斯時跟著他並保護他。完成任務後回到血色守望的主教阿德密特斯那裡。', '向量線圈已摧毀，希羅娜絲已擊殺', '去找鮮血島的主教阿德密特斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9760, 'zhTW', '復仇者之陵', '我不會要你獨自一人背負著摧毀旋繞導航器和殺死賽羅娜斯的重擔，$N;不過，我想你可以幫忙為其他可能接下這樣危險任務的人清理道路。$B$B踏上血色守望外往北邊的路並沿著它一直走到岔路。到了那裡，選擇左邊的路並一直走到你看見復仇者之陵 - 它會在路的偏西邊一點。科林會在那邊等你。', '到血謎島和復仇者之陵的復仇者科林談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9761, 'zhTW', '清除道路', '只有最身經百戰，高尚，又毫無畏懼的德萊尼才會接下於勒茍索的任務。主教不會命令任何一個阿格斯之手的密探接下摧毀旋繞導航器和殺死賽羅娜斯的任務。他拒絕讓任何一個德萊尼去送死 - 像是那些自殺般的任務……$B$B<科林嘆氣。>$B$B我的工作是削弱太陽之鷹的防禦。你要殺死旋繞導航器附近的太陽之鷹並為我們的勇士將道路清空 - 不論我們的勇士是誰。', '復仇者之陵的復仇者科林要你殺死8個太陽之鷹破壞者和8個太陽之鷹密探。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9762, 'zhTW', '未寫下的預言', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9767 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9767, 'zhTW', '[Know Your Enemy]', '[Defeating an enemy requires more than superior power or numbers.  Victory often hinges on knowledge of an opponent\'s weaknesses, the anticipation of their plans or the recognition of a behavior pattern.$B$BWe know much about the naga, yet much of their magical practices remain foreign to us.$B$BI seek to learn of the Hydromancy used by the naga of Coilfang Reservoir.  Bring me one of their spellbooks so I may learn more about it.]', '[Obtain a Coilfang Spellbook from the naga inside of Coilfang Reservoir and bring it to Ashyen at the Cenarion Refuge in Zangarmarsh.]', '', '去找贊加沼澤的艾斯炎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9779, 'zhTW', '攔截訊息', '再見到你真好，$N。我有個困難你或許可以解決。$B$B我們在太陽之鷹陣線後方的密探回報，看見太陽之鷹士兵傳送一份不尋常的文件。$B$B不幸的是，我們未成功取得一份文件的副本。我要你去那裡嘗試弄到那個文件。我確定如果你施加足夠的壓力，太陽之鷹密探就會供出我們要的資訊。必要時你可以使用武力。', '殺死太陽之鷹的血精靈們直到你取得太陽之鷹書信，然後交給血色守望的復仇者波羅斯。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9794, 'zhTW', '沒時間好奇了', '$N，我有件事想請你幫忙。通常我會自己做這件事，但我現在真的太忙了。$B$B我有個叫齊亞隆的朋友在北邊劍刃山脈的希爾瓦納。他在等我的消息，雖然我想他聽到後不會太高興。$B$B如果你可以幫我傳話給他，我會很感謝你。另外我一定要堅持，這很重要，那就是你不能偷讀這封信。這只能讓齊亞隆知道。', '把提莫斯的信帶給位在劍刃山脈希爾瓦納的齊亞隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9795, 'zhTW', '巨魔威脅', '好像納迦和他們的盟友還不夠多似的，巨魔將他們的觸角延伸到了沼澤區。他們已征服了西北邊大部分區域，那裡已經沒有什麼緩衝之地了。我們每殺一個人，就會有好幾個人代替他的位子。我不確定如果他們決定發動攻擊，我們還能保住薩布拉金多久。前往北方進入山裡，到的獸人雷霆王村堡壘讓奈克薩爾知道我們的困境。我們歡迎他可提供的任何幫助。', '前往劍刃山脈的雷霆王村和奈克薩爾談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9798, 'zhTW', '血精靈計畫書', '這些計畫書看起來很重要。你應該帶著它們去找失事地點的復仇者艾德。', '帶著血精靈計畫書到安曼谷的失事地點找復仇者艾德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9811, 'zhTW', '辛多雷的朋友', '這是我們血精靈歷史中嶄新的一章，$N。你的幫助加強了我們雙方種族的關係，$r。$B$B把背叛者的頭顱帶給銀月城的地區統治者，洛索瑪·塞隆。他等不及想聽到這個消息。', '把達克汗的頭顱交給銀月城的洛索瑪·塞隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9812, 'zhTW', '部落的使者', '我們潛在的新盟友對我們的能力有些懷疑。被認為連自己家的問題都無法解決那我們對他們而言還有什麼用?$B$B這會改變一切。我們的能力不再會被質疑。我們會以同等的姿態加入部落。$B$B把這封信交給希瓦娜斯，被遺忘者的統治者。她已經和我們站在同一陣線了，但達克汗的死訊對她而言沒有影響力。準備好長途跋涉吧，$N。如果一切進行順利她會送你到奧格瑪的。', '將來自洛索瑪·塞隆的信帶到幽暗城，提里斯法林地的被遺忘者首都給希瓦娜斯·風行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9877 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9877, 'zhTW', '恢復藥劑', '對抗天譴軍團的戰役讓我們死傷慘重。每天都有很多人被殺，還有更多人的命運更悲慘。天譴軍團俘虜人質也是常見的事。和在死亡之域等待他們的比起來死亡會是更好的選擇。他們在可怕的毒藥效果下喪失意志被嚴刑拷打。安寧地的藥劑師倫澤紳發明了一種解藥;去找他並取得這個恢復藥劑。', '和安寧地的藥劑師倫澤紳談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10063, 'zhTW', '探險者協會，那是給地精的東西嗎?', '帶小孩!你相信嗎?他們把我從前途光明的考古發掘裡叫出來要我去奧迪席斯隊長的遠征隊去照顧一個小地精!我從未聽說有地精要當勘察員，所以我問了。看來好像我們現在接受地精了，而這個特別的傢伙受到魚人們的愛戴!哎，他已經下班了，在島的北方海岸那一個破舊的龜殼處紮營。如果你不相信我就去看看吧!', '在血色守望的北邊海岸上的破舊龜殼處尋找克羅波·維茲班。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10064, 'zhTW', '與阿格斯之手談談', '阿古斯之手在復仇者之陵建立了一個前方據點，但被血精靈及突變的野生生物在數量上遠遠的超過了。沒有後備的話，他們的前哨將有陷落的危險，而我們則無法監視旋繞導航器週遭的狀況。到復仇者之陵西北方找斥候喬爾力報到，並提供你的協助，$N。', '向復仇者之陵的斥候喬爾力報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10065, 'zhTW', '清出一條路來', '在我們偵察太陽之鷹及他們的門戶這段期間，我受了許多的傷。斥候羅莉設法幫我止血，並試著想出一個方法將我疏送到血色守望。$B$B問題就在於我們得放棄現在這個位置以確保日後能夠安全的回來。$B$B只要我們一離開這個神聖的地區，我們就會被劫毀者捉住。如果你能幫我們清理掉一些暴怒的劫毀者，也許就能讓我們回程安全些。', '殺了10個暴怒的劫毀者後回到復仇者之陵找斥候喬爾力。', '', '去找鮮血島的斥候喬爾力。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10066, 'zhTW', '噢，他們所編織的糾纏的圈套', '我們不敢放棄我們的哨站，或離開復仇者之陵太遠，$r。接近旋繞導航器的突變生物藉由水晶洩漏的能量而產生了極大的改變。$B$B突變的糾纏者好像獲得了某些程度的知覺。他們已經懂得創造，佈置，及隱藏惡毒的陷阱，能夠捕捉住即使是最細心的戰士。$B$B假如我們繼續否認事實，我們將無法與這些太陽之鷹對抗。去攻擊問題的源頭，$N。', '殺掉8個突變的糾纏者後向復仇者之陵的復仇者科林回報。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10067, 'zhTW', '污濁的水精靈', '大部分的生物接觸過水晶的能量後都以同樣的方式墮落:肌肉上有奇怪的記號，強烈地侵略性，以及身體有小片的水晶裂片。然而，位於這裡北方的污濁的水之靈似乎整個都晶化了。$B$B我之前從未看過任何生物會這樣晶化的，不過當我們偶然發現他們後，發現他們特別的危險。我們必須在太陽之鷹將他們當成新的力量來源前除掉他們。', '殺掉6個污濁的水之靈後回到復仇者之陵找復仇者科林。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10166, 'zhTW', '白吼的記憶', '這個墜飾喚起了不同時期的回憶。一段比較好的時光。$B$B不幸地是，回憶是我現在最不需要的東西。$B$B我要你把這東西埋葬在烈焰邊境的符文石旁邊。那裡就是我第一次遇見樹人長者的地方。讓我老朋友的回憶休息吧。', '拉瑞安娜·河風要你在烈焰邊境將老白樹墜飾放置在符文石旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10215, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10304, 'zhTW', '復仇者艾德', '有了你的幫忙，我們已經可以比想像中還快的找到解決的方法。我沒有別的工作要交給你。我和我的學徒們可以完成剩下的事情。你應該去船的另一邊跟復仇者艾德談話。', '與安曼谷裡失事地點的復仇者艾德談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10324, 'zhTW', '牧月大獵殺', '做得好，$n!做得好!$B$B既然你已經見識過牧月成鹿了，那麼現在是你晉級去狩獵更可怕的獵物的時候了。不要讓牧月雄鹿平時對週遭事物漠不關心的個性愚弄了你:當它被激怒時，就是一個可怕的敵人。$B$B你可以在這裡北邊發現那些雄鹿。好好狩獵吧。', '將6個牧月雄鹿皮革帶去給藍色守望的艾克緹昂。', '', '去找蔚藍海岸島的艾克緹昂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10356 AND `locale` = 'zhTW';
