INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10373, 'zhTW', '戰鬥的號角:瘟疫之地!', '大家都聽著!大家都聽著!所有的英雄都應該聆聽這號召的聲音!暴風城已經發出了備戰的號召!所有勇士都應該拿起武器，一同面對來自東部王國北部地方天譴軍團的威脅!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，聯盟的安全岌岌可危!聯盟的英雄們-去向指揮官阿胥拉姆·瓦羅菲斯特報到吧，他的大本營就在奧特蘭克山脈北邊的冰風營地!', '找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10374, 'zhTW', '戰鬥的號角:瘟疫之地!', '部落的英雄們，請聆聽這召喚的聲音-部落召喚你們迅速行動起來!戰鬥的號角已經吹響，所有勇士都應拿起武器，準備與天譴軍團殊死作戰!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，部落的安全岌岌可危!部落的英雄們-去向高級執行官德靈頓報到吧，他的大本營就在提里斯法林地東部的亡靈壁壘!', '找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10428, 'zhTW', '失蹤的漁夫', '在我們受傷發燒的客人夢裡，她提到一個漁夫，科倫，在藍謎島西南方海岸外的銀謎小島上身陷苦痛。對於一切所發生的事情，沒有人有機會調查它，但是我確實感到有一點擔心。或許有些你能做的事，$n?', '到藍謎島海岸外的銀謎小島東南方碼頭找到科倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10455, 'zhTW', '失控的侵略', '我們已經加快了種植生命之林的速度，但不知為何那裡的山貓失去了控制。$B$B曾經他們的數量很穩定，但現在森林山貓卻開始侵犯希爾瓦納，而且不久前才發生一連串令人不快的事件。$B$B我懷疑是迷霧拉斯的阿拉卡在背後搞鬼，但目前的問題是與山貓本身有關。$B$B我會很感謝要是你肯幫助我們解決這個問題。', '琳娜·月泉要你以最快的速度殺掉12隻森林山貓後回到劍刃山脈的希爾瓦納找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10456, 'zhTW', '巡邏的狼群', '這些卑鄙的部落種族已經在東邊落腳了。他們帶來了一大隊可怕的恐狼用來作為坐騎及守衛。$B$B這些守衛已經進犯過這座橋隔開了我們。他們一直在偷襲我們生命之林授粉的關鍵生物，精靈龍。$B$B使用東邊的出口穿越血槌深谷的橋樑到東邊的鋸齒山脊去，並將他們的尾巴帶來作為證明!', '琳娜·月泉要你帶給她4根雷霆王恐狼尾。完成後，回到劍刃山脈的希爾瓦納找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10457, 'zhTW', '保護我們自己', '雖然你對於保護我們這裡的新家提供了很大的幫助，但我還是覺得生命之林需要更多的防護。$B$B拜託，帶著這個我施放了自然之力的小樹枝。使用在我栽種的樹叢幼苗身上時，就會出現一股暴風雨加快樹人防衛者的成長速度。$B$B這些樹人是這個樹叢的防禦關鍵，特別是如果你不打算把希爾瓦納當成你長久的家。', '在5株果樹幼苗身上使用琳娜的樹枝以召喚今後生命之林的防護者。完成後回到劍刃山脈的希爾瓦納找琳娜·月泉。', '', '', '生命之林防衛者召喚', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10486, 'zhTW', '失控的侵略', '在雷霆王被曼諾洛斯之血轉化成魔獄獸人前他們曾是一個驕傲的獸人氏族。$B$B最近我們從污染下游河谷的巨魔手中重新發現了這個獸人村落。他們在雷霆王氏族遺棄這裡後進駐。$B$B我們要保住這個地方，而我需要你來幫忙。$B$B在鋸齒山脊的南方及西方，那裡有一群放血者已經變成我們的災難。他們不停地繁殖。$B$B殺掉他們並於完成後回來找我。', '葛德雷克要你去殺掉12個刃翼血信。完成後回到劍刃山脈的雷霆王村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10487, 'zhTW', '龍的粉末', '聯盟最近進駐西邊，使用他們精靈法術在短期內建立一個城鎮及果園。我們得將她們的防禦削弱以防她們不會也生出勇氣來。$B$B我有個方法可以達成目的甚至更好。我要你越過橋到西南方去，經過血槌深谷進去生命之林。$B$B攻擊她們在生命之林的精靈龍防禦並將在它們翅膀中找到的魔法粉塵帶回來給我。', '葛德雷克要你去取得4份精靈龍粉末。完成後，回到劍刃山脈的雷霆王村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10488, 'zhTW', '保護我們自己', '有了你帶回的魔法粉塵，我製作了一個魔法藥膏可助於我們本身的防護。$B$B我們的恐狼完美的將坐騎，守衛及朋友集結於一身，但是那些聯盟的人渣在鋸齒山脊那獵殺它們。$B$B$N，我要你將這個藥膏使用在我們那些恐狼朋友身上。下一次聯盟再派他們的獵殺團隊來時就會得到一個野蠻的驚喜。$B$B要小心還是有一些狼可能不喜歡這個藥膏，將會反咬你。', '在5隻雷霆王恐狼身上使用葛德雷克的藥膏來強化它們及鋸齒山脊的防禦。完成後回到劍刃山脈的雷霆王村找葛德雷克。', '', '', '強化雷霆王恐狼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10489, 'zhTW', '砍伐古老之樹', '懸賞!$B$B斯卓霖普·深根，戰爭古樹及希爾瓦納南方的生命之林防衛者領袖。$B$B往西邊過了橋後越過血槌深谷就可以找到他。$B$B將他的大箱帶回給雷霆王村旅館內的吐查克·雙爪。', '取得斯卓霖普·深根的樹幹並送到劍刃山脈的雷霆王村給吐查克·雙爪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10502, 'zhTW', '血槌巨魔', '希爾瓦納有一個比雷霆王村的部落還要致命的威脅。$B$B我說的是居住在這些山區中的巨魔。這裡的南邊還有東邊，深谷的底部住著血槌氏族。雖然他們並不是唯一威脅我們的巨魔氏族，他們卻是最靠近我們的一族。$B$B我要你往南穿過生命之林，然後轉向東邊的道路前往他們的前哨站。在血槌前哨站盡可能的殺光那些血槌巨魔。', '指揮官天影要你去血槌前哨站殺死30個血槌巨魔。當你完成這個可怕的任務後，回到劍刃山脈的希爾瓦納向他回報。', '', '', '殺死血槌巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10503, 'zhTW', '劍刃的威脅', '雷霆王村有一個比希爾瓦納的聯盟還要可怕的威脅。$B$B我說的是居住在這些山區中的巨魔。這裡的西邊，深谷的底部住著劍刃氏族。雖然他們並不是唯一威脅我們的巨魔氏族，他們卻是最靠近我們的一族，當初我們就是打敗他們才佔領這個地方。$B$B往北越過鋸齒山脊，然後順著路往下走，你就會到達他們的要塞。在劍刃要塞還有劍刃庭園盡可能的殺光那些劍刃巨魔還有劍刃迅猛龍。', '吐查克·雙爪要求你在劍刃要塞還有劍刃庭園殺死30個劍刃巨魔還有10隻劍刃迅猛龍。任務完成時回到劍刃山脈的雷霆王村向他回報。', '', '', '殺死劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10504, 'zhTW', '劍刃巨魔', '血槌氏族的北邊有一個更嚴重的威脅:劍刃要塞。$B$B這些劍刃巨魔是山區之中最強的氏族，受到被稱為弒龍者戈魯爾的古羅還有他的七個兒子所支持。$B$B現在我們已經解決了血槌氏族，是時候該轉移目標到他們的競爭對手了。$B$B從血槌要塞往北穿過深谷直到你到達劍刃要塞還有劍刃庭園。盡可能殺光裡頭的劍刃巨魔。', '指揮官天影要你在劍刃要塞還有劍刃庭園殺死30個劍刃巨魔。任務完成時回到劍刃山脈的希爾瓦納向他回報。', '', '', '殺死劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10505, 'zhTW', '血槌巨魔', '在劍刃氏族的南方還有另外一個威脅:血槌前哨站。$B$B雖然血槌巨魔不是這些山區中最強的氏族，不受名為弒龍者戈魯爾的古羅厚愛，不過他們緊接在第二名。$B$B現在我們已經解決掉劍刃氏族，是時候轉移焦點對付他們的對手了。$B$B從劍刃要塞往南經過深谷一直走直到你到達血槌前哨站為止。盡你所能的殺光附近的血槌巨魔。', '吐查克·雙爪要你在血槌前哨站殺死30個血槌巨魔。任務完成時回到劍刃山脈的雷霆王村向他回報。', '', '', '殺死血槌巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10506, 'zhTW', '情況緊迫', '因為狼群的減少，部落正在尋找代替品。不幸的是附近剛好有可替代的狼。$B$B在東邊深谷下方的血槌巨魔養了一大群強壯的狼作為他們自己的守衛。我不想派你去殺掉那些恐狼，那麼為何這次我們不做點不同的呢?$B$B我已經由精靈龍的翅膀所自然落下的粉塵中提煉出一種魔法粉末。將它灑在那些恐灰狼的身上使部落對他們失去興趣。', '琳娜·月泉要你帶著她的縮小粉末並使用在5隻血槌恐狼身上，你可以在血槌前哨站及血槌深谷找到這些狼群。完成後，回到劍刃山脈的希爾瓦納找她。', '', '', '削弱血槌恐狼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10510, 'zhTW', '進入德萊尼礦坑', '看到有人願意幫助這裡真的是太好了!$B$B波爾葛利姆和我是探險者協會的一員，我們到這是要知道我們能從這些山中得到什麼。我們聽過各種不同的傳說，我等不及要紮營開始探險。$B$B有一個東西特別吸引了我的注意力。夜精靈提到東邊深谷下面有個地方叫做德萊尼礦坑。就在血槌前哨站的南方盡頭。我想要那邊土生土長的一些水晶。', '波爾葛利姆·頑錘要你去收集5個德萊尼礦坑水晶然後回到劍刃山脈的希爾瓦納找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10511, 'zhTW', '怪酒', '如果我要現在就開始這個假期，那麼我就需要更多的酒。不幸的是，這些精靈們根本不懂發酵的藝術。$B$B我偶然聽到深谷那邊的血槌巨魔有很多的酒。我想要試看看。$B$B幫我個忙吧?往南方出發經過生命之林，接著下了斜坡往東進入血槌前哨站帶幾瓶酒給我?我聽說他們有幾大桶的酒就放在附近而釀酒大師會帶著酒到處提供給所有的巨魔。', '波爾葛利姆·頑槌要你拿到11瓶血槌蠻禁烈酒給他。一旦你完成後，將這個帶到劍刃山脈的希爾瓦納給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10512, 'zhTW', '灌醉劍刃巨魔', '我不會再嚐一口那個難聞的穢物!不過這倒是給了我一個點子。$B$B<波爾葛利姆眼中閃了一下。>$B$B計畫是這樣的。我們知道那些血槌氏族實際上每天都要牛飲這些東西。但我好奇他們的敵人，劍刃巨魔，是怎樣想的?$B$B$N，我要你帶著這些剩下的廢物去看看是否能夠讓這些劍刃巨魔喝醉。你可以從血槌前哨站往北通過深谷的地方找到他們。', '帶著這個血槌蠻禁烈酒並試著用來讓5個劍刃巨魔喝醉。如果你成功了，回到劍刃山脈的希爾瓦納找波爾葛利姆。', '', '', '喝醉的劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10516, 'zhTW', '復仇者的服飾', '我知道這很怪，但我真的想要待在這個籠子裡。這讓我有絕佳的機會去進行我來這要做的事;收集劍刃氏族的資訊。$B$B我隨時都可以離開，不過我想要取回我的劍跟盾。$B$B他們的兩位領導者擁有我的裝備。卓克嘎姆擁有我的劍而瑪格多克擁有我的盾。$B$B要是你有需要的話，拿著並使用這個來自血槌前哨站的啤酒到南邊去降低他們的防衛並引誘他們兩個，不過要小心他們那些沒喝酒還清醒著的守衛!', '帶回復仇者瓦黎恩之刃及復仇者瓦黎恩之盾。然後將這兩項物品帶回劍刃山脈的劍刃要塞給復仇者瓦黎恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10518, 'zhTW', '插上戰旗', '我要你去從他們的一位勇士身上將劍刃旗幟偷來，帶到南方的血槌前哨站去。將旗插在他們的北槌哨塔上。$B$B這樣會激怒血槌氏族，他們會毫不留情的攻擊你。不過這樣也會將他們的敵意集中在劍刃要塞上，進而遠離希爾瓦納。$B$B在你打倒葛恩·葛羅巴諾斯拿到他的頭盔時就表示你完成任務了。將頭盔帶回希爾瓦納去。$B$B$N，這並不容易。帶一兩個朋友跟你一起去吧。', '在北槌哨塔頂端使用劍刃旗幟來誘引葛恩·葛羅巴諾斯。將旗幟跟葛恩·葛羅巴諾斯的頭盔送到劍刃山脈的希爾瓦納給指揮官天影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10520, 'zhTW', '協助大德魯伊鹿盔', '打擾一下，$c，如果可能的話，我想佔用你一點時間。達納蘇斯的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究項目。雖然我不知道詳細的情況，但是我可以告訴你，正是伊范達爾·鹿盔親自負責這項研究。要是你感興趣的話，請直接去達納蘇斯的塞納里奧區找他談談。', '與達納蘇斯的大德魯伊范達爾·鹿盔談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10524, 'zhTW', '雷霆王氏族手工藝品', '神器上的標記指出它原來是由雷霆王氏族獸人製造的。這些獸人在變成魔獄獸人之前曾住在雷霆王村這。$B$B血錘巨魔曾暫時居住在這個村落直到最近被部落趕走了。你曾經聽說過人們試著尋找其他遺失的神器。你的腦海中浮現關於這些神器的記憶，那是一個鼓、一支箭及一片石板。$B$B到劍刃要塞去找到它們並帶回給洛克嘎·血握。', '取回雷霆王氏族大鼓，雷霆王氏族之箭以及雷霆王氏族石板。將它們隨同雷霆王氏族手工藝品一起帶回，交給劍刃山脈雷霆王村的洛克嘎·血握。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10525 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10525, 'zhTW', '幻象導覽', '$R笨蛋。你差點毀掉這個鼓!$B$B我費盡千辛萬苦來到這裡，直到現在才有所收獲。至少你能夠在別人都失敗，或是更慘的地方成功。$B$B是時候喚出幻象來引領你找到最後一個我一直在找尋的神器。$B$B拿著這個代表我的靈魂的熾熱之魂碎片。用它來將你的身體轉化為火，將你的靈魂變為幻象指引你前往最後發現雷霆王神器的位置。', '使用熾熱之魂碎片將你的靈魂轉化成幻象導覽模式。在你的幻象導覽帶領你找到最後一個雷霆王神器的所在地後，與雷霆王村的洛克嘎·血握談談。', '已發現最後的雷霆氏族神器', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10526, 'zhTW', '雷霆之矛', '如果那個我讓你看見的幻象屬實，那麼你就得往下到河谷以及血槌深谷的南方盡頭。在那你會找到德萊尼礦坑。$B$B到礦坑的後方去，取得雷霆之矛。不用管其他東西!我對於礦坑內的水晶沒有興趣，還有巨魔也是一樣。$B$B一但你拿到這個矛就馬上帶回來這裡給我!$B$B還有，$N，你要非常小心……我可不願去想要是它有任何損傷的話你會發生什麼事。', '洛克嘎·血握派你去取回雷霆之矛。將它帶回劍刃山脈的雷霆王村給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10542, 'zhTW', '他們偷走我的水煙筒和酒!', '提洽里曾經是一個非常友善的食人妖。我來這裡是為了?血槌氏族如何釀造酒。但是如果我這樣做，血槌氏族會埋了提洽里然後讓他的屍體放在這裡腐爛!$B$B最不好的事情是他們偷走了我的水煙筒!$B$B那麼，你想要幫助提洽里嗎?你幫我找回我的水煙筒。提洽里認為偷走它的巨魔往西南方礦坑的礦坑方向去了。$B$B還有當你到那邊的時候，順便撿一些酒!', '取得提洽里的水煙筒還有10份血槌蠻禁烈酒。帶到劍刃山脈交給血槌深谷的巫醫提洽里。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10543, 'zhTW', '葛瑞諾克和柯爾卡赫，我為你們而來!', '提洽里一直在等待著他復仇的時刻!$B$B他們活埋提洽里讓他自生自滅的那天，就是由葛瑞諾克·巴拓伯恩領導。隔天劍刃氏族的柯爾卡赫到南方發動攻擊的時候踢到提洽里的頭。$B$B我要他們死光光!$B$B你可以在血槌前哨站的南槌哨塔頂端找到葛瑞諾克。柯爾卡赫則在劍刃要塞最北邊的一棟建築物的頂端。柯爾卡赫的身邊有清醒的防衛者，所以你要使用這瓶酒來引誘他離開他們。', '巫醫提洽里要你殺死最令他痛苦的人，葛瑞諾克·巴拓伯恩還有柯爾卡赫。完成後回到劍刃山脈的血槌深谷找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10544, 'zhTW', '詛咒你們的氏族!', '提洽里要向所有的巨魔復仇!$B$B提洽里在世的時候曾經是一個法力強大的巫醫。假如你去我的墳墓就可以找到邪惡重型神像。$B$B將神像的魔力灌注在劍刃要塞還有血槌前哨站的建築物以及塔的門口。你對他們下的巫毒將會召喚出一個邪惡的靈魂而你必須擊敗它。如此你就可以詛咒他們的建築物。$B$B但是要注意，假如你嘗試去詛咒一個已經被詛咒的建築物，你將會喚出另一個詛咒的靈魂!', '使用邪惡重型神像詛咒5個在劍刃要塞的建築物或者高塔以及血槌前哨站的2個建築物或者高塔。任務完成時回到劍刃山脈的血槌深谷找巫醫提洽里。', '', '', '已詛咒劍刃要塞建築物', '已詛咒血槌前哨站建築物', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10545, 'zhTW', '劍刃氏族的喝酒大會', '正如提洽里所說，他幫他的血槌朋友釀造酒。但是他卻沒說背後的原因。$B$B血槌氏族正在面對可怕的困境。劍刃氏族快打垮他們了，而他們需要新的武器來幫助戰鬥。$B$B這個時候提洽里想出了一個很棒的方法。為什麼不釀造一種完美的酒，使這種酒可以提高你們的力量同時又削弱敵人的戰鬥力呢?只不過，提洽里不知道這個方法是否能成功。$B$B所以，你必須把這種酒帶到劍刃要塞看它是否有效用!', '提洽里要你使用血槌蠻禁烈酒讓5個劍刃巨魔喝醉。任務完成後回到劍刃山脈的血槌深谷找巫醫提洽里。', '', '', '劍刃巨魔已喝醉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10555, 'zhTW', '莫名的不安', '拉斯汗阿拉卡所研究的法術是很邪惡的。他們一手抓滿-還是應該說一爪?-自己身上的羽毛當做施法材料!$B$B我並不覺得那是一種善良的法術。我來這邊是為了研究他們的法術，可惜我無法接近他們。$B$B你可以這樣做:將他們的法術施放在你自己身上，然後回來找我。你必須找到他們的其中一本法術書，位置就在迷霧拉斯的樹林高處。$B$B除非你自己可以長出羽毛，我看是長不出來啦，你就必須取回他們的一些羽毛。', '收集18根掉落的拉斯汗羽毛，然後在迷霧拉斯的樹梢上閱讀拉斯汗書卷。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10556, 'zhTW', '達成要求', '書中的圖案文字告訴我們要去迷霧拉斯的魔力法陣使用阿拉卡的羽毛才能施展該法術。$B$B令人困惑的圖案看起來像是一個阿拉卡正在為自己注入卡里瑞的精神力量。', '在拉斯汗的法陣使用一把羽毛，然後在卡里瑞的精神退去之前回去找希爾瓦納的達藍艾歐。', '', '', '讓達藍艾歐分析卡里瑞光環', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10557, 'zhTW', '測試飛行:ZC號', '我製造了一個很棒的裝置，ZC號，我確定他的功能沒有問題，但是……你願意幫我測試它嗎?$B$B傷殘補助金可是很高的喔!$B$B跟我旁邊的雙胞胎兄弟，瑞利談話。祝你好運，$N。測試完畢後回來找我。或者……假如你因為重大傷殘無法回來找我，你的戰友可以來向我回報取得你的報酬。', '跟瑞利·薩普納伯談話然後使用ZC號。回去托斯利基地找塔利·薩普納伯。', '測試塔莉的實驗', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10565, 'zhTW', '維克尼爾之石', '多年來維克尼爾的阿拉卡一直是我們的眼中釘。他們奉行的是一種奇怪的信仰，指使他們做出瘋狂的行為。他們現在把這種水晶隨身攜帶，使用在不好的地方。$B$B我對他們的儀式有一點了解。他們把水晶拿到他們的法陣將能量注入其中。村裡的人都想了解多一些。伏擊幾個阿拉卡直到你得到水晶為止，將水晶灌滿能量，然後交還給我。', '收集一個維克尼爾水晶並且在維克尼爾的法力之環使用它，然後把充能維克尼爾水晶交給摩克納薩爾村的德托克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10566, 'zhTW', '錯誤的試驗', '我已經打造了四根魔杖，我相信可以加強阿拉卡的水晶力量。將這些魔杖帶到索格瑪領土，然後使用在巨魔奴隸身上。$B$B你必須從該區的阿拉卡身上取得注入能量的水晶。$B$B當你測試出來哪一根魔杖是最好的，回來找我。', '對一個阿拉卡巨魔奴隸測試每一根德托克的魔杖。每一根魔杖都需要消耗一個灌能維克尼爾水晶。', '', '', '測試第一根魔杖', '測試第二根魔杖', '測試第三根魔杖', '測試第四根魔杖', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10567, 'zhTW', '製造墜飾', '魯安曠野的阿拉卡依靠著烏鴉神諭使，他們神祇的信使讓他們聚集在一起。$B$B他們相信那些神諭使從天上看著他們，而他們的神則在天上將教義宣揚給信使們，最後信使們從天上下來傳達神的旨意。$B$B神諭使對阿拉卡的靈魂有著非常強的支配能力。他們使用一種魔法的墜飾正好是我們所需要的。$B$B殺死一些阿拉卡並奪取他們的爪子以引起神諭使的注意。把爪子放在他們的祭壇就可以得到信使的注意。', '在魯安歐克神諭者法陣找到6個魯安歐克之爪來召喚1個烏鴉神諭使。殺死它然後將神諭使墜飾交給魯安曠野的泰姆昂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10580, 'zhTW', '這些該死的地精跑去哪裡了?', '儘管我們在這裡的工作已完成，但是有件事讓我覺得很抱歉:我們迫使托斯利還有他的地精朋友們離開了。我們沒有選擇;他們的工程技術還有科學實驗在小樹林裡把我們過去所做的努力弄的一團糟。假如你願意幫我去看看他們後來的情況我會很感激。他們最後的消息是往東方過橋而行。我確定他們後來一定是轉往南方了，遠離雷霆王村。到南方的鋸齒山脊尋找他們移動的線索。', '指揮官天影要求你去劍刃山脈南邊的鋸齒山脊尋找托斯利還有其他地精去向的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10581, 'zhTW', '跟著痕跡走', '很好，我是來警告你在山脊上不會找到任何東西。千萬不要跟著散落地上的備用零件痕跡走，那會通到托斯利基地的!你不會在那邊找到托斯利還有其他地精的。', '講了一圈，原來R-3D0型機器人已經告訴你跟著散落地面的零件痕跡上斜坡到剃刀山脊，你就會發現地精們在一個叫做托斯利基地的地方。假如你找的到托斯利的話，跟他談談吧。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10584, 'zhTW', '收集能量轉換器', '北邊劍刃崗哨那些愚笨的巨魔一直在襲擊我們的能量轉換器!你要為我把它們追回來，可以這麼說。$B$B毫無疑問的，巨魔巨大、笨拙的手毀壞了轉換器。所以，我要你做的就是從他們那裡釋放能量並在組合的電流體上使用這個原始電磁集電器來裝住它。$B$B你可能會感覺有點疼痛，所以在它被裝在磁力發電機球體裡時你需要「殺掉」它。', '托斯利要你帶著原始電磁集電器去收集5個電流體。任務完成時回去劍刃山脈的托斯利基地找托斯利。', '', '', '收集電流體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10594, 'zhTW', '測量共振的頻率', '帶著這些掃描器到美聲山脊。當你依照地上的位置裝設它們，你會創造出彼此相疊的掃描區域來讀取水晶的振幅。但是你必須站在五個震動區域的交錯點，這樣一來我才能獲的我所需要的資料。$B$B你的掃描器同時也會與其他人放置的掃描器產生共鳴。$B$B喔對了，在過程中將會產生一個裂縫!我完全不知道會跑出什麼東西來。', '地鐵地精尼克偉恩寇要你以下列的方式來安裝震盪頻率掃瞄器。你必須在安裝完畢時同時處在五個震盪區域之中。$B$B完成之後，回到劍刃山脈的托斯利基地向地鐵地精尼克偉恩回報。', '已測量鳴唱水晶的共振頻率', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10607, 'zhTW', '烏鴉神的秘密預言', '在葛瑞許納什，烏鴉智者留下的圖騰使得阿拉卡人可以聽見烏鴉的話語。不幸的是，阿拉卡的語言對我們來說太難以解讀。$B$B使用神諭使墜飾就可以讓我們了解他們的語言。你將可以捕捉阿拉卡的靈魂以了解他們的語言。當你身體內充滿著阿拉卡的靈魂時，你可以接近圖騰了解它們想傳達的訊息。$B$B幫助我們了解它們的訊息吧，$n。', '殺死葛瑞納阿拉卡取得理解烏鴉語的效果2分鐘。在法術的效果之下，你可以從四個聖物之中得知四段預言。當你得知四段預言之後就回來找我。', '', '', '獲得第一段預言', '獲得第二段預言', '獲得第三段預言', '獲得第四段預言', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10608, 'zhTW', '清除水晶的障礙', '那些該死的岩石鐮奪怪阻礙了我在美聲山脊所做的研究!當我在挖掘那些歌唱水晶的時候，它們總是跑來破壞我研究那些水晶的美妙旋律。$B$B你看起來像是可以幫我解決這個問題的人。幫我去南邊殺死那些水晶鐮奪怪。', '地鐵地精尼克偉恩寇要你殺死10個水晶鐮奪怪然後回到劍刃山脈的托斯利基地向他回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10609, 'zhTW', '龍生蛋，蛋生龍?', '我在我的醫生領域裡頭研究龍之精華的用途。對於一個生病的人來說，我想它們可能是一種萬靈藥!我需要有人去南邊的美聲山脊幫我取回一些。$B$B你願意帶著我的時光相位轉換器使用在剛從虛空龍蛋孵出來的虛空幼龍嗎?不管它們會變化成什麼，幫我取回精華。$B$B關於這件事，我想補充一下，我並不確定它們變化的結果因為我們所使用的是非常不穩定、改變時間與空間的科技產品。', '收集3個原始虛空龍之精華、3個年輕的虛空龍之精華還有3個成熟的虛空龍之精華。交給劍刃山脈托斯利基地的費茲特「醫生」克羅克塔可。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10614, 'zhTW', '風中低語', '我已經尋遍外域有關摩克納薩爾的謠言，但沒有任何關於它的蹤跡。最後，我們可能找到他們的家。但是既然現在就在這裡，我心裡卻充滿著不安。在我搜尋的期間，心神不安使我到深夜都無法入睡。他們會接受我嗎?我……知道他們領導人的名字:李歐羅克斯。將他找出來。這次你必須當我的眼睛。', '到劍刃山脈的摩克納薩爾村找到李歐羅克斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10615, 'zhTW', '魯安曠野', '你幫助我揭示關於這裡阿拉卡本質的情報，將有很多其他人有很大的興趣知道。我們已經被塞納里奧遠征隊的成員拜訪過，那些人也已經變得掛慮阿拉卡在劍刃山脈這裡的意圖。你應該出外尋找他。他的名字是泰姆昂，而你將在魯安曠野的永恆樹林裡找到他。沿著這裡西方的道路走，然後在剃刀山脊分岔處向北走。最後，當路在刀刃峽谷分開時，沿著西邊的道路走。', '與永恆樹林的泰姆昂交談，永恆樹林在劍刃山脈的魯安曠野。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10617, 'zhTW', '絲翼之繭', '絲翼之繭的絲在我們村子有非常多種的用途。我們永遠都不夠用，絲越多越好。$B$B要從幼蟲身上採集繭是很困難的，因為一旦它們開始成長變化繭就被破壞了。$B$B我們的士兵們都忙於應付對村莊的攻擊行動。假如你可以幫我們收集一些它們的繭來，那就太好了。', '摩克納薩爾村的塔爾瑞克要你從絲翼幼蟲身上收集8個絲翼之繭。$B$B在幼蟲成長成絲翼之前殺掉它，不然繭就會被破壞。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10618, 'zhTW', '最柔軟的翅膀', '捕獵絲翼幼蟲對我們的年輕士兵來說是一項困難的挑戰，但幸運的是，即使他們從幼蟲身上採集繭失敗了，我們仍然可以使用已孵化的絲翼翅膀。$B$B事實上，我們對翅膀的使用量大於繭，而且希望越多越好。$B$B假如你願意幫助我們去外面收集一些翅膀就太好了。', '摩克納薩爾村的希歐瑪納要你收集12個彩虹之翼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10620, 'zhTW', '山脊的威脅', '當托斯利決定搬到外域去後我們就開始幫忙，自此之後就一直幫下去。$B$B現在看來我們終於斬除了一些根源。所有瘋狂的科學家們繼續進行著他們的計畫，而我們非正式騎兵是來保護他們的。$B$B我們現在需要你去北方的剃刀山脊，或是東邊的鱗翼沙洲，殺死行者來保持淨空。他們是住在岩石礦脈間的鬼祟蜘蛛，會對沒有戒心的過路者一撲而上。', '迪希·迪娜要你殺死10隻山脊行者。任務完成後，回到劍刃山脈的托斯利基地向她回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10632, 'zhTW', '割下你的牙齒', '托斯利還有他的科學家們能夠得到你的幫助真是太好了。可惜我並沒有時間可以沉迷在「個人」嗜好上面。$B$B假如你想要幫這裡的忙，你只要聽從我的要求去做，而且是馬上，我需要一些武器。$B$B我們的槍在射程內很有殺傷力，但是當敵人靠近，我們則需要擁有一些強大的近戰武器做預備。$B$B北邊剃刀山脊的匕爪尾龍的牙齒可以做出精良的武器鋸齒劍身，連我都感到畏懼。', '洛薩克·鐵面要你取回5個特級銳利匕爪牙齒。完成後回到劍刃山脈的托斯利基地交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10657, 'zhTW', '操控閃電', '我們並沒有將ZC號的使用量維持在預算之內。但是，我發現剃刀山脊的鱗翼風蛇擁有閃電般的氣息還有腺體可以供我們利用。$B$B我已經重新磨光了電磁收集器好讓它可以吸收雷擊。總而言之，當它遭受雷擊的時候它的保護殼上有一個反應圈可以讓加強雷擊的能量，直到雷擊被吸收為止。喔，而且它會減慢你的速度。$B$B去吧，把收集器打開，然後幫我們帶回來一些便宜的燃料吧。', '托斯利要你使用再極化的磁力發電機球體從鱗翼風蛇身上吸收25個閃電之擊。同時，收集5個鱗翼閃電腺。然後回到劍刃山脈的托斯利基地交給他。', '', '', '吸收閃電之擊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10671, 'zhTW', '一磅多的肉', '$N，我有別的事情要你去做。那些知識份子之中的一個人想要研究在雷森平台那出現像惡魔般的血肉野獸，就在剃刀山脊的北邊。$B$B更重要的是，他們想研究那邊的血肉野獸的肉。$B$B<迪希做出了一個作嘔的表情。>$B$B不過當然，他們不想把自己的手弄髒，而且他們只想要蒼穹能量肉體，這可不是所有的血肉野獸都有的。$B$B我說，拿人的手短，但是你又能怎麼辦呢?', '迪希·迪娜要你取得5個蒼穹能量肉體然後回到劍刃山脈的托斯利基地交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10674, 'zhTW', '捕捉神奇的光球', '北邊雷森平台的雷森伊斯利開發了一些有趣的科技產品。$B$B我相信他們不會介意你使用這個陷阱捕捉幾個他們浮在空中的粉紅色光球吧?反正那些光球八成只是裝飾品而已。$B$B這個陷阱有一個特殊的功能，當陷阱開啟時會吸引一個飄浮的光球飛向它。當然，它同時也會驚動到那些雷森關於你的到來。', '托斯利要你使用聖光陷阱捕捉15個雷森光球。任務完成後回到劍刃山脈的托斯利基地向他回報。', '', '', '已捕捉雷森光球', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10675, 'zhTW', '給他們地精式的解脫!', '<血從托斯利的臉上流了下來。>$B$B這些球體是由虛空的能量還有靈魂所組成的，部分的靈魂竟然是地精的靈魂!$B$B他們真大膽!我們那些往北旅行的同伴們，就是他們殺死的嗎?!$B$B$N，你必須阻止這件事，而唯一的解決方法就是殺死他們的首領，奈薩斯王子洛薩恩。$B$B但是你必須將他從隱匿中引誘出來。我猜你只要殺死大量的雷森伊斯利就會引誘他現身。$B$B將他身上的靈魂收集品交給我，那東西一定在他身上。', '托斯利要你取得靈魂收集品然後回到劍刃山脈的托斯利基地交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10682, 'zhTW', '協商時間……', '當我們抵達魯安曠野，巨龍教徒們正集中在黑翼集會所，經由這個隧道通往西方。不過現在，它們正接近我們這裡，$B$B我需要你去找到巨龍教徒的監督者。他在魯安曠野的各個營地之間定時巡邏。$B$B與他商量一下。讓他知道有協商的空間，不過我們不會寬恕或允許大規模屠殺野生生物，包括樹林的砍伐也是一樣。', '林木守衛蕭恩要你去與監督者奴阿爾協商。完成後回到劍刃山脈的永恆樹林找林木守衛。', '與監工努阿爾的談判已完成', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10690, 'zhTW', '獸穴之后', '懸賞!$B$B瑞瑪，雷霆王村南邊鋸齒山脊的獸穴之后及主要的防衛者。$B$B出到鎮外向東走，越過橫跨血槌深谷的橋找到她。她隱居在橋南邊的隧道內。$B$B帶著她死亡的消息回到希爾瓦納的指揮官天影那裡。', '殺死瑞瑪然後通知在劍刃山脈之希爾瓦納的指揮官天影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10704, 'zhTW', '闖入亞克崔茲的方法', '你發現的阿塔莫水晶中鑲有一則訊息。奈薩斯王子哈拉瑪德已經提供我們關於對抗風暴要塞非常重要的資訊。$B$B他告訴我們他們將一把鑰匙分為兩片裂片，兩者合一時可開啟要塞的亞克崔茲衛星。$B$B一半由波塔尼卡的一位古老生物叫扭曲分裂者所持有。另一半由麥克納爾裡的操縱者帕薩里歐擁有。$B$B將兩個裂片帶來給我，我會將他們合成亞克崔茲鑰匙。', '阿達歐派你去取得亞克崔茲鑰匙的頂部和底部裂片。將它們帶回去給他，他會將他們合成亞克崔茲鑰匙後交給你。', '', '去找沙塔斯城的阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10705, 'zhTW', '先知烏達羅', '我希望你在我告訴你那些從我的爪牙手上取來的好幾片卡拉伯爾勳章都只是複製品時不要太震驚。<阿卡瑪打開他的手掌給你看一個完全相同的勳章。>我的死亡誓言者跟我盡可能的守住這個秘密不讓伊利丹知道。不過我們還是會懷念那最後的一片。烏達羅到我的夢裡宣稱他已找到了那最後的一片勳章。糟糕的是他正被凱爾薩斯監禁在風暴要塞的亞克崔茲裡。去找到他並看看他到底知道些什麼。', '到風暴要塞的亞克崔茲找到先知烏達羅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10709, 'zhTW', '團聚', '所以你來自傳送門外的世界嗎?並且你知道雷克薩。噢是的，我跟他很熟。其實，他是我的兒子。但他在很久以前，做出了他的選擇。他不屬於我們之中的一員，而他在這裡也不受歡迎。有這些血槌巨魔，我們的麻煩已經夠多了。要知道:身為一個混血兒並不代表你就是摩克納薩爾。', '回到劍刃山脈的雷霆王村找雷克薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10710, 'zhTW', '飛行測試:美聲山脊', '我一直都在搬弄著ZC號，因此我準備好進行另一個測試了!你想要幫忙嗎?$B$B下一次的飛行會很短，但是很快!$B$B嗯……雖然我確定不會有危險……不過我有準備這個，呃，同意書要你簽署。這只是形式上啦，我跟你保證!$B$B祝你好運囉!要升空時跟瑞利談談，實驗結束後回來找我!', '簽署塔利的切結書，接著與瑞利·薩普納伯談談以使用ZC號。完成後回到托斯利基地找塔利·薩普納伯。', '拋開謹慎，放手一搏', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10711, 'zhTW', '飛行測試:雷森平台', '$n，我將ZC號的效能提高了百分之三十。那將會一個等同你的體重的測試物品和風阻比率發射達到新的高度!想要驗證我的理論嗎?這個實驗應該會將你發送到接近雷森平台的地方。$B$B與瑞利談談……他會幫你準備好升空。', '與瑞利·薩普納伯談談以使用ZC號。完成後回到托斯利基地找塔利·薩普納伯。', '抵達天空的極限', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10713, 'zhTW', '……行動的時間到了', '我們不能袖手旁觀任由他們在我們身邊屠殺魯安曠野。我們首要的考慮一定是那些樹。$B$B$C，我要你回到曠野去幫我們傳達一個非常特別的訊息。我要你殺掉每一個你接觸到的砍伐者!$B$B如果他們不講道理，或許他們會聽從這種更武斷的勸導!', '到魯安曠野去殺掉10個巨龍教團砍伐者，完成後回到劍刃山脈的永恆樹林找林木守衛蕭恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10714, 'zhTW', '精靈的翅膀上', '如果巨魔們騷擾摩克納薩爾，那麼我將制止他們及他們的跟隨者。巨魔們是一種頭腦簡單的生物，而且摩克納薩爾煩惱對他們而言也幾乎沒有好處。$B$B一定有其他原因。$n，帶著精靈，我的老鷹，並刺探血槌領導人間的談話。他可以進入而不會被發現，但我們不能。', '找到忙著聊天的一對血槌監工及血槌預言者，接著使用雷克薩的哨子召喚出精靈來暗中監視他們。完成後，回到劍刃山脈的雷霆王村找雷克薩。', '', '', '竊聽血槌巨魔的計畫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10715, 'zhTW', '進入翻騰峽谷', '那麼，你的雷克薩想要我為他製作一種毒藥嗎?我將給他所想要的，但是是有價格的。即使對朋友，一定也有一個價格。免費的東西破壞友誼。$B$B首先，你必須冒險一小段路程，往西南方到翻騰峽谷。$B$B在那裡的磨坊裡，有一些在整個外域，或任何地方，最毒的生物。我說的是地殼穿刺者，而做這毒劑，將需要收集它們的腺體來給我。', '沙伯邁恩男爵已經告訴你為了要做出雷克薩需要的毒藥，你必須取得7個地殼穿刺者的毒腺。一旦你完成任務，返回到劍刃山脈位於血之環的沙伯邁恩男爵處。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10717, 'zhTW', '行竊侵入者', '原諒我，但我無法不去偷聽你跟蕭恩的對話。我想要幫忙你。$B$B我正在研究黑翼集會所的事，並幫忙德魯伊們與他們交易。$B$B我很想要幾隻他們的幼龍;這會有助於我們藉由了解他們所尊敬事物來判斷我們真正對抗的是什麼。$B$B不過首先，我們得需要一些網子。我注意到魯安曠野外圍的巨龍教團盜獵者身上有一大堆網子。', '沙彌亞·暗示者要你去取得5個巨龍教團織網並帶回劍刃山脈的永恆樹林交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10718, 'zhTW', '靈魂會說話', '$N，既然你能看見我，有樣東西你必須告訴雷克薩。我知道他在尋找他的族人，並且我也知道他們在那裡。摩克納薩爾，正如他們被人所知道的，在剃刀山脊東方有一個村莊。去那裡，帶給雷克薩這則消息。他的人處境危險，而且我知道他將想要來幫助他們。', '嘎姆·狼伴已經告訴你摩克納薩爾，雷克薩的族人，住在那裡。對劍刃山脈之雷霆王村的雷克薩說這件事。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10720 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10720, 'zhTW', '最小的動物', '那些巨魔們，儘管頭腦簡單的可以，還是會注意到你散播此毒劑於他們整個營地。因此，我將教你怎樣徵募自然界一種最小的生物來幫助你完成這項任務。$B$B藉由在這個鼓上奏出簡單的節奏，你能哄騙一隻土撥鼠遵循你的命令。$B$B往北邊走，進入匕爪峽谷穿過血之環，在血槌營地附近有一個土撥鼠的巢穴。一旦你獲得土撥鼠的幫助，利用它把毒散播到血槌的小桶子內。', '在土撥鼠的巢穴使用科多獸皮鼓。在控制土撥鼠後，在血槌營地的3只小桶裡下毒。當那完成時，返回劍刃山脈之雷霆王村的雷克薩那裡。', '', '', '對綠點烈酒桶下毒', '對成熟的月光酒桶下毒', '對發酵種子啤酒桶下毒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10721, 'zhTW', '葛魯洛克的豬時光', '$N，我有一頭寵物野豬名字叫胡佛。他想要幫助你去整整附近戈魯爾的兒子之一。$B$B葛魯洛克居住在一個稱為詛咒之谷的地方。當你到達那裡時，放開胡佛。那個古羅將有一段時間會在附近追趕胡佛，而你就取回他看守的一只袋子，並且把它交給沙伯邁恩男爵。$B$B想去詛咒之谷就由北邊的斜坡道向下走，並向東穿過飛龍之末。詛咒之谷在東方的邊界上。', '取得葛魯洛克的袋子，並且將它帶到劍刃山脈的血之環交給沙伯邁恩男爵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10722, 'zhTW', '黑翼集會所的集會', '我知道該怎麼做!$N，你必須假扮成監督者奴阿爾參加這場會議!$B$B集會所裡的巨龍教徒都有一套標準的全套穿著，因此去收集他們不要的碎塊，在你湊足後，將它們拼成一個偽裝。$B$B假扮成監督者奴阿爾與克菲斯·暗鱗談話看看他有怎麼反應，然後回去找林木守衛蕭恩。$B$B你朝著龍骨隧道的方向順著路經過烏鴉林及葛瑞許納什到盡頭就會找到這個集會所了。', '從各個巨龍教徒身上收集足夠的戲服碎塊來做出一套監督者偽裝。使用這個偽裝來參加和克菲斯·暗鱗的會議，並將你的發現回報給劍刃山脈裡永恆樹林的林木守衛蕭恩。', '已出席與科菲斯·暗鱗的會面', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10723, 'zhTW', '食龍者柯爾葛羅姆', '我們尋找的古羅是柯爾葛羅姆，食龍者。由於沙伯邁恩的陷阱，你將可迅速解決掉古羅。你將發現他接受圓面之地巨魔們的獻祭。$B$B沿著來自血之環北方的道路，然後再向魯安曠野的西方。穿過隧道往西北去。$B$B首先，殺死巨魔們取下他們的頭。我們將送出一個訊息。在他的祭壇上設置陷阱。當他死掉時，在他身邊插入這可怕的圖騰 - 沒有一個人會誤解那訊息。$B$B做掉這魯莽的人。$B$B<米莎咆哮著。>', '去圓面之地並且從圓面巨魔那裡收集3個可怕圖騰。於柯爾葛羅姆的祭壇使用沙伯邁恩的陷阱，並召喚及殺死食龍者，柯爾葛羅姆。$B$B當柯爾葛羅姆死掉後，把3個可怕圖騰放置在他屍體附近，然後返回劍刃山脈之雷霆王村的雷克薩那裡。', '', '', '放置可怕圖騰', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10724, 'zhTW', '劍刃囚犯', '在我到達這些山之後不久，我受到一隊劍刃巨魔的攻擊。$B$B雖然我在與他們戰鬥中順利逃脫，並且殺死很多巨魔，但他們帶走了我的翼龍，里奧克，還把他關了起來。精靈們已經找到他，被關在戈魯爾之巢外劍刃營地中央的一只籠裡。$B$B其中的一個巨魔必定帶著鎖他的鑰匙。找到它，那精靈就能用它打開關里奧克籠子的鎖。$B$B你可以在下方匕爪峽谷的最北邊找到那些巨魔的營地。', '殺死劍刃巨魔取得雙足翼龍的牢籠鑰匙。取得鑰匙後，找到雙足翼龍的牢籠並且使用精靈之哨召喚打開籠子的精靈。在里奧克自由後，返回劍刃山脈的雷霆王村向雷克薩回報。', '', '', '', '', '拯救里奧克', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10742, 'zhTW', '攤牌', '終於到了。我們會把苟克從他的巢穴引出來，然後我們就會殺了他。隨著苟克一死，這些血錘巨魔就再也無法威脅摩克納薩爾了。到位於戈魯爾之巢外苟克的祭壇去，接著吹響我的號角。我會出現，跟你一起面對這個戈魯爾之子。', '在苟克祭壇上使用雷克薩的戰爭號角，接著殺掉苟克。完成任務後回到劍刃山脈的雷霆王村找雷克薩。', '', '去找劍刃山脈的雷克薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10747 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10747, 'zhTW', '巨龍教團的幼龍', '我需要檢查生長在黑翼集會所的那些幼龍。$B$B那裡有一大群幼龍在洞穴裡外飛來飛去，同樣的也有為數不少的蛋，可能你一靠近就會孵化。$B$B$N，麻煩你拿著這個網子去活抓一堆幼龍給我。$B$B朝西前進越過龍骨橋或經過龍骨隧道可以找到它們。順著路一路經過葛瑞許納什及烏鴉林到盡頭去。', '沙彌亞·暗示者要你使用黑色幼龍網補抓10隻巨龍教團黑色幼龍。將這些幼龍帶到劍刃山脈的永恆樹林給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10748, 'zhTW', '麥克斯納爾必須要死!', '他們讓我們別無選擇，$N。是時候把黑翼集會所帶來的威脅做個了結了，殺掉他們的領導者，灰喉麥克斯納爾。$B$B我不知道你在那裡的時候有沒有瞥見他，但他是龍族的一員，半人半龍。而且他很強壯，所以不要低估了他!$B$B快點把它了結，幸運的話你就能保衛永恆樹林和魯安曠野的安全。', '代表永恆樹林的塞納里奧遠征隊的德魯伊，以及魯安曠野當地的生命，林木守衛蕭恩要你去殺掉灰喉麥克斯納爾。完成後回到劍刃山脈的永恆樹林找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10749 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10749, 'zhTW', '沙伯曼男爵的毒藥', '來，把這個拿給你的主人。我確定無論理由為何，雷克薩都會好好使用它。$B$B喔，記得提醒他，他欠我一次。$B$B他知道我要什麼，因此我相信不管如何他都會把東西交給我，我們會比你想像的還要更快再次見到面。$B$B現在，當個聽話的小<男孩/女孩>把這個送去給雷克薩吧。', '將沙伯曼男爵的毒藥送到劍刃山脈的雷霆王村給雷克薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10752 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10752, 'zhTW', '前進梣谷', '最近萊恩·狼行者從達納蘇斯經過奧伯丁而來，朝著梣谷前進;他提到跟熊怪有關的事情。我沒有機會去問她的情況如何但是也許你可以去找她並且提供協助$C。順著奧伯丁的南部道路走。一旦你到達梣谷邊界繼續順著路走。你會在那邊找到阿斯特蘭納還有萊恩·狼行者。', '在阿斯特蘭納跟萊恩·狼行者談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10753, 'zhTW', '搶救自然', '燃燒軍團所犯下的暴行不記其數。即使在我們對話的同時，他們也派出燃燒軍團部隊對付外域的生物們。無力抵抗燃燒軍團的力量，外域的生物們一個接一個的倒下。$N，幫助我停止他們這些破壞自然的罪行。$B$B越過山丘往東邊去，你會看到燃燒軍團的破壞已經遍及整個刀刃峽谷了。殺死犯下這些罪行的元兇，惡魔墮落者，還有盡可能殺死越多的魔誓越好。', '殺死4隻魔誓鱗翼，4隻魔誓匕爪還有2隻惡魔墮落者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10770, 'zhTW', '一些餘燼', '這裡東北方在我們上方的高原上躺著我老家之被燒盡的灰。在燃燒軍團派他們的灼熱小鬼去燒盡我們之前，有一大片森林在那些繁盛。在過了如此多個死寂的世紀後，我疲倦而老去的心甚至仍然渴望復仇。有太多敵人了以致於不能收復土地，但是你能使他們害怕。$B$B確定你願意幫助我?', '苔木長老想要你殺死8個灼熱小鬼，然後返回魯安曠野找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10771, 'zhTW', '來自灰燼', '如果你沿著東方的道路並上到山的側面，然後轉向北方，那你將會來到我長期失去的家。曾經在那裡有一棵樹。我早已忘記它的名字了。很久以前燃燒軍團召喚灼熱小鬼和其他火焰生物。我的家就被毀滅了，而我的族人逃離了。現在只有我留下來。$B$B我已經保存了一些可以在肥沃的火山土壤種植的鐵樹根種子。他們的魔力是強大的。為我做這件事，而我將與你同享一批被遺忘已久的財寶。', '苔木長老想要你旅行至斯卡德，並將鐵根種子種植在三座不同的肥沃的熔岩泥土內，然後返回魯安曠野到他那裡。', '', '', '南方火山泥土', '中央火山泥土', '北方火山泥土', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10783, 'zhTW', '沙伯邁恩男爵', '我的計畫是。我們毒害巨魔們，然後消滅他們的古羅主人。在我於這些山中旅行期間，我遇見一個名為沙伯邁恩男爵的人。他精通鍊金術，且可確信會幫助我們。你可以在這裡北邊峽谷下方的血之環那裡找到他。無論他需要什麼代價，都由你來判斷是否接受。', '與在劍刃山脈之血之環的沙伯邁恩男爵談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10784, 'zhTW', '粉碎血槌營地', '<吐查克傾身接近低聲地說。>$B$B$N，你到目前為止對我們所做的比與巨魔戰鬥還要自豪。而當我對雷克薩所計畫的有信心時，我將依舊要求你在返回之前，粉碎血槌營地的巨魔們。$B$B那樣我們將加倍確信結果。$B$B要到那裡，向北走，走下雷霆王村外面的斜坡道。然後，在斜坡道底部，向西走越過飛龍之末，並向北穿過翻騰峽谷和匕爪峽谷。', '吐查克·雙爪要求你殺死10個血槌槌兵和5個血槌術士。之後，返回到劍刃山脈之雷霆王村的他那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10785, 'zhTW', '它是一個陷阱!', '在這個世界沒有其他原因能比戈魯爾和他兒子們更能令我憎惡!他們屠殺我的族人-我的孩子-現在我將嚐到報仇的滋味!$B$B我已經利用龍火做成一個陷阱，如果你夠聰明的話，你甚至可以使用它來殺死古羅。$B$B快一點就對了，把陷阱拿給雷克薩。$B$B我渴求報仇的火焰必須要被撲滅!', '將龍火陷阱交付給劍刃山脈之雷霆王村的雷克薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10786, 'zhTW', '圓面之地大屠殺', '我知道雷克薩有計畫要你向圓面之地前進。當你到那裡時，我有一些想要你去做的事情。$B$B我們必須把握任何能打倒這些山上的巨魔的機會，否則他們將佔領我們，這樣我們就會流血並且無意義的死去!$B$B圓面之地位於西北方遠處。向北走到魯安曠野，然後從那裡走向西邊，穿過隧道並通過烏鴉林。$B$B$N，我想要你殺掉圓面之地的劍刃巨魔們。徹底消滅他們!', '屠殺5個劍刃蠻卒和3個劍刃薩滿，然後返回劍刃山脈之雷霆王村的吐查克·雙爪那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10795, 'zhTW', '與多爾哥克的約會', '非常好，我已經看見你在附近，我一直有一些重要的事情想對你講。$B$B有報告說由於某些原因，血槌巨魔計畫對希爾瓦納和魯安曠野發動攻擊。我們不知道是誰或者什麼東西在催促他們做這事，但是我打算趁早摧毀他們的計畫!$B$B攻擊將從血槌營地開始。沿著魯安曠野外面斜坡道向西北走下去，你就會找到它。我要你殺死他們的領導人，多爾哥克!', '指揮官海法斯·石牆要你殺死血槌營地的多爾哥克。在你完成之後，返回劍刃山脈的永恆樹林找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10796, 'zhTW', '粉碎血槌營地!', '我聽說你到目前為止對我們所做的比與巨魔戰鬥還要自豪。現在，我將要求你再次面對他們。我要你摧毀血槌營地的巨魔!$B$B要去那裡，就從魯安曠野外的斜坡往西北方走下去。你將在斜坡道的底部找到他們。$B$B祝你好運，$c!', '中尉費爾威德要你殺死10個血槌槌兵和5個血槌術士。之後，返回劍刃山脈的永恆樹林找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10797, 'zhTW', '古羅的支持', '一個小雕像標誌從多爾哥克死亡的爪子上掉下來。它與某個古羅有明顯的相似處。$B$B想必斜坡上往東，魯安曠野的永恆樹林有個指揮官海法斯·石牆會對這東西感興趣!', '將柯爾葛羅姆的徽章帶到劍刃山脈的永恆樹林交給指揮官海法斯·石牆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10798, 'zhTW', '拜訪男爵', '這是個壞消息。食龍者柯爾葛羅姆是最近對抗希爾瓦納血槌計畫的幕後主使者!為什麼他在操縱他們，而不只是利用劍刃，我不知道。但如果我們要對付古羅，我們就需要幫助。我認識一個精通各種奇特魔法的人。他的名字叫沙伯邁恩男爵，你可以在血之環找到他，回到西北邊的斜坡下，再往西南方通過峽谷。請他幫我們製作一個給古羅的陷阱。', '和沙伯邁恩男爵談談關於製作陷阱的事。他就在劍刃山脈的血之環。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10802, 'zhTW', '食龍者柯爾葛羅姆', '我們必須讓巨魔看看我們不是好欺負的。我們必須送出一個訊息。$B$B到圓面之地殺死那裡的巨魔。把他們的頭帶回來。$B$B然後去柯爾葛羅姆的祭壇，並且為他在那裡佈下陷阱。柯爾葛羅姆將會出現，而你必須誘騙他進入陷阱。當他死掉時，在他的屍體附近裝好你的可怕圖騰，以便巨魔能見他們倒下的主人和兄弟，並且知道想毀滅我們所需付出的代價。', '去圓面之地從圓面巨魔那裡收集3種可怕圖騰。在柯爾葛羅姆的祭壇使用沙伯邁恩的陷阱來召喚並殺死食龍者柯爾葛羅姆。$B$B當柯爾葛羅姆死掉時，把3種可怕圖騰放置在他的屍體附近，然後返回劍刃山脈的永恆樹林找指揮官海法斯·石牆。', '', '', '設置可怕圖騰', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10803, 'zhTW', '圓面之地大屠殺', '我知道我們有讓你向圓面之地前進的計畫。你去那裡的時候，我有些事情想要你去做。$B$B我們必須掌握任何能打倒這些山裡的巨魔的機會，否則他們將征服我們，這樣我們就會流盡鮮血無意義的死去!$B$B圓面之地位於西邊。走到西南方，越過橋並穿過隧道。在烏鴉林的西邊可以找到他們。$B$B$N，我想要你清除圓面之地的劍刃巨魔。', '屠殺5個圓面蠻卒和3個圓面薩滿，然後返回劍刃山脈的永恆樹林找中尉費爾威德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10805, 'zhTW', '戈魯爾之巢大屠殺', '你已經證明你是足智多謀的，現在我想要請你加入我與戈魯爾和他的兒子間的戰鬥。$B$B劍刃家族擁護古羅，當你在別處消減他們的數量時，你還沒有對付到他們最強大的力量。$B$B戈魯爾只用最強壯的巨魔保護他的巢穴外部，而那些就是你必須殺死的人。往北走穿過匕爪峽谷，然後你就會在盡頭發現戈魯爾之巢。', '沙伯邁恩男爵要你和你的朋友殺死10個劍刃執行者，5個劍刃戰鬥法師，5個劍刃劫毀者和他們領導人，費葛羅姆的任務。當你已經設法完成這項偉績時，返回劍刃山脈的血之環找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10806, 'zhTW', '攤牌', '我們面對劍刃巨魔的主人，苟克，的時刻已經來到。那也是著手處理事情的時刻，去告別古羅的生命。$B$B拿著我的璽戒。當你到了苟克祭壇時，使用它，而我到來加入你。$B$B我們將一同毀滅苟克。', '在茍克祭壇使用沙伯邁恩的徽章，然後殺死茍克。當完成時，返回劍刃山脈的血之環找沙伯邁恩男爵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10810, 'zhTW', '破損的面具', '當你檢視破損的面具的時候，你聽見面具發出奇怪的聲音。假如面具沒有破損的話你可以聽見更清楚的聲音。$B$B魯安曠野的歐瑪利·贊普奈可能可以修理這個面具。', '將破損的面具帶給魯安曠野的歐瑪利·贊普奈。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10812, 'zhTW', '神秘面罩', '沒問題，修好了。你問我這是什麼?哦，這是一個通訊裝置-它可以讓那些笨蛋跟彼此通訊。你知道的呀，燃燒軍團!我建議你把這個面具交給野蠻領主安德烈利安。他就在那邊走來走去。他總是不停的移動。$B$B那就快點去吧，他一直很想得到這個東西。', '將神秘面罩帶給魯安曠野的野蠻領主安德烈利安。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10819, 'zhTW', '邪誓防毒面具', '我有一個非常特殊的任務要交給你，$N。我要你滲透進入東邊的煉冶場:怒氣。當你到達煉冶場你將需要戴上邪誓防毒面具然後找到軍團通報器。一旦你找到通報裝置就跟裝置另一邊的人談話，不管他是誰。$B$B假如一切順利你就可以誆騙這些惡魔做出一些不光明正大的事情!試著告訴那個惡魔，煉冶場:怒氣已經造反了。$B$B祝你好運$C。', '戴著邪誓防毒面具使用煉冶場:怒氣的軍團通報器。$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10821, 'zhTW', '你被開除了!', '末日哀嚎者沒有想辦法阻止那場叛變嗎?她真大膽!她一直以來都在質疑我的權威。不論如何，這會是她的最後一次了。你必須召喚她然後親自解決她。$B$B她的煉冶場守衛擁有可以召喚她到煉冶場:怒氣的鑰匙。取得五把鑰匙然後啟動五座軍團尖塔。那些方尖塔的啟動時間很短，所以確認要全部同時啟動。記住，煉冶場守衛擁有比較多的鑰匙。', '殺死末日哀嚎者然後回到永恆樹林向野蠻領主安德烈利安回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10825, 'zhTW', '未知的真相', '這個奇怪，魔法的寶珠從阿拉卡的廓羽下方落下。$B$B充滿著怪異，紫色的光輝，寶珠跟著一個聽不到的節拍跳動著。拿著它使你略感不舒服，因此你迅速地把它放到你的背包裡。$B$B或許穿過隧道越過龍骨橋，在魯安曠野西邊的林木守衛蕭恩會有興趣看看它?', '將葛瑞納寶珠送到劍刃山脈的魯安曠野給林木守衛蕭恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10829, 'zhTW', '樹老長者必須知道', '這真麻煩!阿拉卡害長者和保衛者被邪惡靈魂附身!但是有一位長者無論如何不能被影響。他的名字是樹老長者，如果我們要拯救烏鴉林的樹木，那你必須立刻去找他!回到烏鴉林。你可在過了葛瑞許納什的道路分岔處找到他。', '林木守衛蕭恩要你尋找並且與樹老長者交談，一位傳說住在劍刃山脈的烏鴉林裡的長者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10830, 'zhTW', '淨化樹林', '葛瑞納已經讓葉鬚樹人和石化樹人被邪惡的可伊靈魂佔據。$B$B我們必須拯救這些樹，否則整個烏鴉林很快將永遠消失!$B$B結合在葛瑞許納什找到的葛瑞許納什寶珠魔法，和兇暴烏鴉身上的一根可怕幼羽。$B$B使用結合成的驅邪羽毛引出可伊靈魂並盡快殺了它。石化樹人對這儀式來說太強大了，但如果我們拯救了足夠的葉鬚樹人，他們也將獲得自由。', '收集5個葛瑞許納什寶珠和5根可怕幼羽，然後將它們合併成驅邪羽毛。使用這些羽毛驅除並殺掉5個佔據烏鴉林葉鬚樹人的可伊靈魂。等你完成，返回劍刃山脈的烏鴉林找樹老長者。', '', '', '葉鬚樹人已驅魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10843, 'zhTW', '不知道從什麼時候開始……', '不知道從什麼時候開始，我們就已經在和劍刃巨魔作戰了。$B$B我們已經設法把他們擊退，因此現在他們只微弱的掌握住劍刃崗哨。按你來的路回去，在剃刀山脊的西南邊緣。$B$B藉由殺死他們的領導人，葛諾斯·布羅格納，向我證明你的價值。$B$B讓我們看看當你與巨魔作戰時，你是塊什麼料。', '為了向摩克納薩爾證明自己，李歐羅克斯已經命令你殺死葛諾斯·布羅格納，劍刃崗哨的巨魔領導人。完成後返回劍刃山脈的摩克納薩爾村找李歐羅克斯，不然就不要回來。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10845, 'zhTW', '殺死幼龍之母', '我的獵人剛完成美聲山脊的偵察任務回來。看來寄生於那些水晶的虛空龍已經大幅增加並威脅到我們。$B$B既然你已證明你是一個有能力的殺手，讓我們看看你的$c技能是否敵的過一隻成年的龍。$B$B向南方穿過鱗翼沙洲並找到美聲山脊。進入那裡並殺死他們的母親，魔翼。', '李歐羅克斯要你殺死魔翼 。等你殺死她再返回摩克納薩爾村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10846, 'zhTW', '了解摩克納薩爾', '<李歐羅克斯用一種讓你的靈魂凝結的眼神注視著你的眼睛。>$B$B你來到摩克納薩爾，但是你不了解我們。你不了解我們鬥爭以求生存。$B$B假如你要了解我們，那麼你必須忍受一次那種鬥爭的滋味。$B$B南方是維克尼爾阿拉卡。他們在一個叫做索格瑪領土的洞穴裡奴役一群巨魔，而他們的領導人，維克也在那裡。$B$B殺了他!', '要開始你對摩克納薩爾的了解，就要殺掉維克，維克尼爾阿拉卡的領導者。然後，返回劍刃山脈的摩克納薩爾村找李歐羅克斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10851, 'zhTW', '敵人的圖騰', '尊敬一個人的祖先有正確的方式，也有錯誤的方式。$B$B劍刃巨魔帶著圖騰，但是他們並非用它們來表現他們的尊敬。相反的，他們想使用它們去操作並且控制。$B$B我們應該偷取他們的圖騰，因為他們不值得擁有!我們會把它們拿來做更好的利用。$B$B去西方的劍刃崗哨，就在剃刀山脊的西南邊。殺死劍刃秘法師和粉碎者，並從他們那裡拿走圖騰!', '收集5個劍刃氏族圖騰交給劍刃山脈的摩克納薩爾村的招魂師多赫加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10853 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10853, 'zhTW', '呼喚靈魂', '美聲山脊的虛空龍靈魂需要解放。$B$B虛空龍不永遠都是虛空龍。他們過去是黑龍。$B$B但是，由於這個世界的毀滅，一股虛空能量改變了一切，並且產生了改變幼龍蛋的副作用。$B$B現在他們全都是以前自身的扭曲版本。我們必須幫助他們找到平靜。$B$B要這樣做就要去殺死一隻靠近召靈圖騰的龍，然後自它身上取走它的靈魂。', '招魂師多赫加要你使用召靈圖騰收集8個次級虛空龍靈魂然後回到劍刃山脈的摩克納薩爾村交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10859, 'zhTW', '收集寶珠', '雷森伊斯利有一種奇怪的儀器會發出微小、粉紅色光芒的飄浮光球。它們讓我想起靈魂。$B$B它們不會與伊斯利死亡時所釋放的大黃球相混淆，這些完全是別種東西。$B$B我要你到北方的雷森平台設置一些圖騰，這些圖騰將會攻擊粉紅光球。$B$B把它們帶回來給我這樣我才能確切地判斷它們是什麼。', '招魂師多赫加要你使用寶珠召集圖騰收集15個雷森光球。任務完成後回到劍刃山脈的摩克納薩爾村向他回報。', '', '', '收集雷森光球', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10860, 'zhTW', '摩克納薩爾的款待', '餓嗎，$r?偉大的靈魂會幫助那些自助者。如果你想要掙一頓飯，我建議你注意聽著，因為布拉格爾那裡不會給你任何免費的東西，而且也不可口!$B$B剃刀山脊和鱗翼沙洲的迅猛龍及鱗翼具有你從未嚐過之最美味的兩種佳餚中所需要的東西。把他們的迅猛龍肋骨和毒蛇肉帶來給我，我將為你做出這兩道菜。$B$B我甚至可以教你如何自己烹煮它們，如果你動作快的話。', '女總管瓦拉給你一份可以製作兩道他最喜歡的菜餚的材料名單，包含了3個迅猛龍肋骨還有3份毒蛇肉。回到劍刃山脈的摩克納薩爾村的把材料交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10888, 'zhTW', '那魯的試煉:瑪瑟里頓', '在你被那魯認可之前，你必須通過四次考驗。$B$B只剩一個障礙了，凡人。召集一支軍隊並且前往地獄火堡壘深處的瑪瑟里頓巢穴。一路殺進密室的中心，並毀滅那邪惡的腐敗者!', '撒塔斯城的阿達歐要你殺死瑪瑟里頓。', '', '去找沙塔斯城的阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10893, 'zhTW', '長尾是關鍵', '黑翼巨龍教徒集中在隧道裡，我們難以應付此情勢。十分坦白的，他們為數眾多。$B$B當我們有辦法注意到他們中的任何人太過接近，事實就是如果他們認真攻擊，我們就會被佔領。$B$B目前的狀況需要有人穿過隧道到另一端那兒，並且殺掉他們的領導人，德拉卡·長尾。打算找點樂子嗎?', '殺死德拉卡·長尾，龍骨隧道裡的巨龍教徒領導者。一旦你完成，回到劍刃山脈的龍骨隧道看守者月影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10894 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10894, 'zhTW', '龍骨看守者', '嗯，我不確定我們應該怎麼做。我不適合當軍事行動的策劃人。$B$B看守者月影會知道怎麼做。他目前正前往我們在西邊的龍骨隧道的防禦工事，就在龍骨橋的尾端。我們有部隊在那邊以防那些教徒們想搞鬼。$B$B拜託你，請以最快的速度將信件送到他手中。', '將會見紙條交給劍刃山脈的龍骨隧道入口的看守者月影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10910, 'zhTW', '死亡之門', '現在燃燒軍團有一個更大的威脅。南邊有一個被人稱為死亡之門的傳送門，它開啟另一個可怕的世界，燃燒軍團在那邊養殖他們致命的地獄獵犬。$B$B要去那裡，就離開永恆樹林往東邊斜坡上去。沿著往南的路走，通過刀刃峽谷，雷森平台，剃刀山脊和鱗翼沙洲。然後，走下斜坡進入維克哈爾看臺，再通過摩克納薩爾南邊的隧道進入死亡之門。$B$B當你到達的時候，使用這個德魯伊信號。', '野蠻領主安德烈利安請你到死亡之門。到達之後，使用德魯伊信號召喚一個永恆樹林德魯伊好讓你可以跟他們談話。$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10927, 'zhTW', '殺光爬行者', '指揮官天影要清空這條通道以促進我們跟避難營的貿易。我不能離開我的哨站所以我只好把任務交到你的手裡。清空通道然後馬上回報指揮官天影!', '連接贊格沼澤和劍刃山脈隧道的哨兵月語要你殺死6隻洞穴爬行者然後回報希爾瓦納的指揮官天影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10928, 'zhTW', '殺光爬行者', '吐查克·雙爪要清空這條通道以促進我們跟沼澤叛徒的交易。我不能離開我的哨站所以我把任務交到你的手上。清空這個通道然後馬上回報吐查克·雙爪!', '連接贊格沼澤和劍刃山脈隧道的蠻兵葛拉赫要你殺死6隻洞穴爬行者然後回報雷霆王村的吐查克·雙爪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10931, 'zhTW', '回到艾克索達', '你在艾克索達的主人希德摩斯想見你。他關切你的訓練進度，除此之外的事情我不太清楚。', '跟艾克索達的希德摩斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10932, 'zhTW', '回到艾克索達', '你在艾克索達的主人希德摩斯想見你。他關切你的訓練進度，除此之外的事情我不太清楚。', '跟艾克索達的希德摩斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10933, 'zhTW', '回到銀月城', '你在銀月城的主人艾爾崔想見你。他關切你的訓練進度，除此之外的事情我不太清楚。', '跟銀月城的艾爾崔談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10934 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10934, 'zhTW', '回到銀月城', '你在銀月城的主人艾爾崔想見你。他關切你的訓練進度，除此之外的事情我不太清楚。', '跟銀月城的艾爾崔談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10946, 'zhTW', '[Ruse of the Ashtongue]', '[Olum\'s sacrifice was tremendous.  I would never have asked him to give up his life myself.  But it is done.$B$BIf we\'re to lure Illidan back into a false sense of security, we need to do his bidding - at least for now.$B$BI command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted.$B$BYou are to perform the deed that Illidan demands.  Take this cowl; it is magical in nature.  You will appear to be one of my men to any who see you slaying Kael\'s phoenix, Al\'ar.]', '[Travel into Tempest Keep and slay Al\'ar while wearing the Ashtongue Cowl.  Return to Akama in Shadowmoon Valley once you\'ve completed this task.]', '灰舌氏族的詭計', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10947, 'zhTW', '[An Artifact From the Past]', '[Illidan\'s attention is now on Kael\'thas, thanks to you.  The time has come to make our move.$B$BI\'ve had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill.  Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal.$B$BThere might be a way to retrieve this artifact, however.  Legend speaks of a place in Azeroth guarded by bronze dragons...  a place where past and present meet.  It is there you will find what we seek.]', '[Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal.  Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley.]', '', '去影月谷找守望者牢籠的阿卡瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10948, 'zhTW', '', '', '[Travel to Shattrath City to tell A\'dal about Akama\'s request.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10949, 'zhTW', '', '', '[Travel to the entrance to the Black Temple in Shadowmoon Valley and speak to Xi\'ri.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10957, 'zhTW', '[Redemption of the Ashtongue]', '[When Illidan obtained the Broken\'s allegiance, Akama was our wisest.  He knew that openly opposing the Betrayer would lead to the extinction of our race.$B$BInstead he has plotted and schemed for this very moment under utmost secrecy.  Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland.  No one this close to Illidan has ever been able to deliver such a terrible blow to him.$B$BHelp Akama free his soul and he will grant you access to Illidan\'s sanctum.]', '[Help Akama wrest control back of his soul by defeating the Shade of Akama inside the Black Temple.  Return to Seer Kanai when you\'ve completed this task.]', '', '去找黑暗神廟的先知卡奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10958, 'zhTW', '', '', '[Find Akama\'s Deathsworn inside the Black Temple.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10959, 'zhTW', '[The Fall of the Betrayer]', '[With Illidan\'s lieutenants defeated, Akama will be able to force open the doors to Illidan\'s sanctum.  Be ready to bring your force inside as soon as Akama does.$B$BWe still do not know what has become of Maiev, but we must make our move without her.$B$BI hope your force is up to the task.  Illidan will not be pleased to see Akama.]', '[Seer Kanai wants you to defeat Illidan inside the Black Temple.]', '', '去找黑暗神廟的先知卡奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10974, 'zhTW', '貝許爾的靜止密室', '伊斯利恩在劍刃山脈最北邊人稱貝許爾平臺的沙洲上有一塊領地。根據鑰匙碎片上的記載，他們在貝許爾有更大規模的監獄。我應該跟你提一下，伊斯利恩稱呼那些監獄為靜止密室。$B$B這個鑰匙碎片可以讓你進入其中一個特殊的靜止秘室叫做靜止密室A。帶著這個鑰匙碎片前去調查吧。$B$B調查完成以後我的幻影將會在貝許爾平臺等你，跟我交談。', '使用伊斯利恩鑰匙片 - A打開在劍刃山脈貝許爾平臺的靜止密室A。$B$B將調查密室得到的證據交給貝許爾平臺的指揮官阿密爾的影像。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10976, 'zhTW', '奈薩斯王印記', '我必須知道伊斯利恩在奧齊頓的法力墓地裡關著什麼樣的東西。$B$B在你與貝許爾的靜止密室野獸戰鬥的時候，你可能會看到一樣叫做奈薩斯王印記的東西。如果你找到這樣東西，馬上交給我!這是要製作通往法力墓地裡頭的靜止密室鑰匙所欠缺的最後一樣材料。', '劍刃山脈貝許爾平臺的指揮官阿密爾的影像要你交給他1個奈薩斯王印記。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10983, 'zhTW', '乾癟的莫格多克', '莫格多克真聰明!他派葛羅克來城市，找幫助。血槌氏族需要幫助。莫格多克說找幾個強壯的小伙子來劍刃山脈找他。他站在血之環的塔頂。莫格多克真聰明!', '到劍刃山脈血之環外面的高塔頂端找乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10989, 'zhTW', '乾癟的莫格多克', '乾癟的莫格多克在塔頂等你。他叫我找一個$r$c就像你這樣。你去找他說重要的事情。去吧，但是不要告訴別人。這是秘密!', '前往劍刃山脈的血之環找乾癟的莫格多克。他就站在劍刃山脈，血之環外的塔頂，丘特的旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10994, 'zhTW', '[Chasing the Moonstone]', '[If the essences are combined within a rare gemstone such as a Southfury moonstone, you\'ll be able to release them when you\'re prepared to challenge Anzu.$B$BThe only problem is that Southfury moonstones are only found on the Azshara side of the river, on the cliffs near the river\'s source.$B$BTragedy befell the last night elf party that sought the stone. Their boat is still anchored in the river near where they sighted the moonstone. Keep your eyes open and approach the site by land from the Azshara side.]', '[Bring a Southfury Moonstone to Morthis Whisperwing at the Cenarion Refuge.]', '', '去找贊加沼澤的莫西斯·語翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10995, 'zhTW', '葛魯洛克的兩個龍頭骨', '詛咒之谷位在東邊飛龍之末的邊界處。戈魯爾之子，葛魯洛克就在那邊策劃他的愚蠢計劃。$B$B我聽說他的一樣物品被人用巧妙的手法給偷走了。是你做的嗎?可惜他沒有在過程中喪失性命。$B$B如果我們想重獲自由，我要你搶走他最重要的資產，那就是他父親屠殺黑龍軍團的龍頭骨。你要取得龍頭骨的唯一方法就是殺死他。', '取得葛魯洛克的龍頭骨，帶到劍刃山脈的血之環外，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10996, 'zhTW', '瑪格歐克的寶箱', '瑪格歐克在剃刀山脊的山坡上以及東南邊巡邏。他的父親指派他為東邊山區的看守者，而他則享受著殘虐當地任何看不順眼的生物。$B$B為了我的部族生存權，身為戈魯爾之子的他必須被消滅。這就要靠你幫忙了。$B$B瑪格歐克總是隨身攜帶一個寶箱。將他的寶箱帶來給我，證明你已經殺死他。你可以拿走寶箱裡頭的任何東西。', '取得瑪格歐克的寶箱，帶到劍刃山脈的血之環，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10997, 'zhTW', '就連古羅也有軍旗', '你聽說過撒塔斯城嗎，$c?它的西北邊上方有個地方叫做阻礙之丘，一個你只能藉由飛行坐騎才能到達的地方。$B$B其中一位戈魯爾之子 - 史拉格，離鄉背井到那邊並且控制當地的戈杜尼巨魔。即使距離如此遙遠，我們也不能讓他坐大，免得當他的兄弟們都被殺死之後會回來復仇。$B$B$N，你必須到那邊並且取得他的軍旗，證明他已經被擊潰了。', '取得史拉格的軍旗，帶到劍刃山脈的血之環，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10998, 'zhTW', '搶奪魔典', '還有一個古羅要殺:史庫洛克·靈魂研磨者。他的藏身處非常隱密，但是有一個辦法可以引誘他現身。$B$B他曾經受過一個叫做邪惡的梵戈的巨魔術士訓練，你必須取得他的魔典!$B$B梵戈必須由你加上其他四名人員才能召喚，每個人站在一個火焰之環內。到東北邊的山區，靠近破碎荒野的附近尋找梵戈之環。$B$B還有一點，$N，假如你聽見梵戈說什麼變大之類的話，快回到你的火焰之環裡面!', '你必須取得梵戈的邪惡魔典。把它交給劍刃山脈血之環外塔頂的乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10999, 'zhTW', '[One Shot, One Kill]', '[Bring me 8 trogg stone teeth.]', '[Bring me 8 trogg stone teeth.]', '', '去找喬‧蘭姆西。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11000, 'zhTW', '深入靈魂研磨者獸穴', '這本魔典是殺死史庫洛克的關鍵。$B$B在靈魂研磨者獸穴大聲的閱讀這本魔典以啟動儀式。接著一個叫做靈魂研磨者的東西會伴隨著許多史庫洛克的靈魂受害者出現，這些靈魂會試著破壞靈魂研磨者。你必須阻止這些靈魂這麼做，直到史庫洛克被迫在這個世界上現身為止。$B$B往北穿過匕爪峽谷，到達血之環的另一邊。$B$B獸穴的位置就在你到達戈魯爾之巢之前的右手邊。$B$B將史庫洛克的靈魂帶回來。', '取得史庫洛克的靈魂並且交給劍刃山脈血之環外塔頂的乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11001, 'zhTW', '[Vanquish the Raven God]', '[We must waste no time in dealing with the raven god. You must take the essence-infused moonstone to a place of great power in order to lure the god from the relative safety of the Emerald Dream.$B$BDescend into the Sethekk Halls and set the moonstone in the clutches of the raven\'s claw. You\'ll find it in the chamber before the talon king\'s hall.$B$BAnzu must be made believe that his followers have gathered to welcome him back into the world. Once he has manifested, show him no mercy!]', '[Slay the Raven God and return to Morthis Whisperwing at Cenarion Refuge.$B$BThis quest must be completed in Heroic dungeon difficulty.]', '', '去找贊加沼澤的莫西斯·語翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11004, 'zhTW', '[World of Shadows]', '[Sky Commander Adaris was seriously injured during a Skettis incursion.  He\'s been in and out of consciousness since.$B$BI fear he has succumbed to a feverish delirium.  During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa.  He seems to believe it will allow him to see into a "world of shadows" where the arakkoa\'s true leaders dwell.$B$BI do not believe this nonsense for a second, but I fear he won\'t rest until I obtain such an elixir.  Will you help?]', '[Severin wants you to venture into Skettis and retrieve 6 Shadow Dusts from the arakkoa that dwell there.]', '', '去找泰羅卡森林的瑟弗林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11005, 'zhTW', '魔爪祭司的秘密', '感謝你還聽我瘋狂的豪言壯語。一直以來我們都想要摧毀司凱提斯的指揮系統;我們已經探聽到他們有三個叫魔爪祭司的聖職人員，但是我們從未親眼見過。現在我們知道其中的原因。$B$B去跟瑟弗林交談以取得更多他發現的藥劑。使用藥劑找到並殺死那三個魔爪祭司:艾夏歐、史奇吉克以及札列克。據說他們住在迷霧亞拉芮克，靠近黑風湖的東邊海岸。', '從瑟弗林那裡取得暗影藥劑，用它找到並殺死司凱堤斯的魔爪祭司艾夏歐，魔爪祭司史奇吉克和魔爪祭司札列克。完成這個任務後回去找天空指揮官艾德瑞斯。', '', '去找泰羅卡森林的天空指揮官艾德瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11006 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11006, 'zhTW', '[More Shadow Dust]', '', '', '', '去找泰羅卡森林的瑟弗林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11007, 'zhTW', '[Kael\'thas and the Verdant Sphere]', '[The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael\'thas Sunstrider. What secrets could it hold?$B$BPerhaps A\'dal in Shattrath City could make sense of the item.]', '[Take the Verdant Sphere to A\'dal in Shattrath City.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11008, 'zhTW', '向司凱堤斯開火', '你認為你夠資格成為禦天者的一員嗎?讓我們看看你在空中的能耐吧。阿拉卡正在培植一批數量龐大的變種攻擊寵物，用來攻擊我們的斥候。我要你拿著這些爆破彈炸毀阿拉卡住所屋頂的孵卵所。盡量避開守衛那些卵的巨大的卡里瑞，要不然在你還沒發現是什麼東西攻擊你之前，你已經從坐騎上被擊落了。', '在司凱堤斯住所的屋頂尋找巨大的卡里瑞蛋，並且對其使用禦天者爆破彈藥。完成之後回報天空士官多林。', '', '去找泰羅卡森林的天空士官多林。', '已摧毀巨大的卡里瑞蛋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11009, 'zhTW', '巨魔的天堂', '既然你已經解放了我們的奴役生涯，我們可以開始重新統合整個部族。這可能要花點時間;部族之間的舊仇很難化解。但是現在有一件更迫切的事情，你必須前往位於西方上空的歐格利拉。你必須保護歐格利拉還有我們不受上方的軍隊威脅，就像之前古羅為了保護我們而對抗伊斯利、惡魔還有最可怕的黑龍軍團一樣。當你到達巨魔的天堂時，請教裘阿洛該如何做最好。', '乾癟的莫格多克要你去劍刃山脈的歐格利拉與裘阿洛交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11010 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11010, 'zhTW', '[Bombing Run]', '[You have a flying mount... so what!  You think you have what it takes to use it properly?$B$BForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri\'la.  With all of those fel cannons shooting down the Skyguard left and right, we can\'t get through there to take care of business.$B$BYou want to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don\'t let them shoot you down, too!]', '[Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.]', '', '', '邪能砲彈堆已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11021, 'zhTW', '[Ishaal\'s Almanac]', '[This mysterious tome was on Talonpriest Ishaal\'s body.  It contains arcane symbols and charts of celestial bodies beyond your comprehension.$B$BAll writing is in a language you don\'t understand; likely an ancient version of the arakkoa written tongue.  Perhaps you should bring this to Sky Commander Adaris.]', '[Bring Ishaal\'s Almanac to Sky Commander Adaris north of Skettis.]', '', '去找泰羅卡森林的天空指揮官艾德瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11023, 'zhTW', '再度轟炸!', '那些高射火砲仍然對我們造成威脅，$N。$B$B你可別誤會我的意思，我認為你上次執行任務的表現非常出色。但事實上，那些該死的惡魔們補充砲彈的速度似乎比我們摧毀他們砲彈的速度還快。這同時表示我們的士兵很難通過該區域，更別提那些惡魔們對歐格利拉所造成的風險。$B$B你意下如何?想再次轟炸他們嗎?', '天空士官樊德麗要你炸毀15個惡魔砲彈堆。任務完成後回到劍刃山脈的禦天者崗哨向她回報。', '', '', '已摧毀惡魔砲彈堆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11024, 'zhTW', '[An Ally in Lower City]', '[There is an arakkoa in Lower City by the name of Rilak...  He can be trusted.  Take the book... to him.$B$B<Adaris drifts into unconsciousness as he returns the book to you.>]', '[Bring Ishaal\'s Almanac to Rilak the Redeemed in the Lower City section of Shattrath City.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11026, 'zhTW', '驅逐惡魔', '朋友，你到達的時間真是太完美了!我們真的需要幫助。你會得到一個非常稀有的物品作為回報，這樣你我兩方都能得到好處。$B$B我們已經不再是兇暴的巨魔了，不過附近的惡魔們威脅要侵擾我們和禦天者。對抗惡魔的問題是，他們一旦被殺死，就會以一個新的軀體重新回來! $B$B不過，如果你使用這個水晶來召喚一個驅逐傳送門，當他們在傳送門附近死亡時，他們的精華就會被抽走，並且放逐回他們的老家!', '克朗克要求你使用驅逐水晶來放逐劍刃山脈上煉冶場:憤怒與煉冶場:驚駭中的惡魔。當你完成任務後回去找他。', '', '', '已驅逐惡魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11028, 'zhTW', '', '', '[Return to Sky Commander Adaris at Blackwind Landing in Terokkar Forest with the news about Terokk\'s return.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11029, 'zhTW', '殘破的偽裝', '打開包裹，$N。這是一個偽裝。看起來沒什麼說服力對吧?$B$B我為伊斯利走私者製作它們以搜尋稀有的書本。有一個阿拉卡作家住在司凱堤斯的中心島嶼，泰洛克之墓;他的名字叫撒哈克。他既老又幾近全盲。$B$B利用這個偽裝來和他交談並取得那本叫敵人之血的書。小心點，$N。這個偽裝騙不了其他的阿拉卡。', '使用殘破的阿拉卡偽裝從撒哈克那裡取得敵人之血再回到海茲克那裡。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11030, 'zhTW', '[Our Boy Wants To Be A Skyguard Ranger]', '[$C, we\'ve got a problem -- we have lots of sons.  And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks.$B$BAs a proud father, we want them to have every advantage for when they apply.  So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons?  You can\'t miss their green smoke.$B$BWe think that they take ten apexis shards to make.  We\'d give you the shards, but we don\'t have any at the moment.]', '[Collect an Unstable Flask of the Beast.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11036 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11036, 'zhTW', '絕無僅有的產品!', '我先承認我不太清楚這個訂單是要用來幹嘛的，但火箭主管夫斯拉吉的指示非常明確 - 只要品質最好的水果，製成足夠長期航行的罐頭食品並密封它們不受自然腐壞的影響。$B$B還有其他的說明，這個要無重力那個要低壓力。我不會假裝我了解，但價錢不錯，所以他會得到他要的超級食品。把這個木箱帶到52區給他。越過了虛空風暴後，順著路走直到你看見城鎮。', '將罐頭水果交給52區的火箭主管夫斯拉吉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11040, 'zhTW', '火箭主管的零件', '我和哥布林合作的次數用一隻手就數的出來。我們和他們比較像在競爭，但當我接到火箭主管夫斯拉吉的請求，我實在沒辦法拒絕他。$B$B這個木箱裝滿了我在這裡用不到的零件，但那個火箭主管或許可以用在他的工程上。如果你正要去52區的話可以幫忙運送它們嗎?$B$B誰知道，或許一些精細的地精零件可以讓他的創作免於爆炸!', '把波西的備用零件送給52區的火箭主管夫斯拉吉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11043, 'zhTW', '更好的獅鷲獸', '我聽說那些蠻錘矮人在影月谷的南邊要塞有一座獅鷲獸棲息處。假如你順路到那邊的話，可以幫我傳話給他們嗎?我有一些想法可以改良他們的獅鷲獸!明明可以在獅鷲獸身上裝飛行儀表板、照後鏡還有火箭，為什麼他們不武裝獅鷲獸呢?想想看裝了之後獅鷲獸可以飛的多快!我稱它為渦輪獅鷲獸8000型!', '跟蠻錘要塞的布朗恩·焰鬚談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11047 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11047, 'zhTW', '學徒的請求', '身為雙足飛龍管理員的學徒，我的其中一項工作就是當牠們沒有執行飛行任務時要照顧牠們。問題是我們這邊的雙足飛龍數量太少了，牠們根本沒有休息的時間。假如我們不能補充雙足飛龍的數量的話，我怕牠們會操勞致死。影月谷西邊的影月村有一個大型的雙足飛龍廄。達瑪·野鬃負責照顧和訓練那裡的雙足飛龍。你可以幫我們去跟她講幾句好話，同時讓她了解我們的情況嗎?', '跟影月村的達瑪·野鬃談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11051, 'zhTW', '放逐更多惡魔', '如果我們了解惡魔，其實基於我們深入地研究，我們是了解他們的，他們能快速修補珍貴的轉換門上所受到的任何傷害。$B$B所以，如果你想要取得另一個暗色符文的機會，帶著我們的驅逐水晶回到那裡並消滅更多惡魔。此外，你想幫我們減輕惡魔造成的威脅，對吧?$B$B我之所以會說「機會」是因為我們使用的程序會產生不同的結果。你可能會得到一個暗色符文，或是可能得到一個完全不同的東西。', '克朗克要求你使用驅逐水晶來放逐劍刃山脈上煉冶場:憤怒或煉冶場:驚駭中15個惡魔。當你完成任務後回去找他。', '', '', '已驅逐惡魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11056 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11056, 'zhTW', '海茲克的交易', '不要讓我們的對話引來注意。艾德瑞斯不會贊同的。$B$B我是阿拉卡社會最低等級的人，$N。在泰洛克的規則裡，我早已被他的魔爪祭司崇拜的黑暗力量犧牲了。如果你說的是真的，魔爪祭司在尋求泰洛克的歸來，那麼你一定要阻止他們成功 - 不管你的領導者怎麼說!$B$B我有個對你有用的東西要給你。我在迷霧希拉克上層的舊居所有一個包裹。把它拿來給我!', '到東司凱堤斯，海茲克的住所取得海茲克的包裹再拿回去給他。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11057 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11057, 'zhTW', '', '', '[Speak with Mog\'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade\'s Edge Mountains. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11058, 'zhTW', '頂尖聖物', '很久以前有個已絕種的部族曾經住在這裡，一支叫頂尖的阿拉卡部族。他們文明遺物仍然存在。我們稱它們為頂尖聖物。$B$B我們只知道，適當地使用它們會帶來很多好處。每個聖物會呈現不一樣的顏色，以正確的順序去點按水晶，就會進入下一個等級，一次會比一次還要困難。$B$B要啟動聖物就需要一個頂尖裂片。等你洞悉了頂尖顫動後再來找我們。', '裘阿洛要你從一個頂尖聖物獲得頂尖顫動效果後回到劍刃山脈頂端的歐格利拉找他。', '已取得頂點震波', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11059, 'zhTW', '紀念碑護衛', '你已經知道怎麼使用這些單人型聖物，但如你所見，還有更大型的聖物，被單人型聖物環繞著。$B$B這些更大型的頂尖紀念碑功能差不多，但它們需要更多的頂尖裂片來啟動，並且需要四個人來操作。$B$B我們最擔心的就是使用它們時召喚出的護衛。這些水晶結構喚醒了它們很久以前的阿拉卡主人，現在危害著歐格利拉。$B$B我們要你摧毀一個並帶來給我們做為證據。', '裘阿洛要你取得頂尖守護者頭顱給他做為證據。完成後帶著它回到劍刃山脈頂端的歐格利拉找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11061, 'zhTW', '[A Father\'s Duty]', '[As to that other magical flask, it can only be obtained from one spot: Bash\'ir Landing.  It\'s an ethereal base, and they aren\'t too friendly with outsiders, so it might be a little dangerous to obtain.$B$BWhere\'s Bash\'ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you\'ll eventually spot it.  The Bash\'ir crystalforge itself is at the northeast corner of the landing.$B$BThank you for doing this, $N.  It\'ll mean the world to our sons!]', '[Collect an Unstable Flask of the Sorcerer for him.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11062, 'zhTW', '', '', '[Speak with Sky Commander Keller at the Skyguard Outpost in the Blade\'s Edge Mountains.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11064, 'zhTW', '[Dragonmaw Race: The Ballad of Oldie McOld]', '[Don\'t let the gray hair fool you, grunt. I\'m still ten times the rider that you are! And don\'t go thinking that this old dog doesn\'t have any tricks up his sleeve.$B$BNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.$B$BWe\'ll lift off as soon as you\'re ready.$B$B]', '[Follow Murg "Oldie" Muckjaw while attempting to stay on your flying mount. Should you defeat Murg "Oldie" Muckjaw, report your victory to Ja\'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.]', '已擊敗「老骨頭」馬格·爛顎', '去找影月谷的傑‧諾斯利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11065, 'zhTW', '[Wrangle Some Aether Rays!]', '[Wanna help the Skyguard and Ogri\'la?$B$BJust hear me out before you walk away, <hot stuff/girly>.  We\'re in need of remounts!  The bombing runs and missions to Bash\'ir Landing have taken a toll on our mounts.$B$BThe aether rays that fly around Vortex Pinnacle, and the Crystal Spine to the northeast, look like they\'d do just fine.  You don\'t even have to bring them back here, though that would be nice.  Just break and rope them, and we\'ll track them down later.$B$BThink you can wrangle me up some?]', '[Use the Wrangling Rope to capture 5 Aether Rays.]', '', '', '以太魟已被馴服', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11066, 'zhTW', '[Wrangle More Aether Rays!]', '[So, I hope that you\'re up to helping us wrangle up even more aether rays!  From what I can see, you\'re a natural with the rope!  And it\'s for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri\'la, which the ogres appreciate.$B$BRemember, the aether rays fly around Vortex Pinnacle, and the Crystal Spine to the northeast.$B$BThink you can wrangle me up some more?]', '[Use the Wrangling Rope to capture 5 Aether Rays.]', '', '', '以太魟已被馴服', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11072 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11072, 'zhTW', '敵人之血', '被司凱堤斯魔爪祭司扣留為囚犯的子嗣都列在這本書裡:女獵人吉札拉，水晶巨人葛洛克，異教徒黑暗尖叫者阿卡萊和『風怒者』瓦奇茲。殺了他們才能讓泰洛卡回到這個世界。$B$B你需要時光流逝阿拉卡身上帶的卷軸，才能在司凱堤斯的召喚法陣召喚他們。幫我從他們身上各帶一個象徵物回來。你挑戰的是強大的生物;帶朋友一起去會比較好。', '在司凱堤斯的召喚法陣中央找到顱骨堆。在顱骨堆用10個時光流逝卷軸召喚並擊敗每個子嗣。帶著各個象徵物回到黑風平臺找海茲克。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11073 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11073, 'zhTW', '[Terokk\'s Downfall]', '[I... I\'ve turned a blind eye to your dealings with the arakkoa prisoner, $N.  It looks like your instincts to cooperate with him were right.$B$BYou must understand... I would\'ve faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.$B$BTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you\'ll only get one chance at this.]', '[Take the Time-Lost Offering prepared by Hazzik to the Skull Pile at the center of Skettis and summon and defeat Terokk.  Return to Sky Commander Adaris when you\'ve completed this task.]', '', '去找泰羅卡森林的天空指揮官艾德瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11078, 'zhTW', '統治天空', '你四處飛行的時候，一定注意到上方的龍群了。我相信你還沒在他們的憤怒下成為受害者。幫我們結束它，$N!$B$B瑞文達科和歐比希迪亞主宰這個平臺，而印希迪恩和狂怒之翼則管理東北方平臺上方的天空。他們在各自的平臺都有自己的棲所。不知道你和你的朋友是否能去其中一個棲所，<小伙子/小姑娘>，打破一顆蛋把龍引下來。$B$B將龍牙交給我做為證據。要統治天空，不是我們死就是他們亡。', '天空指揮官凱勒要你取得龍牙，然後回到劍刃山脈頂端的禦天者崗哨交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11079, 'zhTW', '[A Fel Whip For Gahk]', '[Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little $r to smash big demons!$B$BDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!$B$BYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use many apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo\'arg Incinerator.]', '[Collect a Fel Whip.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11080, 'zhTW', '聖物的增益', '既然你已感受了頂尖聖物的啟發顫動，是時候讓你更了解它們的作用了。我們很希望得益於你對聖物的觀察!$B$B隨著你調合聖物的能力更進一步，你會獲得更高一層的知識。這個認知來自於聖物的放射增益。$B$B等你獲得這樣的放射增益後再來找我們。', '裘阿洛要你從頂尖聖物獲得頂尖放射增益效果再到劍刃山脈頂端的歐格利拉找他。', '已取得頂點放射物', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11085 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11085, 'zhTW', '逃離司凱堤斯', '嗨，$N。謝謝你來幫我。$B$B阿拉卡的怪鳥在我進行偵察任務時把我從虛空鰭刺上擊下。$B$B我們快離開這裡，趁還來的及。', '安全護送禦天者囚犯並向天空士官多林報告。', '營救天空守衛的囚犯', '去找泰羅卡森林的天空士官多林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11091 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11091, 'zhTW', '', '', '[Speak with Jho\'nass at Ogri\'la in the Blade\'s Edge Mountains.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11093, 'zhTW', '飢餓的虛空鰭刺', '虛空鰭刺一旦經過適當的訓練就會出奇地忠誠和順從。不幸的是司凱堤斯的戰役讓它們傷亡慘重。$B$B我們每天都有許多的突擊 - 可憐的伙伴們都很少休息。隨著最近食物短缺，如果那些可惡的鳥人不殺他們，飢餓也會把他們殺死。$B$B如果你可以幫個忙，帶一隻我們的鰭刺到南邊的樹林去。他們不喜歡扭曲追趕者的肉，除非是新鮮的。', '在黑風平臺南邊的樹林裡使用虛空鰭刺籠並殺死飢餓的虛空鰭刺附近的黑風扭曲追趕者。完成任務後回去找禦天者管理者迪塞克。', '', '去找泰羅卡森林的禦天者管理者迪塞克。', '', '鰭刺大餐', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11098, 'zhTW', '[To Skettis!]', '[The Barrier Hills are only one of the fronts where we\'ve been deployed.  A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis.$B$BA few months ago our scouts detected a huge increase in arakkoa activity there.  Several attacks against Shattrath followed.  We\'ve stationed forces outside of their city since.$B$BTake these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis.  Tell him you\'re a new recruit.]', '[Take the Explosives Package to Sky Sergeant Doryn at Blackwind Landing outside Skettis.]', '', '去找泰羅卡森林的天空士官多林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11100, 'zhTW', '[Commander Arcus]', '[The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.$B$BI want you to let them come, $N.$B$B<Ceyla nods.>$B$BYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.$B$B]', '[Give the Dragonmaw Flare to Commander Arcus at the Altar of Sha\'tar in Shadowmoon Valley.]', '', '去找影月谷的指揮官阿克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11102, 'zhTW', '[Bombing Run]', '[You can fly around as a crow... so what!  Ever annihilate something on the ground while you were flying?  Want to?$B$BForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri\'la.  With all of those fel cannons shooting down the Skyguard left and right, we can\'t get through there to take care of business.$B$BWant to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don\'t let them shoot you down, too!]', '[Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.]', '', '', '邪能砲彈堆已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11117 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11117, 'zhTW', '抓住野生鹿角兔!', '就是現在。你聽到了嗎?從那邊的丘陵傳過來的。那是鹿角兔!被啤酒節氣味吸引過來的野生動物。我一直想抓一些，可惜我撞傷了小腿，跑不過那些兔崽子。但是你可以幫我!$B$B帶著這個網子然後用它抓住那些小傢伙。帶五隻回來給我，我會給你很不錯的報酬!還有一件事 - 你得喝到醉眼惺忪才能看到牠們!大杯乾下去或者跟我要一副模擬醉眼護目鏡!', '茍達克·狙獵者要你用鹿角兔捕網幫他抓5隻昏迷的鹿角兔。他提到你必須要喝醉或戴上模擬醉眼護目鏡才看得到那些鹿角兔。', '', '去找丹莫羅的苟達克‧狙獵者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11118, 'zhTW', '粉紅伊萊克遊行', '在啤酒節時喝醉是個長久以來的優良傳統 -- 是天殺的必要!問題是，我接到從艾澤拉斯各地的報告都指出，我們的慶典被幻像所騷擾!我們可不能容許這種事!$B$B這些伊萊克不能被一般武器所傷害 -- 武器會直接穿過牠們 -- 所以帶著這個驚人的地精裝置前往其他的啤酒廣場，讓牠們灰飛湮滅。要記得，你一定要喝醉或戴上模擬醉眼護目鏡才能看到牠們!如果你需要一副的話跟我說一聲。', '前往暴風城、達納蘇斯還有艾克索達外頭的啤酒廣場，在那些地方宰掉三頭伊萊克，然後回去找茍達克·狙獵者。你一定要喝醉或戴上模擬醉眼護目鏡才看得見那些粉紅伊萊克。', '', '去找丹莫羅的苟達克‧狙獵者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11119 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11119, 'zhTW', '', '', '[Speak with the Aether-tech Apprentice at Skyguard Outpost in the Blade\'s Edge Mountains.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11120, 'zhTW', '粉紅伊萊克遊行', '聽著，我們正在此地做點生意。人們都喝醉啦?這是筆好生意，但我得告訴你有件事情在限制我們的利潤 - 那些幻覺。你不知道那個嗎?那些孩子向我報告說，我忠實的老主顧們正在四處尋找粉紅伊萊克。$B$B我可不希望我的老主顧心神不寧。聽好，帶著這隻鰭刺去其他的啤酒廣場，並且替我好好照顧牠，行嗎?記得一定要喝醉啊!', '造訪銀月城、雷霆崖還有幽暗城外的啤酒廣場，在每個地方各宰掉三隻伊萊克，然後回去找葛羅卓克·獵狙者。你一定要喝醉才看得見那些粉紅伊萊克。', '', '去找杜隆塔爾的葛羅卓克‧獵狙者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11122, 'zhTW', '[There and Back Again]', '[So you want to help out at Brewfest?  I\'ve got the perfect task for ya.  I\'ll put you on one of my racing rams and you head down to Kharanos.  I\'ve got some kegs I need to pick up.  $B$BFlynn Firebrew is waiting on a hill near a stack of kegs.  He\'ll toss you a keg when you get near, then you run the keg back here and toss the keg to Pol Amberstill.  You can only carry one at a time.  $B$BReady?]', '[Get a keg from Flynn Firebrew in Kharanos and return it to Pol Amberstill.  Do this 3 times before your ram goes away.]', '', '去找丹莫羅的奈爾‧拉姆斯登。', '酒桶已運送', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11127, 'zhTW', '[<NYI>Thunderbrew Secrets]', '[Now I\'d never steal a thing from our Thunderbrew cousins. They\'re good people. But if you want to get ahead in this business, sometimes you have to do unfortunate things, and that\'s why I hire other people to do it for me.$B$BGrimbooze Thunderbrew is a nutty member of the family who lives south of Moonbrook in the hills of Westfall. I hear he has a new recipe for ale, and I want it before it hits the market. You can fetch it for me, can\'t you? I\'ll reward you. A Barleybrew pays his debts.]', '偷走格林布茲在西部荒野營地裡的秘密配方，然後回到啤酒節廣場交給$n‧麥酒。', '', '去找丹莫羅的畢肯‧麥酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11129, 'zhTW', '凱爾失蹤了!', '幫幫我，$N! 我最寶貝的寵物，凱爾跑不見了!我只知道牠平常會在血蹄村附近亂跑，牠現在一定是迷了路又餓著肚子。$B$B你願意幫我找到牠並且餵牠嗎?只要牠吃飽了，牠就會安靜下來並且回家來。$B$B你需要去找食物來餵牠。牠最喜歡的就是嫩陸行鳥肉了，你只需要獵一隻並且拿那些多汁的肉給凱爾。你要是看見凱爾在村子裡，牠一定會過來找你的。', '莫高雷-血蹄村的亞哈伯·麥蹄希望你幫忙找他珍貴的寵物，狂怒的凱爾。$B$B餵凱爾吃嫩陸行鳥肉，然後回去找亞哈伯·麥蹄。', '', '去找莫高雷的亞哈伯·麥蹄。', '', '凱爾被餵飽了', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11131, 'zhTW', '[Stop the Fires!]', '[You must help us!  The Headless Horseman is attacking the village.  Fires are everywhere!  The children aren\'t safe!$B$BPlease, $n, join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who\'s closer to the blaze.  Put out all the fires and we may yet be saved!]', '[The Costumed Orphan Matron wants you to help put out all the village fires.  When they are out, speak again to the Costumed Orphan Matron.]', '撲滅火勢', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11132, 'zhTW', '[Promises, Promises...]', '[My inscrutable theories confirm rumors of vast treasure in Zul\'Aman. There\'ll be mounts and mansions for everyone! First things first, though. You must earn your share, after all....$B$BOur initial efforts here haven\'t gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk.$B$BForget the crew, I need that map! Succeed, and you\'ll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul\'Aman!]', '[Budd Nedreck in Hatchet Hills wants you to retrieve his map from High Priest Nalorakk\'s terrace in Zul\'Aman.]', '', '去找幽魂之地的霸德·奈德瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11135, 'zhTW', '', '', '此任務已經絕版。[Find the Headless Horseman\'s pumpkin Shrine.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11153, 'zhTW', '[Break the Blockade]', '[All of our ships are sunk! We need your help to break the pirate blockade below in the Shattered Straits!$B$BTake these cluster bombs and hitch a ride on the zeppelin that Harrowmeiser has \'loaned\' to us.  He\'ll fly you over the decks of those pirate scoundrels, and you make sure to give it to them good!$B$BIf you can\'t bomb them to smithereens, I\'m afraid we\'ll never be able to break the blockade.]', '[Take Petrov\'s Cluster Bombs and drop them on enough pirates to kill or destroy 25 Blockade Pirates and 10 Blockade Cannons.  Once you\'ve accomplished that, return to Bombardier Petrov at Westguard Keep.]', '', '去找嚎風峽灣的投彈手派特洛夫。', '', '封鎖砲台已摧毀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11154, 'zhTW', '[Scare the Guano Out of Them!]', '[You, yes you... I need your help!$B$BPetrov sent me up here to get bat guano for the cluster bombs he\'s making back at the keep. He sent me to my doom!$B$BThe darkclaw bats hang out in the Rivenwood to the north, but I\'m not taking a step off of this platform unless it\'s to go home!$B$BBut you... you could get it for me! Yes? Pretty please?!!!$B$BHere, take these firecrackers. My thinking is that if you drop \'em underneath the bats, the guano will be scared right out of them!]', '[Collect 10 Darkclaw Guano and deliver them to Engineer Feknut at Steel Gate.]', '', '去找嚎風峽灣的工程師費克努。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11155, 'zhTW', '[Shoveltusk Soup Again?]', '[With all of the strange disappearances of our livestock, we better resupply in a hurry, or the beasties around these parts will be the least of our worries!$B$BSeeing as I\'m in charge of feeding this lot, I\'m going to need you to head east and get me some meat. More to the point, I\'m looking to cook us up some tender shoveltusk meat.$B$BJust beware the stags... they\'re mean!]', '[Chef Kettleblack has asked you to obtain 6 Shoveltusk Meat and deliver them to her at Westguard Keep.]', '', '去找嚎風峽灣的主廚黑壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11157 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11157, 'zhTW', '[The Clutches of Evil]', '[$N, I don\'t trust anyone but you to take care of this.  I need the proto-drake eggs and proto-whelps in the burning forest to the southeast destroyed!$B$BSince we arrived here, the Ember Clutch has been ablaze; there must be some sort of perverse magic at work. And lately it seems to be growing. My men tell me that if we don\'t do something quickly, we\'ll be surrounded on all sides by the fire within a few weeks\' time!$B$BGet down there and eliminate the threat by destroying those eggs and the proto-whelps.]', '[Destroy 15 Proto-Drake Eggs and 15 Proto-Whelps, and then return to Captain Adams at Westguard Keep.]', '', '去找嚎風峽灣的亞當斯隊長。', '元龍幼龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11164, 'zhTW', '[Tuskin\' Raiders]', '[\'Ey mon! You be new around \'ere, eh? Lemme ask a favor of ya.$B$BBudd\'s been refinin\' his forest troll disguise. Says that he be close now - just be needin\' one last touch. Tusks.$B$BMy skinnin\' talents be wasted \'ere. Somethin\' about yankin\' troll tusks be makin me queasy. $B$BBring me back 10 troll tusks, eh mon?]', '[Prigmon needs you to collect 10 Forest Troll Tusks from the trolls in Zul\'Aman. Bring them to him at Budd\'s camp in the Ghostlands.]', '', '去找幽魂之地的皮格蒙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11165, 'zhTW', '', '', '[Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul\'Aman.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11167, 'zhTW', '[The New Plague]', '[Not long after Arthas condemned us to this wretched existence, we in the Royal Apothecary Society endeavored to create a plague of our own.  A plague that would devour all flesh: living, dead or undead.$B$BWe\'ve succeeded in creating this plague and we\'re here to hand deliver it to the Scourge\'s doorstep.$B$BThe Alliance intercepted the ship carrying the latest strain engineered in our Undercity laboratories.  Head to the wreckage southeast of here and salvage whatever containers you can.]', '[Apothecary Lysander at Vengeance Landing wants you to recover 10 Intact Plague Containers from the wrecked ship to the southeast.]', '', '去找嚎風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11168, 'zhTW', '[Spiking the Mix]', '[I\'ve a feeling the long trip across the sea is affecting the effectiveness of our plague.  What is needed is a potent toxin to boost the potency of the strain.$B$BThe crabs near this beach are a distant relative of the much smaller brown-shelled tidecrawler.  The smaller tropical variety produces a paralytic toxin strong enough to knock out an ogre.$B$BAs we all know bigger is better!  The much larger glands on the local variety should prove more potent.  Bring me a few!]', '[Bring 3 Giant Toxin Glands from Giant Tidecrawlers to Apothecary Lysander at Vengeance Landing in Howling Fjord.]', '', '去找嚎風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11170, 'zhTW', '[Test at Sea]', '[We\'ve just received word of reinforcements coming to the aid of the Alliance forces.  Their timing couldn\'t be better!$B$BWe\'re in sore need of test subjects and these North Fleet reservists will do nicely!$B$BTake these plague vials with you and speak to Camille, the Bat Handler.  Tell her you need to commandeer a riding bat for a special assignment for us.$B$BOnce you\'re at sea, drop the vials on the reinforcement fleet.  I can\'t wait to see the results!]', '[Speak to Bat Handler Camille and take a riding bat to intercept the Alliance reinforcements.  Once above their fleet, use the Plague Vials to infect 16 North Fleet reservists.]', '', '去找嚎風峽灣的藥劑師黎珊達。', '北方艦隊後備兵已感染', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11175 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11175, 'zhTW', '', '', '[Old Man Stonemantle has asked you to find his daughter, Overseer Irena Stonemantle, at Steel Gate.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11176 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11176, 'zhTW', '', '', '[Explorer Irena Stonemantle has asked you to speak with a Steel Gate Chief Archaeologist at Steel Gate.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11182, 'zhTW', '[Root Causes]', '[All things in nature seek a balance. It is only through the interference of those not in tune with that harmony that the balance is shifted.$B$BYou waste your efforts when you kill the whelps and drakes. The real culprits behind the expansion of these magically burning woods are the newly awakened vrykul and their master, Skeld Drakeson.$B$BIf it\'s blood on your hands that you seek, start with them. You will find their lair on the south side of the Ember Clutch.]', '[Slay 5 Dragonflayer Handlers and Skeld Drakeson.  If you manage to do so, return to an Ember Clutch Ancient in the Ember Clutch.]', '', '去找嚎風峽灣的餘燼窩巢古樹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11187, 'zhTW', '', '', '[Captain Adams has asked you to speak with his advisor, Mage-Lieutenant Malister, at Westguard Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11188, 'zhTW', '[Two Wrongs...]', '[Now that we\'ve riled up these Ember Clutch proto-drakes, they may be inclined to continue their attacks upon the keep. This will not do.$B$BI hate to compound one wrong with another, but in this case it would appear that we will have to destroy the creatures. A regrettable course of action, but one that we need to undertake regardless.$B$BTake my wand. I\'ve been experimenting with increasing its range, but it doesn\'t pack much of a punch. However, what it will do is get a proto-drake\'s attention.]', '[Mage-Lieutenant Malister at Westguard Keep has tasked you with the destruction of 3 Proto-Drakes.]', '', '去找嚎風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11190, 'zhTW', '[One Size Does Not Fit All]', '[$G小夥子：小姑娘;, who\'s the genius that made our cannons a non-standard size? Now we have ta make special cannonballs ta shoot out o\' the infernal contraptions!$B$BI would look kindly on ye if ye would go out and find the balls we\'ve already shot. No doubt with the way these louts shoot they be all o\'er the place ta the south and east.$B$B<The cannoneer spaces his hands apart to give you an idea of how big the cannonballs are.>$B$BThat would be faster than us making \'em from scratch fer a certainty.]', '[Cannoneer Ely has tasked you with rounding up 10 Westguard Cannonballs and returning them to him at Westguard Keep.]', '', '去找嚎風峽灣的砲手伊利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11199, 'zhTW', '', '', '[Captain Adams has asked you to report to Scout Knowles at the Ember Spear Tower.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11202, 'zhTW', '[Mission: Eternal Flame]', '[The Forsaken are up to no good and from what I can tell, those plague tanks of sludge are a big part of it.$B$BIf I may suggest, $g先生：女士;, we should probably destroy them before they can get any more use out of the things. I took the liberty of preparing a bundle of torches from the Ember Clutch. These things have been burning for days!$B$BHere, I\'m sure you can put them to better use than I in destroying those tanks.]', '[Scout Knowles at the Ember Spear Tower has recommended that you use the Ever-burning Torches to destroy the four Plague Tanks surrounding Halgrind.]', '', '去找嚎風峽灣的斥候諾雷斯。', '西南方瘟疫戰車已摧毀', '西北方瘟疫戰車已摧毀', '東北方瘟疫戰車已摧毀', '東南方瘟疫戰車已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11218, 'zhTW', '[Danger! Explosives!]', '[$N, the captain\'s tasked me with a mission. I\'d like you to help.$B$BA bunch of my fellow Explorers\' League people went nuts digging up stuff in the Whisper Gulch just to the north. They\'re attacking anyone trying to get in!$B$BThe captain is only concerned with the ore for the keep. Lucky for us, I have just the thing to do the trick.$B$BGet in there, blow up the ore, and bring it back along with any gems you find. Running this place isn\'t cheap you know!$B$BI gotta warn you though, that ore is strange!]', '[Use Steelring\'s Foolproof Dynamite to collect 6 Whisper Gulch Ore Fragments and 18 Whisper Gulch Gems. Then return them to Sapper Steelring at Westguard Keep.]', '', '去找嚎風峽灣的賽波‧鋼環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11219, 'zhTW', '[Stop the Fires!]', '[The Horde\'s children need you, $n.  The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village!  You must put out those fires!$B$BGrab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames.  Extinguish all the fires and thwart the Headless Horseman!]', '[The Masked Orphan Matron wants you to help put out all the village fires.  When they are out, speak again to the Masked Orphan Matron in town.]', '撲滅火勢', '去找戴面具的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11220, 'zhTW', '', '', '此任務已經絕版。[Find the Headless Horseman\'s Pumpkin Shrine.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11221, 'zhTW', '[Reports from the Field]', '[Our mission in Northrend is to destroy Arthas.  The Alliance are but an obstacle that we\'ll crush wherever we find them.$B$BWe\'ve managed to destroy their easternmost fleet; but the survivors have barricaded themselves on the Derelict Strand, south of here.$B$BOur forces should\'ve overwhelmed their make-shift defenses long ago, but we underestimated their will to live.  Seek my officers in the field, Dark Ranger Lyana and Deathstalker Razael and get them to report on the situation.]', '[Speak to Dark Ranger Lyana and Deathstalker Razael in the battlefield at the Bleeding Vale south of Vengeance Landing.  Return to High Executor Anselm when you\'ve completed this task.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '聆聽拉薩爾的回報', '聆聽萊亞娜的回報', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11224, 'zhTW', '[Send Them Packing]', '[I\'ve heard rumors of bad happenings in the Whisper Gulch to the north. Most of the Explorers\' League went down into that place, and some say they went mad with what they discovered.$B$BThat doesn\'t change the fact that they took most of our mules and equipment with them, though. I won\'t lose those mules!$B$BIf you find yourself in there, and happen across any of my mules, just get up close on them and threaten them with a raised hand. They\'ll spook and come home for sure.]', '[Explorer Abigail has asked you to /raise your hand at 10 Abandoned Pack Mules and then return to her at Westguard Keep.]', '', '去找嚎風峽灣的探險者艾比蓋兒。', '遺棄的騾子已被趕走', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11227, 'zhTW', '[Let Them Eat Crow]', '[The high executor wants me to use my dogs to sniff out enemy scouts, but I can tell you right now these plaguehounds aren\'t going anywhere until they\'re properly fed.$B$BIf our military doesn\'t understand that these beasts are picky enough to not eat the rubbish they\'ve given me, then they can\'t expect them to be of any use in the field.$B$BYou seem to have some time on your hands, why don\'t you take one of these dogs out hunting for crows out west?  Their meat isn\'t very tasty to us, but my boys love it!]', '[Pontius, the kennel keeper at Vengeance Landing, wants you to use the Plaguehound Cage to summon a Hungry Plaguehound and feed it Crow Meat from Fjord Crows west of Vengeance Landing.]', '', '去找嚎風峽灣的龐提烏斯。', '已餵食瘟疫獵犬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11228, 'zhTW', '', '', '[Speak with Vice Admiral Keller at Valgarde Port.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11229, 'zhTW', '', '', '[Speak to Bat Handler Camille at Vengeance Landing and obtain passage to the Windrunner. Report to Captain Harker aboard the ship.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11230, 'zhTW', '[Ambushed!]', '[This should have been a walk in the park.  Their forces are hungry, injured and ill equipped.  Yet somehow, we walked right into their trap.$B$BWe approached these reefs from the south to gain cover and were immediately boarded by the Alliance dogs.$B$BI\'m sorry to say, if you want our cannons to fire at anything, you\'re going to have to help us take our ships back.]', '[Captain Harker aboard the Windrunner wants you to kill 15 North Fleet Marines.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11231, 'zhTW', '[Of Keys and Cages]', '[The captain may not care, but from the little we know, the vrykul are conducting heinous rites in some sort of \'awakening\' ritual up north in Gjalerbron.$B$BThey\'re using living sacrifices to fuel their unholy rituals!$B$B$C, you must put a stop to this! It matters not who or what is in those cages, they must be freed. I\'d bet that the vrykul hold the keys.$B$BThe Light knows the last thing we need is more of those strange vrykul walking about, or worse yet, them wakening something even more evil!]', '[Father Levariol has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to him at Westguard Keep when you manage to do so.]', '', '去找嚎風峽灣的雷瓦瑞爾神父。', '傑拉布倫的囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11232, 'zhTW', '[Guide Our Sights]', '[We should be able to kill our way back to our guns.  Unfortunately, visibility is less than desirable so you will have to mark our targets from the ground.$B$BTake these smoke flares with you and use them to mark the locations of the cannons along the northern wall in the Derelict Strand, west of here, where the Alliance are holding out.$B$BLet Lyana know as soon as the way is clear for the ground troops.  We can take care of ourselves over here.]', '[Use the Smoke Flares at the location of the Alliance Cannons on the northern wall of the Derelict Strand.  Report to Dark Ranger Lyana at the Bleeding Vale after you\'ve completed this task.]', '', '去找嚎風峽灣的黑暗遊俠利雅娜。', '東方火砲已標記', '西方火砲已標記', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11233, 'zhTW', '[Landing the Killing Blow]', '[You\'ve proven yourself in the field of battle, $N.  You might very well have changed the tides in our favor.$B$BI\'ve an important assignment for you now.  I\'m not sure how much longer the weakness we\'ve exposed is going to last, so we must use the element of surprise to our advantage.$B$BI want you to use the confusion created by our attack and go behind enemy lines to assassinate their leaders.  In order of rank, they are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric.  Good luck, $c.]', '[Dark Ranger Lyana south of the Vengeance Landing wants you to kill Captain Olster, Lieutenant Celeyne, and Sergeant Lorric at the Derelict Strand.]', '', '去找嚎風峽灣的黑暗遊俠利雅娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11234, 'zhTW', '', '', '[Report back to High Executor Anselm at Vengeance Landing in Howling Fjord.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11235, 'zhTW', '[Dealing With Gjalerbron]', '[And now we have a different problem. My scouts that have lived to return have informed me that the vrykul are up to no good at their main fortress to the north.$B$BThey call the place Gjalerbron, though you\'d pronounce the \'Gj\' as if it were an \'Sh\'. Odd creatures.$B$BBut that\'s not important; what is, is that you get up there and put an end to the lives of as many of those creatures as you can while trying to figure out what they\'re up to.$B$BI know that I can count on you, $N.]', '[Captain Adams has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Westguard Keep.]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11236, 'zhTW', '[Necro Overlord Mezhen]', '[The Scourge are at Gjalerbron and they have necromancers with them! They must be working to bring the vrykul into Arthas\' fold.$B$BI want the leader of these necrolords eliminated!$B$BDo whatever it takes, $N, but see to it that Necro Overlord Mezhen, and whatever he\'s attempting to accomplish, is neutralized.$B$BI will not see the vrykul successfully allied with the Scourge!$B$BLook for Mezhen on the platform in the rear right section of Gjalerbron.]', '[Kill Necro Overlord Mezhen. Then, return to Captain Adams at Westguard Keep.]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11237, 'zhTW', '[Gjalerbron Attack Plans]', '[These plans detail an imminent attack upon Westguard Keep. It would appear that the frost wyrm, Glacion, who circles overhead is to be used for the offensive.$B$BSurely Mage-Lieutenant Malister would be of some assistance in this matter. Deliver the plans to him at the keep to the south.]', '[Deliver the Gjalerbron Attack Plans to Mage-Lieutenant Malister at Westguard Keep.]', '', '去找嚎風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11238, 'zhTW', '[The Frost Wyrm and its Master]', '[You were right to bring this to me, $N. You must take help back north with you to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile!$B$BEven now, as we speak here, the frost wyrm may be on its way.$B$BHowever, if I\'m reading these plans correctly, blowing the wyrmcaller\'s horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!$B$BAnd $N, please bring me the horn. We wouldn\'t want it falling back into the wrong hands.]', '[Slay Wyrmcaller Vile and use the Wyrmcaller\'s Horn to call down and slay Glacion. Then, return with the horn to Mage-Lieutenant Malister at Westguard Keep.]', '', '去找嚎風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11239, 'zhTW', '[In Service to the Light]', '[Your service has been exemplary, $N, but there is something that is troubling me: the Scourge.$B$BThe Light cannot abide their presence, and neither shall we. I hope that it is not asking you too much, but I would have you return north to Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in the Waking Halls beneath Gjalerbron as well.$B$BPurification is the key to salvation, my child. Make us proud!]', '[Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Father Levariol at Westguard Keep of your success.]', '', '去找嚎風峽灣的雷瓦瑞爾神父。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11240, 'zhTW', '[Leader of the Deranged]', '[So, I hate to say it, pal, but while you were out, the captain took a keener interest in that place.$B$BLooks like he wants my old Explorers\' League boss in there dead. My guess would be that we\'re gearing up for an offensive to clear out the rest of them, and the captain wants their head lopped off, as it were.$B$BDo me a favor? Head back into Whisper Gulch and put an end to Squeeg Idolhunter. From what I remember, my guess would be that he\'s in the cave in the northwest corner.]', '[Slay Squeeg Idolhunter and then report back to Sapper Steelring at Westguard Keep.]', '', '去找嚎風峽灣的賽波‧鋼環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11241, 'zhTW', '[Trail of Fire]', '[Thanks for bailing me out of this mess, $N.  I was not looking forward to what these Alliance scumbags had in store for me.$B$BLet\'s get out of here and see if we can get back at them somehow.  Is that a campfire over there?]', '[Escort Apothecary Hanes out of the Derelict Strand.  Report to Apothecary Lysander at Vengeance Landing in Howling Fjord when you\'ve completed this task.]', '營救藥劑師哈尼斯', '去找嚎風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11242, 'zhTW', '[Free at Last!]', '[Rage was my prison, $N, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.$B$BThank you for leading me back to the Light.  May I never again lose my way.$B$BTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.]', '[Take the Tome of Thomas Thomson to the Costumed Orphan Matron in Goldshire, Kharanos or Azure Watch.]', '', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11243, 'zhTW', '[If Valgarde Falls...]', '[If Valgarde falls, our primary supply line into Northrend will cease to exist. From there it\'ll only be a matter of time before we\'re all servants of the Lich King. Now I don\'t know about you, but I\'ve got a wife and three kids back in Elwynn and I\'ll be damned if I\'ll go down without a fight.$B$BThe situation here is critical and we can use all the manpower you\'re able to muster. Get to the front gate and help the guards defend the city against the invading monsters!]', '[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to slay 12 Dragonflayer Invaders or Dragonflayer Worgs.$B$B]', '', '去找嚎風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11244, 'zhTW', '[Rescuing the Rescuers]', '[We\'d been here for a month when those malformed giants appeared out of thin air. We were ill-prepared for any sort of attack and paid dearly for our complacency. An entire archaeology team was lost and several townsfolk were abducted and taken to the ruins. We\'ve been on the defensive ever since.$B$BTo make matters worse, the scouts we sent to rescue our people have been harpooned by the vrykul and left for dead in the forest directly north of Valgarde. Dislodge those harpoons and free our scouts!$B$B]', '[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 8 Valgarde Scouts that have been impaled and left for dead.]', '', '去找嚎風峽灣的海軍中將凱勒。', '已救出瓦爾加德偵察兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11248, 'zhTW', '[Operation: Skornful Wrath]', '[$N, I must now ask you to undertake an operation so hazardous, so deadly, that only you can see it through.$B$BThe vrykul fortress, Skorn, sits on our eastern border. My scouts inform me that those \'giants\' are poised to strike us, and with my forces scattered all over the fjord, I don\'t have the men to take the place by force.$B$BInstead, you\'re going to use your cunning. I\'ve sent a sergeant ahead with the details. Show this command insignia at Skorn and he\'ll reveal himself and follow your orders.]', '[Captain Adams has asked you to use the Westguard Command Insignia at Skorn, and then to speak with the Westguard Sergeant.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11250, 'zhTW', '[All Hail the Conqueror of Skorn!]', '[We -- well, you -- have done everything that we were sent here to accomplish $g先生：女士;. I must say that it\'s been a pleasure taking orders from such a fine, young $r.$B$BThe captain is sure to want to hear of your success, but if you decide to stay out here for whatever reason, I am at your disposal.]', '[Return the Westguard Command Insignia to Captain Adams at Westguard Keep.]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11251, 'zhTW', '', '', '[Scout Valory wants you to investigate the sounds of battle coming from the northeast of Wyrmskull Village.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11252, 'zhTW', '[Into Utgarde!]', '[Listen up, youngster. I\'ve put down me share of these creatures - and your share too fer that matter. Here be what ya need to know....$B$BThe vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we\'re doomed - plain and simple.$B$BThere\'s one they esteem though, goes by the name of Ingvar. I dunno why they be seekin\' his praise, but bring him down and you\'ll deal a mighty blow to their spirit.$B$BThen, perhaps, we\'ll have a chance....]', '[Defender Mordun has tasked you with the execution of Ingvar the Plunderer who resides deep in Utgarde.$B$BYou are then to bring his head to Vice Admiral Keller.]', '', '去找嚎風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11253, 'zhTW', '[Sniff Out the Enemy]', '[Now that this rascal\'s belly\'s full, maybe he will be more willing to cooperate.  Here\'s his leash, just come get him from his cage whenever you\'re ready to take him.$B$BI don\'t know what Anselm expects you to find, but look for clues wherever it is that the dog takes you.]', '[Use the Plaguehound Leash near the plaguehound cages at Vengeance Landing and look for clues at the location you\'re led to by the Plaguehound Tracker.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11254, 'zhTW', '[The Dragonskin Map]', '[Upon closer inspection, the scroll appears to be a heavily-illustrated map of the fjord.  The location of various villages are depicted in what seem to be tribal symbols.$B$BThe location of Vengeance Landing is marked with a disproportionately large skull.$B$BThis map will almost certainly be of military value to High Executor Anselm.]', '[Bring the Dragonskin Map to High Executor Anselm in Vengeance Landing.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11255, 'zhTW', '[Prisoners of Wyrmskull]', '[This battle is far from over, $N. If our people are still alive inside that village, someone has to go and get \'em.$B$B<Vice Admiral Keller nods at you.>$B$BHead north and enter Wyrmskull Village. Once there, look for our people. If they are imprisoned you\'ll need to find a way to break them out.$B$BMaybe they\'ll have some more information about what it is that we\'re actually fighting.]', '[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 3 Captured Valgarde Prisoners.]', '', '去找嚎風峽灣的海軍中將凱勒。', '已救出瓦爾加德的俘虜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11256, 'zhTW', '[Skorn Must Fall!]', '[$N, the vrykul fortress, Skorn, sits to the south. Its strange giants have recently awakened and have begun to spread, attacking us wherever they can.$B$BMy scouts inform me that they are poised to strike at us here, but I do not have the strength to repel such a force. Instead, we will prepare to leave north to less dangerous lands.$B$BI ask that you use your cunning to buy us time. I\'ve sent a brave ahead with the details. Show this emblem at Skorn and he\'ll reveal himself and do all he can to aid you.]', '[Chieftain Ashtotem has asked you to use the Winterhoof Emblem at Skorn, and then to speak with the Winterhoof Brave.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11257, 'zhTW', '[Gruesome, But Necessary]', '[Our elders say that these vrykul may be able to rise from the dead; not unlike the walking dead you call the Scourge, but a different kind of undeath.$B$BWe should not take any chances.$B$BHere, take my machete. As we move through this place, carve up the remains of the vrykul that we slay.$B$BI spent the morning sharpening it, so it should cleave even through their thick bones.]', '[The Winterhoof Brave has asked you to use The Brave\'s Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.]', '', '', '寒冬扭曲維库人已肢解', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11258, 'zhTW', '[Burn Skorn, Burn!]', '[Chieftain Ashtotem ordered me to destroy many buildings here.$B$BHowever, you are in charge, so it falls to your hands, $N.$B$BI suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn. All we have to do is get inside each and set them ablaze with this torch.]', '[The Winterhoof Brave suggests that you use the Brave\'s Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.]', '', '', '西北方長屋已點燃', '東北方長屋已點燃', '軍營已點燃', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11259, 'zhTW', '[Towers of Certain Doom]', '[As we move through Skorn, we must destroy the towers.$B$BIf you have a look at them, you\'ll notice that their tops are lined with casters. Getting too close to them would mean certain doom.$B$BHowever, we can call in wind rider air strikes from Camp Winterhoof. To do so, we need to get close enough so that you can lob a smoke flare atop of them.$B$BJust don\'t get too close.]', '[The Winterhoof Brave has informed you that using the Brave\'s Flare to target all four of the towers at Skorn for air strikes would be advisable.]', '', '', '西北方塔樓已標記', '東方塔樓已標記', '西南方塔樓已標記', '東南方塔樓已標記', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11260, 'zhTW', '[Stop the Ascension!]', '[This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.$B$BA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture\'s background.$B$BA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane\'s lodge.]', '[Present the Vrykul Scroll of Ascension near the Thane\'s Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you\'re sure that Greatmother Ankha at Camp Winterhoof will be interested in seeing the scroll.]', '', '去找嚎風峽灣的主母安卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11261, 'zhTW', '[The Conqueror of Skorn!]', '[You have done everything that we were sent here to do, $c. I must admit that you fight well. Your people are not as strange as I first thought.$B$BChieftain Ashtotem is certain to want to hear of your success, but if you decide to stay out here for whatever reason, I will continue to fight at your side.]', '[Return the Winterhoof Token to Chieftain Ashtotem at Camp Winterhoof.]', '', '去找嚎風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11262, 'zhTW', '[Ingvar Must Die!]', '[Finally, someone\'s come. I\'ve been here far too long and my wits are beginning to fail me. Of our entire recon party, only I remain.$B$BI shall give you my report and it will be up to you to act upon the information. Know this, $c; it did not come cheaply.$B$BThese vrykul are relentless fighters. Given their numbers and their savage tactics, our only hope is to bring down their leader and pray it brings chaos to their ranks.$B$BIngvar is his name. Bring his head to Anselm when your duty is done.]', '[Dark Ranger Marrah has asked you to kill Ingvar the Plunderer in Utgarde Keep, then bring his head to High Executor Anselm at Vengeance Landing.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11263, 'zhTW', '[Dealing With Gjalerbron]', '[My longrunners that have lived to return have informed me that the vrykul have awakened at their main fortress to the west.$B$BIt is a forbidden place known as Gjalerbron. The longrunners tell me that the vrykul are performing strange rituals.$B$BWe cannot allow this to continue.$B$BAre you willing to continue to assist us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing and attack us here?]', '[Chieftain Ashtotem has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Camp Winterhoof.]', '', '去找嚎風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11264, 'zhTW', '[Necro Overlord Mezhen]', '[The dead ones are at Gjalerbron and they have necromancers with them?$B$BWe must eliminate the leader of these necrolords.$B$BDo whatever it takes, $N, but see to it that Necro Overlord Mezhen, and whatever he\'s attempting to accomplish, is neutralized.$B$BWe cannot afford to see the vrykul successful in whatever they are doing with these undead creatures!$B$BLook for Mezhen on the platform in the rear right section of Gjalerbron.]', '[Kill Necro Overlord Mezhen. Then, return to Chieftain Ashtotem at Camp Winterhoof.]', '', '去找嚎風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11265, 'zhTW', '[Of Keys and Cages]', '[From the little we know, the vrykul are conducting unnatural rites in an \'awakening\' ritual to the west in Gjalerbron.$B$BThey\'re using living sacrifices to fuel their rituals.$B$B$N, you must stop this. It matters not who or what is in those cages, they must be freed. I would guess that the vrykul hold the keys.$B$BThe last thing we need is more of those strange vrykul threatening us, or worse, them wakening something even more evil....]', '[Greatmother Ankha has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to her at Camp Winterhoof when you manage to do so.]', '', '去找嚎風峽灣的主母安卡。', '傑拉布倫的囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11266, 'zhTW', '[Gjalerbron Attack Plans]', '[These plans detail an imminent attack upon Camp Winterhoof. It would appear that the frost wyrm, Glacion, who circles overhead, is to be used for the offensive.$B$BSurely Celea Frozenmane would be of some assistance in this matter. Deliver the plans to her at the camp to the east.]', '[Deliver the Gjalerbron Attack Plans to Celea Frozenmane at Camp Winterhoof.]', '', '去找嚎風峽灣的賽利亞‧冰鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11267, 'zhTW', '[The Frost Wyrm and its Master]', '[Your instincts were right to bring this to me, but my wind riders cannot fight a dragon. You must take help back west with you to Gjalerbron and slay the frost wyrm and its master, Wyrmcaller Vile!$B$BEven now it may be on its way!$B$BIf I\'m reading these plans correctly, blowing the wyrmcaller\'s horn on his platform, outside in the rear left area of Gjalerbron, will  call Glacion back. When the creature lands, destroy it!$B$BAnd $N, bring me the horn. We wouldn\'t want it falling back into the wrong hands!]', '[Slay Wyrmcaller Vile and use the Wyrmcaller\'s Horn to call down and slay Glacion. Then, return with the horn to Celea Frozenmane at Camp Winterhoof.]', '', '去找嚎風峽灣的賽利亞‧冰鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11268 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11268, 'zhTW', '[The Walking Dead]', '[Your assistance to us has been tremendous, $N, but there is something that is troubling me: these so-called Scourge.$B$BThe spirits of the land and air, the waters and the fire below the world, would not abide their presence, but seem to do nothing about them. We will see to it that they are dealt with!$B$BPerhaps it is asking too much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!]', '[Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Greatmother Ankha at Camp Winterhoof of your success.]', '', '去找嚎風峽灣的主母安卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11269 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11269, 'zhTW', '[Down to the Wire]', '[The vanguard of the Alliance force will be arriving within days. The soldiers will be expecting their winter gear to be prepared, but I\'ve still got more cloaks to make.$B$BI\'ve been using spotted hippogryph down for the cloaks\' linings, but my stock won\'t last!$B$BYou\'ve got to help me, $N. Captain Adams will have my hide if those cloaks aren\'t ready in time! Bring me all the down you can find out there. It\'s dropped to the ground by molting hippogryphs flying over the wilderness around the fort.]', '[Gil Grisert wants you to bring him 10 clumps of Spotted Hippogryph Down.]', '', '去找嚎風峽灣的吉爾‧葛瑞斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11270 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11270, 'zhTW', '[War is Hell]', '[We\'re slowly finishing off the remnants of Stormwind\'s North Fleet stationed on this coast.  The bodies to the west are a testament to how brutal this confrontation has been.$B$BThis does not happen to bother my refined aesthetics, but it does present a danger to our lives.$B$BIn the lands of the Lich King, the dead are a weapon that can rise against us at any point in time.  Take this torch - you\'re going to make sure that doesn\'t happen.]', '[High Executor Anselm at Vengeance Landing wants you to take the Burning Torch and use it to burn 10 of the corpses littered to the west of town.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '陣亡戰士已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11271 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11271, 'zhTW', '[Hasty Preparations]', '[The down of the spotted hippogryph is prized by my people and used for everything from fletching to ceremonial clothing. We\'re making preparations to leave the post, so this is the last chance I\'ll get to gather it this season.$B$BWith your help, I\'ll have enough to make sure everyone has the equipment they need for the long trek into the hills. Conditions worsen very quickly up there and a storm can blow in without warning.$B$BThe down can be found all over the ground in the area surrounding the post.]', '[Ahota Whitefrost at Camp Winterhoof wants you to bring him 10 clumps of Spotted Hippogryph Down.]', '', '去找嚎風峽灣的阿喉塔‧白霜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11272 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11272, 'zhTW', '[A Score to Settle]', '[This elf prince thinks he can come to my town, insult my queen, kill my men and get away with it?  He thinks we\'re going to stand by while the hordes of Utgarde build up to launch an attack?$B$BNot in a million years.$B$BYou\'re going to walk right into Utgarde and kill him in front of any of these vrykul gorillas that might be watching.  I want Arthas to know that we\'ve arrived and we\'re playing for keeps.]', '[High Executor Anselm wants you to to go into Utgarde and slay Prince Keleseth.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11273 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11273, 'zhTW', '', '', '[Search Wyrmskull Village for Pulroy.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11274, 'zhTW', '', '', '[Search Wyrmskull Village for Zedd.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11275, 'zhTW', '[Making the Horn]', '[My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever.$B$BTo prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts.$B$BBring me the best dire ram horns you can find, $N, and I\'ll select one from among them.]', '[Nokoma Snowseer at Camp Winterhoof wants you to bring her 6 Undamaged Ram Horns.]', '', '去找嚎風峽灣的諾可瑪‧雪先知。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11276, 'zhTW', '', '', '[Search the Utgarde Catacombs for Glorenfeld.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11277, 'zhTW', '[The Depths of Depravity]', '[They\'re keepin\' Daegarn locked up in a cage at the large fightin\' ring nearby. From what I\'ve gathered, the Dragonflayers bring out their prisoners to battle against their most powerful gladiators. They dump the losers in the basement where Scourge necromancers turn \'em into ghoulies! It\'s horrifying!$B$BBut first things first! The tablets are strewn about all across this dungeon. Let\'s get those recovered before you go off tryin\' to be a hero.]', '[Glorenfeld at the Utgarde Catacombs wants you to collect 10 Wyrmskull Tablets.]', '', '去找嚎風峽灣的葛羅倫費德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11278, 'zhTW', '[Return to Valgarde]', '[\'Tis a shame we lost two of our best dwarves while uncovering these relics. They sacrificed their lives to keep this information safe.$B$B<Glorenfeld wraps the cipher and tablets in a tattered cloth.>$B$BTake these back to Valgarde. McSorf will know what to do with the find.$B$BAs for me? I\'ll be alright on my own. I\'ve gotten this far in one piece!]', '[Take Glorenfeld\'s Package to Beltrand McSorf at Valgarde Port.]', '', '去找嚎風峽灣的貝爾川·麥克索夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11279, 'zhTW', '[Green Eggs and Whelps]', '[This new plague that we\'re working on is wonderful and I think we should expand its testing.$B$BHow about testing it on proto-whelps?!$B$BJust think of the possibilities. The ability to infect not only humanoids, but extend our reach to any creature!$B$BHere, I\'ve hoarded an extra plague canister for the right time and place, and you look like the right person.$B$BSpray the eggs at Ember Clutch to the northwest, then get specimens from the plagued proto-whelps that hatch.]', '[Plaguebringer Tillinghast has asked you to collect 10 Plagued Proto-Whelp Specimens and deliver them to him at New Agamand.]', '', '去找嚎風峽灣的瘟疫使者提林加斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11280, 'zhTW', '[Draconis Gastritis]', '[Wait, that gives me an idea! What if it didn\'t kill the whelps because it was sprayed on the outside of their eggs?$B$B$N, we have to get the plague inside of them!$B$BI know! I\'ve got some plagued meat here. Take it to the Ember Clutch and get them to eat it!$B$BBut no, we\'re thinking too small. Let\'s get one of the proto-drakes flying overhead to come down and eat it.$B$BYes!$B$BStay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.]', '[Plaguebringer Tillinghast at New Agamand wants you to use Tillinghast\'s Plagued Meat to attract down a Proto-Drake and observe its reaction to eating the stuff.]', '', '去找嚎風峽灣的瘟疫使者提林加斯特。', '已觀察始祖幼龍瘟疫的結果', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11281, 'zhTW', '[Mimicking Nature\'s Call]', '[The horn has been roughed out, but before I make the traditional carvings, I want to be certain that it will work. Ahota tells me that he tests his horns at the foot of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters have used the acoustics of frozen water in this way for generations. I can\'t wait to learn more!$B$BWill you help me test out the horn? If I\'ve done everything right, you may even attract a yeti, so be prepared! Bring the horn back once you\'ve tested it. ]', '[Test the Carved Horn and then return to Nokoma Snowseer at Camp Winterhoof with the results.]', '', '去找嚎風峽灣的諾可瑪‧雪先知。', '測試諾科瑪之角', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11282, 'zhTW', '[A Lesson in Fear]', '[When you\'ve been in lots of fight like Gorth, you learn that to beat enemy good you have to make them really scared to die!$B$BBut these vrykuls not afraid.  You kill one and another comes... screaming louder and with a bigger weapon than the one before.$B$BOnly thing that makes vrykuls afraid is when we kill the biggest and baddest vrykul of all.$B$BGo fight the Winterskorn across the blockade until hero vrykuls show up!  Then you kill them dead and put queen\'s flag on corpses.  They must learn to fear!]', '[Gorth wants you to kill Ulf the Bloodletter, Oric the Baleful and Gunnar Thorvardsson and drive the Forsaken Banner through their corpses.  Slay Vrykul across the Forsaken blockade until they appear.]', '', '去找嚎風峽灣的葛司中士。', '邪惡者歐里克的屍體已被刺穿', '放血者烏爾夫的屍體已被刺穿', '岡納·索爾瓦森的屍體已被刺穿', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11283, 'zhTW', '[Baleheim Bodycount]', '[Them vrykuls just keeps coming and coming out from town west of here.  No end in sight!$B$BGorth has an idea.  You go INSIDE town and kill them Winterskorn there.  THEN they stop coming here!]', '[Sergeant Gorth wants you to kill 16 Winterskorn Vrykul inside Baleheim.]', '', '', '巴雷海姆的死亡人數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11284, 'zhTW', '[The Yeti Next Door]', '[Maybe if the sentries won\'t help me, you will? I\'m the foreman of the mine just across the bridge. My men are mining ore for the weapons our expeditionary force will need to carve a path into the Grizzly Hills.$B$BA giant yeti has invaded the mine, blocking the tunnel we need to expand! We\'ve tried yelling at him and smoking him out, but nothing\'s worked.$B$BMaybe you could rouse it from its sleep with a meal of meat from the frosthorn rams in the snowy areas around town? Please? We\'re desperate!]', '[Foreman Colbey at Fort Wildervar wants you to defeat Shatterhorn.]', '', '去找嚎風峽灣的工頭寇畢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11285, 'zhTW', '[Baleheim Must Burn!]', '[Killing the Winterskorns maybe not enough.  Maybe we burn their houses too!  Uh... and their bridges.  We should burn whole town to be safe!$B$BYou take this torch.  Go to Baleheim, to the west, and burn EVERYTHING!  That teach them good.]', '[Sergeant Gorth wants you to go to Baleheim and use Gorth\'s Torch to burn 1 Winterskorn Dwelling, 1 Winterskorn Watchtower, 1 Winterskorn Bridge and 1 Winterskorn Barracks.]', '', '', '寒冬扭曲住所已焚燒', '寒冬扭曲瞭望塔已焚燒', '寒冬扭曲橋樑已焚燒', '寒冬扭曲軍營已焚燒', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11286, 'zhTW', '[The Artifacts of Steel Gate]', '[I came out here for a different reason; an old friend of mine has been calling to me in my dreams. But now that I see these small things with their machines making a big hole in the ground, it makes my blood boil.$B$BFrom what I can see, these dwarves, as they are known, are digging up artifacts; artifacts that could be important to our past.$B$BI want you to go down there and get these things for me. Don\'t let any of those dwarves stand in your way.]', '[Sage Mistwalker has asked you to collect 10 Steel Gate Artifacts. When you have all of them, return to him at Steel Gate.]', '', '去找嚎風峽灣的賢者霧行。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11287, 'zhTW', '', '', '[Greatmother Ankha has asked you to check on the condition of Sage Mistwalker. She believes him to be at or near Steel Gate.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11288, 'zhTW', '[The Shining Light]', '[<Ares gasps for air as he tries to speak.>$B$BI am an envoy of the Argent Crusade, charged with a sacred duty.$B$BOur forces were decimated in the Plaguelands. By the light of dawn, the artifact was cleansed and made pure once more. So many perished in the wake of its redemption.$B$BThere is still a chance... still time.$B$BThe artifact was hurled into the den of the fallen, far below us. Guarded by the unmerciful dead.$B$B<Ares\' body glows with blinding light.>$B$BLight. Will. Protect. You.$B$B]', '[Ares the Oathbound in the Utgarde Catacombs wants you to recover the Sacred Artifact.$B$BThis is a timed quest.]', '', '去找嚎風峽灣的『誓縛』愛力士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11289, 'zhTW', '[Guided by Honor]', '[<Ares smiles.>$B$BGlory to the Light. You have done it!$B$B<Ares coughs.>$B$BTake the artifact and return it to Valgarde. Lord Irulon Trueblade awaits its return.$B$BFight with honor, friend. Always. Honor.$B$B<Ares dies.>]', '[Return the Sacred Artifact to Lord Irulon Trueblade at Valgarde.]', '', '去找嚎風峽灣的埃盧隆·真刃領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11290, 'zhTW', '[Dragonflayer Battle Plans]', '[While we were able to gather very little information as to the whereabouts of Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull Village.$B$BIntelligence gathered from the rescued soldiers indicates that Yanis guards Dragonflayer battle plans.$B$BI need you to go back to Wyrmskull and recover those plans. Kill any vrykul that get in your way - including Yanis!]', '[Vice Admiral Keller at Valgarde Port in the Howling Fjord has asked that you bring him the Dragonflayer Battle Plans.$B$B]', '', '去找嚎風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11291, 'zhTW', '[To Westguard Keep!]', '[<Vice Admiral Keller rolls up the battle plans.>$B$BWe\'ve got all the information we need to keep Valgarde protected. You must take these battle plans to Westguard Keep, located on the western fjord cliff wall. Speak with the flight master assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards Westguard.$B$BOnce there, find Captain Adams. He\'s the one in charge. Adams will know what to do with these plans.]', '[Take the Dragonflayer Battle Plans to Captain Adams at Westguard Keep in the Howling Fjord.$B$B]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11292, 'zhTW', '[Preying Upon the Weak]', '[Glad to meet you. I\'ve come here from the Grizzly Hills to do business with your cohorts. My people maintain a large outpost there, and you\'d do well to visit it when you head north.$B$BI\'ve set up traps in the woodlands and snowy areas around here. With the meat and the furs from the creatures they capture, I\'ll have plenty to barter with the townspeople.$B$BI can offer you a share of my profits if you\'re willing to help gather prey from the traps. Beware though, you won\'t be the only predator out there.]', '[Trapper Jethan at Fort Wildervar wants you to bring him 8 pieces of Trapped Prey.]', '', '去找嚎風峽灣的陷捕者傑桑。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11293, 'zhTW', '叫賣麥酒!', '我們需要讓大家知道有關麥酒家族在啤酒節的事。你得到銀行外、軍事區、探險者大廳以及秘法區外的旗幟下大聲叫喊。不過我會讓事情簡單點，我會借你競速山羊韁繩和一隻競速山羊4分鐘。用馬鞭驅趕山羊奔跑，不過試著別讓牠累過頭。', '在銀行外、軍事區、探險者大廳及秘法區外散佈有關啤酒節的訊息。', '', '去找丹莫羅的畢肯‧麥酒。', '在銀行外叫賣', '在軍事區叫賣', '在探險者大廳叫賣', '在秘法區叫賣', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11294, 'zhTW', '叫賣雷酒!', '是時候讓人們知道雷酒聽見了他們對於好啤酒的渴求。你得到銀行外、軍事區、探險者大廳以及秘法區外的旗幟下大聲叫喊。$B$B不過我會讓事情簡單點，我會借一隻山羊和一些馬鞭給你4分鐘。$B$B跑太快的時候要小心，你在鐵爐堡可找不到蘋果......我們可不想幫到麥酒的使者。', '在銀行外、軍事區、探險者大廳及秘法區外散佈有關啤酒節的訊息。', '', '去找丹莫羅的達然‧雷酒。', '在銀行外叫賣', '在軍事區叫賣', '在探險者大廳叫賣', '在秘法區叫賣', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11295, 'zhTW', '', '', '[Speak to Sergeant Gorth at the blockade near the elevator west of Vengeance Landing in Howling Fjord.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11296, 'zhTW', '[Rivenwood Captives]', '[Something, most likely the walking dead known as the Scourge, has agitated the creatures hereabouts.$B$BWhile escorting the sage here, we lost most of our hunting force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the north.$B$BI must stay here to protect the small force we have left, but you... you could see if my longrunners are still alive, trapped within the riven widow\'s cocoons.$B$BWould you do this, stranger?]', '[Longrunner Skycloud has asked you to free his 7 Winterhoof Longrunners. Once you have managed to do so, return to him at Steel Gate.]', '', '去找嚎風峽灣的遠偵斥候穹雲。', '已釋放冬蹄長跑者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11297 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11297, 'zhTW', '', '', '[Speak to Apothecary Malthus at the Apothecary Camp.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11298, 'zhTW', '[What\'s in That Brew?]', '[To the southeast is an area called Whisper Gulch. It\'s overrun with members of the Explorers\' League who\'ve gone mad! They attacked our caravan as it passed through the area, and they\'ve harried our foraging parties as well.$B$BI must know what\'s causing this madness! I suspect that whatever they\'re drinking from the kegs scattered around the gulch contributes to their insanity. I want you to steal the kegs from those dwarves while they\'re busy mining away.]', '[Apothecary Malthus at the Apothecary Camp wants you to bring him 5 Dwarven Kegs.]', '', '去找嚎風峽灣的藥劑師馬爾薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11299, 'zhTW', '', '', '[Find Daegarn in the Ring of Judgement located inside the Utgarde Catacombs.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11300, 'zhTW', '[Stunning Defeat at the Ring]', '[Oluf will come out if you defeat the other gladiators. That\'s \'bout the only way we\'re getting\' that cipher back. Put on your whompin\' boots and get busy in the Ring of Judgement. If you do manage to get the cipher back, return it to Glorenfeld o\'er near the entrance to these catacombs.$B$BMe? Don\'t worry about me! We\'re on the brink of discovering the missing link to human-kind!]', '[Defeat the gladiators at the Ring of Judgement and face Oluf the Violent. Defeat Oluf and recover the Ancient Cipher.$B$BReturn the Ancient Cipher to Glorenfeld at the entrance to the Utgarde Catacombs.]', '', '去找嚎風峽灣的葛羅倫費德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11301, 'zhTW', '[Brains! Brains! Brains!]', '[Has Malthus drawn you in with his blather about beer kegs and crazy dwarves?$B$BI\'m not questioning that the dwarves are crazy, but I don\'t think stealing their beer is going to do any good.$B$BWhat we need is brains. Lots of brains. We\'ll get down to the bottom of this mystery in no time, and perhaps even find a new component for the plague.$B$BTake this saw, go southeast into the Whisper Gulch, and kill yourself some dwarves. Use the saw to help you harvest the brains and bring them back here.]', '[Apothecary Grick at the Apothecary Camp wants you to bring him 12 Deranged Explorer Brains.]', '', '去找嚎風峽灣的藥劑師格里克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11303, 'zhTW', '', '', '[Speak to Lydell at Lydell\'s Ambush.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11304, 'zhTW', '[New Agamand]', '[I\'m afraid our equipment isn\'t exactly the best here at Vengeance Landing.  After all it\'s a military controlled outpost.$B$BI will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do.$B$BYou must hurry, $N.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!]', '[Bring Lysander\'s Strain to Chief Plaguebringer Harris in New Agamand in western Howling Fjord.]', '', '去找嚎風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11305, 'zhTW', '[A Tailor-Made Formula]', '[We\'ve been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won\'t drop dead.$B$BLet\'s face it, $N, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul\'s biology.$B$BHalgrind\'s chieftain fled the town after we took it over; you\'ll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.]', '[Obtain the Dragonflayer Patriarch\'s Blood from Thorvald at Thorvald\'s Camp and bring it to Chief Plaguebringer Harris in New Agamand.]', '', '去找嚎風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11306, 'zhTW', '[Apply Heat and Stir]', '[You\'ve done well so far, $N.  I\'d like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague.$B$BTake this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.]', '[Fill the Empty Apothecary\'s Flask at the Cauldron of Vrykul Blood, then mix the Flask of Vrykul Blood with Harris\'s Plague Samples nearby until you\'ve obtained a Balanced Concoction.$B$BReturn to Chief Plaguebringer Harris when you\'ve completed this task.]', '', '去找嚎風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11307, 'zhTW', '[Field Test]', '[Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind.  If all goes according to plan, they will disintegrate immediately as the plague devours their innards!$B$BYou will find Halgrind north of here.  Our plaguebringers are deploying the previous strain there - shouldn\'t be hard to spot.]', '[Venture into Halgrind and use the Plague Spray on 10 Plagued Dragonflayer Vrykul.  Return to Chief Plaguebringer Harris to report the results.]', '', '去找嚎風峽灣的首席瘟疫使者哈里斯。', '已對染疫維库人噴灑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11308, 'zhTW', '', '', '[Speak to "Hacksaw" Jenny in New Agamand.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11309, 'zhTW', '[Parts for the Job]', '[So Harris wants a demolition job, eh?  Yeah, I can help out.$B$BYou\'re gonna have to get me some parts, though.  I can\'t afford to use up my choice components on something that\'s gonna get blown up.$B$BFirst of all, I\'m going to need shoveltusk ligaments... way better than the human kind.$B$BI will also need a pound of flesh.  A fellow known as Anton sells cheap meat.  He travels up and down the road to the west.]', '["Hacksaw" Jenny in New Agamand wants you to obtain 6 Shoveltusk Ligaments and 1 Fresh Pound of Flesh.]', '', '去找嚎風峽灣的『鋼鋸』潔妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11310, 'zhTW', '[Warning: Some Assembly Required]', '[Well, here you are!  Our friend\'s going to be somewhat... unstable.  So I suggest not putting him together until reaching Halgrind.$B$BOnce you\'re there, use the abomination to round up as many vrykul as you can before self-destructing.$B$BCome back with whatever\'s left once you\'re done.  I can always use more body parts!]', '[Use the Abomination Assembly Kit in Halgrind and round up plagued Vrykul with your Mindless Abomination.  Slay at least 20 and return to "Hacksaw" Jenny in New Agamand when you\'re done.]', '', '去找嚎風峽灣的『鋼鋸』潔妮。', '染疫維库人已消滅', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11311, 'zhTW', '[Suppressing the Elements]', '[If you are to survive here, as we have, you must learn to face the environment\'s challenges head on. The elements will claim your life if you\'re not vigilant, as the proliferation of elementals in these northern hills shows.$B$BWe must cull the elementals one last time before we can leave this place. Are you willing to aid us while we continue to make preparations?$B$BYou must kill any iceshard elementals or howling cyclones you encounter in the snowy hills surrounding the outpost.]', '[Wind Tamer Kagan at Camp Winterhoof wants you to kill 8 mountain elementals. You may kill either Howling Cyclones or Iceshard Elementals.]', '', '去找嚎風峽灣的馴風者卡剛。', '山脈元素生物已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11312, 'zhTW', '', '', '[Speak with Lurielle at the Frozen Glade.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11313, 'zhTW', '[Spirits of the Ice]', '[The ice elementals surrounding our glade were once our companions, but a volatile and destructive force has swept through the land, turning them against us!$B$BThis is but one of the horrors my sisters and I have endured. We have revealed ourselves to you in the hope that you will help us stave off the decay that has crept into our glades and poisoned our sisters!$B$BWe\'ve been gathering the cores of the ice elementals and keeping them safe so that one day, we might be able to restore them. Will you help?]', '[Lurielle at the Frozen Glade wants you to bring her 15 Icy Cores.]', '', '去找嚎風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11314, 'zhTW', '[The Fallen Sisters]', '[To the southwest was a glade that used to look much like this one. Mysterious forces and alien magics are reshaping the land. The glade has thawed, the sisters living there driven mad by the sudden change.$B$BWe thought to reach out to them, but they attacked us. I fear many may be beyond saving, but I cannot give up hope.$B$BTake my pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.]', '[Lurielle at the Frozen Glade wants you to use her pendant on 7 Chill Nymphs.]', '', '去找嚎風峽灣的露麗兒。', '已釋放寒冰水靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11315, 'zhTW', '[Wild Vines]', '[The sisters who lived in the Vibrant Glade, to the southwest, used to tend to gorgeous beds of scarlet ivy, but the same force that has driven them mad has transformed their beloved ivy.$B$BThe vines now grasp at the feet of the unwary, or lash at any who approach the glade. Before we can reclaim the glade, the vines must be tamed and uprooted.$B$BClear as much of the ivy as you are able. It has already begun to grow out of control.]', '[Lurielle at the Frozen Glade wants you to kill 8 Scarlet Ivy.]', '', '去找嚎風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11316, 'zhTW', '[Spawn of the Twisted Glade]', '[The glade to the west has been transformed into a hideous place called the Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the glade.$B$BI cannot guess where the creatures came from or what horrible forces animate them, but they must be dealt with!$B$BI fear that if they are allowed to dominate the glade, they will poison it beyond redemption. Clear the glade of these creatures who murdered our sisters.]', '[Lurielle at the Frozen Glade wants you to kill 10 Thornvine Creepers.]', '', '去找嚎風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11317, 'zhTW', '[The Cleansing]', '[We braved the Rivenwood because of my troubled dreams concerning my worg life-friend, Ulfang. He has called out for help, and you must go to him.$B$BBut, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.$B$BFirst, you must cleanse your inner turmoil.$B$BThere is a shrine that sits at the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it from the western base of the mountain.$B$BMeditate there and then return to me.]', '[Sage Mistwalker at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.]', '', '去找嚎風峽灣的賢者霧行。', '已淨化內心的紛亂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11318, 'zhTW', '現在就是山羊競速…差不多。', '所以你想瞧瞧競速山羊?希望你已經準備好面對極速挑戰了。『但是』在我讓你出發之前，你得向我證明你知道該如何操控這些良好的生物。$B$B條件如下:我會借給你一些競速韁繩還有一頭山羊。你得向我證明你會操縱這些山羊。$B$B讓山羊在疾馳、快步和慢跑的狀態下各維持8秒。假如你想知道如何駕馭這些山羊，去找我的學徒保爾·安伯斯堤爾吧。', '你有4分鐘的時間可以鞭打山羊，然後在3種不同速度下各維持8秒。', '', '去找丹莫羅的奈爾‧拉姆斯登。', '維持快步8秒', '維持慢跑8秒', '維持疾馳8秒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11319, 'zhTW', '[Seeds of the Blacksouled Keepers]', '[The glade to the northwest, now the Twisted Glade, used to be home to a number of keepers of the glade. Together with the sisters, they saw to the glade\'s upkeep.$B$BWhen the glade changed, the sisters died, but somehow the keepers managed to survive. Now, they seed the land with poisonous spores that wither healthy greenery.$B$BI\'ll give you one of the cores from the ice elementals. Once you\'ve destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.]', '[Lurielle at the Frozen Glade wants you to freeze 8 Spores.]', '', '去找嚎風峽灣的露麗兒。', '孢子已冰凍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11320, 'zhTW', '[[NYI] Now this is Ram Racing... Almost.]', '[Quest Description]', '[Log Descritpion ]', '', '去找丹莫羅的達然‧雷酒。', '維持綠色速度6秒', '維持黃色速度6秒', '維持紅色速度6秒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11322, 'zhTW', '[The Cleansing]', '[Of late I\'ve had nightmares concerning a worg named Ulfang. He has called out for help, and you must go to him.$B$BHowever, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.$B$BBut first, you must cleanse your inner turmoil through meditation.$B$BThere is a shrine that sits at the top of Frostblade Peak, far to the northeast. A single path leads up to it from the western base of the mountain.$B$BMeditate there to cleanse yourself and then return to me.]', '[Watcher Moonleaf at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.]', '', '去找嚎風峽灣的看守者月葉。', '已淨化內心的紛亂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11323, 'zhTW', '[In Worg\'s Clothing]', '[From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.$B$BHe is in great danger.$B$BI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.$B$BPlease, $c, find and help him.]', '[Sage Mistwalker has asked you to seek out and help Ulfang in the Rivenwood.$B$BIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11324, 'zhTW', '[Alpha Worg]', '[When you\'ve eaten Talonshrike\'s eyes, you should be able see Garwal and rip out his throat!$B$B$R-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Mistwalker that I am once more the alpha worg!]', '[Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Sage Mistwalker at Steel Gate.]', '', '去找嚎風峽灣的賢者霧行。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11325, 'zhTW', '[In Worg\'s Clothing]', '[From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.$B$BHe is in great danger!$B$BI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.$B$BPlease, $c, find and help him.]', '[Watcher Moonleaf has asked you to seek out and help Ulfang in the Rivenwood.$B$BIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11326, 'zhTW', '[Alpha Worg]', '[When you\'ve eaten Talonshrike\'s eyes, you should be able see Garwal and rip out his throat!$B$B$R-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Moonleaf that I am once more the alpha worg!]', '[Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Watcher Moonleaf at Steel Gate.]', '', '去找嚎風峽灣的看守者月葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11327, 'zhTW', '[Mission: Package Retrieval]', '[Well darn, we need some of that plague-stuff.$B$BI know!$B$BWhile you were destroying the vats, I happened to spy one of the apothecaries from New Agamand being pulled into Halgrind by the vrykul down in there. Poor fella\'.$B$B$N, I\'d bet anything that apothecary has the goods on him. Think you could go into Halgrind and retrieve his package?]', '[Scout Knowles has asked you to retrieve the Apothecary\'s Package from inside Halgrind. Once you have it, return to the scout at the Ember Spear Tower.]', '', '去找嚎風峽灣的斥候諾雷斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11328, 'zhTW', '[Mission: Forsaken Intel]', '[Right, so I think you should get this stuff over to Peppy Wrongnozzle back at the keep. She\'s something of an amateur alchemist, but she\'s the only one we\'ve got.$B$BOne thing about Peppy; she does love her drink. So, you\'ll likely find her at the tavern \'soaking up the atmosphere\'.$B$BI\'m sure she\'ll know what to do.]', '[Scout Knowles has asked you to deliver the Apothecary\'s Package to Peppy Wrongnozzle at Westguard Keep.]', '', '去找嚎風峽灣的派比·錯鼻。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11329, 'zhTW', '[I\'ll Try Anything!]', '[I never want to see another barrel of salted fish as long as I live! Filling barrels day in and day out, and there are still more to be filled!$B$BI wish I hadn\'t used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I\'m lucky if I can catch a fish an hour!$B$BI hear the northern barbfish make pretty good bait, but who\'s crazy enough to dive into a freezing cold lake and hack up the water plants in search of them? Not me... but maybe, just maybe, I can persuade you to...]', '[Christopher Sloan at Fort Wildervar wants you to bring him 5 Northern Barbfish.]', '', '去找嚎風峽灣的克里斯多夫·斯洛安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11330, 'zhTW', '[Absholutely... Thish Will Work!]', '[Voila, inshtant plague vacshine!$B$BBut I sure as heck am not going to try thish on myself. And I know you don\'t want to be my tesht shubject!$B$BOh, I\'ve got... I\'ve got an idea!$B$BWe\'ve got a vrykul prishoner being held down in the cells under the keep. Why don\'t you take thish mix I whipped up down there, and get that giant to drink it ...hic?!]', '[Peppy Wrongnozzle at Westguard Keep has suggested that you take her Peppy\'s Special Mix and administer it to the Dragonflayer Vrykul Prisoner to witness its results.]', '', '去找嚎風峽灣的派比·錯鼻。', '已對維库人囚犯施用佩皮的調製藥劑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11331 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11331, 'zhTW', '', '', '[Peppy Wrongnozzle has suckered you into giving the bad news about the Forsaken plague to Captain Adams. Visit him at Westguard Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11332, 'zhTW', '[Mission: Plague This!]', '[The Royal Apothecary Society thinks they\'re going to perfect a new plague to melt us down where we stand?!$B$BNot on my watch!$B$BGet out to the courtyard and speak with Greer Orehammer. He\'s got a gryphon and some bombs ready for you. I want you to bomb the plague tanks at New Agamand to smithereens!]', '[Captain Adams has ordered you to get 5 bomb hits on the Plague Tanks at New Agamand. Do not return to him at Westguard Keep until you have accomplished that.]', '', '去找嚎風峽灣的亞當斯隊長。', '瘟疫戰車命中次數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11333 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11333, 'zhTW', '[Into the World of Spirits]', '[While the Explorers\' League may discern bits and pieces of the past through their archaeological findings and the Vice Admiral might extract some knowledge of the present through brute force, the truth lies with the spirits.$B$BWith the proper reagents I am able to see into the spirit world. It is there that the past, present and future of Northrend resides.$B$BIf you wish to learn more, I will require my reagent pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of here.]', '[Thoralius the Wise at Valgarde wants you to find his Reagent Pouch.]', '', '去找嚎風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11337 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11337, 'zhTW', '戰鬥的號角:暴風之眼', '和部落的鬥爭沒有邊界，$N。既使在外域，領土的糾紛與古老的仇恨依舊可以挑起戰爭的烽火。$B$B前往暴風之眼吧，確保聯盟將會像在艾澤拉斯一樣地獲勝。', '在暴風之眼的戰場中獲勝，然後向任何一座首都或撒塔斯的聯盟准將回報。', '風暴之眼的勝利', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11341, 'zhTW', '戰鬥的號角:暴風之眼', '我們將會戰鬥並擊敗我們在各處發現的敵人。艾澤拉斯，外域，各地都一樣。$B$B我們不允許聯盟在暴風之眼中佔有優勢。今天就去對他們開戰...明天可能就太遲了!', '在暴風之眼的戰場中獲勝，然後向任何一座首都或撒塔斯的部落戰爭使者回報。', '風暴之眼的勝利', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11343, 'zhTW', '[The Echo of Ymiron]', '[The spirit world has fallen under the sway of the Lich King. Fearsome creatures made of pure nightmare now stand watch over the realm of the elements. I sense that these val\'kyr are guarding a terrible secret.$B$BI am too old and weak to survive another journey. You must go in my place, $N.$B$BTake this incense burner to Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the northeast! Avoid the val\'kyr at all costs lest they make you a permanent fixture in their world.]', '[Thoralius the Wise wants you to search Wyrmskull Village while you are in the spirit world and find information about the Secrets of Wyrmskull.]', '巨龍顱骨的秘密已揭露', '去找嚎風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11344, 'zhTW', '[Anguish of Nifflevar]', '[All that we know of the vrykul indicates that they only recently appeared in Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? Surely if the vrykul had previously existed in Northrend we would have known.$B$BYou must press on to Nifflevar. To get there you must go northeast, through Wyrmskull Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the fjord.$B$BUse the incense burner once you arrive at Nifflevar and search the area for clues.]', '[Thoralius the Wise wants you to search Nifflevar while you are in the spirit world and find information about the Secrets of Nifflevar.]', '尼弗雷瓦爾的秘密已揭露', '去找嚎風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11346, 'zhTW', '[The Book of Runes]', '[The vast rocky area to the southeast, Giants\' Run, has been overrun by Iron Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, then carving runes on them.$B$BI can\'t fathom their motives, but I suspect they\'re somehow trying to turn the giants into weapons. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they\'re carving on the giants.$B$BCapture the pieces of this book, assemble them, and bring it back to me, $N.]', '[Prospector Belvar at Fort Wildervar wants you to bring him The Book of Runes.]', '', '去找嚎風峽灣的勘察員貝爾瓦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11348, 'zhTW', '[The Rune of Command]', '[Can you feel the power emanating from the runes I\'ve carved on this tablet? They\'re smaller versions of the runes that the Iron Dwarves are using. We\'ll use it to shut down their operation.$B$BTake it to Giants\' Run and use it on a stone giant that the dwarves have not altered.$B$BThe giant should obey you, but I\'ve tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants\' Run.]', '[Prospector Belvar at Fort Wildervar wants you to test the Rune of Command and defeat Binder Murdis.]', '', '去找嚎風峽灣的勘察員貝爾瓦。', '測試指揮符文', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11350, 'zhTW', '[The Book of Runes]', '[Chieftain Ashtotem dispatched me on a scouting mission to Giants\' Run, a broad, rocky plateau to the southeast, past the Frozen Glade.$B$BThe area has been taken over by Iron Dwarves who seem to be altering the giants as they emerge from the earth.$B$BThe iron rune stonecallers and binders carry large tomes with them, which must contain the runes they\'re carving on the giants.$B$BCapture the pieces of this book, assemble them, and bring it back to me. It\'s the only way we\'ll understand their plans.]', '[Longrunner Pembe at Camp Winterhoof wants you to bring him The Book of Runes.]', '', '去找嚎風峽灣的遠偵斥候潘比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11351, 'zhTW', '[Mastering the Runes]', '[I think I\'ve figured out what the Iron Dwarves are doing. The tools they use are imbued with magic during their forging.$B$BWhen they\'re used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.$B$BIf I had a set of those tools, I could mimic the runes in the book. I captured one of these boxes from one of the pavilions at Giants\' Run, but it was empty. Look for similar boxes and recover a set of tools from them.]', '[Bring a set of Iron Rune Carving Tools to Longrunner Pembe at Camp Winterhoof.]', '', '去找嚎風峽灣的遠偵斥候潘比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11352, 'zhTW', '[The Rune of Command]', '[Can you feel the power emanating from the runes I\'ve carved on this tablet? They\'re smaller versions of the runes that the Iron Dwarves are using. We\'ll use it to shut down their operation.$B$BTake it to Giants\' Run and use it on a stone giant that the dwarves have not altered.$B$BThe giant should obey you, but I\'ve tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants\' Run.]', '[Longrunner Pembe at Camp Winterhoof wants you to test the Rune of Command and defeat Binder Murdis.]', '', '去找嚎風峽灣的遠偵斥候潘比。', '測試指揮符文', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11356, 'zhTW', '', '', '[Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11357 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11357, 'zhTW', '', '', '[Speak with a Masked Orphan Matron in either Razor Hill, Brill or Falconwing Square.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11358, 'zhTW', '[The Lodestone]', '[If we can locate what\'s luring the giants northwest, we might be able to stop them before they reach their destination.$B$BAlthough I was able to decipher many of the runes on the samples you brought me, the ones I don\'t know concern me the most. When I visited Giants\' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn.]', '[Researcher Aderan at Fort Wildervar wants you to compare the Rune Sample with the Broken Tablet.]', '', '去找嚎風峽灣的研究員艾德蘭。', '將符文與破碎石板比對', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11359, 'zhTW', '[Demolishing Megalith]', '[Binder Murdis created Megalith to be the most powerful of the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. After the expeditionary force arrives, our soldiers will be able to isolate and defeat the remaining giants and oust their Iron Dwarf masters from their camps.$B$BSearch the foothills of Frostblade Peak, north of Giants\' Run for Megalith and defeat him!]', '[Defeat Megalith and return to Researcher Aderan at Fort Wildervar.]', '', '去找嚎風峽灣的研究員艾德蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11360, 'zhTW', '[Fire Brigade Practice]', '[With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?$B$BNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.$B$BGood bye, $N.  When you\'re done with fire brigade practice, please visit us again!]', '[Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.]', '', '去找艾爾文森林的變裝的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11361, 'zhTW', '[Fire Training]', '[The grunts set up a fire training area outside the village.  These days, Razor Hill\'s buildings often catch fire -- you should lend a hand and train as a fire fighter!$B$BHead west out of Razor Hill, then turn right as you pass the village\'s wall.  Find the training area, then grab buckets and toss them on the practice fires.]', '[Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.]', '', '去杜隆塔爾找剃刀嶺的戴面具的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11365, 'zhTW', '[March of the Giants]', '[To the east, at Giants\' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. I know nothing of their goals, nor of their destination.$B$BThe glowing runes inscribed in the stone flesh of the giants guide them on their journey. Fell some of these giants.$B$BTake this pick with you and use it on the corpses of the runed stone giants. It will deactivate the runes. Once you\'ve tested enough giants, return to me with your findings.]', '[Sage Edan and Camp Winterhoof wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.]', '', '去找嚎風峽灣的賢者伊丹。', '符文石巨人屍體已分析', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11366, 'zhTW', '[The Lodestone]', '[We must find what\'s luring the giants northwest, so we can stop them before they reach their destination.$B$BWhile the rune samples gave us some clues, the unknown runes worry me.$B$BWhen I visited Giants\' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn about the identity of this lodestone.]', '[Sage Edan at Camp Winterhoof wants you to compare the Rune Sample with the Broken Tablet.]', '', '去找嚎風峽灣的賢者伊丹。', '將符文與破碎石板比對', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11367, 'zhTW', '[Demolishing Megalith]', '[Binder Murdis created Megalith to be a kind of keystone for the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and dedicate them to eliminating the last of the runed giants. Without their giants, the Iron Dwarves cannot stand against us.$B$BSearch the foothills of Frostblade Peak, north of Giants\' Run for Megalith and defeat him!]', '[Defeat Megalith and return to Sage Edan at Camp Winterhoof.]', '', '去找嚎風峽灣的賢者伊丹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11368, 'zhTW', '懸賞:奎克米瑞之心', '我有個不尋常的任務。我接觸到一個來自異世界的有錢人，對於恐怖的東西特別有興趣。$B$B她尤其想要奎克米瑞之心。$B$B我聽說那個怪物有三顆心臟，不過一顆就足夠滿足我們的需求。據我所知，你可以在奴隸監獄的深水池中找到奎克米瑞。', '風之貿易者札令姆要你取得奎克米瑞之心。將這顆心帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11370, 'zhTW', '懸賞:督軍的論述', '很多人都知道納迦族中的督軍卡利斯瑞是個強大的戰士，卻很少人知道他把他的知識全都記錄下來。$B$B我有位顧客得知了此事，有很高的興趣想把論述拿到手。$B$B我想拜託你去盤牙蓄湖的蒸汽洞窟把那本書拿來給我。', '風之貿易者札令姆要你取得督軍的論述。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11371, 'zhTW', '懸賞:盤牙侍從', '瑪頓恩聆聽並且遵從，我現在希望你協助我。$B$B現在這是我的職責了，盤牙部族的侍從必須被毀滅。去那些陰暗潮濕的角落尋找他們，就在盤牙蓄湖的蒸汽洞窟中。$B$B我只接受他們終極的滅絕。', '虛空行者瑪頓恩要你殺死14名盤牙侍從。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11372, 'zhTW', '懸賞:伊奇斯的冠羽', '最近有個牛頭人向我接頭，她的丈夫最近獲選成為酋長。她想替他的頭飾增添一點花樣。$B$B她尤其想拿到卑鄙的鷹王伊奇斯的冠羽。$B$B你要是對我的賞金有興趣的話，可以前去奧齊頓的賽司克大廳。', '風之貿易者札令姆要你取得伊奇斯的冠羽。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11373, 'zhTW', '懸賞:薩法爾的奇妙護符', '今天我有個私人的任務要拜託你，當然酬勞與它的危險度相等。$B$B我的家族和奈薩斯王子薩法爾還有他的手下，很有點『淵源』。要是他配戴的護符落入我的手中，那就表示他已經被解決了。$B$B如果你對我提供的賞金有興趣的話，你可以前往他在奧齊頓，法力墓穴的老巢。', '風之貿易者札令姆要你取得薩法爾的奇妙護符。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11375, 'zhTW', '懸賞:莫爾墨的低語', '等我說完，也許你就不會接下這個任務了。$B$B我有個古怪的客人專門在研究死去的存在。謠傳說現在被稱為莫爾墨的東西摧毀了那個他原先存在的世界。教授對他的「低語」很感興趣，想知道莫爾墨是如何完成這項任務。$B$B你願意前往奧齊頓的暗影迷宮，把那個東西帶來給我嗎?', '風之貿易者札令姆要你取得莫爾墨的低語。把東西帶到撒塔斯陰鬱城交給他好換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11376, 'zhTW', '懸賞:惡毒導師', '瑪頓恩聽說沒有人比暗影迷宮中的六臂女惡魔更殘酷了。$B$B前往奧齊頓吧，那這些惡魔給揪出來，全部殺光。$B$B如果這麼簡單的任務你都無法達成，那我們彼此也沒什麼話好說了。', '虛空行者瑪頓恩要你殺死3名惡毒導師。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11384, 'zhTW', '懸賞:扭曲分裂者的剪枝', '不久之前，一個卡多雷的女德魯伊交給我一項任務。當然，還有不少的金幣!$B$B顯然達納蘇斯方面希望能夠讓一個名為扭曲分裂者的秘法古樹復原。那棵巨樹現在陷入了恍惚或是腐化中，我不是很確定，但你可以在風暴要塞的波塔尼卡深處找到它。$B$B她說他們只需要一小段剪枝來讓它重新生長。', '風之貿易者札令姆要你取得扭曲分裂者的剪枝。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11385, 'zhTW', '懸賞:尋日導魔師', '風又再對瑪頓恩低語，隸屬於尋日者的導魔師今天就得被殺死。$B$B你可以在風暴要塞的波塔尼卡中找到他們。$B$B你想要賞金的話，就殺死那些導魔師。', '虛空行者瑪頓恩要你殺死6名尋日導魔師。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11386, 'zhTW', '懸賞:帕薩里歐的投映器', '我一直以為操縱者帕薩里歐使用魔法將他的影像在外域各處投射。很顯然我錯了。$B$B我最近的一個客人告訴我，血精靈使用一種特殊的機械裝置來和凱爾薩斯王子的投影溝通。就我所知，他們是從虛空風暴的薩希斯反叛者那邊取得的。$B$B我的客戶想要那個投映器。你何不去拜訪一下帕薩里歐?他就在風暴要塞的麥克納爾。', '風之貿易者札令姆要你取得帕薩里歐的投映器。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11387, 'zhTW', '懸賞:風暴要塞-熔爐毀滅者', '有些機械構裝生物在麥克納爾之中，瑪頓恩被告知它們必須被毀掉。$B$B前往風暴要塞，把那些風暴要塞-熔爐毀滅者給毀掉。$B$B然後你可以回來領取你的賞金。', '虛空行者瑪頓恩要你殺死5名風暴要塞-熔爐毀滅者。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11388, 'zhTW', '懸賞:史蓋力司卷軸', '今天的客人想找樣真的很罕見的東西。$B$B傳說先驅者史蓋力司是上古諸神的僕人。還說他有著一個巨大的卷軸記載著他們要如何支配宇宙生命的指示。$B$B目前的這位買家希望<他/她>能親自摸摸那個卷軸，當然<他/她>是讀不了上頭的文字的。$B$B到風暴要塞的亞克崔茲，把東西拿來給我，好嗎，$c?', '風之貿易者札令姆要你取得史蓋力司卷軸。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11389, 'zhTW', '懸賞:亞克崔茲哨兵', '亞克崔茲的哨兵們陷入瘋狂了。裡面的囚犯們行為全都失控了而其他的守衛會攻擊想幫忙的人。$B$B瑪頓恩聽見了虛空之風中的細語。它說消滅那些哨兵們。$B$B完成這項任務的話，今天的賞金就屬於你的了。', '虛空行者瑪頓恩要你解決5個亞克崔茲哨兵。完成之後回到撒塔斯的陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11390, 'zhTW', '[I\'ve Got a Flying Machine!]', '[Well, what are you waiting for, there\'s work to be done!$B$BHere\'s the keys to our flying machine. Grab three sacks of relics and haul them up to the crane platforms on the north and south sides of Steel Gate.  I\'ll mark them for you.$B$BHurry up! We haven\'t got all day!]', '[The Steel Gate Chief Archaeologist wants you to transport 3 Sacks of Relics from the bottom of the site and take them to the platform on the north or south side of Steel Gate.$B$BUse the grappling hook on the flying machine to do this.$B$BReport back to him after you\'ve done so.]', '', '去找嚎風峽灣的鋼鐵之門首席考古學家。', '遺物袋已送達', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11391, 'zhTW', '[Steel Gate Patrol]', '[Eh? Yer back for another day\'s work?$B$BWell, alright, here\'s the keys. We don\'t need any haulin\' today, so just keep an eye out for anything suspicious, okay?$B$BI\'ve hooked her up with some rockets and a machine gun - just in case.]', '[You\'re Steel Gate\'s ace pilot now, so the Steel Gate Chief Archaeologist wants you to keep patrol around the dig site and fight off anything that attacks.$B$BReport back to him when you\'re done with your patrol.]', '', '去找嚎風峽灣的鋼鐵之門首席考古學家。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11393, 'zhTW', '', '', '[Overseer Irena Stonemantle has asked you to locate her fiance, Explorer Jaren.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11395, 'zhTW', '[It\'s a Scourge Device]', '[The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.$B$BSurely, Explorer Jaren would like to have a look at this.]', '[Deliver the Scourge Device to Explorer Jaren on the Chillmere Coast.]', '', '去找嚎風峽灣的探險者賈倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11397, 'zhTW', '[And You Thought Murlocs Smelled Bad!]', '[I came here to investigate a rumor about a Scourge presence nearby. I expected murlocs along the coast down below, but I never thought I\'d see this!$B$BThe Scourge are down there, and they\'re changing murlocs, and anything else they can get their hands on, into the walking dead!$B$B$C, we will not suffer them to create more of their kind, especially not from murlocs! There is a ramp down to the beach just northwest of the camp. See to it that you deal with the Scourge in a timely fashion!]', '[Apothecary Anastasia has asked you to destroy 15 Scourge of any type along the Chillmere Coast. Return to her at the Apothecary Camp once you have done so.]', '', '去找嚎風峽灣的藥劑師安娜塔西亞。', '寒湖海岸的天災已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11398, 'zhTW', '[It\'s a Scourge Device]', '[The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.$B$BSurely, Apothecary Anastasia would like to have a look at this.]', '[Deliver the Scourge Device to Apothecary Anastasia at the Apothecary Camp.]', '', '去找嚎風峽灣的藥劑師安娜塔西亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11399, 'zhTW', '[Bring Down Those Shields]', '[Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.$B$BBrave enough to hazard another trip down there, $N? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.$B$BHow can you refuse if it means less Scourge, especially ones made from murlocs?]', '[Apothecary Anastasia at the Apothecary Camp has asked you to destroy 3 Scourging Crystals.]', '', '去找嚎風峽灣的藥劑師安娜塔西亞。', '鞭笞水晶已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11403, 'zhTW', '[Free at Last!]', '[Rage was my prison, $N, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.$B$BThank you for leading me back to the Light.  May I never again lose my way.$B$BTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.]', '[Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square.]', '', '去找戴面具的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11405, 'zhTW', '[Call the Headless Horseman]', '[Many dreary candles adorn this pumpkin shrine, which grins, taunting...]', '[Take a Dreary Candle to the Loosely Turned Soil.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11406 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11406, 'zhTW', '', '', '[Speak with Gil Grisert at Fort Wildervar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11407, 'zhTW', '[Bark for Drohn\'s Distillery!]', '[So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.$B$BWe\'ll lend you a racing ram for 4 minutes and also give you these racing reins.$B$BBe careful though, the cheap goblins didn\'t put any apple crates along the way.]', '[Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.]', '', '去找杜隆塔爾的寇特‧高斯坦。', '在拍賣行外叫賣', '在榮譽谷叫賣', '在智慧谷叫賣', '在靈魂谷叫賣', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11409, 'zhTW', '現在就是山羊競速...差不多。', '所以你想瞧瞧競速山羊?那些矮人覺得自己會駕馭山羊，但說實話，他們大部分的時候都醉得一塌糊塗，你想這能有多難?$B$B在我讓你出發之前，你得向我證明你能控制這些善良又合法的動物。$B$B條件如下:我會借給你一些競速韁繩還有一頭競速山羊。你得向我證明你會操縱這些山羊。$B$B讓山羊在快步、慢跑和疾馳的狀態下各維持8秒。', '你有4分鐘的時間可以鞭打山羊，然後在3種不同速度下各維持8秒。', '', '去找杜隆塔爾的山羊管理員雷。', '維持快步8秒', '維持慢跑8秒', '維持疾馳8秒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11412, 'zhTW', '[There and Back Again]', '[Am I glad you\'re here.  We are in big trouble!  The goblin that was supposed to be bringing us more brew had an accident on his way from Razor Hill.  You gotta get us that brew!$B$BI\'ll put you on one of my racing rams and you follow the road to Razor Hill.$B$BOnce you get near him he\'ll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant.  For now, all we want are 3 kegs.  Do a good job and maybe we\'ll have another job for you.]', '[Get a keg from the Goblin stranded on the road to Razor Hill and return it to Ram Master Ray\'s assistant.  Do this 3 times before your ram goes away.]', '', '去找杜隆塔爾的山羊管理員雷。', '酒桶已運送', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11415, 'zhTW', '[Brother Betrayers]', '[Mistwalker is from my dreams! If you are his friend, you are mine.$B$BI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha. There is something unnatural about him.$B$BTo help, you must first kill those who betrayed me.$B$BBjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look for Varg to the southeast, near the West Spear Tower.$B$BThey will not be fooled by your form.]', '[Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.$B$BIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11417, 'zhTW', '[Eyes of the Eagle]', '[Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.$B$BMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.$B$BTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.$B$BGet her eyes.]', '[Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.$B$BIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11419, 'zhTW', '啤酒節騎乘用山羊', '假如你給山羊競速學徒，德瑞茲·迅跌看這個手印的話，他就會讓你購買啤酒節騎乘用山羊。', '將『榮譽釀酒者』手印交給德瑞茲·迅跌，他就在杜洛塔的啤酒營地入口附近。', '', '去找杜隆塔爾的德瑞茲·迅跌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11420, 'zhTW', '[The Path to Payback]', '[Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the same type of gun that the vrykul use to take down our ships. By studying that gun he managed to put together a comprehensive operation manual.$B$BUnfortunately he was abducted and taken north of here to Wyrmskull Village. We eventually did find him, but near death and without the manual. His dying words indicated that the manual was lost in the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!]', '[Guard Captain Zorek at Valgarde in Howling Fjord wants you to recover the Harpoon Operation Manual.]', '', '去找嚎風峽灣的守衛隊長索芮克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11421, 'zhTW', '[It Goes to 11...]', '[We must strike while the vrykul forces are in disarray! Take the harpoon control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff side of the village.$B$BOnce there, commandeer one of the vrykul harpoon guns that are stationed on the building\'s deck. Use the harpoon gun to rain hell upon Wyrmskull Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the vrykul may send at you!$B$BDo this and Daggercap Bay will become a much safer port!]', '[Lieutenant Icehammer in the Howling Fjord wants you to destroy the Dragonflayer Longhouse, Dragonflayer Dockhouse, Dragonflayer Storage Facility and 8 Dragonflayer Defenders.$B$BReturn the Harpoon Control Mechanism to him once the task is complete.]', '', '去找嚎風峽灣的冰錘中尉。', '', '屠龍者長屋已摧毀', '屠龍者碼頭小屋已摧毀', '屠龍者儲藏設施已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11422, 'zhTW', '[Trident of the Son]', '[<From the scratches he makes in the rock, you see several symbols: a trident, a mur\'ghoul, the sun, a wrecked ship, and a rough stick-figure of yourself.>$B$B<Puzzling out what the murloc is conveying takes a while. Obviously he wants you to get a trident from the Chillmere Coast, but the image of the sun is puzzling. That is until you realize he means his son.>$B$B<His son was changed into a mur\'ghoul! He wants you to find him to the south near the wrecked ship and return with his trident.>]', '[Old Icefin wants you to obtain Rotgill\'s Trident. Return it to him on the small island on the Chillmere Coast.]', '', '去找嚎風峽灣的老冰鰭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11423, 'zhTW', '[The Enemy\'s Legacy]', '[As our armies march through Northrend, our enemies will not suffer mere defeat.  Their houses will burn, their corpses will be devoured by our plagues, all trace of their existence will be lost.$B$BThis worries me as a seeker of knowledge.  The eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing.  The vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val\'kyr.  Obtain them before Nifflevar is destroyed.]', '[Go into Nifflevar, north of Ghostblade Post and look for the Saga of the Winter Curse, the Saga of the Val\'kyr and the Saga of the Twins.]', '', '去找嚎風峽灣的抄寫員賽昆恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11424, 'zhTW', '[Shield Hill]', '[My work should be extremely easy in a time of war.  There ought to be usable body parts everywhere.$B$BIt\'s not that simple, though.  With these eggheads making all sorts of killer plagues and sending them to enemy towns, most of the material gets contaminated.$B$BThere is a place, though, where usable samples exist.  Shield Hill, south of here, is an ancient vrykul burial ground where the dead walk but are not afflicted with any plague - ours or the Lich King\'s.  Get me some bones, I\'ll pay ya well.]', '["Hacksaw" Jenny wants you to bring her 5 Ancient Vrykul Bones from the reanimated Vrykul in Shield Hill, south of New Agamand.]', '', '去找嚎風峽灣的『鋼鋸』潔妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11426, 'zhTW', '[Locating the Mechanism]', '[Don\'t worry, $N; this is all going to lead to something big! HUGE! You\'re just going to have to trust me for now and do as I ask of you.$B$BWe need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you\'ll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You\'ll find them on the east side of the village, on the docks by the longhouses.]', '[Guard Captain Zorek at Valgarde in Howling Fjord wants you to bring him a Harpoon Control Mechanism.]', '', '去找嚎風峽灣的守衛隊長索芮克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11427, 'zhTW', '[Meet Lieutenant Icehammer...]', '[Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It\'s where most of their harpoon attacks on our frigates originate.$B$BWell guess what? The time for payback has come, $N. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar.$B$BWhen you\'re ready I\'ll place you on the back of one of our gryphons and zip you right to him! $B$B]', '[Guard Captain Zorek wants you to take the Harpoon Control Mechanism to Lieutenant Icehammer stationed outside of Nifflevar.]', '', '去找嚎風峽灣的冰錘中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11428, 'zhTW', '[Keeper Witherleaf]', '[You have been a great friend and ally to us, $N. There is one more thing I must ask of you.$B$BYou have seen the corruption of the Twisted Glade and the beasts that dwell there. The blacksouled keepers will continue raising these abominations from the waters and soil of our glade unless we act against them.$B$BThe most powerful of the blacksouled keepers is known as Keeper Witherleaf. Slay him, $N, and open the way for the redemption of the glade as you once redeemed my sisters.]', '[Lurielle at the Frozen Glade wants you to kill Keeper Witherleaf.]', '', '去找嚎風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11429, 'zhTW', '[Drop It then Rock It!]', '[I\'m not about to put the fate of this mission into the hands of some untested scrub.$B$BNow, if you want to prove to me that you\'ve got what it takes to carry out this mission, you\'ll need to do what I tell you.$B$BTake this battle standard and head over to Baleheim, directly north of here. Once you\'re at Baleheim, find the center of town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our beloved flag and return to me once you\'ve established Alliance dominance!]', '[Lieutenant Icehammer in the Howling Fjord wants you to place the Alliance Banner in Baleheim and then defend the banner against attackers.$B$BReturn to Lieutenant Icehammer with the Alliance Banner should you survive.]', '已防禦聯盟旗幟', '去找嚎風峽灣的冰錘中尉。', '聯盟旗幟已放置', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11430, 'zhTW', '[Harpoon Master Yavus]', '[That was a fairly strong showing at Baleheim, $N. Before you go off patting yourself on the back there\'s work to be done at Nifflevar.$B$BWe\'ve located the vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the name of Yavus. You\'ll find him in the main harpoon structure on the bluffs of Nifflevar, southeast of here.$B$BTrack him down and execute him for crimes against the Alliance!$B$BDo me proud, $N!$B$B]', '[Lieutenant Icehammer in the Howling Fjord wants you to slay Harpoon Master Yavus at Nifflevar.]', '', '去找嚎風峽灣的冰錘中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11431, 'zhTW', '抓住野生鹿角兔!', '你好啊!我是個瘋矮人!我們矮人相信只要你喝夠多啤酒，隱形的生物就會出現。事實上它們可能現在就在啤酒營地附近閒晃!但除非你喝醉不然你是看不見它們的。$B$B我們矮人想得出任何可以喝得爛醉的理由。$B$B我打賭你也想要一個喝酒的理由...所以幫我帶五隻鹿角兔回來，就用這個我從一個爛醉如泥的矮人身上弄來的網子。$B$B要是你看不見它們，那就表示你還不夠醉。', '『矮鬼』葛羅卓克·獵狙者要你用鹿角兔補網幫他抓5隻昏迷的鹿角兔。他提到你必須在喝醉的情況下才看得到那些鹿角兔。', '', '去找杜隆塔爾的葛羅卓克‧獵狙者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11432, 'zhTW', '[Sleeping Giants]', '[I\'ve overheard what you\'ve had to say with Father Levariol. Allow me to suggest that he\'s not having you go far enough.$B$BYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!$B$BI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.$B$BSurely such a disruption will prove fatal to the vrykul.]', '[Mage-Lieutenant Malister has tasked you with slaying 5 Dormant Vrykul. Return to him at Westguard Keep when you have done so.]', '', '去找嚎風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11433, 'zhTW', '[Sleeping Giants]', '[I\'ve overheard what you\'ve had to say with Greatmother Ankha. With all due respect, she\'s not having you go far enough.$B$BYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!$B$BI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.$B$BSurely such a disruption will prove fatal to the vrykul.]', '[Ahota Whitefrost has tasked you with slaying 5 Dormant Vrykul. Return to him at Camp Winterhoof when you have done so.]', '', '去找嚎風峽灣的阿喉塔‧白霜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11434, 'zhTW', '[Forgotten Treasure]', '[I\'ve made my fortune by specializing in treasure that regular pirates don\'t appreciate: art, antiquities, collector\'s pieces.$B$BBlack Conrad\'s fleet sank south of here years ago.  All the gold and jewelry was picked clean by divers, but two ancient relics remain there.  One is a museum-quality Amani vase, the other is an eagle figurine.$B$BGo and retrieve them for me and I\'ll vouch for you with the other pirates.  I\'ll even throw in something to make your underwater adventure a bit more manageable.]', '[Handsome Terry at Scalawag Point wants you to bring him 1 Amani Vase and 1 Eagle Figurine from the shipwreck to the south.]', '', '去找嚎風峽灣的帥哥泰瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11435, 'zhTW', '[Gathered Pumpkins NYI]', '[Hi, $N!  Thanks for driving away the Horseman!  Now that he\'s gone, the matron said we can roam the village!$B$BI found some pumpkins that the Horseman dropped.  They look scary... will you take them and show  them to the matron?]', '[Take the bunch of jack-o\'-lanterns to the Costumed Orphan Matron.]', '', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11436, 'zhTW', '[Let\'s Go Surfing Now]', '[Navigating the steep bluffs of Howling Fjord can be nerve-racking! I\'ve come up with a solution to ease that burden by utilizing vrykul technology and dwarven ingenuity. With just a few adjustments and some fine tuning I\'ve created Icehammer\'s harpoon controller! Of course it hasn\'t been tested, but that\'s what you\'re here for!$B$BTake the controller to the big gun in Nifflevar and use it to launch yourself into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.]', '[Use the large Vrykul Harpoon Gun in Nifflevar to launch yourself into Valgarde. Report your victory over the Vrykul to Guard Captain Zorek.]', '進行魚叉衝浪', '去找嚎風峽灣的守衛隊長索芮克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11439, 'zhTW', '[Fire Brigade Practice]', '[The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?$B$BSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.$B$BGood bye, $N.  When you\'re done with fire brigade practice, please visit us again!]', '[Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.]', '', '去找丹莫羅的變裝的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11440 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11440, 'zhTW', '[Fire Brigade Practice]', '[With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?$B$BWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.$B$BGood bye, $N.  When you\'re done with fire brigade practice, please visit us again!]', '[Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.]', '', '去找蔚藍海岸島的變裝的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11441, 'zhTW', '啤酒節!', '前往在鐵爐堡外的啤酒節營地，找啤酒節管理人談談並取得一杯免費啤酒。', '和啤酒節管理人交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11443, 'zhTW', '[Daggercap Divin\']', '[Hey... Uh... What\'s up? What are you doing down here?$B$BMe? Oh... Well, you see... I\'m... Um... I\'m trying to clean this place up! Orders from Keller himself! He says to me, "Harry, I want you to put on a divin\' bell and search the shipwrecks of Daggercap for OUR stuff..."$B$BSay, maybe you could lend me a hand while you\'re down here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and bring me back whatever you find. Use this diving helm so you don\'t run out of air and die.]', '[Harold Lagras at the bottom of Daggercap Bay wants you to recover 10 Valgarde Supply Crates.]', '', '去找嚎風峽灣的哈洛德‧拉格銳思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11446, 'zhTW', '啤酒節!', '前往在奧格瑪外的啤酒節營地，找啤酒節管理人談談並取得一杯免費啤酒。', '和啤酒節管理人交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11447, 'zhTW', '歡迎來到啤酒節!', '[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.', '[PH] Speak to the Brewfest Organizer and receive a free beer.', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11448, 'zhTW', '[The Explorers\' League Outpost]', '[It\'s all a bunch of cryptic nonsense! Even with this cipher I can\'t make heads or tails of these tablets. Admittedly, cryptography is not my strong point.$B$BYou\'ll need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I haven\'t heard from Stanwad in two weeks. He took a team of twenty scientists to the dig sites on the southeastern bluffs of the fjord and hasn\'t been heard from since. The best I can do is have McGoyver over there give you a lift with his flying machine.]', '[Deliver McSorf\'s Bundle to Stanwad at the Explorers\' League Outpost in Howling Fjord.]', '', '去找嚎風峽灣的史坦華。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11449, 'zhTW', '[Fire Training]', '[The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.$B$BHead west past the graveyard, following the road. You\'ll find the training area there.]', '[Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.]', '', '去找提裏斯法林地的戴面具的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11450, 'zhTW', '[Fire Training]', '[The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.$B$BHead south through the gate to the crossroads. You\'ll find the training area there.]', '[Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.]', '', '去找永歌森林的戴面具的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11452, 'zhTW', '[The Slumbering King]', '[A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.$B$BHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter\'s Terrace, on the north end of Gjalerbron.$B$BIf you hurry, you may be able to stop her before it is too late.]', '[Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Westguard Keep and report your success to Captain Adams.]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11453, 'zhTW', '[The Slumbering King]', '[A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.$B$BHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter\'s Terrace, on the north end of Gjalerbron.$B$BIf you hurry, you may be able to stop her before it is too late.]', '[Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Camp Winterhoof and report your success to Chieftain Ashtotem.]', '', '去找嚎風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11454, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11455, 'zhTW', '[The Fragrance of Money]', '[Us pirates are known for many things, but hygiene isn\'t one of them.  Most pirate ships be carrying five or six times as many rats as people.$B$BIt\'s no wonder all the bears on this island caught the rabies soon after we moved in.  Long story short, the boss wants \'em all dead.$B$BIt just so happens I know a recipe for a bear musk fragrance popular among Stormwind nobles.  We kill the bears and sell the musk.  I see a fine business opportunity for us here.  What say ye?]', '[Handsome Terry at Scalawag Point in Howling Fjord wants you to obtain 4 Bear Musk from the Rabid Brown Bears in the surrounding area.]', '', '去找嚎風峽灣的帥哥泰瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11456, 'zhTW', '[Feeding the Survivors]', '[We tuskarr rely mostly on our fish catch for sustenance.  In times of great need, however, we will on occasion hunt land animals.$B$BThe nearby village of Iskaal was recently attacked by pirates and the survivors just keep pouring in.$B$BOur catch has been modest this week, but there are many shoveltusk on the island and their meat is plentiful.$B$BAid my people by hunting these great beasts and obtaining their meat.]', '[Elder Atuik at Kamagua in Howling Fjord wants you to obtain 6 pieces of Island Shoveltusk Meat from Island Shoveltusk in the Isle of Spears.]', '', '去找嚎風峽灣的長者阿推克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11457, 'zhTW', '[Arming Kamagua]', '[Issliruk, the spirit of war, is depicted as a silver eagle by my people.  Our stories tell of how Issliruk fought against a hundred worgs to save his young.$B$BIt is time for us, too, to fight against our foes to save our brethren.  We will need to craft new weapons.  The horns of the frostwing chimaera that make their home in the snowy parts of the island are sharp and are easily crafted into spear tips.  Bring me the best of these horns that you can find.]', '[Elder Atuik wants you to obain 3 Chimaera Horns.]', '', '去找嚎風峽灣的長者阿推克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11458, 'zhTW', '[Avenge Iskaal]', '[The totem of Issliruk is ready, $N, and for that I thank you.  We must cast our peaceful ways for the time being and strike at those who\'ve attacked our land and our kin.$B$BThe pirate slavers that raided Iskaal have lost their minds and slaughtered all their captives.  Go to Iskaal, to the east of here and do what must must be done.  Take this horn and call on my brethren should you need assistance.]', '[Elder Atuik wants you to go to Iskaal and slay 8 Northsea Slavers.  Use the Horn of Kamagua should you need assistance.]', '', '去找嚎風峽灣的長者阿推克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11459, 'zhTW', '', '', '[Return to Handsome Terry to decipher what Zeh\'gehn asked of you.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11460 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11460, 'zhTW', '[Trust is Earned]', '[The first and most important factor in falconry is the bond between the falconer and $g他的：她的; bird. Trust must be earned by the master!$B$B<Hidalgo points to the falcons in the cage at his feet.>$B$BIf you are to earn their trust you will first need to fill their bellies.$B$BThe fjord rock falcon, as these birds are known, primarily eat grubs. Throughout the fjord you will find loose rocks that serve as breeding grounds for these grubs. Find a grub and return here to feed the falcons in the cage.]', '[Hidalgo at the Explorers\' League Outpost in the Howling Fjord wants you to find a Fjord Grub and feed it to one of the falcons in the cage by his feet.]', '已餵食峽灣岩隼', '去找嚎風峽灣的『馴鷹者大師』海達戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11461, 'zhTW', 'DEPRECATED', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11462, 'zhTW', '[Handsome Terry]', '[Your people paid me good money to infiltrate the Northsea Freebooters and get your foot in the door.$B$BI talked you up to a fellow in Scalawag Point called Handsome Terry.  I told him you come highly recommended.$B$BPut your disguise on and go see him.  Here comes someone to take you there.$B$BYou\'re going to have to prove yourself a bit before they introduce you to their higher ups.  But that\'s all up to you.  Remember, $N, once you\'re inside you\'re on your own!]', '[Don the Pirate Disguise and speak to Handsome Terry inside Scalawag point.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11464, 'zhTW', '[Gambling Debt]', '[I heard you did a little work for Terry.  I was hoping someone reliable would show up around these parts.$B$BSee, pirates love to gamble.  They, however, do not love to pay their gambling debt.$B$BIf you\'re interested in collecting some coin on my behalf, I\'d be willing to give you a cut.$B$BLet\'s start you out with an easy one.  "Silvermoon" Harry\'s a bit of an eccentric, keeps all sorts of expensive blood elf knickknacks inside his tent - yet when I see him he always pretends to be broke.  Get my gold.]', '[Taruk at Scalawag Point wants you to collect "Silvermoon" Harry\'s Debt.]', '', '去找嚎風峽灣的塔廬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11465, 'zhTW', '[The Ransacked Caravan]', '[I was leading a caravan here from Valgarde that was attacked by Dragonflayers. I was the only survivor of that ambush. Unfortunately, I couldn\'t make it back here with the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet with your rock falcon.$B$B<Hidalgo hands you a cage.>$B$BTake this falcon cage and head west down the road leading out of this camp. Use the falcon to capture the loose turkeys and return here when you\'ve gathered enough.$B$BRemember to feed the falcon!]', '[Hidalgo at the Explorers\' League Outpost in the Howling Fjord wants you to use the Trained Rock Falcon to recover 5 Fjord Turkeys.$B$BReturn to Hidalgo with the cage once you have completed this task.]', '', '去找嚎風峽灣的『馴鷹者大師』海達戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11466, 'zhTW', '[Jack Likes His Drink]', '[Our next customer,  Jack Adams, won\'t be the pushover that Harry was.  He spends all day drinking with his friends, tough pirates all of them.  Let\'s not use force this time, could get ugly.$B$BSee if you can use his drinking habit to your advantage.  There\'s only so much alcohol someone can handle before passing out.$B$BMaybe one of the bar wenches will be of assistance.  Once he\'s out, see if you can slip your hand into his pocket and get what\'s mine.]', '[Taruk at Scalawag Point in Howling Fjord wants you to collect Jack Adams\' Debt.]', '', '去找嚎風峽灣的塔廬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11467 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11467, 'zhTW', '[Dead Man\'s Debt]', '[You might\'ve heard of Black Conrad, he\'s a famous pirate around these parts.$B$BWell, he had a thing for gambling on my fights.  He had a thing for not paying, too.$B$BI\'d love to collect, but trouble is... he\'s dead.$B$BI was about ready to write the whole thing off, when I came across this...$B$B<Taruk unfolds a map of the Isle of Spears with an X on a northeastern plateau.>$B$BHe hid his treasure on tuskarr land.  I want you to get it.  I\'ll be damned if I let that bilge sucker get away without paying.]', '[Taruk at Scalawag Point wants you to search for Black Conrad\'s Treasure on the plateau in the northeastern end of the Isle of Spears, just north of Iskaal.]', '', '去找嚎風峽灣的塔廬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11468 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11468, 'zhTW', '[Falcon Versus Hawk]', '[Do you feel the closeness, $N? Surely you feel a true bond forming between you and your falcon. Would you believe me if I told you that when the time is right you\'ll be able to see through the eyes of your bird? Aye, it is the ultimate level of falconry.$B$BBut first you must hunt more! The bird must hone and quicken its reflexes. Send it against a more formidable opponent! The fjord hawks of the region make the tops of the trees around us their homes. They shall be your next target!  ]', '[Hidalgo at the Explorers\' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 10 Fjord Hawks.$B$BReturn to Hidalgo with the cage when you have completed this task.$B$B]', '', '去找嚎風峽灣的『馴鷹者大師』海達戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11469 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11469, 'zhTW', '[Swabbin\' Soap]', '[Yeah, I got to get the deck swabbed spotless afore Mad Jonah comes \'round. An\' I ain\'t gonna do it on my hands and knees neither!$B$BProblem is, we\'re all outa soap. That\'s more your problem than mine though, mate. Being the newbie \'round here, I gots a special trip for ya to make.$B$BUp on the northwest coast of this island, there\'s a whole mess o\' sea lions. Amongst the nearby ice floes you\'ll find the alpha bull, Big Roy. Bring me back his blubber and I\'ll magic-up the best soap ya ever seen!]', '[Scuttle Frostprow wants you to obtain Big Roy\'s Blubber as the main ingredient for her magic swabbin\' soap. Return to her on the eastern pirate ship at Scalawag Point when you have it.]', '', '去找嚎風峽灣的史加斗‧霜首。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11470, 'zhTW', '[There Exists No Honor Among Birds]', '[You are most definitely ready for the next step in falconry, $N.$B$BTake your trained falcon east of here, to the vrykul hawk roost near the Stonewall Lift. From the roost you will send out your falcon to steal the eggs of the hawks. Their nests will be located in remote areas of the cliff walls surrounding the roost. Locate those nests and use your falcon to scavenge for the eggs!$B$BBeware the fjord hawk matriarchs, $N. Should you come under attack, use your falcon\'s escape and soar abilities to flee!]', '[Hidalgo at the Explorers\' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 8 Fjord Hawk Eggs.$B$BReturn to Hidalgo with the cage when you have completed this task.]', '', '去找嚎風峽灣的『馴鷹者大師』海達戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11471 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11471, 'zhTW', '[The Jig is Up]', '[I know why you\'re here, $N.  You\'ve been sent to kill our leader, Jonah Sterling.$B$BI\'d like to offer my help.  Jonah\'s leadership threatens our operation.$B$BAttacking the Horde and the Alliance fleets simultaneously?  Suicidal.  Trying to sell the tuskarr as slaves when they die days after leaving this climate?  Disastrous.$B$BJonah\'s hideout is located inside a cave west of here.  Bring me his spyglass as proof of the deed  and my first action as lead will be to end all attacks against your allies.]', '[Annie Bonn at Scalawag Point wants you to bring her Jonah Sterling\'s Spyglass.]', '', '去找嚎風峽灣的安妮‧波恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11472 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11472, 'zhTW', '[The Way to His Heart...]', '[The Northsea Pirates slaughtered the isles\' alpha sea lion bull, Big Roy. They made soap from him to clean the decks of their ships!$B$B<Anuniaq sighs.>$B$BNow the sea lions won\'t mate. Help me to repopulate their numbers.$B$BThe reef bulls can be found at the Twin Shores to the southeast. They crave the tasty reef fish that can be found on the east and west sides of the isles.$B$BTake this net and gather enough fish, at least a dozen -- maybe more, to lure a bull across the strait to a reef cow.]', '[Toss Tasty Reef Fish at a Reef Bull to lead it to a Reef Cow. Once you have helped the two to find true love, return to Anuniaq at Kamagua.]', '已將珊瑚公牛引導至珊瑚母牛處', '去找嚎風峽灣的安努尼亞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11473 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11473, 'zhTW', '', '', '[Speak to Zeh\'gehn at Scalawag Post.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11474 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11474, 'zhTW', '', '', '[Speak with Walt.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11475 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11475, 'zhTW', '[Tools to Get the Job Done]', '[I\'ve been studying this deactivated construct for days, $N. I think I can create a reasonable facsimile of the golem that would have room inside to fit one passenger. The idea being that it would fool those iron dwarves and allow us to get inside Baelgun\'s.$B$BNow I\'m not gonna be able to make anything with a hammer and poker. I need my tools! Unfortunately I left those behind at Ivald\'s Ruin when the iron dwarves first attacked. Get me my tools!$B$BIvald\'s Ruin is located far to the northeast.]', '[Walt at the Explorers\' League Outpost in the Howling Fjord wants you to recover his Building Tools.]', '', '去找嚎風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11476, 'zhTW', '[A Carver and a Croaker]', '[Some of the pirates around here... we have our own special way of talking.  Zeh\'gehn has... many different special ways of talking... all mixed together.$B$BFrom what I can tell he wants a frog and a knife.$B$B"Silvermoon" Harry might have a knife on the cheap.  There\'s frogs all over town, just grab one and bring it to him along with the knife.$B$BI\'d hate to be in the poor critter\'s shoes, if you know what I mean.]', '[Get a Shiny Knife from "Silvermoon" Harry and capture a Scalawag Frog.  Bring these to Zeh\'Gehn at Scalawag Point.]', '', '去找嚎風峽灣的賽吉恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11477, 'zhTW', '[Out of My Element?]', '[Keep it down, $r. These iron dwarves are quick on the trigger. Now don\'t let the activities down in the dig fool you. Those steel-skinned abominations aren\'t digging anything up! No sir - on the contrary - they\'re burying the site! For whatever whacked out reason, they don\'t want anyone finding this place.$B$BWhat kind of dwarf buries ancient relics and dig sites? I\'ll tell you what kind: the kind you kill with reckless abandon! Get in there and take \'em out!]', '[Donny at Ivald\'s Ruin in the Howling Fjord wants you to kill 10 Iron Rune Destroyers, 5 Iron Rune Laborers and 2 Iron Rune Sages.]', '', '去找嚎風峽灣的多尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11478, 'zhTW', '[Outpost Over Yonder...]', '[I see that you haven\'t visited my brothers at the Explorers\' League Outpost south of here. Why don\'t you do Donny a favor and deliver this message to Stanwad. He\'ll be interested to hear about the activities of the iron dwarves up here.$B$BLike I said, mount up and start heading south. You\'ll see the outpost right before you get to Baelgun\'s.]', '[Deliver Donny\'s Letter to Stanwad at the Explorers\' League Outpost.]', '', '去找嚎風峽灣的史坦華。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11479, 'zhTW', '["Crowleg" Dan]', '[Croaker\'s spoken, matey. "Crowleg" Dan\'s on da ship yonder.$B$BBest go trace that blaggard, mon.  Show\'im dis set\'s not fe be crossed.  Gaan back fe Terry when ye keelhaul \'is behind.]', '[Confront "Crowleg" Dan, who is in one of the ships at Scalawag Point. Speak to Handsome Terry when you\'ve completed this task.]', '', '去找嚎風峽灣的帥哥泰瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11480, 'zhTW', '', '', '[Speak to Annie Bonn at Scalawag Point.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11482, 'zhTW', '', '', '[Dathris Sunstriker on Scryer\'s Tier in Shattrath City has insisted that you travel to Azeroth at once and report to Larethor at the Sunwell.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11483, 'zhTW', '[We Can Rebuild It]', '[Tools? Check. Materials? Negative.$B$BIf we\'re going to build this thing, you\'re going to have to get me the materials.$B$BFirst things first, $N. For the skeletal structure I\'m going to need a large barrel from Nifflevar, some dark iron ingots from Valgarde, and industrial strength rope from Baleheim.$B$BNifflevar and Baleheim are vrykul towns northwest of here. Valgarde is located in Daggercap Bay, also to the northwest. Speak with McGoyver to get the ingots. He\'ll fly you back here once you\'re all done.]', '[Walt at the Explorers\' League Outpost in the Howling Fjord wants you to bring him a Large Barrel, Industrial Strength Rope and Dark Iron Ingots.]', '', '去找嚎風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11484, 'zhTW', '[We Have the Technology]', '[While the infrastructure for a piece of machinery like this is important, we can\'t underestimate the appearance of the construct. If we\'re to fool the iron dwarves the clone must be exact!$B$BI can make this happen.$B$BBring me a pristine shoveltusk hide from the shoveltusk of this region and steel ribbing from vrykul in Nifflevar or Baleheim to the northwest.]', '[Walt at the Explorers\' League Outpost in the Howling Fjord wants you to bring him a Pristine Shoveltusk Hide and Steel Ribbing.]', '', '去找嚎風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11485, 'zhTW', '[Iron Rune Constructs and You: Rocket Jumping]', '[Alright, $N; the time has come for you to climb inside this thing and learn how to use its basic abilities. When you\'re ready, get on the work bench and I\'ll get you situated inside the construct.$B$BYour first lesson is going to be using the construct\'s transportation system. You\'ll notice that the iron dwarves have set up special rune carvings around the dig site. Their constructs use those rune carvings to power up and fly from point to point. Try it with the rune carving I built here.$B$B]', '[Walt at the Explorers\' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct\'s Rocket Jump ability at Walt\'s Iron Rune Carving.$B$BDismiss your construct by dismissing it from the pet window once you have completed the quest.]', '已掌握火箭跳躍', '去找嚎風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11488, 'zhTW', '', '', '[Exarch Larethor at the Shattered Sun Staging Area wants you to search Magisters\' Terrace and find Tyrith, a blood elf spy.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11489, 'zhTW', '[Iron Rune Constructs and You: Collecting Data]', '[The most important part of your job while controlling the construct is the collection of data. I\'ve placed an iron dwarf relic in the cart over yonder. It\'s the floating, lightning infused crystal.$B$BGet on the work bench and I\'ll put you back in the construct. Once you\'re back in the driver\'s seat, use the construct\'s data collection ability to pick up the test data.]', '[Walt at the Explorers\' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct\'s Collect Data ability while standing near the Iron Dwarf Relic.$B$BDismiss your construct by dismissing it from the pet window once you have completed the quest.]', '', '去找嚎風峽灣的渥特。', '已收集測試資料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11490, 'zhTW', '[The Scryer\'s Scryer]', '[<Tyrith winces in pain as he speaks.>$B$BGo to the terrace... use the orb.$B$B...They\'re...feeding the sunwell....$B$B <Tyrith gasps for breath.>$B$BHurry... They must be stopped... before they can....$B$B<Tyrith dies.>]', '[Tyrith wants you to use the orb on the balcony in Magisters\' Terrace.]', '', '去找魔導師平台的卡雷苟斯。', '占卜法球已啟動', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11491, 'zhTW', '[Iron Rune Constructs and You: The Bluff]', '[You always gotta have a contingency plan in case your main plan backfires! That\'s why I\'ve built in some anti-intelligence systems into the construct.$B$BYour shiny new ride might rouse some suspicion while you\'re at Baelgun\'s excavation site. That\'s what your bluff ability is for! Just use that any time you\'re confronted and you\'ll be safe from harm.$B$BTest it out on Lebronski by walking on his rug. Once he starts huffin\' and puffin\', use the bluff!$B$BGet on the work bench when you\'re ready to begin.]', '[Walt at the Explorers\' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct\'s Bluff ability on Lebronski after you\'ve walked on his rug.$B$BDismiss your construct by dismissing it from the pet window once you have completed the quest.$B$B]', '已唬弄勒布朗斯基', '去找嚎風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11501, 'zhTW', '', '', '[Speak with Captain Adams at Westguard Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11504, 'zhTW', '[The Dead Rise!]', '[The path east of us is a primary hunting trail of the tuskarr. At least that\'s what it used to be...$B$BMore recently our hunters have been returning to Kamagua claiming that the dead have risen and are out for blood! That is what has brought my son and me here. Elder Atuik asks that we find resolution in the bluffs.$B$BWill you assist us in our time of need? I seek heroes willing to brave the perils of Shield Hill, southeast of here. Search the desecrated graves for clues and return your findings to me.]', '[Orfus of Kamagua at the Ancient Lift in the Howling Fjord wants you to find Fengir\'s Clue, Rodin\'s Clue, Isuldof\'s Clue and Windan\'s Clue.]', '', '去找嚎風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11507, 'zhTW', '[Elder Atuik and Kamagua]', '[<Orfus bundles up the clues you brought him.>$B$BMy people are bitterly entrenched in a war with the Northsea Freebooters. If any tuskarr could help us in our quest to right the wrongs of the pirates, it will be Elder Atuik of Kamagua. You must take these clues to him at once.$B$BTo get to Kamagua you must take the Ancient Lift, behind me. Take the lift directly to Kamagua and find Elder Atuik.]', '[Orfus of Kamagua in the Howling Fjord wants you to deliver Orfus\'s Bundle to Elder Atuik at Kamagua.]', '', '去找嚎風峽灣的長者阿推克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11508, 'zhTW', '', '', '[Speak with Grezzix Spindlesnap.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11509, 'zhTW', '', '', '[Speak with "Silvermoon" Harry at Scalawag Point about the missing Vrykul artifacts.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11510, 'zhTW', '["Scoodles"]', '[One of the first things Jonah Sterling did after he went crazy was to take my prized sin\'dorei scrying crystal and feed it to the bane of my existence, "Scoodles" the orca.$B$BNo I didn\'t name the damned thing. I just know that she swims out past the ships directly southeast of Scalawag. Kill that overinflated goldfish and rip out my beautiful sin\'dorei crystal from its stomach.$B$BDo this and we can get down to business.]', '["Silvermoon" Harry at Scalawag Point wants you to recover his Sin\'dorei Scrying Crystal from the orca, "Scoodles."]', '', '去找嚎風峽灣的『銀月』哈利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11511, 'zhTW', '[The Staff of Storm\'s Fury]', '[Those artifacts are cursed and you\'d be crazy to go looking for them, $r. I know for certain that anyone that\'s come into direct contact with any of those items has either gone mad or been killed.$B$BTake that staff, for example. Last I heard the ship that held it was abandoned and left to rot on the coast of the Isle of Spears, north of here.$B$BIf you want that thing, check the ship\'s hold.$B$BWhatever you do, don\'t bring that staff back here! And steer clear of Abdul! He\'ll tear your heart out.]', '[Recover the Staff of Storm\'s Fury and deliver it to Orfus of Kamagua in the Howling Fjord.$B$B]', '', '去找嚎風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11512, 'zhTW', '[The Frozen Heart of Isuldof]', '[Some say Jonah was never quite right in the head, but I know the truth. It was the heart. That damned frozen heart! I saw the change in him the second he pulled it from the grave. I could see the blood freeze in his veins... It was then that the madness truly took over.$B$BHe left us to hole up in his cave on the north side of this island. Last I heard he had thrown the heart in the back of his bear den. Too little, too late...$B$BI\'ll kill you myself if you even think about bringing that heart back here!]', '[Recover the Frozen Heart of Isuldof and deliver it to Orfus of Kamagua in the Howling Fjord.]', '', '去找嚎風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11513, 'zhTW', '[Intercepting the Mana Cells]', '[I have devised a plan to acquire a power source strong enough for the creation of our portal.$B$BThe ethereal forces at Bash\'ir Landing, atop the northwestern Blade\'s Edge Mountains, have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael\'thas.$B$BThey have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods.$B$BJust beware the mana cells\' phase wyrm guardians.]', '[Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.]', '', '去找沙塔斯城的主教納蘇安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11514, 'zhTW', '[Maintaining the Sunwell Portal]', '[We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash\'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade\'s Edge Mountains, far to the north.$B$BRemember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods.$B$BJust be cautious of the phase wyrms that they use to guard the mana cells.]', '[Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.]', '', '去找沙塔斯城的主教納蘇安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11517, 'zhTW', '', '', '[Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11519, 'zhTW', '', '', '[Speak with Captain Ellis aboard the Sister Mercy.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11520, 'zhTW', '[Discovering Your Roots]', '[Greetings, $r.$B$BI\'m afraid I have little to offer here until my reagents are stocked.$B$BOf the supplies I require, there is a special reagent, razorthorn root, that is particularly difficult to harvest.$B$BFortunately, I know a secret....$B$BUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.$B$BTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.]', '[Mar\'nah at Sun\'s Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.]', '', '去找奎爾丹納斯島的瑪納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11524, 'zhTW', '[Erratic Behavior]', '[We lack the numbers to capture the Sanctum at Sun\'s Reach, but I\'ve a plan that will tip the scales in our favor.$B$BThe loose energy from the Sunwell has caused the sentries that patrol this island to malfunction.  The crystal cores that control their behavior are damaged beyond repair.$B$BI\'ve crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries.  We will need all the help we can get.]', '[Vindicator Xayanna at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.]', '', '去找奎爾丹納斯島的復仇者薩楊。', '已部署被策反的哨兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11527, 'zhTW', '[Mutiny on the Mercy]', '[Aye, we got problems, matey. Me gunners have mutinied! M\'n\'the crew up top be tryin\' to kick Sorlof\'s keester while dealin\' with the mutinous gunners down\'blo.$B$BYe\'re gonna have to go down\'blo and deal with those mutinous sea dogs and take their blastin\' powder for the big\'un o\'er on the poop deck.$B$BWith ye mannin\' the big\'un, Sorlof is sure to die and give up the booty!]', '[Captain Ellis aboard the Sister Mercy in the Howling Fjord has asked that you recover 5 Barrels of Blasting Powder from the ship\'s hold.$B$B]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11528, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11529 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11529, 'zhTW', '[Sorlof\'s Booty]', '[Me crew is gonna get the big\'un all primed an\'ready for ya, matey. She\'s restin\' snuggly on the bow, o\'er on the other side of the ship. Go\'n man it and be ready to fire when Sorlof is in our sights!$B$BOnce we take that landlubber down, ye\'ll have to recover the booty for us, seein\' as how we can\'t leave the damned ship! Bring that booty back to me and ye\'ll get your cut - the shield...]', '[Slay Sorlof using the Big Gun and recover Sorlof\'s Booty. Return Sorlof\'s Booty to Captain Ellis aboard the Sister Mercy.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11530, 'zhTW', '[The Shield of the Aesirites]', '[Here\'s yer shield. Me hopes it doesn\'t curse ye like it did me\'n\'me crew. Ye don\'t have to go home, but ye can\'t stay here... I be certain that thar be some that would be interested in getting\' it back.$B$BNow get that thing off me ship!]', '[Return the Shield of the Aesirites to Orfus of Kamagua at the Ancient Lift in the Howling Fjord.]', '', '去找嚎風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11532 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11532, 'zhTW', '[Distraction at the Dead Scar]', '[The Legion will move against us as soon as their forces to the south are freed up.  The Scourge at the Dead Scar are keeping their forces occupied at the moment.  It won\'t last long, however.$B$BI want you to fly a dragonhawk over to the scar and put a dent in the demons\' numbers with these arcane charges.$B$BIf all goes well, they won\'t even notice us taking the armory from Kael\'s lackeys.  Talk to Ayren, the dragonhawk master in the west part of the harbor, when you\'re ready to fly there.]', '[Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you\'re ready to fly over the Dead Scar.  Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.]', '', '去找奎爾丹納斯島的戰鬥法師艾里娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11535, 'zhTW', '[Making Ready]', '[Supplies are inbound, or so I\'m told.$B$BRegardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have.$B$BAs for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons.$B$BThere are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion.$B$BRelieving them of their ore will help our efforts in more ways than one....]', '[Smith Hauthaa in Sun\'s Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.]', '', '去找奎爾丹納斯島的鐵匠荷莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11538, 'zhTW', '[The Battle for the Sun\'s Reach Armory]', '[The Burning Legion holds the Sun\'s Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.$B$BThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.$B$BToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.]', '[Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun\'s Reach Armory.  Use the Shattered Sun Banner to impale the Emissary of Hate\'s corpse.]', '', '去找奎爾丹納斯島的先驅者因努羅。', '憎恨使者已被刺穿', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11539, 'zhTW', '[Taking the Harbor]', '[One of Kael\'s most elite forces, the Dawnblade army, has been stationed at the Sun\'s Reach Harbor and Dawnstar Village.$B$BThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael\'thas will rue the day that he turned his back on his people and sided with the Burning Legion.]', '[Magister Ilastar at Sun\'s Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.]', '', '去找奎爾丹納斯島的博學者伊拉斯塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11542, 'zhTW', '[Intercept the Reinforcements]', '[We\'re making a push to solidify our control of Sun\'s Reach by capturing the harbor next.  Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael\'s forces there.$B$BTake this oil and secure a dragonhawk from Ayren Cloudbreaker.    You should be able to fly within reach of the ships\' sails; once you\'re close enough, set them on fire.$B$BLand in one of the ships and attack the reservists.  With their ship sails on fire they won\'t be able to mount much of a defense.]', '[Vindicator Kaalan at the Sun\'s Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet.  Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.]', '', '去找奎爾丹納斯島的復仇者卡藍。', '辛羅倫之帆已焚燒', '血誓之帆已焚燒', '逐日者之帆已焚燒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11545, 'zhTW', '[A Charitable Donation]', '[We\'ve taken Sun\'s Reach from the enemy and our final victory is at hand.  The cost was high and many brave combatants gave their lives so we could achieve this.$B$BIt is my goal to ensure that those who perished in combat are not forgotten.  I ask that you take a moment to consider making a donation towards a memorial fund.  Any leftover gold will go to the widows and orphans of the fallen.]', '[Anchorite Ayuri at Sun\'s Reach in Sunwell Isle wants you to donate 10 gold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11551 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11551, 'zhTW', '[Agamath, the First Gate]', '', '', '', '去找奎爾丹納斯島的大法師奈蘇爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11552 AND `locale` = 'zhTW';
