INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11788, 'zhTW', '[Lefty Loosey, Righty Tighty]', '[Okay, I think we\'re ready for the penultimate assault... before you can bring down Mechazod, you\'re going to have to dismantle his lieutenants first!$B$BYou\'ll find Twonky, ED-210, Max Blasto, and The Grinder at the West Point, North Point, Mid Point and South Point stations, respectively.$B$BTo get them to show up, just turn the valves at the stations to mess up whatever they\'re trying to do out there. You can\'t miss the places, they all have spinning lights.]', '[Dismantle Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Jinky Wingnut at Fizzcrank Airstrip.]', '', '去找北風苔原的金基‧翼果。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11789, 'zhTW', '[A Soldier in Need]', '[You there!  Please, I need your help.  This soldier will succumb to the cryptfiends\' venom unless we act immediately.$B$BI\'ve managed to slow down the poison, but without a suitable supply of antidote I cannot counteract it.$B$BI was promised a new shipment of anti-venom in the Stormbreaker\'s most recent trip from the south.  Go inside its hold and search for a chest of first aid supplies.$B$BHurry, $c!  We can\'t afford to lose any more men unnecessarily.]', '[Medic Hawthorn, outside of Valiance Keep, wants you to go inside the Stormbreaker\'s hold and retrieve Hawthorn\'s Anti-Venom from a crate of First Aid Supplies.]', '', '去找北風苔原的醫護兵赫索恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11790, 'zhTW', '', '', '[Speak to Captain "Lefty" Lugsail above the Stormbreaker in Valiance Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11791, 'zhTW', '', '', '[Speak to General Arlos inside the Inner Hold at Valiance Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11792, 'zhTW', '[Enemies of the Light]', '[Not so fast there.  I don\'t know about you, $c, but I was hardly convinced by the general\'s words.  They rung unsure... as if they were not his own.$B$BSomething\'s amiss here.  All of our efforts to collaborate have been blocked and delayed.  It is time we took a more independent approach.$B$BIf we\'re to learn more about the cultists inside the keep... perhaps we should investigate those outside.$B$BIntelligence reports a small group of them aiding the Scourge north of here.  See if they carry any clues.]', '[Harbinger Vurenn wants you to fight the Cultist Necrolytes near Farshire to the north of Valiance Keep and retrieve the Cultist Communique from them.]', '', '去找北風苔原的先驅者瓦銳恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11793, 'zhTW', '[Further Investigation]', '[I\'m afraid this is a matter I must delegate to one of my operatives... someone who can work in secret.  Keep the evidence with you and take it to Vindicator Yaala inside the inn.$B$BTell her I sent you and speak of this matter to no one else.  We do not know who might be working for the cult.]', '[Bring the Cultist Communique to Vindicator Yaala inside the inn in Valiance Keep.]', '', '去找北風苔原的復仇者亞拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11794, 'zhTW', '[The Hunt is On]', '[I\'ve made it my business to learn as much as possible about the vile death cult, including their secret language.$B$BVurenn was right.  The cultists mention disguised operatives in various locations in Valiance Keep: the lower docks, the jail inside the inner hold and in the inn\'s kitchen.$B$BTake this oculus.  Use it at those three locations - anyone that has recently used the cult\'s necromancy will be enshrouded by a dark aura.  Take care of the cultists before something nefarious happens.]', '[Vindicator Yaala wants you to use the Oculus of the Exorcist in three different locations in Valiance Keep to uncover and defeat Cult of the Damned members.]', '', '去找北風苔原的復仇者亞拉。', '碼頭的異教徒已擊敗', '監獄的異教徒已擊敗', '廚房的異教徒已擊敗', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11795, 'zhTW', '[Emergency Protocol: Section 8.2, Paragraph C]', '[Injured or not, as squadron commander, I\'m responsible for locating and returning the insignia of all fallen pilots under my command. In all the years I\'ve flown with Fizzcrank, we\'ve never failed to return the signet of a pilot.$B$BMy injuries make it dangerous for me to stray far from the safety of the wreckage, but perhaps you would be willing to help me recover the insignia? In the meantime, I\'ll make preparations to carry out my final duty as squadron commander.]', '[Recover 6 Fizzcrank Pilot Insignia from the bodies of Fizzcrank Recon Pilots and return them to Iggy "Tailspin" Cogtoggle in the Scalding Pools.]', '', '去找北風苔原的『尾旋』艾基‧榫栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11796, 'zhTW', '[Emergency Protocol: Section 8.2, Paragraph D]', '[There\'s only one more thing left to do before I can finally return to the airstrip and make my report. Section 8.2, paragraph D of the emergency protocol requires me to scuttle as much of the wreckage as possible, in order to prevent our technology from falling into enemy hands.$B$BI\'ll give you my torch if you agree to help me complete this last duty. I don\'t want to think about what the Horde\'s goblin allies will do if these machines fall into their hands.]', '[Iggy "Tailspin" Cogtoggle wants you to scuttle the Eastern Wreck, a Southern Wreck, and a Northwestern Wreck.]', '', '去找北風苔原的『尾旋』艾基‧榫栓。', '鑿沉東方殘骸', '鑿沉南方殘骸', '鑿沉西北方殘骸', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11797, 'zhTW', '[The Siege]', '[Well, well, well.  It\'s good to see Arlos bring out the big guns.$B$BDon\'t get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us.  I\'m not sure how much longer we can hold out against these undead Nerubians.$B$BWhat do you say you get out there and kill me some creepers?  Show these boys how it\'s done.]', '[Sergeant Hammerhill wants you to kill 6 Crypt Crawlers in the Sands of Nasam outside of Valiance Keep.]', '', '去找北風苔原的錘丘中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11798, 'zhTW', '[The Gearmaster]', '[Gearmaster Mechazod is insane! He says that he offers us immortality by removing this so-called \'Curse of the Flesh\', but what he\'s really making are robotic slaves!$B$B$N, we\'re pretty certain that he\'s still at the pumping station out in the middle of the pools to the east.$B$BThe last we saw of him, he was in the command hut up top. Go up there and research his stuff.$B$BYou must confront Mechazod if gnomes everywhere,... no, everyone everywhere, are to stay alive!]', '[Research the Gearmaster\'s Manual and return Mechazod\'s Head to Fizzcrank Fullthrottle.]', '', '去找北風苔原的嘶軸‧滿閥。', '已研究齒輪大師的手冊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11799 AND `locale` = 'zhTW';
