INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11865, 'zhTW', '[Unfit for Death]', '[Just south of us the caribou used to roam freely, peacefully. Then Nesingwary showed up and everything changed. Now the caribou are in a perpetual state of frenzy, always in a panic. They are stalked by the hunters and trappers hidden in the field.$B$BNesingwary\'s executioners are unfit for death. They must feel the torture that they put the caribou through!$B$BTake this pile of fake furs and lay it upon their caribou traps to the south. Watch as the hunters are caught in their own deadly traps!]', '[Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the Pile of Fake Furs to trap 8 Nesingwary Trappers.$B$B]', '', '去找北風苔原的札扎。', '奈辛瓦里的陷阱師已被困', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11866, 'zhTW', '[Ears of Our Enemies]', '[Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.$B$BShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.$B$B]', '[Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.]', '', '去找北風苔原的大德魯伊拉索利厄思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11867, 'zhTW', '[Can\'t Get Ear-nough...]', '[Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nessingwary and does dare strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.$B$B]', '[Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.]', '', '去找北風苔原的大德魯伊拉索利厄思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11868, 'zhTW', '[The Culler Cometh]', '[Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons!$B$BFind this murderer, Karen, and end her worthless existence.$B$BPrepare yourself properly, $N. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her! She will be well armed and guarded by lackeys.]', '[Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Karen the Culler.]', '', '去找北風苔原的札扎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11869, 'zhTW', '[Happy as a Clam]', '[To the west of us you will find Lake Kum\'uya. It is, as far as we know, the only freshwater giant clam habitat in the world.$B$BOf course Nesingwary\'s lackeys are now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught to those that would think to endanger an entire species.$B$BGo to Lake Kum\'uya and locate the loot crazed divers. Slay them until the water runs red! Return to me when a proper example has been made!]', '[Hierophant Cenius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill 10 Loot Crazed Divers.]', '', '去找北風苔原的祭師賽紐斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11870, 'zhTW', '', '', '[Seek out Hierophant Liandra at the Abandoned Reach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11871, 'zhTW', '[Not On Our Watch]', '[Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks of animal parts. It would seem that Nesingwary is in cahoots with the Northsea Freebooters. Those dirty pirates are transporting the goods that Nesingwary\'s murderous lackeys gather offshore. No doubt they will end up in the homes and on the backs of wealthy, unscrupulous individuals across Azeroth.$B$BThis won\'t happen. Not on our watch. Bring me all shipments that you find upon this beach. They\'ll never have them!]', '[Hierophant Liandra at the Abandoned Reach in the Borean Tundra wants you to recover 12 Shipments of Animal Parts.]', '', '去找北風苔原的祭師利安卓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11872, 'zhTW', '[The Nefarious Clam Master...]', '[It\'s despicable, really, to anoint one\'s self as the "Clam Master," as if they hold mastery over the creatures of the sea. None may make such claims!$B$BThis "Clam Master" must be found and slain. He was last seen at the wreckage just off the coast of the Abandoned Reach. Find him and kill him.$B$BOnce this is done, return to Hierophant Cenius at the D.E.H.T.A. Encampment, north of here, and let her know that the mission was a success.]', '[Slay Clam Master K and return to Hierophant Cenius at the D.E.H.T.A. Encampment.$B$B]', '', '去找北風苔原的祭師賽紐斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11873, 'zhTW', '', '', '[Make your way back to Fizzcrank Airstrip and speak with Fizzcrank Fullthrottle.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11876, 'zhTW', '[Help Those That Cannot Help Themselves]', '[They\'re majestic beasts, aren\'t they?$B$B<Lathorius points towards the mammoths of the northern tundra.>$B$BWith each passing day their numbers diminish. Demons that call themselves hunters slay the beasts for sport and riches.$B$B<Lathorius\' face contorts with anger.>$B$BIt\'s the whimpers that drive me to madness, $N. You can hear them, carried by the wind. The mammoth calves, trapped in the hunters\' vile traps, call out to us.$B$BTake this hammer and smash those traps. Free the calves!]', '[Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the D.E.H.T.A. Trap Smasher to free 8 Mammoth Calves.]', '', '去找北風苔原的大德魯伊拉索利厄思。', '已釋放長毛象幼獸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11878, 'zhTW', '[Khu\'nok Will Know]', '[Although you have acted valiantly in freeing the trapped calves, many of them will still die. You see, without a caretaker, these calves must fend for themselves in the wild.$B$BBut there is a way! Hope yet remains!$B$BNorth of here in the mammoth fields, bordering the Scalding Pools, you will find Khu\'nok the Behemoth: a mammoth as wise as he is ancient. Take this mammoth orphan and present it to Khu\'nok. He will know what to do.]', '[Take the Orphaned Mammoth Calf to Khu\'nok the Behemoth in the Borean Tundra.]', '孤兒長毛象幼獸已送交庫諾克', '去找北風苔原的『巨獸』庫諾克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11879, 'zhTW', '[Kaw the Mammoth Destroyer]', '[You cannot defeat the being responsible for the slaughter of my kind by yourself. The mammoths of the tundra will help you!$B$BVenture forth to the plains and find a mammoth bull. He will allow you to mount him and control his movements and actions. Ride upon his back and find Kaw, north of here at Kaw\'s Roost. Together, you will be the instrument of Kaw\'s demise.$B$BDestroy Kaw\'s armies and take from Kaw his coveted war halberd. Return to Lathorius at the D.E.H.T.A. Encampment should you succeed.]', '[Kill Kaw the Mammoth Destroyer and recover Kaw\'s War Halberd. Deliver Kaw\'s War Halberd to Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra.]', '', '去找北風苔原的大德魯伊拉索利厄思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11881, 'zhTW', '[Load\'er Up!]', '[Have you seen the flying machines buzzing around? That\'s gnomish innovation at its finest.$B$BI\'ve long waited to get my hands on some of their technology and a perfect opportunity has presented itself. One of their recon wings crashed in the Scalding Pools, in the southwest part of the Geyser Fields.$B$BBlow this whistle near one of the crashed machines and my trusty mule, Jenny will answer. She\'ll follow you and carry the salvage, but you must keep her safe. She\'ll begin to drop the cargo if attacked.]', '[Help Jenny make her way from the crash site to Fezzix Geartwist at Taunka\'le Village without losing all her cargo.]', '', '去找北風苔原的菲奇司‧絞輪。', '在不遺失貨物的情況下護送珍妮安全返回', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11882, 'zhTW', '玩火', '你想學點熱騰騰的新技巧嗎?我不知道你有沒有辦法學會我這種技藝，不過如果你是個夠專心的學生的話，或許能學會一兩招。去跟任何一個聯盟主城的吞火者大師談談。他們應該可以協助你。', '跟任何一個聯盟主城的吞火者大師談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11883, 'zhTW', '火舞?', '你想要學習火舞的藝術?很好，那去跟任何一個部落主城的火舞者大師談談。他們應該可以協助你。', '跟任一個何部落主城的火舞者大師談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11884, 'zhTW', '犀牛王尼德…', '在此地之西，庫姆亞湖之上的高崖，有一隻名叫尼達爾的卑鄙生物在晃蕩著。他自稱為『犀牛王』，在荒野上狩獵那些受傷或太年幼而無法自保並抵抗尼達爾的犀牛。更糟糕的是，尼德還復活了一隻犀牛作為他的坐騎和保鏢。$B$BD.E.H.T.A絕少會要一隻動物死亡，但尼德那被污染的犀牛必須要被處理掉…殺死他們兩個，然後再回來找我。', '『獸穴看守者』基林格爾要你去殺死『犀牛王』尼達爾和他的同伴『午餐盒』，完成之後再回到北風凍原的D.E.H.T.A.駐營向他回報。', '', '去找北風苔原的『獸穴看守者』基林格爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11885, 'zhTW', '敵人之血', '被司凱堤斯魔爪祭司扣留為囚犯的子嗣都列在這本書裡:女獵人吉札拉，水晶巨人葛洛克，以及異端黑暗尖叫者阿卡萊和『風怒者』瓦奇茲。殺了他們才能讓泰洛卡回到這個世界。$B$B你需要時光流逝阿拉卡身上帶的卷軸，才能在司凱堤斯的召喚法陣召喚他們。你挑戰的是強大的生物;帶朋友一起去會比較好。', '在司凱堤斯的召喚法陣中央找到顱骨堆。在顱骨堆用10個時光流逝卷軸召喚並擊敗每個子嗣。回到黑風平臺找海茲克。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11886, 'zhTW', '不尋常的活動', '當慶典舉行時，$c，我們當中的某些人就需要留意那些較嚴重的問題。$B$B在節慶開始時，我們收到了來自佐拉姆海岸的報告，有關於暮光教派的活動明顯增加。這個節日的起源就是緬懷那些瘋子所崇敬的強大力量;這不可能是巧合。前往黑暗深淵入口南邊的營地去，看看那些暮光教徒在搞什麼鬼 - 必要的時候使用武力也沒關係。等你找到的時候，使用這個信號來召喚一個嚮導。', '前往位於梣谷，佐拉姆海岸的黑暗深淵入口南邊新成立的暮光營地。為陶土議會找出答案，然後使用圖騰信號召喚陶土議會嚮導。', '', '去找陶土議會嚮導。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11887, 'zhTW', '[Emergency Supplies]', '[Rifling through the dead gnome\'s possessions, you come across a small packet filled with rations, tools, and a handy roll of gnomish duct tape. The contents of these kits might prove helpful to Fezzix Geartwist when it comes time for him to reassemble the wreckage of the gnomish flying machines.$B$BBringing a few of these kits to Fezzix might just be worth a nice bonus.]', '[Collect 7 Gnomish Emergency Toolkits from the bodies of crashed Fizzcrank Recon Pilots and bring them to Fezzix Geartwist at Taunka\'le Village.]', '', '去找北風苔原的菲奇司‧絞輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11888, 'zhTW', '', '', '[Speak with Sage Earth and Sky at Taunka\'le Village.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11889, 'zhTW', '[Death From Above]', '[We\'re doing a good job of holding the front lines against these bugs.  Some of these cheeky fiends, however, can fly over the aforementioned front lines and are really beating down on our inner defenses.$B$BI\'ve requisitioned reinforced fishing nets from our civilian ships.  If you\'ve got a good enough throwing arm, they\'ll help you knock the enemy out of the sky.  Thin their numbers so that our defenses can hold the keep.]', '[Sergeant Hammerhill wants you to use the Reinforced Net to help you slay 6 Scourged Flamespitters outside of Valiance Keep.]', '', '去找北風苔原的錘丘中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11890 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11890, 'zhTW', '[What Are They Up To?]', '[The gnomes have run into some trouble in the pools to the west. It serves them right as they have been fouling up the land with their so-called inventions.$B$BI want you to go out to their pumping station and observe what has befallen them. Return to me after.]', '[Investigate the area surrounding the Fizzcrank Pumping Station. Then, return to Sage Earth and Sky at Taunka\'le Village.]', '已檢查嘶嘶剎車抽水站周邊環境', '去找北風苔原的賢者地空。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11891, 'zhTW', '無辜的偽裝', '根據這個看來，在佐拉姆海岸的大集會西北邊有另一個教徒營地，而且他們正在與...客人說話?$B$B親耳聽聽會知道的更多，$r。拿著這個寶珠;它可讓你以本地海灘爬行物的模樣出現。去刺探那些教徒在西北邊營地中的「客人」談話，成功後回報給我。', '使用爬行者寶珠去刺探位於梣谷，佐拉姆海岸的黑暗深淵西邊新成立的暮光營地。然後使用圖騰信號召喚陶土議會嚮導。', '聆聽暮光異教徒的計畫', '去找陶土議會嚮導。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11892 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11892, 'zhTW', '[The Assassination of Harold Lane]', '[You have done much for the animals of the Borean Tundra, $N. Nesingwary\'s lackeys have been beaten back and taught a lesson that they will not soon forget.$B$BHarold Lane, the primary agent responsible for the mass slaughters in Nagrand, has been identified as the man in charge of Nesingwary operations in the tundra. He is stationed at Lake Kum\'uya, west of here.$B$B<Lathorius hands you an intricately carved oak horn.>$B$BFind Lane and kill him. Use this horn should you require our aid.$B$B]', '[Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra wants you to kill Harold Lane.]', '', '去找北風苔原的大德魯伊拉索利厄思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11893, 'zhTW', '[The Power of the Elements]', '[I kept trying to tell that silly goblin his machines are unreliable.$B$BBut the power of the elements; that is deep and abiding. When my apprenticeship is over, I will wield their full power. What I know now should be sufficient to help out our friend Fezzix, though.$B$BTake this windsoul totem and plant it near any of the steam ragers to the west of the village. The totem will gather up the energies of slain elementals. Return the fully charged totem to me and I\'ll do the rest.]', '[Dorain Frosthoof at Taunka\'le Village wants you to use the Windsoul Totem to gather the energy of 10 Steam Ragers.]', '', '去找北風苔原的杜然‧霜蹄。', '已收集能量', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11894 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11894, 'zhTW', '[Patching Up]', '[Remember all that gnomish duct tape you brought me?$B$BWell, I\'ve found a use for it. The body of this flying machine is so banged up in places, that I\'m going to need to reinforce it if I ever hope to fly.$B$BDorain over there has been telling me that the taunka use steam cured caribou leather for making watertight containers. Marsh caribou live all around the village and in the Flood Plains to the south. Get the best hides you can find and cure them over the steam vents in the Geyser Fields.]', '[Fezzix Geartwist at Taunka\'le Village wants you to bring him 5 Steam Cured Hides.]', '', '去找北風苔原的菲奇司‧絞輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11895, 'zhTW', '[Master the Storm]', '[From what you describe, the creatures of metal should be easy to deal with. But first, you must master the storm.$B$BBehind me in the lodge is a totem. When you are ready, focus your will upon it and the storm will come. You must defeat the storm and in so doing take its essence into yourself.$B$BIf others are there, it is enough that you all work together to defeat it. Return to me after, $c.]', '[Defeat the Storm Tempest and then return to Sage Earth and Sky at Taunka\'le Village.]', '', '去找北風苔原的賢者地空。', '已掌控風暴', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11896 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11896, 'zhTW', '[Weakness to Lightning]', '[You now have the power of the storm within you. I will give you the means to focus that power and weaken the robots in the pools.$B$BTake this lightning rod. Use it against the robotic creations of the mechagnomes you find within the greater pools area to the west. Do not worry about using it against the mechagnomes themselves; Greatmother Taiga has other plans for them.$B$BOnce the robots are weakened by the power of the storm, dismantle them utterly!]', '[While weakened by the Power of the Storm, destroy any 15 of the robotic units, except the mechagnomes, in the greater pools area surrounding the Fizzcrank Pumping Station.$B$BAfterward, return to Sage Earth and Sky at Taunka\'le Village.]', '', '去找北風苔原的賢者地空。', '機器人已削弱並摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11897 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11897, 'zhTW', '[Plug the Sinkholes]', '[The Scourge are showing no sign of letting up, $N.  It\'s those blasted sinkholes; they connect to tunnels all the way to Icecrown for all we know.  Giant undead worms burrow under the ground to create them.$B$BIf there\'s something years of mining has taught me it\'s that without support beams, tunnels will cave in easily after an explosion.$B$BTake these explosives and place them at the entrance to the sinkholes up on the ridge beyond the beach to the west.  Come back after you\'ve collapsed them.]', '[Sergeant Hammerhill wants you to use the Incendiary Explosives to collapse the sinkholes southwest and northwest of Valiance Keep.]', '', '去找北風苔原的錘丘中士。', '南方坑洞已安置炸藥', '北方坑洞已安置炸藥', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11898, 'zhTW', '[Breaking Through]', '[On the lowest tier of the Temple City, there is a gray altar bathed in light. Step into it to gain entry to the dread necropolis Naxxanar.$B$BBe cautious, $N. Prince Valanar will certainly be defended by his personal retainers, who will give their lives to keep you from ascending to the top level of the necropolis.$B$BYou must find your way through the necropolis to the prince\'s seat. If you fail to defeat him, $N, I fear my people will never know the safety Icemist offers.]', '[Defeat Prince Valanar and his lieutenants, Vanthryn the Merciless and Luthion the Vile, then report to Chieftain Wintergale at Taunka\'le Village.]', '', '去找北風苔原的冬風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11899, 'zhTW', '[Souls of the Decursed]', '[The mechagnomes in the pools to the west are a great mystery to us. They appeared not long after the gnomes disappeared from their pumping station and its environs.$B$BThey are an unnatural danger and must be dealt with.$B$BTake this soulcatcher and use it on the remains of the mechagnomes to capture their souls. When you return, we will set them free so that we might find out what happened.]', '[Use The Greatmother\'s Soulcatcher to capture the souls of 10 Fizzcrank mechagnomes. Then, return to Greatmother Taiga at Taunka\'le Village once you have done so.]', '', '去找北風苔原的主母泰嘉。', '地精之魂已捕獲', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11900, 'zhTW', '檢查讀數', '我本來希望奧核之心的衝擊能夠被侷限在這個區域，但根據最近的報告，顯然波動已經影響了整個艾澤拉斯，地質不穩定的情況幾乎是指數性飆升!$B$B我需要有人在我研究解決之道時，隨時監控奧核之心。$B$B我在凜懼島周圍安置了檢測儀器，偽裝成瑪里苟斯的占卜寶珠。一個就在奧核之心的裂溝附近，另外三個則藏在山谷四周的裂縫中。去察看每一個然後向我回報讀數。', '隘境之盾的大法師貝瑞那德希望你去收集他設在凜懼島的儀器的數據。', '', '去找北風苔原的大法師貝瑞那德。', '讀取奧核之心地質數據', '讀取南部凜懼島數據', '讀取北部凜懼島數據', '讀取西部凜懼島數據', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11901, 'zhTW', '', '', '[Gerald Green in Farshire wants you to go into the mine to the north and find out what happened to the military detachment that was sent there.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11902, 'zhTW', '', '', '[Return to Gerald Green in Farshire.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11903, 'zhTW', '[It\'s Time for Action]', '[Well, $N.  With the last of our military in Farshire dead or worse, we can do but one thing: fight these Scourge ourselves.$B$BWe have deployed militia in what remains of Farshire.  Without your help, they\'ve but little hope of winning.  Go and lend them a hand.  Me and the lads will watch this path.  We can\'t let the Scourge break through!]', '[Gerald Green in Farshire wants you to kill 14 Plagued Scavengers.]', '', '去找北風苔原的吉羅德‧葛林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11904, 'zhTW', '[Fruits of Our Labor]', '[The Scourge just keeps coming... but we can\'t give up!  Listen, $N.  Inside that mine there\'s a cart with the last of the ore the Alliance is going to see on this side of the continent for a long time.$B$BThe problem is the cart release is locked.  When the military went in there, Captain Jacobs commandeered all the important equipment, including the cart release key.$B$BThe plague that affected the soldiers in the mine must also have affected Jacobs.  Get the key from him and salvage the ore.]', '[Go to the mine in Farshire, obtain the Cart Release Key from Captain Jacobs and use it to release the ore cart.  Return to Gerald Green in Farshire when you\'ve completed this task.]', '', '去找北風苔原的吉羅德‧葛林。', '礦車已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11905, 'zhTW', '[Postponing the Inevitable]', '[I\'ve determined the cause of the instability!$B$BAzeroth\'s ley lines are being redirected to the Nexus. It\'s fascinating! If only I could spend the remainder of my days studying this anomaly....$B$BSadly, I must focus on the immediate crisis. The influx of arcane energies is tearing a rift between dimensions.$B$BDeep inside the Nexus, the fabric of our universe is being weakened. I cannot stop it, but I\'ve discovered a way to slow it down.$B$BTake this into the Nexus and activate it near the forming rift.]', '[Archmage Berinand in the Transitus Shield wants you to use the Interdimensional Refabricator near the rift in the Nexus.]', '', '去找北風苔原的大法師貝瑞那德。', '次元裂隙已延緩', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11906, 'zhTW', '[Cleaning Up the Pools]', '[<A single tear rolls down the face of Iron Eyes.>$B$BI have heard that you are heading back into the pools to the west. I have something for you to do while you are out there, $r.$B$BThe gnomes, who care nothing for the land, have polluted it with their machinery. I want you to pick up any spare parts that you come across.$B$BReturn them to me here. I will see to it that they are properly disposed of before we leave this place for good.]', '[Collect 15 Fizzcrank Spare Parts and deliver them to Iron Eyes at Taunka\'le Village.]', '', '去找北風苔原的鐵眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11907, 'zhTW', '[The Sub-Chieftains]', '[It is known that Gearmaster Mechazod has four sub-chieftains that manage the robots in the pools.$B$BWe must put an end to them!$B$BOur longrunners and snow trackers say that if you were to turn the valves at the west point, north point, mid point and south point stations, each of his sub-chieftains would come quickly to prevent you from fouling their operations.$B$BThe stations are centered on the spinning lights in the pools surrounding the pumping station.$B$BHurry, $N!]', '[Defeat Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Sage Earth and Sky at Taunka\'le Village.]', '', '去找北風苔原的賢者地空。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11908, 'zhTW', '[Reference Material]', '[I was in charge of the harvest golems - an important job until the Scourge destroyed most of our farmlands.  I\'ve an idea that would make the golems useful again, however.$B$BI think I can rewire the harvest collectors so they\'ll give us a hand fighting the Scourge.$B$BI\'m not an expert at this just yet, so I\'m going to need my manual.  The problem is, I left it at the workshop... which happens to be that burning building next to the mine.  Think you could go salvage it?]', '[Jeremiah Hawning wants you to retrieve the book "Fields, Factories and Workshops" from the burning building next to the mine in Farshire.]', '', '去找北風苔原的杰瑞米亞‧豪寧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11909 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11909, 'zhTW', '[Defeat the Gearmaster]', '[Clearly this Gearmaster Mechazod creature is not in his right mind. If his offer of a cure and immortality means all of us becoming robotic slaves then he must be stopped!$B$BThe winds that guide me whisper that he\'s atop the pumping station out in the middle of the pools to the west.$B$BMost likely, he\'ll be found in the command hut on top of the structure. Go inside and research his works.$B$B$N, you must confront Mechazod if we are to survive!]', '[Research the Gearmaster\'s Manual and return Mechazod\'s Head to Greatmother Taiga at Taunka\'le Village.]', '', '去找北風苔原的主母泰嘉。', '已研究齒輪大師的手冊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11910, 'zhTW', '古樹的秘密', '很顯然這個區域的不穩定已經對本地的生物造成影響。$B$B我對冰川古樹以及他們最近的適應性變化有特殊的興趣。我懷疑他們轉變成為『咒縛』古樹的情況，可能會有著我們目前困境的線索。$B$B為了我的研究，我需要這兩者的樣本。行動要快……', '隘境之盾的大法師貝瑞那德希望你從凜懼島的古樹身上收集3個冰川裂塊和3個咒縛裂塊。', '', '去找北風苔原的大法師貝瑞那德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11911 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11911, 'zhTW', '[Quickening]', '[Though we may be witnessing the end of our existence, I can\'t help but marvel. I\'ve learned more in my short time here than in decades of studies.$B$BThese Ancients are being exposed to incredible levels of arcane energy. It\'s literally transforming them into something... different.$B$BI\'m confident that there\'s another stage in their metamorphosis. I\'ll need you to actually enter the Nexus, $n, and find me some evidence of their final state.$B$BDo be careful....]', '[Archmage Berinand in the Transitus Shield wants you to enter the Nexus and collect 5 Arcane Splinters from Crystalline Protectors.]', '', '去找北風苔原的大法師貝瑞那德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11912 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11912, 'zhTW', '為莓發狂', '噢!能看到一個新面孔真叫人鬆了一口氣。我都開始以為我們已經被遺忘了。$B$B我們的補給線好幾天前就被切斷了，而事情看起來 - 嗯，很絕望。老實說，我從一開始就認為這是個自殺任務。$B$B我本來就不適合這樣的戰亂生活，更別提這刺骨之寒!我寧可回到達拉然去研究那些古文獻。$B$B總而言之，我們的食物補給幾乎用盡了。拜託，不管你收集到什麼都請交給我。', '隘境之盾的圖書管理員瑟菈要你從凜懼島的霜莓叢收集10個霜莓。', '', '去找北風苔原的圖書管理員瑟菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11913 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11913, 'zhTW', '[Take No Chances]', '[I heard what you told Gerald and I don\'t like it one bit.  If cultists managed to poison the grain in the mines with their foul plague, they could\'ve easily done the same with the grain outside.$B$BWe don\'t have time to sort the good grain from the bad.  We must act quickly and burn it all.$B$BTake this torch and set fire to any sacks of grain you find out here.  It would be a tragedy if we survived this attack only to succumb to the plague afterwards.]', '[Wendy Darren wants you to use Wendy\'s Torch to burn 8 sacks of Farshire Grain.]', '', '去找北風苔原的溫蒂‧達倫。', '遠陽郡的穀物已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11914 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11914, 'zhTW', '[Keep the Secret Safe]', '[Our existence here depends entirely upon staying hidden. Should the shield fail, even for a moment, Malygos\' minions would have us.$B$BOne of my responsibilities is to rejuvenate the warmages\' mana levels so their focus doesn\'t falter. With our supply lines lost, I\'ve been forced to improvise.$B$BI could use your help, $n.$B$BVery near the Nexus, Arcane Serpents feast on the abundant magical energies. Once defeated, they will yield a mana essence that I can make use of.]', '[Librarian Serrah in the Transitus Shield needs you to kill Arcane Serpents near the Nexus and collect 5 Nexus Mana Essences from them.]', '', '去找北風苔原的圖書管理員瑟菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11915 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11915, 'zhTW', '玩火', '你想學點熱騰騰的新技巧嗎?我不知道你有沒有辦法學會我這種技藝，不過如果你是個夠專心的學生的話，或許能學會一兩招。去跟任何一個部落主城的吞火者大師談談。他們應該可以協助你。', '跟任一個何部落主城的吞火者大師談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11916 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11916, 'zhTW', '', '', '[Seek out Chieftain Wintergale at Taunka\'le Village.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11917 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11917, 'zhTW', '反擊', '我們必須以行動來維持平衡!時間對我們相當不利。$B$B帶著大型的冰石回到佐拉姆海岸的營地。他們可以利用這些東西來和元素溝通，就像是希利蘇斯那樣。雖然我不喜歡這樣，那些精靈會瞭解的 - 你必須要召喚艾胡恩手下的一個副官，並且摧毀它。或許這樣先發制人的行動會有效……', '把冰石召喚出來的霜浪副官殺死，冰石就在梣谷的佐拉姆海岸。然後向主城中的陶土議會長老回報。', '', '去找陶土議會長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11918, 'zhTW', '基本訓練', '這是一場戰爭，凡人，而我們就是長矛的尖端。$B$B你對這塊土地或當前局勢的看法與我們眼前的戰爭相比根本是微不足道。我們面對的是守護巨龍瑪里苟斯和他整個藍龍軍團。你只需要知道，如果他獲勝了，那麼這個世界將不復存在。$B$B我們在此地的數量稀少，而我們所對抗的敵人卻數量龐大。我們的死亡是必然的結果，我們最終的成功也只是拖延我們的敵人。$B$B去吧。在我想到要如何運用你之前，替自己找點事情做。', '隘境之盾的瑞洛拉茲要你去殺死10隻凜懼島織法者。', '', '去找北風苔原的瑞洛拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11919, 'zhTW', '[Drake Hunt]', '[The blues have begun to cover their drakes in mysterious runes. I must discover their significance.$B$B<Raelorasz pokes his hand with a spear and coats the tip with his blood.>$B$BTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.$B$BTheir hatchlings feed around the northwest edge of the valley.]', '[Raelorasz wants you to use Raelorasz\'s Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.]', '', '去找北風苔原的瑞洛拉茲。', '已捕獲奧術龍獸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11920 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11920, 'zhTW', '', '', '[Speak to Captain "Lefty" Lugsail above the Stormbreaker in Valiance Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11921, 'zhTW', '投擲更多的火炬', '哈囉，火焰雜耍師!你玩得開心或是燒掉了什麼嗎?那就是我想聽到的事!現在，你覺得自己是個火炬投擲的專家嗎?既然這樣的話我有個測試給你…$B$B你知道規則:將火炬投擲到標記的火盆裡。不過，這一次你擁有的時間變少，你得投中的火盆更多了。$B$B準備好了嗎?', '在火炬投擲遊戲中獲勝，然後與吞火者大師談話。', '擊中20個火盆', '去找吞火者大師。', '火盆已擊中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11922, 'zhTW', '投擲火炬', '你想當一名火焰雜耍師?你已經具備這個資格了嗎?你夠靈敏嗎?反應夠快嗎?你有勇氣嗎?假如你認為你已經具備以上的條件，那麼我們來做個小小的練習吧!$B$B拿著這些火炬，然後跑到營火的旁邊。你會看到火盆上閃爍著標誌。對標示的火盆投擲一根火炬。動作要快!你得在標誌消失以前擲出火炬才算數!$B$B在時間結束之前擊中足夠數量的火盆，然後回到這裡……我們再來進行下一個課程。', '在火炬投擲遊戲中獲勝，然後跟吞火者大師談話。', '擊中8個火盆', '去找吞火者大師。', '火盆已擊中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11923, 'zhTW', '接住火炬', '現在你會投擲火炬了，來看看你是否接得住吧!$B$B拿著這堆未點燃的火炬。到營火前去並將火炬高高丟入空中。在火炬掉落至地面前接住...然後再將它丟高!連續接住4根火炬，就回來找我。$B$B當心點!要是火炬掉到地上可是很危險的!別漏接了!如果你真得漏接了，你就得回到營火前重新再來一次。祝你好運啦!', '連續接住4根火炬，然後跟吞火者大師談話。', '連續接住4支火把', '去找吞火者大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11924, 'zhTW', '接住更多的火炬', '接火炬當然可以讓你保持清醒。你以為你可以持續很久嗎?$B$B走著瞧吧…', '連續接住10根火炬，然後跟吞火者大師談話。', '連續接住10支火把', '去找吞火者大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11925, 'zhTW', '接住更多的火炬', '接火炬當然可以讓你保持清醒。你以為你可以持續很久嗎?$B$B走著瞧吧...', '連續接住10根火炬，然後跟吞火者大師談話。', '連續接住10支火把', '去找吞火者大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11926, 'zhTW', '投擲更多的火炬', '哈囉，火焰雜耍師!你燒得開心嗎?那就是我想聽到的事!現在，你覺得自己是個火炬投擲的專家嗎?既然這樣的話我有個測試給你...$B$B你知道規則:將火炬投擲到標記的火盆裡。不過，這一次你擁有的時間變少，你得投中的火盆更多了。$B$B準備好了嗎?', '在火炬投擲遊戲中獲勝，然後跟吞火者大師談話。', '擊中20個火盆', '去找吞火者大師。', '火盆已擊中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11927 AND `locale` = 'zhTW';
