INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12180, 'zhTW', '被俘的勘察員', '為了探查神器和當地歷史的資訊，瑞加爾派了一隊的勘察員進丹亞戈。瑞加爾的小隊卻從未料想到丹亞戈是如此的人口眾多。當鐵矮人備戰的同時，他們被俘，但是我們不夠人手救出他們，而瑞加爾又忙著幻想著如何打敗鐵矮人而分身乏術。任務落在你肩上了，$N，任何鐵矮人和他們僕役的身上，都有可能帶著關有勘查員牢房的鑰匙。', '救出勘察員加恩、勘察員拓剛和勘察員韋拉那，再向勘察員崗哨的巡山人基立安回報。', '', '去找灰熊丘陵的巡山人基立安。', '救出勘察員加恩', '救出勘察員拓剛', '救出勘察員韋拉那', '', 0);
