DELETE FROM `quest_template_locale` WHERE `ID` = 12222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12222, 'zhTW', '[Secrets of the Flamebinders]', '[Even as we attempt to fight off the Horde, the Dragonflayer tribe musters in their village of Voldrune, near the coast to the south.$B$BThe most powerful warriors in the village are granted flame-imbued talismans that give them the ability to control powerful, savage proto-drakes. If we can gain control of one of these drakes, perhaps we can use it to neutralize the threat posed by Voldrune.$B$BThe Dragonflayer flamebinders create the talismans and imbue them with power. Kill them and take the talismans.]', '[Bring 3 Flame-Imbued Talismans to Woodsman Drake at Amberpine Lodge.]', '', '去找灰熊丘陵的護林者崔克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12223, 'zhTW', '[Thinning the Ranks]', '[There\'s a flurry of activity down in Voldrune village to the south. Thane Torvald Eriksson and his huscarls are preparing for war. With most of our men in the field dealing with the Horde\'s treachery, Amberpine will be vulnerable.$B$BTravel to Voldrune, which is near the southern coast, and show those Dragonflayers we\'re no soft target.$B$BSlay as many of the huscarls as you can find. Make them think twice about taking advantage of our conflict with the Horde.]', '[Kill 12 Dragonflayer Huscarls and return to Woodsman Drake at Amberpine Lodge.]', '', '去找灰熊丘陵的護林者崔克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12224, 'zhTW', '', '', '[Report to Saurfang the Younger at the Kor\'kron Vanguard.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12225, 'zhTW', '', '', '[Speak with Master Woodsman Anderhol in Amberpine Lodge.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12226, 'zhTW', '[Just Passing Through]', '[We must act quickly, $r! We can\'t risk letting those precious seeds become fully digested. They need to come out, NOW.$B$BForage up some blackroot from the riverbank just west of here and I\'ll make you a purgative that should get things moving.$B$BHurry now! And remember, you brought this upon yourself....]', '[Anderhol at Amberpine Lodge wants you to bring him 5 Blackroot Stalks.]', '', '去找灰熊丘陵的護林者大師安德豪爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12227, 'zhTW', '[Doing Your Duty]', '[Alright, $r. Here\'s the juice.$B$BIt works immediately, so don\'t use it until you\'re safely inside the outhouse.$B$BNow go get me those seeds!]', '[Anderhol in Amberpine Lodge wants you to take the Anderhol\'s Slider Cider and use the nearby outhouse to retrieve the Partially Processed Amberseeds.]', '', '去找灰熊丘陵的護林者大師安德豪爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12228, 'zhTW', 'Reacquiring the Magic [PH]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12229, 'zhTW', '[A Possible Link]', '[Not long ago we sent an expedition to the east, where it was attacked by crazed furbolgs.  One of the survivors described slaying one of them and its body expelling a dark slimy substance.$B$BFor thousands of years, the furbolgs in this region have been peaceful.  It is possible that there is a link to the furbolgs\' behavior and the dark energy we were able to detect earlier.$B$BBring me samples of the furbolgs\' blood.  You will find them to the east in the Rage Fang Shrine and the Heart\'s Blood Shrine.]', '[Windseer Grayhorn in Conquest Hold wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart\'s Blood Shrine and Rage Fang Shrine.]', '', '去找灰熊丘陵的風先知灰角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12230, 'zhTW', '[Stealing from the Siegesmiths]', '[I\'m tasked with the destruction of the Scarlet Onslaught\'s ballistae. Unfortunately, the apothecaries and I are at odds on the use of our resources, so I\'ve nothing to destroy them with!$B$BTo the northeast are the Carrion Fields. The Scourge siegesmiths there at their forge and meat wagons are demolition masters.$B$BLuckily for us, they also leave their bombs lying about. $B$BI want you to retrieve them for me, off of the ground or the siegesmiths, I don\'t care which.]', '[Deathguard Molder at Venomspite has asked you to retrieve 6 Siegesmith Bombs.]', '', '去找龍骨荒野的亡靈衛兵莫爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12231, 'zhTW', '[The Bear God\'s Offspring]', '[It is possible that the furbolg of Grizzly Hills have the same taint that plagued Vordrassil.  They\'ve been involved in a deadly tribal war recently after years of peaceful coexistence.$B$BThe shrines that they guard to the east are home to Ursoc\'s offspring.$B$BIf the corruption has affected the furbolg, it is possible that because of their lineage, Kodian and Orsonn have remained unharmed.$B$BIf that\'s the case, find them and listen to what they have to say.]', '[Windseer Grayhorn in Conquest Hold wants you to speak to Orsonn at the Ragefang Shrine and Kodian at the Heart\'s Blood Shrine.]', '', '去找灰熊丘陵的風先知灰角。', '歐爾森的故事', '科迪安的故事', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12232, 'zhTW', '[Bombard the Ballistae]', '[At last, our chance to strike at their siege engines! Don\'t flub it.$B$BI kid.$B$BA little.$B$B$C, bombard New Hearthglen\'s ballistae with these bombs.$B$BWe\'ll show the Royal Apothecary Society how it\'s done old style. No concoctions required!]', '[Deathguard Molder at Venomspite has asked you to use the Siegesmith Bombs to bombard 5 New Hearthglen Ballistae.]', '', '去找龍骨荒野的亡靈衛兵莫爾德。', '已轟炸新爐火谷投石車', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12234 AND `locale` = 'zhTW';
