INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12272, 'zhTW', '[The Bleeding Ore]', '[Hours before the Naxxramas invasion, one of the miners stumbled upon a dark ore that was oozing a viscous fluid. In the chaos that occurred during the evacuation of the mine, we lost the samples taken from the alien node. Now the Scourge prospects the ore for use in their machines of death.$B$BYou must get back to Wintergarde Mine, due northeast of here in the Carrion Fields, and recover the strange ore. It is imperative to our mission\'s success!]', '[Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight wants you to recover 10 samples of Strange Ore from Wintergarde Mine.]', '', '去找龍骨荒野的攻城工程師刻閃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12273 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12273, 'zhTW', '[The Denouncement]', '[It\'s time for us to utterly demoralize the Onslaught forces!$B$BI want you to take the rod and use it on four of their leaders: Commander Jordan upstairs at the barracks, Lead Cannoneer Zierhut down the southeast ramp overlooking the beach, Blacksmith Goodman at the smithy, and Stable Master Mercer at the stables.$B$BPlace them under the rod\'s compulsion, concentrate on making them denounce the Onslaught, and then kill them!]', '[High Executor Wroth at Venomspite has tasked you with using the Rod of Compulsion on Commander Jordan, Lead Cannoneer Zierhut, Blacksmith Goodman, and Stable Master Mercer.$B$BOnce the rod has been used on them, kill each to exact a denouncement of the Scarlet Onslaught as their final words.]', '', '去找龍骨荒野的高階執行官羅思。', '喬丹指揮官的指控與死亡', '首席砲手齊爾胡特的指控與死亡', '鐵匠古德曼的指控與死亡', '馬廄主人默瑟的指控與死亡', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12274, 'zhTW', '[A Fall From Grace]', '[We need more information from the high abbot, and now that we have the visage of one of the raven priests, I think we can get you close to talk with him.$B$BUnfortunately, we need to separate him from his bodyguards or you\'ll never get any information out of him.$B$B<The agent leans on her shovel and thinks a moment.>$B$BI think I\'ve got it! While in disguise, go to the top of the abbey and ring the bell. That should bring the abbot\'s bodyguards running and you can then head down to speak with him.]', '[Agent Skully at New Hearthglen has asked you to ring the bell in the abbey and then go speak with the high abbot and get information out of him.]', '', '去找龍骨荒野的史考莉探員。', '修道院的鐘已敲響', '已與大修道院長交談', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12275 AND `locale` = 'zhTW';
