DELETE FROM `quest_template_locale` WHERE `ID` = 12276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12276, 'zhTW', '[The Search for Slinkin]', '[While I have not heard from Slinkin or know what fate has befallen him, perhaps I can assist in finding him.$B$B<Quarterflash holds up a tiny mechanical toy.>$B$BThis is not a toy, newfound compatriot. It is, in fact, my latest mechanical creation. The machine was created with the sole purpose of finding that which has been lost. These are unfortunate circumstances, but the machine is your best chance at finding Slinkin.$B$BWhen you are ready to begin your search, place the bot on the ground next to me.]', '[Find Slinkin the Demo-gnome in Wintergarde Mine. Use Quarterflash\'s Homing Bot if you need help finding the mine.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12277 AND `locale` = 'zhTW';
