INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12301, 'zhTW', '[The Truth Shall Set Us Free]', '[Zelig gave this crystal ball to me years ago with specific instruction on its use. For five years - whenever I would feel anger, anxiety, or sorrow over the events that transpired here - I was to focus my thoughts upon the orb.$B$BI now understand why Zelig gave this crystal to me.$B$BTake my crystalline orb to the Forgotten Shore. Find the ruins of my old base on the upper reaches of the beach and place the orb in the center of town. Let the forgotten see the world through my heart and soul.]', '[Orik Trueheart at Dawn\'s Reach in Dragonblight wants you to use Orik\'s Crystalline Orb in the ruins located at the Forgotten Shore to redeem the Forgotten.]', '被遺忘者已救贖', '去找龍骨荒野的歐利克·真心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12302 AND `locale` = 'zhTW';
