DELETE FROM `quest_template_locale` WHERE `ID` = 12303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12303, 'zhTW', '[Funding the War Effort]', '[<The quartermaster lowers his voice and whispers to you.>$B$B$C, I need your help; our coffers are empty. The Kor\'kron Vanguard at the Wrath Gate has taken all of our coin for the fight there.$B$BBut, I\'ve heard whispers that there\'s treasure to be had amongst the wrecks on the Forgotten Shore to the southeast.$B$BWe have to do something soon, or we won\'t be able to continue the fight against the Scarlet Onslaught. War isn\'t cheap, you know!]', '[Quartermaster Bartlett at Venomspite has asked you to recover 6 Forgotten Treasure.]', '', '去找龍骨荒野的軍需官巴特勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12304, 'zhTW', '[Beachfront Property]', '[It\'s time for Venomspite to expand!$B$BWe\'ll take care of the Onslaught in due time, but I want you to spearhead our efforts on the Forgotten Shore. The property value has outstanding potential and just look at that view!$B$BUnfortunately, there\'s an infestation of human ghosts, shipwrecked crews and the like who haven\'t quite realized that they\'re dead.$B$BClear the beach and the waters off the shore, and maybe you and I will talk about building a cozy, new mausoleum down there soon.]', '[Surveyor Hansen, just north of the Forgotten Shore, has asked you to slay 20 Forgotten ghosts.]', '', '去找龍骨荒野的勘測員漢森。', '被遺忘的幽魂已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12305, 'zhTW', '', '', '[Return to Zelig the Visionary at Wintergarde Keep in Dragonblight.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12306, 'zhTW', '每月啤酒俱樂部', '$n，團結就是力量。成為「每月啤酒」俱樂部的一員，意味著你和你的同好隨時享用最青的啤酒。$B$B帶著你的「每月啤酒」俱樂部會員表格交給雷瑪，他就在奧格瑪精神谷的暗木小屋裡。', '帶著「每月啤酒」俱樂部會員表格交給雷瑪，他就在奧格瑪精神谷的暗木小屋裡。', '', '去找奧格瑪的雷瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12307, 'zhTW', '[Wolfsbane Root]', '[Have you heard of the wolfsbane plant?  It is a horrible weed... it destroys our farmable crops.$B$BWe spent all of last week cutting them down, but the roots are beginning to sprout again.$B$BIt might not seem like an urgent matter, but a resurgence of the plant could be a real... disaster.  Do you think you could help us by uprooting them where you find them near the village?]', '[Katja in Silverbrook wants you to uproot 8 Wolfsbane Roots.]', '', '去找灰熊丘陵的卡特加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12308, 'zhTW', '[Escape from Silverbrook]', '[You... you\'re not one of them?  Quick!  Let me out!$B$BWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!]', '[Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook.  Report to Lieutenant Dumont when you reach Amberpine Lodge.]', '', '去找灰熊丘陵的都蒙特中尉。', '從銀溪村逃脫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12309 AND `locale` = 'zhTW';
