INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12315, 'zhTW', '[Crush Captain Brightwater!]', '[With every advance, our men are met by fresh Alliance reinforcements. It\'s almost as though their commander anticipates my every move!$B$BThe time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay.$B$BThis will be no easy fight, $N. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!]', '[Slay Captain Brightwater and report to General Khazgar at Venture Bay.]', '', '去找灰熊丘陵的卡茲嘉將軍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12316, 'zhTW', '[Keep Them at Bay!]', '[We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond.$B$BCaptain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we\'ll have no reinforcements.$B$BGo into the field, $N, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!]', '[Defeat 10 Horde units or players in Venture Bay and return to Lieutenant Stuart.]', '', '去找灰熊丘陵的斯圖亞特中尉。', '探險灣的部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12317, 'zhTW', '[Keep Them at Bay]', '[This wretched Westfall Brigade is proving a tougher opponent than we\'d thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out.$B$BConqueror Krenna\'s orders were to capture the port quickly. You must break the stalemate, $N. Find the enemy\'s marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port.$B$BGo quickly. We don\'t want to keep Conqueror Krenna waiting.]', '[Defeat 10 Alliance units or players in Venture Bay and return to Centurion Kaggrum.]', '', '去找灰熊丘陵的百夫長卡格朗姆。', '探險灣的聯盟成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12318, 'zhTW', '', '', '[Speak with the Brewfest Spy in the Grim Guzzler of Blackrock Depths. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12319, 'zhTW', '[Mystery of the Tome]', '[What can it be, $N? That was certainly no ordinary curse that the blasted lich put on you!$B$B<Durkon flips through the grisly pages of the tome.>$B$BI don\'t even know if I\'m looking at it the right way. We must find out what information is held within this tome!$B$B<Durkon hands the book back to you.>$B$BThe High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.]', '[Take the Flesh-bound Tome to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.]', '', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12320, 'zhTW', '[Understanding the Language of Death]', '[Take the book and follow the path leading up to the barracks. Once inside the barracks take the staircase down to the prison. At the prison you will find Inquisitor Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this puzzle and Hallard the man to put it all together.$B$BGo now!]', '[Take the Flesh-bound Tome to Inquisitor Hallard at the Wintergarde Keep prison.]', '', '去找龍骨荒野的審判官哈拉德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12321, 'zhTW', '[A Righteous Sermon]', '[Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an agent of the Scourge. His transformation from man to undying ghoul has taken place slowly, over time. He hears the call of the Lich King now and lives only to serve his master.$B$BBut as with all Scourge, Godfrey knows the language of death and with proper motivation, will tell us what we need to know about the tome.$B$BOnce you hear what you need to hear, return to the High Commander at the front lines. I\'ll clean up here as needed.]', '[Wait for Inquisitor Hallard to finish his Righteous Sermon and return to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight with the information you uncover.]', '已聆聽正義佈道', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12323, 'zhTW', '[Smoke \'Em Out]', '[There are still pockets of cowardly Venture Company men holed up in some of the buildings at the center of Venture Bay. I need every man I can spare out there fighting against the Horde, but we can\'t allow those Venture Company stragglers to camp out in those buildings, either.$B$BMaybe we can "convince" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don\'t get too close, though; they probably bite.]', '[Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Sergeant Downey.]', '', '去找灰熊丘陵的士官當尼。', '探險公司的落隊者已被煙燻逼出', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12324, 'zhTW', '[Smoke \'Em Out]', '[Not only is this port infested with sniveling Alliance cowards, but to make matters worse, there are still Venture Company employees holed up in some of the buildings. They\'re not worth the time it takes to kill and I can\'t spare the warriors anyway.$B$BMaybe we can "convince" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don\'t get too close, though; there\'s no telling what diseases they\'re carrying.]', '[Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Stone Guard Ragetotem.]', '', '去找灰熊丘陵的石衛士狂暴圖騰。', '探險公司的落隊者已被煙燻逼出', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12325, 'zhTW', '', '', '[Speak with Gryphon Commander Urik to secure a ride to Thorson\'s Post. Report to Duke August Foehammer when you arrive at Thorson\'s Post in Dragonblight. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12326, 'zhTW', '[Steamtank Surprise]', '[This is a seek and destroy mission. You\'ll be driving a tank into the Carrion Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th Legion soldiers. All must survive if this mission is to succeed!$B$BYou\'ll need to get in close to a plague wagon to unleash your engineer. Let them do their deed and move on to the next one. When the field is clear of plague wagons, head to the mausoleum in front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.]', '[Use an Alliance Steam Tank to destroy 6 Plague Wagons and deliver the 7th Legion Elites to Wintergarde Mausoleum. Speak with Ambo Cash inside the Wintergarde Mausoleum in Dragonblight should you succeed.]', '', '', '瘟疫馬車已破壞', '第七軍團精英安全送達', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12327, 'zhTW', '[Out of Body Experience]', '[Ah, you seek a vision of the past.  You\'re a wise $r.$B$BEvery time someone drops by for a reading, they seem to always ask about the future.  When you get to be my age, you learn that scrying the past, more often than not, is more useful.$B$BDrink this potion and peer into my crystal ball.  Let us see what knowledge we can obtain.]', '[Drink the Gossamer Potion near Ruuna\'s Crystal Ball and witness the Vision from the Past.]', '來自過去的異象', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12328, 'zhTW', '[Ruuna\'s Request]', '[I will not charge you gold for my services, for I can foresee that your actions are necessary and much hinges on what you learn today.$B$BI will, however, ask you to collect a reagent for me.  Obtain gossamer dust from the fern feeder moths northeast of here.  Do this and I will prepare a potion that will take you to the time and place where the events took place that you need to witness.]', '[Ruuna the Blind wants you to obtain 4 handfuls of Gossamer Dust.]', '', '去找灰熊丘陵的『瞎子』魯巫娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12329, 'zhTW', '', '', '[Speak to Sasha at the White Pine Trading Post.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12330, 'zhTW', '[Anatoly Will Talk]', '[My sister is here somewhere, and I can\'t seem to get this monster to talk.$B$BHe doesn\'t seem to care about his own well-being, but I\'ve an idea.  I knew Anatoly\'s wife, Tatjana, from before the wolfcult arrived -- she was a horse-handler.$B$BTake this tranquillizer dart.  Bring her back alive, we\'re going to need her if we\'re to have any leverage with Anatoly.$B$BI will help you find the person behind all this once we save my sister.]', '[Sasha at the White Pine Trading Post wants you to take the Tranquilizer Dart and use it on Tatjana in Solstice Village.  Bring Tatjana back to the White Pine Trading Post.]', '塔佳娜已送達', '去找灰熊丘陵的莎夏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12331 AND `locale` = 'zhTW';
