INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12372, 'zhTW', '[Defending Wyrmrest Temple]', '[Emboldened by the overabundance of magic now flowing through the Azure Dragonshrine, the blue dragonflight has dared to attack Wyrmrest Temple itself!$B$BI ask that you ride one of our defenders into battle to slay their dragons and drakes, and to attack the eruption of ley line energies at the dragonshrine itself in order to destabilize it.$B$BOutside on the east and west terraces are wyrmrest defenders. Speak with one to ride it into battle.$B$BWithout your help, $N, we will surely lose.]', '[Devrestrasz at Wyrmrest Temple has asked you to slay 3 Azure Dragons, slay 5 Azure Drakes, and to destabilize the Azure Dragonshrine while riding a Wyrmrest Defender into battle.]', '', '去找龍骨荒野的戴伏斯塔茲領主。', '', '', '使蔚藍龍神殿失去穩定', '', 0);
