DELETE FROM `quest_template_locale` WHERE `ID` = 12696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12696, 'zhTW', '', '', '[Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12697 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12697, 'zhTW', '', '', '[Speak with Gothik the Harvester at Death\'s Breach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12698, 'zhTW', '[The Gift That Keeps On Giving]', '[I have come from the frozen heart of Naxxramas to feast on souls and deliver a vicious thrashing upon our sworn enemies - and I\'m all out of souls.$B$BThis device I am about to give to you is a portable plague spreader. Take it east, to the Havenshire Mines, and unleash it near the Scarlet miners working inside. Use it to turn the miners into ghouls and return to me when you have a small army at your side. I have saved a special place for them in the vacuum cleaner of souls!]', '[Gothik the Harvester at Death\'s Breach has given you the Gift of the Harvester to use on Scarlet Miners. Create 5 Scarlet Ghouls with the device and return the ghouls to Gothik.]', '', '去找瘟疫之地：血色禁地的『收割者』高希。', '血色食屍鬼已歸還', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12699, 'zhTW', '難堪的插曲', '在我們出發之前得先解決一個小問題。懂嗎，我好像找不到飛行器的鑰匙。$B$B我幾乎把每個地方都找遍了…也許你可以幫我一把。我還沒找過的地方就只剩下湖裡而已了。$B$B我甚至可以把我自己的氣瓶給你。雖然氣瓶裡面的空氣不多了，但是還能讓你呼吸個幾口。', '在大河之心的湖水中尋找維克的鑰匙串。', '', '去找索拉查盆地的駕駛員維克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12700 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12700, 'zhTW', '', '', '[Speak with Prince Valanar at Death\'s Breach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12701, 'zhTW', '[Massacre At Light\'s Point]', '[In their haste the Crusade will make one fatal error: forgetting to check the mine cars.$B$BYou are to return to Havenshire Mine, east of here, and locate the mine car that my minions have planted near the outhouse. Climb inside the mine car and a Scarlet miner will unwittingly see to it that you are placed safely behind enemy lines.$B$BOnce aboard one of their ships, use the cannons against them! SLAUGHTER THEM ALL!$B$BCall the Scourge gryphon from the cannon when you are ready to return.]', '[Prince Valanar at Death\'s Breach has commanded you to slaughter 100 Scarlet Defenders.]', '', '去找瘟疫之地：血色禁地的瓦拉納爾親王。', '血色守衛已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12702, 'zhTW', '[Chicken Party!]', '[I bet you not guess what happen again.$B$BNope, not Goregek or chickens.$B$BOkay, I lie. Goregek let chickens out again. Dumb Goregek and rumbly belly.$B$BLet me know if you need help from any of the hunters... they around here somewhere.]', '[Capture 12 Chicken Escapees for Elder Harkek at Frenzyheart Hill.]', '', '去找索拉查盆地的長者哈爾凱克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12703, 'zhTW', '[Kartak\'s Rampage]', '[You the great Lich Hunter, eh? Good to have such strong Frenzyheart ally for battle. Maybe you strong enough to call Kartak even.$B$BBig battle at Kartak\'s Hold to southwest.  Go kill spark big-tongues until you get good bit of Oracle Blood. Bring blood to altar in Kartak\'s Hold to call Kartak for delicious feast of big-tongue.$B$BKartak take your body if you worthy... with Kartak\'s powers, you slaughter more big-tongues than even best dreams.$B$BGo kill lots, hunter!]', '[Bring a pure sample of Oracle Blood to the Altar of Kartak to summon Kartak. With the aid of Kartak\'s shared powers, slaughter 50 of the nearby Sparktouched Gorlocs for Shaman Jakjek in Kartak\'s Hold.]', '', '去找索拉查盆地的薩滿賈克杰克。', '電光魚人已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12704, 'zhTW', '[Appeasing the Great Rain Stone]', '[Since mosswalker been attacked I worried maybe we not good to Great Rain Stone... we maybe too greedy. We need more treasures to offer!$B$BYou good at finding shinies last time... maybe you go look more around village for shinies? You maybe need one of good Rainspeakers for help. Just tell us who.]', '[High-Oracle Soo-say in Rainspeaker Canopy wants you to take a companion to dig up and collect 6 Shiny Treasures.$B$BBe sure to speak to High-Oracle Soo-say in Rainspeaker Canopy about securing the aid of one of your previous companions.]', '', '去找索拉查盆地的高階神諭者蘇-楔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12705, 'zhTW', '[Will of the Titans]', '[Puppy-men been attacking Sparktouched... we need fight or they just attack other Oracles too.$B$BYou been good friend to us, so maybe we allow you special honor. Great Ones left protector long time ago for shrines... it here still, but it not know something wrong til shrines messed with.$B$BPuppy-men down there have bad crystals for making trouble... bring a bad crystal to Lightning Shrine so Soo-holu know to help.$B$BDon\'t be scared if Soo-holu take your body... he very powerful, so he keep you safe.]', '[Obtain a Tainted Crystal from the wolvar near Sparktouched Haven and bring it to the Great Lightning Stone to call Soo-holu. With the aid of Soo-holu\'s shared powers, kill 50 of the nearby Frenzyheart wolvar, then return to Lightningcaller Soo-met near the Great Lightning Stone.]', '', '', '狂心攻擊者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12706, 'zhTW', '[Victory At Death\'s Breach!]', '[<Prince Valanar hands you a sealed scroll.>$B$BThis is the full report of our victory at Death\'s Breach. You are to deliver this to Highlord Mograine - inside Acherus. I have made sure to include your heroics in the report. Mograine will undoubtedly reward you greatly for this victory, $N.$B$BGo now!]', '[Deliver Prince Valanar\'s Report to Highlord Darion Mograine in Acherus: The Ebon Hold.]', '', '去找黑鴉堡壘的大領主達瑞安‧莫格萊尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12707 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12707, 'zhTW', '[Wooly Justice]', '[Ahunae hear about your trip to Mam\'toth Crater, mon. The children of Mam\'toth are enraged and cry out for justice!$B$BFollow the avenue northeast up the steps to the next tier of Zul\'Drak. On your right you will find what\'s left of the Altar of Mam\'toth.$B$BWhen you get there, flash this Medallion of Mam\'toth in front of the eyes of one of the enraged mammoths. It\'ll calm down for a little while, letting you hop on its back.$B$BRide it around, trampling all of the Mam\'toth disciples that you can find!]', '[Scalper Ahunae at Zim\'Torga wants you to use the Medallion of Mam\'toth to calm and ride an Enraged Mammoth. You are then to trample 12 Mam\'toth Disciples to death.]', '', '去找祖爾德拉克的割顱者艾胡奈。', '瑪姆托斯的信徒已被踐踏致死', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12708, 'zhTW', '[Enchanted Tiki Warriors]', '[I know that you\'re headed up to the Zol\'Maz Stronghold to the northeast, $c. While you\'re there, I need you to deal with the warlord\'s special guardians.$B$BThe enchanted tiki warriors, as they\'re called, represent a very real threat. If the Drakkari were to mass produce them, we\'d quickly be overrun.$B$BLet\'s you and I demonstrate that they\'re not worth the effort to create, shall we?]', '[Element-Tamer Dagoda at Zim\'Torga has asked you to destroy 12 Enchanted Tiki Warriors.]', '', '去找祖爾德拉克的元素馴伏者達苟答。', '附魔提基戰士已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12709, 'zhTW', '[Hexed Caches]', '[Pardon me, $N. I\'m given to understand that you might be heading northeast up to the Zol\'Maz Stronghold. Such a trip presents a great opportunity for us to conclude our Drakkari goods gathering.$B$BAs I have come to know, the Drakkari warlord is extremely paranoid. He\'s had all of his caches at the stronghold hexed with dire magic. Rumor has it that his tiki warriors carry the cure, but who can say?$B$BIf you could find the time to acquire some of those goods, I would be most appreciative.]', '[Chronicler To\'kini at Zim\'Torga has asked you to acquire 12 Zol\'Maz Stronghold Caches.]', '', '去找祖爾德拉克的撰史者托基尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12710, 'zhTW', '[Disclosure]', '[Ya doin\' well, $n.$B$BYou be provin\' dat I got an eye for talent! Now ya see why da Lich King gave me his blessing....$B$BDa time has come for me to reveal my master plan to ya, mon.$B$BNow you be seein\' how we gunna sweep through da swarms of Drakkari trolls to take our rightful place in da great palace of Gundrak.$B$BTake dis scepter, mon. It be a token of my trust in ya. With it, you be able ta access my upper chamber and witness for yourself our secret weapons.]', '[Drakuru in Voltarus wants you to take the teleporter to his upper chamber.]', '', '去找祖爾德拉克的德拉庫魯霸主。', '已探索達庫魯的上層密室', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12711, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12712, 'zhTW', '[The Key of Warlord Zol\'Maz]', '[$N, we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter.$B$BThe Drakkari warlord, Zol\'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast.$B$BThe warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home\'s gate.]', '[Har\'koa at Zim\'Torga has asked you to acquire the Key of Warlord Zol\'Maz.]', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12713, 'zhTW', '[Betrayal]', '[The time has come to end this charade, $n.$B$BAs valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed.$B$BWe\'ve modified your scepter for the job. When the time is right, you will be able to use it on Drakuru\'s Blightbloods and turn them against him. It\'s your only hope of defeating him.$B$BFight well.]', '[Stefan in Ebon Watch wants you to defeat Drakuru.$B$BIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '已擊敗上將達庫魯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12714, 'zhTW', '', '', '[Return to Death\'s Breach and report to Prince Valanar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12715, 'zhTW', '', '', '[Report to Prince Keleseth at the Crypt of Remembrance.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12716, 'zhTW', '[The Plaguebringer\'s Request]', '[Look at this pumpkin patch! Notice anything missing? Of course you don\'t, because you\'re a moron! Your brain was probably the first thing to die.$B$B<Noth sighs.>$B$BI have been commanded to put together a plague cauldron. You will help me.$B$BDirectly inside the gate of New Avalon is the inn. Enter the inn and steal an empty cauldron. Then go to the forge, also near the gate, and steal some iron chains. Bring those back to me along with 10 Crusader skulls. Do I need to tell you where to get those too?]', '[Noth the Plaguebringer has requested that you bring him 1 Empty Cauldron, 1 Iron Chain and 10 Crusader Skulls.]', '', '去找瘟疫之地：血色禁地的瘟疫者諾斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12717, 'zhTW', '[Noth\'s Special Brew]', '[The cauldron is ready to begin spewing its foul corruption across the land!$B$BNow, death knight, a brief lesson in plague cauldrons. The gas that the cauldron emits is deadly to the living, but empowers Scourge. As with all Scourge creations, it feeds off of death and grows stronger the longer it feeds.$B$BTake these Crusader skulls and drop them in the cauldron. You will be quite happy with the results.]', '[Place the Pile of Crusader Skulls inside the Plague Cauldron.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12718, 'zhTW', '[More Skulls For Brew]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12719, 'zhTW', '[Nowhere To Run And Nowhere To Hide]', '[Nothing less than total annihilation will suffice, $N. To that end, a few hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must infiltrate the inner sanctum and dispose of their officials. They must be shown that no one can escape the Scourge\'s grasp!$B$BMake your way to the New Avalon Town Hall, southwest of here, and assassinate the mayor. Search the building for the New Avalon registry and bring it to me.]', '[Prince Keleseth at the Crypt of Remembrance has ordered you to kill Mayor Quimby and recover the New Avalon Registry. ]', '', '去找瘟疫之地：血色禁地的凱雷希斯親王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12720 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12720, 'zhTW', '[How To Win Friends And Influence Enemies]', '[In my travels across this world I have made several interesting discoveries. For instance, did you know that with the proper amount of encouragement one can extract all the truths that a man dares hide? As luck would have it, I happen to have some encouragement on hand.$B$B<Keleseth pulls something out of an ornately jeweled box.>$B$BThese are my "persuaders." Equip them and take to the field, death knight. Apply the pointy ends to the soldiers of New Avalon. Discover the truth about this "Crimson Dawn."]', '[Prince Keleseth at the Crypt of Remembrance has ordered you to discover the truth about the "Crimson Dawn."$B$BRemove Keleseth\'s Persuaders from the Ornately Jeweled Box and use them to "persuade" the Scarlet Crusade into talking.]', '「緋紅曙光」已揭露', '去找瘟疫之地：血色禁地的凱雷希斯親王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12721, 'zhTW', '[Rampage]', '[$N, there is no time left. You must take the key and use it to unlock Akali.$B$BHe is being held in the courtyard in front of Gundrak, the capital of Zul\'Drak. Akali\'s chains are secured by four anchor points. You must unlock each of them to set the rhino god free.$B$BGundrak is teeming with ice trolls. However, I believe that if you\'re careful, you should be able to slip in without too much danger.$B$BOnce you\'re done, please inform the witch doctor.]', '[Har\'koa at Zim\'Torga has asked you to free Akali and then to inform Witch Doctor Khufu at Zim\'Torga.]', '阿卡利已擺脫枷鎖', '去找祖爾德拉克的巫醫庫弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12722, 'zhTW', '[Lambs To The Slaughter]', '[Most humans would have fled the moment a Scourge necropolis took up residence in their air space. Not the Scarlet Crusade!$B$BI must confess - I rather enjoy our exchanges with the Crusade. Through the years, Scourge battles against them have resulted in several of the most tragic events in human history. Yet here we stand - AGAIN - locked in battle!$B$BWe shan\'t deny them the pleasures of eternal servitude to the Lich King! Enter New Avalon and fulfill their death wish. Leave no survivors.]', '[Baron Rivendare at the Crypt of Remembrance has commanded you to slay 10 Scarlet Crusade Soldiers and 15 Citizens of New Avalon.]', '', '去找瘟疫之地：血色禁地的瑞文戴爾男爵。', '血色十字軍士兵已擊殺', '新阿瓦隆的居民已擊殺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12723, 'zhTW', '', '', '[Report to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12724, 'zhTW', '[The Path Of The Righteous Crusader]', '[We haven\'t got a damned clue about when or where this courier is supposed to show up. None of these humans had an answer either.$B$B<Orbaz points to the Scarlet corpses strewn across the floor.>$B$BI did manage to beat something useful out of the last one. Inside Scarlet Hold they keep a schedule of all patrol routes. I want you to break into the hold and steal the schedule.$B$BThe hold is the largest building in New Avalon - northeast of here. ]', '[Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to steal the New Avalon Patrol Schedule from the Scarlet Hold.]', '', '去找瘟疫之地：血色禁地的歐貝茲‧血禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12725, 'zhTW', '', '', '[Search for Koltira Deathweaver in the Scarlet Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12726, 'zhTW', '[Song of Wind and Water]', '[Listen to storm, yes?  The Stormwright\'s Shelf echoes with ancient song.... the Song of Wind and Water.$B$BThe great tempest devours the sons of typhoons and storms.  Take this drum and play his song... play Haiphoon\'s song.$B$BHelp him feed on wind and water so tempest can continue. ]', '[Soo-nee wants you to use the Tempest Drums at the Stormwright\'s Shelf and help Haiphoon devour 3 Storm Revenants and 3 Aqueous Spirits.]', '', '去找索拉查盆地的神諭者蘇-睨。', '已吞噬水靈', '風暴亡魂已吞噬', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12727, 'zhTW', '[Bloody Breakout]', '[The alarms have been sounded. The High Inquisitor and his acolytes will be here soon. I\'m too badly injured to be of much use, but I\'ll do what little I can to help.$B$BSlay the High Inquisitor and his cronies. Tear off his head and return with it to Thassarian. Vengeance will soothe his savage soul.$B$BOne more thing, $N. If you do manage to survive and make it back to Thassarian, tell him that they\'re executing prisoners at the chapel. Perhaps he\'ll send you there to play the hero once more.]', '[Slay High Inquisitor Valroth and take Valroth\'s Head to Thassarian at the Scarlet Tavern in New Avalon.]', '', '去找瘟疫之地：血色禁地的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12728, 'zhTW', '[Monitoring the Rift: Winterfin Cavern]', '[I need to compile my notes and prepare a presentation for my colleagues in Dalaran.$B$BWhile I do, I must ask that you visit the Winterfin Cavern to the north. You must use the Arcanometer while standing in the mouth of the cavern.$B$BReturn to me at once when you have the data. My documentation will be incomplete without it.]', '[Librarian Garren at Amber Ledge wants you to use the Arcanometer at Winterfin Caverns.]', '', '去找北風苔原的圖書管理員加倫。', '已取得冬鰭洞窟讀數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12729, 'zhTW', '諸神已然開口', '諸神已然開口，而我們必須回應祂們的睿智。$B$B把你的朋友召集起來吧，$N。帶著他們到北邊的辛茹克去殺死那裡的守護者，直到得到一顆無瑕疵的心臟。帶著他們到東南邊的奎茲倫祭壇去瓦解祭壇守望者，直到取得他們的陣風精華。$B$B把兩者都送去給哈寇亞，她將會把它們結合成一樣物品，能夠強迫死去阿卡利的預言者現身。', '將無瑕疵的守護者之心和守望者的陣風精華送去給辛托加的哈寇亞。', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12730, 'zhTW', '佐爾希伯的召集', '你和你的夥伴必須把這個召集裝置，或者說召喚裝置，拿去剛德拉克南方的佐爾希伯。$B$B你會在裡面找到一個法陣。使用召集裝置強迫阿卡利得預言者現身。$B$B我心與你同在，$N。我們共同經歷了這麼多事，你不但盡力拯救了我的性命，還幫助了其他被德拉克瑞食人妖毀滅的神。$B$B但這次，我擔心我們也許要在彼世才能再會了。', '辛托加的哈寇亞要你殺死阿卡利預言者。', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12731, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12732, 'zhTW', '[The Heartblood\'s Strength]', '[One day, Rejek will be mighty warrior. Blood and skyfire will make Rejek strong. You see soon.$B$BRejek give you vial, you take to very top of Suntouched Pillar, far to west. Put waters there in vial.$B$BThen go to north edge of basin, to ledge north of Bonefields. You find and kill goretalon matriarch. Take heartblood.$B$BYou combine heartblood and water, bring to Rejek. Rejek drink, make strong.]', '[Bring a vial of Suntouched Heartblood to Rejek at Frenzyheart Hill.]', '', '去找索拉查盆地的瑞傑克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12733, 'zhTW', '[Death\'s Challenge]', '[Born of the Lich King\'s victory over Illidan Stormrage in the heart of the frozen wastes, Death\'s Challenge is a rite of passage that all death knights must undergo.$B$BSeek out other death knights of Acherus and challenge them to a duel. They must accept and fight until a victor emerges!$B$BGo now, $N! Victory for the Scourge! Glory to the Lich King!$B$B]', '[Olrun the Battlecaller has ordered you to win 5 duels against other death knights.$B$BYou may choose to battle death knight initiates or players.]', '', '去找瘟疫之地：血色禁地的『戰鬥召喚者』歐魯。', '已在決鬥中擊敗死亡騎士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12734, 'zhTW', '[Rejek: First Blood]', '[Rejek just became youngest warrior in all of Frenzyheart tribe. Father gave Rejek a mighty sword to defeat Frenzyheart enemies, but old tradition say sword need to be blooded first. Older warrior usually do that. You do this honor for Rejek?$B$BTake blade, put in corpses of all Frenzyheart foes: wasps and hardknuckles to southwest, and the big-tongues. Maybe blood blade on Mistwhispers, far to northwest near Bittertide Lake.]', '[Blood Rejek\'s Blade on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger, and 3 members of the Mistwhisper Tribe. You may blood the sword on either Mistwhisper Oracles or Mistwhisper Warriors. Return to Rejek at Frenzyheart Hill when your task is complete.]', '', '去找索拉查盆地的瑞傑克。', '已在藍寶石蜂巢黃蜂身上見血', '已在鐵拳衝鋒者身上見血', '已在迷霧低語成員身上見血', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12735, 'zhTW', '[A Cleansing Song]', '[Earth in Sholazar is pure.  The pillars have protected the land for centuries.$B$BWater, not as pure, it comes from outside Sholazar.... from oceans, from lakes, from rivers.  Water sometimes bring bad spirits - need to be cleansed.$B$BYou take this chime and play at Bittertide Lake, Wintergrasp River and River\'s Heart.  It make bad spirit angry... and then you must kill it.]', '[Soo-nee, at the Rainspeaker Canopy, wants you to play the Cleansing Chime at Bittertide Lake, Wintergrasp River and River\'s Heart and slay the evil spirits that plague the waters there.]', '', '去找索拉查盆地的神諭者蘇-睨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12736 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12736, 'zhTW', '[Song of Reflection]', '[Of course you not as smart as gorloc!  You just simple $r.$B$BYou not without hope, though!  You show you can learn.  Maybe crystals make you smart like crystals make us smart!$B$BI teach you to play song to clear your mind.  You play song by crystals then crystals make your mind better... not as good as gorloc\'s but better than you have now.  Lifeblood Pillar is broken, but other pillars still good!]', '[Soo-nee at Rainspeaker Canopy wants you to use the Didgeridoo of Contemplation at the top of the Glimmering Pillar, the Suntouched Pillar, the Mosslight Pillar and the Skyreach Pillar.]', '', '去找索拉查盆地的神諭者蘇-睨。', '在微光之柱沉思', '在苔光之柱沉思', '在觸天之柱沉思', '在陽光之柱沉思', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12737 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12737, 'zhTW', '[Song of Fecundity]', '[The storm is a destructive force.  Storm burns trees.  Storm floods houses.$B$BBut storm can also be life force if you know right song.  In Stormwright Shelf, above Maker\'s Perch, you can find small dirt mounds.  They very fertile -- they carry inside a strong seed.  All they wait for is the right song.$B$BYou take this horn and play song for them.]', '[Soo-nee at Rainspeaker Canopy wants you to go to the Stormwright\'s Shelf, northwest of the Maker\'s Perch, and play the Horn of Fecundity near 8 piles Soaked Fertile Dirt.]', '', '去找索拉查盆地的神諭者蘇-睨。', '已演奏豐饒之歌', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12738, 'zhTW', '', '', '[Report to Knight Commander Plaguefist at the Chapel of the Crimson Flame.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12739, 'zhTW', '[A Special Surprise]', '[We got here, tore the place apart, and headed toward the prison house. We weren\'t expecting what we found in there, $N. Seems the Crusade\'s been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there\'s a real feisty tauren in there that I think you\'ll take great pleasure in executing.]', '[Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Malar Bravehorn, an Argent Dawn prisoner inside the nearby prison house.]', '', '去找瘟疫之地：血色禁地的騎士指揮官瘟疫之拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12740, 'zhTW', '[Parachutes for the Argent Crusade]', '[Those sky terrors are destroying my men and women! Dying from falling is a horrible way to go.$B$B$C, you have to get these parachutes out to them! At least then they\'ll have a fighting chance to survive.]', '[Commander Falstaav at The Argent Stand has asked you to equip 10 Argent Crusaders or Argent Shieldmen out in the courtyard with parachutes.]', '', '去找祖爾德拉克的指揮官法爾斯戴夫。', '已為銀色部隊裝備降落傘', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12741, 'zhTW', '[Strength of the Tempest]', '[Silly big-tongues think singing to the clouds give them power. Rejek show big-tongues how to get power by taking it!$B$BFar to northwest, there is large, flat area the big-tongues call \'Stormwright\'s Shelf.\' Rejek is sure you can only get there by flying like bird.$B$BOn this shelf, Rejek has heard of mighty forces of wind and water. Kill them for their badness, then take it to the big-tongue \'Shrine of the Tempest\' at shelf\'s western side. Rejek will await your return with ultimate power.]', '[Gather 3 Essences of the Monsoon and 3 Essences of the Storm and take them to the Shrine of the Tempest. Return to Rejek at Frenzyheart Hill with the True Power of the Tempest.]', '', '去找索拉查盆地的瑞傑克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12742, 'zhTW', '[A Special Surprise]', '[We got here, tore the place apart, and headed toward the prison house. We weren\'t expecting what we found in there, $N. Seems the Crusade\'s been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there\'s a real feisty human in there that I think you\'ll take great pleasure in executing.]', '[Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Ellen Stanbridge, an Argent Dawn prisoner inside the nearby prison house.]', '', '去找瘟疫之地：血色禁地的騎士指揮官瘟疫之拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12743, 'zhTW', '[A Special Surprise]', '[We got here, tore the place apart, and headed toward the prison house. We weren\'t expecting what we found in there, $N. Seems the Crusade\'s been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there\'s a real feisty night elf in there that I think you\'ll take great pleasure in executing.]', '[Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Yazmina Oakenthorn, an Argent Dawn prisoner inside the nearby prison house.]', '', '去找瘟疫之地：血色禁地的騎士指揮官瘟疫之拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12745, 'zhTW', '[A Special Surprise]', '[We got here, tore the place apart, and headed toward the prison house. We weren\'t expecting what we found in there, $N. Seems the Crusade\'s been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there\'s a real feisty gnome in there that I think you\'ll take great pleasure in executing.]', '[Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Goby Blastenheimer, an Argent Dawn prisoner inside the nearby prison house.]', '', '去找瘟疫之地：血色禁地的騎士指揮官瘟疫之拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12746, 'zhTW', '[A Special Surprise]', '[We got here, tore the place apart, and headed toward the prison house. We weren\'t expecting what we found in there, $N. Seems the Crusade\'s been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there\'s a real feisty draenei in there that I think you\'ll take great pleasure in executing.]', '[Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Valok the Righteous, an Argent Dawn prisoner inside the nearby prison house.]', '', '去找瘟疫之地：血色禁地的騎士指揮官瘟疫之拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12747 AND `locale` = 'zhTW';
