INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12773, 'zhTW', '[Darnassus]', '[Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King\'s machinations.$B$BTake this, $n.  Guard it close, and secure its passage to Darnassus.  Deliver it to Tyrande Whisperwind -- her priests will find it a vital source of power in their fight against the unholy forces from the North.]', '[Bishop Lazaril wants you to bring the Light-infused Artifact to Tyrande Whisperwind in Darnassus.]', '', '去達納蘇斯找神殿花園的泰蘭妲·語風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12774, 'zhTW', '[Stormwind]', '[Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King\'s machinations.$B$BTake this, $n.  Guard it close, and secure its passage to Stormwind.  The King of Stormwind has recently returned; I\'m sure he will welcome this tool.]', '[Bishop Lazaril wants you to bring the Light-infused Artifact to King Varian Wrynn in Stormwind.]', '', '去找艾爾文森林的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12775 AND `locale` = 'zhTW';
