INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12779, 'zhTW', '[An End To All Things...]', '[You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, $N.$B$B<The Lich King pauses.>$B$BThere must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness.$B$BUse this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.]', '[The Lich King has commanded you to eradicate the Scarlet Crusade.$B$BUse the Horn of the Frostbrood to call forth a Frostbrood Vanquisher and with it slay 150 Scarlet Soldiers and destroy 10 Scarlet Ballistas. Avoid incoming projectiles by moving out of their line of fire!]', '', '去找瘟疫之地：血色禁地的巫妖王。', '血色士兵已擊殺', '血色投石車已摧毀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12780 AND `locale` = 'zhTW';
