INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12785, 'zhTW', '[Orgrimmar]', '[We have a breakthrough!  Our zombie specimens have given us new insight into the nature of the Scourge\'s plague.  They have born rotten, delicious fruit...$B$BTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Karlov.  He attends Warchief Thrall in Orgrimmar.]', '[Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar.]', '', '去找奧格瑪的藥劑師卡洛孚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12786, 'zhTW', '[Thunder Bluff]', '[We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge\'s plague.  They have born rotten, delicious fruit...$B$BTake this box to Thunder Bluff.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Chaney.  He attends Magatha Grimtotem in Thunder Bluff.]', '[Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Chaney in Thunder Bluff.]', '', '去莫高雷找雷霆崖的藥劑師夏睨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12787, 'zhTW', '[The Undercity]', '[The zombie plague was a blessing in disguise.  In our search for a cure, we have learned so much of the Scourge and their contagion.  Our research has given us weapons against them.  Weapons, and tools...$B$BTake this -- it is a zombie\'s head and has been partially cured of its plague by injecting it with a compound derived from our recent discoveries.  Deliver the head to Master Apothecary Faranell; I have a list of experiments I would like him to perform on it.]', '[Grand Apothecary Putress wants you to give the Dual-plagued Brain to Master Apothecary Faranell in the Undercity.]', '', '去找奧特蘭克山脈的藥劑大師法拉尼爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12788, 'zhTW', '[Silvermoon]', '[We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge\'s plague.  They have born rotten, delicious fruit...$B$BTake this box to Silvermoon City.  Inside is a head that is infected with the zombie plague, and something else... an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Tepesh.  She attends Lor\'themar Theron in Silvermoon City.]', '[Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Tepesh in Silvermoon City.]', '', '去找銀月城的藥劑師提琵希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12789, 'zhTW', '', '', '[Crusader Valus at Light\'s Trust wants you to report to Sergeant Riannah at Light\'s Breach in Zul\'Drak.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12790, 'zhTW', '[Learning to Leave and Return: the Magical Way]', '[Just in case you don\'t already know, you can use the crystal on the platform behind me to teleport to the Violet Stand in Crystalsong Forest beneath Dalaran.$B$BCorrespondingly, you can use the crystal at the stand below to return to the chamber above me.$B$BI would like for you to do this now.]', '[Archmage Celindra at The Violet Gate in Dalaran wants you to use the Teleport to Violet Stand Crystal and the Teleport to Dalaran Crystal.]', '', '去找達拉然的大法師瑟琳卓。', '已使用紫羅蘭崗哨傳送水晶', '已使用達拉然傳送水晶', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12791, 'zhTW', '[The Magical Kingdom of Dalaran]', '[Hello, $N. You may or may not be aware that we Kirin Tor moved our city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.$B$BWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.]', '[Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12792, 'zhTW', '', '', '[Commander Kunz at Argent Stand wants you to report to Sergeant Riannah at Light\'s Breach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12793, 'zhTW', '', '', '[Khufu in Zim\'Torga wants you to travel to Light\'s Breach and report to Sergeant Riannah there.Maaka will provide you with transportation there.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12794, 'zhTW', '[The Magical Kingdom of Dalaran]', '[Hello, $N. You may or may not be aware that we Kirin Tor moved our city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.$B$BWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.]', '[Deliver the Kirin Tor Signet to Archmage Celindra at the Violet Gate in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12795, 'zhTW', '', '', '[Bloodrose Datura at Ebon Watch wants you to speak with Commander Falstaav at The Argent Stand.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12796, 'zhTW', '[The Magical Kingdom of Dalaran]', '[Hello, $N. You may or may not be aware that we Kirin Tor moved our city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.$B$BWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.]', '[Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12797, 'zhTW', '[Back Through the Waygate]', '[You speak the truth, $r.  I can sense the very essence of Sholazar Basin begin to fray by the blight of undeath even as we speak.$B$BI\'ve bound my being into the rune, $r.  Deliver it to she who sent you here -- for only her power can grant me passage to her lands.]', '[Bring the Omega Rune to the Avatar of Freya at the Rainspeaker Rapids in Sholazar Basin.]', '', '去找索拉查盆地的芙蕾雅的化身。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12798, 'zhTW', '[Swords Deck]', '[Now that you have gathered all of the Swords cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.$B$BYou feel the card could be used to communicate with someone.]', '[Use the Swords Deck to summon a Darkmoon Fortune Teller and give the deck to them.]', '', '去找暗月算命師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12799, 'zhTW', '[Siphoning the Spirits]', '[You should be happy he\'s coming, they said. You\'ll enjoy his company, they said....$B$BWell it\'s not as if I had a choice in the matter. Finklestein is the Crusade\'s best alchemist. I suppose I should be honored that he\'s chosen my post to set up shop. But ever since he\'s arrived, I\'ve been relegated to collecting various alchemical ingredients.$B$BSay, $r, how about you give me a hand? Just south of here are some pools that are haunted by spirits of ancient trolls. Collect their ectoplasm for me.]', '[Captain Arnath at Heb\'Valok wants you to collect 5 Ancient Ectoplasms from the Lost Drakkari Spirits at the Pools of Zha\'Jin.]', '', '去找祖爾德拉克的阿爾納斯上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12800, 'zhTW', '', '', '[Report to Scourge Commander Thalanor at Browman Mill.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12801, 'zhTW', '[The Light of Dawn]', '[The Argent Dawn stands defiantly against us at Light\'s Hope Chapel. They dare oppose the Scourge and for that reason alone they must be destroyed!$B$BThe mighty armies of the Lich King stand at the ready as the final battle for the Plaguelands approaches. Today we ascend into the immortal realm of Scourge heroes!$B$BWhen you are ready for battle, report to Highlord Darion Mograine. It is the highlord who will issue the final march orders and command our armies at Light\'s Hope Chapel.]', '[Defeat the forces of the Argent Dawn and uncover the Light of Dawn.$B$BReport to Highlord Darion Mograine should you survive.]', '', '', '拂曉之光已發現', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12802, 'zhTW', '', '', '[Drakuru wants you to bring the Heart of the Ancients to him at Drak\'atal Passage.You will need to collect 5 Desperate Mojo to use the elixir there.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12803, 'zhTW', '', '', '[Travel to the Blight Line, between Rainspeaker Rapids and the Lost Lands in Sholazar Basin and seek the Avatar of Freya.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12804, 'zhTW', '[A Steak Fit for a Hunter]', '[Sometimes, there\'s nothing worse than a camp full of hunters. They\'re all so busy taking down prey animals that the only meat I get is tough and stringy. That\'s hardly the kind of thing you want to come home to after a long day on the hunt.$B$BLucky for us, though, there is a source of tender, succulent meat nearby. To the south of the river and the camp live longneck grazers. They\'re a perfect source of meat for our hungry hunters. Bring me back the best cuts of meat and we\'ll properly toast our comrades.]', '[Bring 5 Longneck Grazer Steaks to Korg the Cleaver at the Nesingwary Base Camp.]', '', '去找索拉查盆地的『斬擊者』寇爾格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12805, 'zhTW', '[Salvaging Life\'s Strength]', '[The Lifeblood Pillar was toppled over with great force, sending the very earth into an upheaval.$B$BThe elementals that wander the sundered shard carry with them the very life essence that gave the pillar its strength.  I cannot allow this energy to be wasted, for only four pillars remain.$B$BHead to the sundered shard, to the southeast, and seek the lifeblood elementals.$B$BUse this gem on their remains to recover their rampant energy.  We\'ll need the energy to heal the land when all this is over.]', '[The Avatar of Freya wants you to go to the Sundered Shard to the southeast and use the Lifeforce Gem on 8 destroyed Lifeblood Elementals.]', '', '去找索拉查盆地的芙蕾雅的化身。', '已回收生命之血能量', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12806, 'zhTW', '', '', '[Report to Lord-Commander Arete at Death\'s Rise in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12807 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12807, 'zhTW', '[The Story Thus Far...]', '[We have much to do, but first I believe a short refresher is in order.$B$BWe death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest.$B$BWhen you are ready for an earful, speak with me again and I shall provide enlightenment.]', '[Listen to Lord-Commander Arete\'s tale at Death\'s Rise.]', '已聆聽將軍阿雷特的故事', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12808 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12808, 'zhTW', '', '', '[Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12810, 'zhTW', '[Blood in the Water]', '[The forces at Onslaught Harbor are heavily reinforced by gryphon riders. You need a mount that will enable you to put them down. But first, we need the components for the ritual that is going to make it all happen.$B$BA great deal of blood is necessary for the ritual to be undertaken.$B$B<The lord-commander points down and to the northwest.>$B$BThere is a readily available supply down there in the harbor... sharks. Do not return to me until you\'ve filled this bladder with their blood.]', '[Lord-Commander Arete at Death\'s Rise wants you to fill the Gore Bladder with the blood of 10 Ravenous Jaws.]', '', '去找冰冠冰川的指揮統領艾睿特。', '已從貪婪之顎收集血液', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12811, 'zhTW', '', '', '[Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12813, 'zhTW', '[From Their Corpses, Rise!]', '[How kind... how generous our lord-commander is. Where he is flowers and sunshine, I am filled only with hatred.$B$BIt is not enough to end their miserable lives... I want them humiliated... debased!$B$BWhat could be more unspeakable than to be turned into that which you hate? To dedicate your existence to eradicating a thing, and then in the end to become it?$B$BHow sad.$B$BTake this tincture northwest to Onslaught Harbor. Apply it to their still corpses and watch what happens, but avoid the cathedral.]', '[Setaal Darkmender at Death\'s Rise has given you the Darkmender\'s Tincture. Apply it to the corpses of 10 of any of the Scarlet Onslaught units found at Onslaught Harbor.]', '', '去找冰冠冰川的瑟塔爾‧暗癒者。', '血色十字軍屍體已轉化', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12814, 'zhTW', '[You\'ll Need a Gryphon]', '[What could be more fitting than to take one of their own gryphons to use against them? Go to Onslaught Harbor and take the reins to one of their gryphons from the dead clutches of its rider.$B$BReturn with the gryphon, delivering it to Uzo Deathcaller. He will see to its proper transformation and provide you with further instructions.]', '[Deliver an Onslaught Gryphon to Uzo Deathcaller at Death\'s Rise.]', '', '去找冰冠冰川的烏佐‧喚死者。', '十字軍獅鷲已交給烏索·喚死者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12815, 'zhTW', '[No Fly Zone]', '[Now that you got your bone gryphon, I wantcha to take it back down there everyday and make a no fly zone over Onslaught Harbor.$B$BI gotta admit, mon, I don\'t really care if you use the bone gryphon to kill them gryphon riders or not. But I\'m guessin\' that if you do, you\'ll find it much easier to get to \'em.$B$BBesides, it\'s got lots of neat tricks you can use.]', '[Uzo Deathcaller at Death\'s Rise wants you to kill 10 Onslaught Gryphon Riders.]', '', '去找冰冠冰川的烏佐‧喚死者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12816, 'zhTW', '[Investigate the Scourge of Silvermoon]', '[The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Silvermoon from these accursed invaders? $B$B $B$BThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I\'m certain, and I want you to find out what. Thin the numbers of those aberrations while you\'re at it; bring me proof of their death along with your results, and I will reward you.  Go!]', '[Collect three Dim Necrotic Stones from the Scourge outside Silvermoon and investigate the glowing runic circles near their encampment.]', '調查一個法陣', '去找永歌森林的朱雷克中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12818, 'zhTW', '清理', '直接講重點…瑞基特要我組裝一些更強力的地雷，但是我的零件快不夠用了。$B$B在城鎮的西邊，你可以找到上一艘火箭雪橇的殘骸…瑞基特在替它加油的時候可能有點太興奮了，但是也許我早該想到不能把噴嘴放的太靠近排氣孔。活到老，學到老啊，嗯?$B$B在雪橇的殘骸附近應該有很多多餘的零件…你何不去那裡趕跑那些拾荒者，然後替我搶點殘骸來呢?', 'K3的吉爾·炫臼想要10塊燒焦的殘骸。', '', '去找風暴峭壁的吉爾·炫臼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12819, 'zhTW', '[Just Around the Corner]', '[Blast it! Where are my tools? I had them here just a moment ago.$B$BOh! I probably forgot them when I was setting up that minefield in the west. That\'s mildly inconvenient. I\'d be quite appreciative if you could go get them for me. You\'ll need to watch your step though... you should be able to use the same path that I did to get out.$B$BOh, and don\'t try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren\'t very discerning in who they target.]', '[Jeer Sparksocket at K3 would like Sparksocket\'s Tools retrieved from his minefield.]', '', '去找風暴峭壁的吉爾·炫臼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12820, 'zhTW', '[A Delicate Touch]', '[I\'ve been waiting an eternity for these mines! Well, a few days at least. What took him so long?$B$BHere\'s the low down, compadre... there\'s this nasty bunch of magnataur--you know, big, hairy, and extremely ugly--and they seem pretty keen on taking K3 for themselves.$B$BNot going to happen.$B$BWe\'ve got some defenses set up in their path, northeast of here. Sadly, our laser turrets have pretty limited power supplies... that\'s where these mines come in! Get over there and blow them up good!]', '[Ricket at K3 wants you to use Improved Land Mines at Garm\'s Bane to fend off 12 attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.]', '', '去找風暴峭壁的瑞基特。', '加姆攻擊者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12821, 'zhTW', '[Cell Block Tango]', '[The sapper squad is ready. That means it\'s time for fun!$B$BThere\'s only one thing holding us up from our full-scale assault on Garm! I sent a runner to set a teleporter up behind him--successfully I might add--and he returned to get the power cell it needs to function. It isn\'t working yet... which means the power cell didn\'t get there.$B$BI need you to look just on the other side of Garm\'s Bane for the power cell. When you find it, bring it farther east to Garm\'s Rise and activate the teleporter.]', '[Ricket at K3 would like you to locate the Transporter Power Cell and use it to activate the Transportation Pad at Garm\'s Rise.]', '加姆傳送裝置已啟動', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12822, 'zhTW', '[Know No Fear]', '[Now that we have the teleporter open, my plan is quite complex... it has several facets and will take impeccable coordination. And there are supplies to be gathered! And troops to recruit! Likely, weeks of hard labor as well!$B$BHahah, I had you going there for a moment, didn\'t I? You\'ve got this, kid. Hop through the teleporter and take the fight to them! Our sappers will back you up... they won\'t have anywhere to run.]', '[Ricket at K3 wants you to kill 6 Garm Watchers and 8 Snowblind Devotees.]', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12823, 'zhTW', '[A Flawless Plan]', '[Hey there! Joining us for the assault I assume?$B$BI\'ve got a special task for you... we\'re going to bring the whole cave down on their heads! Towards the back of their cave, you should find Frostgut\'s Altar.  Sneak up and plant this hardpacked explosive bundle somewhere close to it.$B$BOnce the charge is placed, stick around just long enough to make sure Frostgut bites it, then get out quickly! There\'s no knowing how long the cave will last once that thing goes off!]', '[Gino at Garm\'s Rise wants you to plant the Hardpacked Explosive Bundle near Frostgut\'s Altar, kill Tormar Frostgut, and then escape the cave before it collapses on you.]', '', '', '放置炸藥包', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12824, 'zhTW', '', '', '[Return to Ricket at K3.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12826 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12826, 'zhTW', '[Slightly Unstable]', '[Looking good!$B$BNo, not you - my new mines. You\'re just a little full of yourself, aren\'t you? I, on the other hand, am absolutely brilliant! My intellect cannot be matched.$B$BWhat were we talking about? Oh yes, my new mines! New and improved... ready for whatever devious use Ricket has concocted.$B$BBe a <good lad/doll> and go hand them off to Ricket, will you? She\'s right over there... it should be quite the epic journey, I\'m sure. Be careful though, she\'s a little loopy.]', '[Deliver Jeer\'s Improved Land Mines to Ricket in K3.]', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12827 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12827, 'zhTW', '回收乾糧再利用', '嘿，嘿!你是新面孔!要不要幫瑞基特一個忙啊?$B$B我們有個預料外的問題…存糧不足。我知道，我知道…我們早該預料到有這麼一天，但你不懂。我們原本只是想要帶著工兵分隊迅速的在這邊繞一圈，就這樣，所以通常咱們不擔心長期食糧問題。但老K3似乎越來越熱鬧了。$B$B簡單的解決方案?西邊有個豺狼人營地，附近有些豺狼人在亂晃，有些到處在拾荒。能不能幫忙弄點他們的乾糧來?', 'K3的瑞基特，要你從附近的野生山丘豺狼人身上，回收16份風乾的豺狼人口糧。', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12828, 'zhTW', '[Ample Inspiration]', '[Wow! That stuff is nasty. Not to account for gnoll taste or anything, but I figured whatever they had would at least be... edible?$B$BLet\'s get more creative.$B$BTore\'s got an explosive dispenser north of town... not far from the big cavern entrance, can\'t miss it. I\'m sure she intends them for mining purposes of some sort, but I\'ve got a better idea.$B$BGrab one of those things and rush it to one of the nearby mammoths... most of them are to the west. Collect the meat, bring it back.]', '[Ricket at K3 wants you to retrieve a U.D.E.D, use it to blow up a mammoth, and retrieve 8 Hearty Mammoth Meat.]', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12829, 'zhTW', '[Moving In]', '[Hiya! The name\'s Tore. I  head up the mining operation here at K3... or I will shortly anyway!$B$BThis here cave is full of creepy-crawlies. I think we could do with a few less spiders before we move in - what\'d you think?]', '[Tore Rumblewrench outside of Crystalweb Cavern wants you to kill 12 Crystalweb Spiders.]', '', '去找風暴峭壁的托爾‧滾鉗。', '水晶蛛網蜘蛛已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12830, 'zhTW', '[Ore Repossession]', '[We\'re moving in!$B$BThere were some snobolds here when we arrived... their mining operation seems to have met some unfortunate happenings though. Doesn\'t much matter - we were taking over soon anyway.$B$BI sent some of our miners in there to get me some ore samples that I can use to calibrate our machines for processing, but they haven\'t come back.$B$BMind going in there and nabbing some samples for me in their stead? The snobolds probably have some on them, though I\'d expect most of them are dead by now.]', '[Tore Rumblewrench outside of Crystalweb Cavern would like you to retrieve 5 samples of Impure Saronite Ore.]', '', '去找風暴峭壁的托爾‧滾鉗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12831 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12831, 'zhTW', '只忘一半', '喂…我胃裡好像有個螺旋槳一樣。$B$B我想我走得動，但是從我在洞穴後方被某個生物咬了一下之後我就覺得身體裡面有個很糟糕的東西。那玩意比其他蜘蛛都來的大…而且色彩鮮豔。$B$B瑞基特可能可以替我做出解毒劑，但是她會需要咬我的那玩意身上的毒囊。你願意幫我找到它嗎?我不覺得托爾會來幫忙。$B$B我會躺在這裝死，希望他們不會來煩我。', '晶網洞窟中受傷的哥布林礦工要你從冰尖爬行者身上取得冰尖毒囊。', '', '去找風暴峭壁的受傷的哥布林礦工。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12832, 'zhTW', '[Bitter Departure]', '[Oi - thank you! I thought for sure I\'d just be a spider snack. Perhaps I\'m speaking a bit soon though - let\'s get the heck out of here!$B$BLet me know as soon as you\'re ready to go... make it quick.]', '[Escort the Injured Goblin Miner out of Crystalweb Cavern and then speak to Ricket at K3.]', '護送受傷的地精礦工前往K3', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12833, 'zhTW', '[Overstock]', '[Hey there again! You didn\'t run off like all the other adventurers did? Well, you\'re just a peach, aren\'t ya? I was beginning to think I smelled funny or something!$B$BWe could still use a bit of a hand around here, and you have just the right experience.  Remember those magnataur? Well apparently the cave didn\'t completely collapse... there are still quite a few left. So much for Gino taking care of them, eh?$B$BFortunately, Jeer made way more than enough mines. You\'ve got this!]', '[Ricket at K3 wants you to use Improved Land Mines at Garm\'s Bane to fend off the attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.]', '', '去找風暴峭壁的瑞基特。', '加姆入侵者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12836, 'zhTW', '表達謝意', '我正好知道一項工作，很適合急著表現的菜鳥!我們有個豺狼人的麻煩…你甚至可以說是個豺狼人流行病!討厭的生物。他們不斷地湧出，現在已經跑到了我們的門口，偷我們的東西!真是難以相信。$B$B事情全都是因為他們的領袖，瘤皮而起，也會因為他結束。我要你去處理「結束」的部分…一路前往西邊雪盲丘的營地，去拜訪他。$B$B當我說「拜訪他」的時候，其實就是婉轉地在說「將他凌遲至死」。瞭嗎?瞭吧!', 'K3的瑞基特要你殺死瘤皮。', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12838, 'zhTW', '[Intelligence Gathering]', '[I need to know what the Scarlet Onslaught is planning today. You will be my instrument in this task.$B$BFly to Onslaught Harbor and rifle through their baggage trunks for documents. The trunks will be locked, so you\'ll have to take the keys from the Scarlet Onslaught members by whatever means.]', '[Aurochs Grimbane at Death\'s Rise wants you to collect 5 Onslaught Intel Documents.]', '', '去找冰冠冰川的野牛‧厲禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12839, 'zhTW', '[The Grand (Admiral\'s) Plan]', '[At first this note looks like any of the other intel that you\'ve been looking for. However, a quick perusal of its contents disabuses you of this notion.$B$BThe letter conveys that Grand Admiral Westwind is present somewhere on the island, but that he is keeping himself secluded for now. He speaks of a glorious day that is coming soon in which the Scarlet Onslaught will wash over first the Lich King and then the rest of world to finally bring order to Azeroth.$B$BThe lord-commander will want to see this!]', '[Deliver the Note from the Grand Admiral to Lord-Commander Arete at Death\'s Rise.]', '', '去找冰冠冰川的指揮統領艾睿特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12840, 'zhTW', '[In Strict Confidence]', '[If anyone knows where the admiral is, then surely it must be his captains on the ships in Onslaught Harbor.$B$B<The lord-commander rubs his hands together.>$B$BWelsington and Hartford are their names if memory serves. Go beat the information out of them and then end their miserable lives.$B$BI want to know where the grand admiral is hidden!]', '[Lord-Commander Arete at Death\'s Rise wants you to beat information out of Captains Welsington and Hartford.]', '', '去找冰冠冰川的指揮統領艾睿特。', '已拷問並殺死威靈頓隊長', '已拷問並殺死哈特福隊長', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12841, 'zhTW', '[The Crone\'s Bargain]', '[Yes, it must be the little green prisoner you\'re after...  We might be able to help each other.$B$BYou\'re not going to get the goblin out of here by force. Not alive, anyway.$B$BAmong my people I am known as a Yrkvinn, a practitioner of illusions. As you can see, the Hyldnir have made me their prisoner.$B$BIf I had my runes, I could make you go unnoticed among them. Further inside, patrolling the mines, you\'ll find an overseer named Syra. She has my runes. Retrieve them and we\'ll talk some more.]', '[Lok\'lira the Crone inside the Forlorn Mine wants you to retrieve the Runes of the Yrkvinn from Overseer Syra.]', '', '去找風暴峭壁的『巫婆』洛莉拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12842, 'zhTW', '[Runeforging: Preparation For Battle]', '[The mark of war is etched indelibly upon your soul, death knight. You have learned the dark art of runeforging and with it you will engrave runes of power upon your weaponry.$B$BPreparations for battle must be made. Return to one of the runeforges, here in the Heart of Acherus, and use the power of runeforging to emblazon your weapon with a rune of power!$B$BReturn to me when your blade glows with dark energy!]', '[Instructor Razuvious in Ebon Hold has commanded you to use your Runeforging ability to engrave a rune [of your choosing] upon your Runed Soulblade.$B$BYou may freely replace the engraving upon your weapon at any time, so long as you are near a Runeforge.]', '武器已鑲飾', '去找黑鴉堡壘的講師拉祖維斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12843, 'zhTW', '他們把男人抓走了!', '你得幫幫我們！當我們遠征到山裡架設發射塔的時候被襲擊了。$B$B他們看起來很像維酷人，但皮膚是藍色的，而且表面還覆著霜…而且全是女性！他們把遠征隊的男人全都抓走了，放過我們女性。求求你，$N！我想他們應該被關在希弗爾達村，就是那個能俯瞰K3的村子。', '格雷徹·嘶炫要你前往希弗爾達村並拯救5個哥布林囚犯。', '', '去找風暴峭壁的格雷森·嘶炫。', '釋放哥布林囚犯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12844, 'zhTW', '裝備回收', '拜託你，$N。當海迪尼爾帶走我們的男人的時候，他們也把我們的裝備全都給拿走了。當然，把人救回來是比較重要的，但假如你找到了我們的裝備，能帶回來給我們的話，我們也會非常感激你的。$B$B你可以在我們的上方找到他們的村子，就在北方。', '格雷徹·嘶炫要你到K3北邊的希弗爾達村收集8份K3裝備。', '', '去找風暴峭壁的格雷森·嘶炫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12846, 'zhTW', '', '', '[Find the entrance to the Forlorn Mine in northern Sifreldar Village and look for clues for Zeev Fizzlespark\'s whereabouts.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12847, 'zhTW', '第二次機會', '我聽說過他們的大教堂裡有個大主教，但是我完全沒想到他們是把蘭格瑞給復活起來，又讓他晉升了!赤紅大教堂有重兵駐防，而且只有一個出入口，所以你得找些幫手。$B$B我們還是得弄清楚上將在哪裡，但這次我們絕不依賴運氣!$B$B帶著這個裝置。一旦你殺死了大主教，就可以用它來開啟一道傳送門讓我通過。$B$B我要直接從他的靈魂上把答案逼出來!我們一定會把海軍上將韋斯溫找出來的!', '殺死大主教蘭格瑞，然後在他的屍體旁召喚艾睿特之門。等指揮統領艾睿特訊問完大主教的靈魂之後，在赤紅大教堂與他交談。', '', '去找冰冠冰川的指揮統領艾睿特。', '', '召喚艾睿特之門', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12848, 'zhTW', '[The Endless Hunger]', '[The endless hunger will soon take hold of you, $c. When it does, you will feel pain immeasurable. There is only one remedy for the suffering: the hunger must be sated.$B$BI give you the key to your salvation.$B$BChained to the Heart of Acherus are those deemed unworthy of the dark brotherhood. Use the key to free an unworthy initiate. Allow them to equip their gear and battle you for their freedom. Kill and the pain will cease. Fail and suffer for eternity.$B$BLive or die - the choice is yours to make.]', '[Instructor Razuvious in Ebon Hold has commanded you to free an Unworthy Initiate and then kill the Unworthy Initiate in cold blood!$B$BIt\'s your life or theirs!]', '', '去找黑鴉堡壘的講師拉祖維斯。', '不配的新成員已被壓制', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12849, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12850, 'zhTW', '', '', '[Report to Scourge Commander Thalanor at the balcony on the first floor of Ebon Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12851, 'zhTW', '[Bearly Hanging On]', '[The test awaits, woman!$B$BDo you have the heart of a warrior queen? Or that of a sniveling seamstress?$B$BOne taste of war and you\'ll know the answer.$B$BYou might lie to your mother, your sisters, and even yourself, but the battlefield always exposes one\'s true nature.$B$BWhen you\'ve made your preparations, mount Icefang and ride into battle. From her back, you must rain down a shower of death upon our enemy.]', '[Brijana at Brunnhildar Village wants you to mount Icefang and shoot 7 Frostworgs and 15 Frost Giants in the Valley of Ancient Winters.]', '', '去找風暴峭壁的布瑞嘉娜。', '寒冰座狼已焚燒', '寒冰巨人已焚燒', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12852 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12852, 'zhTW', '[The Admiral Revealed]', '[When High General Abbendis was confronted at New Hearthglen, the grand admiral protected himself within an impenetrable sphere of magic before making his escape.$B$BI am particularly adept at nullifying magic.$B$BTake this to use against him inside The Hidden Hollow when he puts the sphere up. I wish that I could be there to see the look on his face when you do it.$B$BDeal with him.]', '[Lord-Commander Arete wants you to deal with Grand Admiral Westwind. Return to the lord-commander upon Death\'s Rise after you have done so.]', '', '去找冰冠冰川的指揮統領艾睿特。', '已處理大提督維斯特文', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12853 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12853, 'zhTW', '', '', '[Speak to Jeer Sparksocket at K3 in the Storm Peaks.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12854 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12854, 'zhTW', '跟隨布萊恩的足跡', '自從在灰白之丘找到了布萊恩的日誌以來，我們只有發現過另外一個布萊恩的線索。有一封神秘的信寄到了鐵爐堡的探險者協會，沒有任何關於寄出地點的訊息。上頭只寫著我們應該要與布萊恩在他的營地碰面，然後協助他進行搜索。$B$B我只知道那個營地應該位於此地的東北方，越過伯爾之息河谷，座落於泰坦之途的某些遺跡處。', '從布萊恩的營地取得粗麻包裹的信箋，然後交還給霜堡的考古學家安多林。', '', '去找風暴峭壁的考古學家安多林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12855 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12855, 'zhTW', '[Sniffing Out the Perpetrator]', '[The tone of Brann\'s note suggests he meant to bury something with the note, maybe a pack of some kind. You\'re sure this was all you found?$B$BOkay, I\'m going to have you take one of these frosthounds with you. The frostborn use them for tracking. Bring it to the destroyed camp and let it get Brann\'s scent.$B$BIt should at least lead you to the location of those missing possessions, and if we\'re lucky, Brann himself. ]', '[Use the Frosthound Collar at the Abandoned Camp to track down whoever took Brann\'s possessions. When you recover them, use the communication device and speak to whoever you can contact.]', '', '', '追蹤小偷', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12856 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12856, 'zhTW', '[Cold Hearted]', '[To be slain honorably on the field of battle brings us all glory. To be frozen in a block of ice and endlessly taunted does not....$B$BYou are to fly to the frost giant city of Dun Niffelem, just east of the Valley of Ancient Winters, and liberate a captive proto-drake. With her, you will be able to free our sisters from their frozen bonds and carry three of them safely home.$B$BBeware the giants\' clubs, sister, lest you find yourself numbered among the captives.]', '[Brijana, just east of Brunnhildar Village, wants you to fly to Dun Niffelem, then free 3 Captured Proto-Drakes and rescue 9 Brunnhildar Prisoners.]', '', '', '已救出布倫希爾達的囚犯', '已釋放始祖幼龍', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12857, 'zhTW', '[Wanted: Ragemane\'s Flipper]', '[Posted by Chief Rageclaw:$B$BChief Rageclaw trusty lion seal, Ragemane, bite hand that feed him. Rageclaw say Ragemane no more good because of bad Drakuru trolls. Chief Rageclaw very sad to ask that Ragemane be killeded and Ragemane flipper be returned to chief as proof.$B$BYou find Ragemane to southeast, at Rageclaw Lake.$B$BChief Rageclaw sorry for bad writing. First time use one of these things; plus, Chief Rageclaw is wolvar, not person.$B$B]', '[Recover Ragemane\'s Flipper and return it to Chief Rageclaw at Light\'s Breach in Zul\'Drak.]', '', '去找祖爾德拉克的怒爪酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12858, 'zhTW', '[Pieces to the Puzzle]', '[Thank the Light that someone got my message. Now that I\'m safe from the iron dwarves, I need to ask your help with something. I\'ve got a lead on Norgannon\'s keystone, which guards access to Ulduar\'s archives, but the Titans divided it into two pieces and secreted them away.$B$BOne of the pieces, the keystone\'s shell, is held within the Inventor\'s Library on the northern coast, south of Ulduar itself. The first thing you\'ll need to do is retrieve the fragments of an access disk from the library\'s guardians.]', '[Gather 6 Inventor\'s Disk Fragments and use them to assemble the Inventor\'s Disk.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12859, 'zhTW', '[This Just In: Fire Still Hot!]', '[Trolls attack Rageclaw Den and kick Rageclaw out! It get worse. Trolls now burning village! This very bad. Chief make top Rageclaw shaman, Moky, do study on fire. Results very surprising! Fire still hot and can burn things.$B$BWill you help Rageclaw and put fire out? Moky has special Rageclaw fire extinguisher for you. Use special fire extinguisher to put out fire at Rageclaw Den to southeast. Sometimes take many sprays to douse fire, but extinguisher always have water! Rageclaw magic strong!]', '[Elder Shaman Moky at Light\'s Breach in Zul\'Drak wants you to use the Rageclaw Fire Extinguisher to douse 15 hut fires at Rageclaw Den.$B$B]', '', '去找祖爾德拉克的薩滿長老摩基。', '小屋的火已撲滅', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12861, 'zhTW', '[Trolls Is Gone Crazy!]', '[Drakuru... You know who this troll is? I think bad troll are controlled by the Drakuru troll. They call themself Drakuru trolls - that how I know. Now you see why I am chief of Rageclaw. Smartest of all wolvar!$B$BBut that not why I talk to you now. Bad troll come and kick Rageclaw out of den. Rageclaw that no run away held as prisoner in village. You go to Rageclaw Den, southeast, and free captured Rageclaw. Kill troll for lock opener. You maybe kill many troll for many lock opener.]', '[Chief Rageclaw at Light\'s Breach in Zul\'Drak wants you to use the Drakuru "Lock Openers" found on various Drakuru trolls to free 8 Captured Rageclaw.]', '', '去找祖爾德拉克的怒爪酋長。', '已釋放被俘的怒爪', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12862, 'zhTW', '', '', '[Speak to Ricket to make use of Ricket\'s D16 Propelled Delivery Device to enter further into Storm Peaks.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12864, 'zhTW', '[Missing Scouts]', '[There is something that I could use a hand with now that I have you.$B$BWe have a few scouts that are extremely late in returning. The peaks are harsh... but these boys know what they\'re doing.$B$BHead to the east... along the Bor\'s Breath valley and near Bor\'s Fall... they should be out that direction. If you find any sign of one of them, bring me back news immediately. We have a few enemies in the area - if any of them are getting a bit uppity, the more warning the better.]', '[Glorthal in Frosthold has requested a search of the Bor\'s Breath valley and Bor\'s Fall for any sign of the missing Frostborn Scouts.]', '找出失蹤的偵察兵', '去找風暴峭壁的格洛梭·硬鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12865, 'zhTW', '[Loyal Companions]', '[Fresh blood! Good to meet ya! I\'ve got some work if you\'ve got some time.$B$BOff to the east are the Foot Steppes... pretty hard land, but there\'s quite a group of rhino that graze there. Our birds have a taste for that rhino meat, but it\'s always a bit dangerous for them to go hunting with all of the proto-drakes that nest around there.$B$BIf you\'re keen, head over that way and get some rhino meat, bring it back to the peaks above here, and then use it to feed some of the eagles that nest there.]', '[Fjorlin Frostbrow at Frosthold wants you to obtain 8 slabs of Fresh Ice Rhino Meat and use them to feed the Stormcrest Eagles above town.]', '', '去找風暴峭壁的弗尤林·霜眉。', '已餵食風脊鷹', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12866, 'zhTW', '[Stemming the Aggressors]', '[Damn harpies. We\'ve beat that bunch into submission more times than I can remember... and they stay quiet for a time after each bout. This time, I\'d thought that maybe it sunk in.$B$BApparently not.$B$BTheir memory may be a bit short, but if their numbers are thinned enough, they\'ll keep to themselves. Head into the valleys in the north and east and clear out a fair chunk of them for me, will ya?]', '[Glorthal Stiffbeard at Frosthold wants you to kill 8 Frostfeather Screechers and 8 Frostfeather Witches.]', '', '去找風暴峭壁的格洛梭·硬鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12867, 'zhTW', '[Baby Stealers]', '[A few weeks ago, if you looked up, you\'d see dozens of those beautiful eagles soaring the skies. Now, only a few if any. They\'ve taken to staying with their nests nearly all the time now because the harpies have been stealing their eggs.$B$BThe harpies have grown a taste for eagle flesh, it seems... the sick wretches are caring for the eggs long enough to feast on the hatchlings. Go into the valleys to the north or the east and find the eggs... bring them back here, and I\'ll take them back to the nests.]', '[Fjorlin Frostbrow at Frosthold would like you to bring back 15 Stormcrest Eagle Eggs.]', '', '去找風暴峭壁的弗尤林·霜眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12868, 'zhTW', '[Sirana Iceshriek]', '[This Sirana Iceshriek sounds like the one that\'s spurring the harpies to be more aggressive. If we kill her, I suspect their attacks won\'t last long afterwards.$B$BOne of our stormriders claims to have spotted her circling the peak directly northwest of here.  Go find the wench and put her down. Let\'s see this done.]', '[Glorthal Stiffbeard at Frosthold wants you to kill Sirana Iceshriek.]', '', '去找風暴峭壁的格洛梭·硬鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12869, 'zhTW', '[Pushed Too Far]', '[You were there with Loken, weren\'t you? The iron dwarves captured Veranus, the brood mother of the proto-drakes. The drakes don\'t seem even a little bit happy about the situation... they\'ve gotten very aggressive.$B$BThey\'ve pushed into stormcrest territory and the eagles have taken to an all out fight with them. It\'s time to return the favor. We\'re riding to the Foot Steppes and slaughtering them there.$B$BKing Stormheart left this hammer to me - make good use and see to it that I get it back.]', '[Fjorlin Frostbrow at Frosthold wants you to ride with a Stormcrest Eagle and kill 16 Stormpeak Wyrms in the Foot Steppes.]', '', '去找風暴峭壁的弗尤林·霜眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12870, 'zhTW', '遠古聖物', '哎呀你好哇!$B$B在你出發去進行你偉大的任務與冒險之前，我可以拜託你幫個小忙嗎，<小子/小女孩>?$B$B這山脈中藏著滿滿的聖物和漂亮的小東西…對探險者協會來說簡直就是美夢成真啊。如果你碰巧找到這些寶藏，然後帶來給我，我會萬分感激的。我甚至可以跟你分享我的麥芽酒!相信我，<小子/小女孩>，這是筆划算的交易!', '把10個奧杜亞聖物帶去給霜堡的洛克·銳頦。', '', '去找風暴峭壁的洛克·銳頦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12871, 'zhTW', '來自探險者協會的援助', '真有趣。我在外殼上並沒有看到任何鎖定的結構。這代表我們要做的不僅僅是找到另外一部份，然後組合成拱心石就好。$B$B把外殼拿去霜堡，給遠征隊的領導者拉格努斯看。等他佩服完了，應該就能夠靠著外殼推敲出核心的樣子，也許還能讓冰霜矮人幫忙找它。$B$B我去查查看能否找出結合兩個部分的方法。當我們都有了進展再碰頭。', '帶著諾甘農之殼去霜堡找拉格努斯。', '', '去找風暴峭壁的拉格努斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12872, 'zhTW', '[Norgannon\'s Shell]', '[Charging inventor\'s disk.$B$BDisk charging completed.$B$BPreparing emergency protocol gamma.$B$BEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon\'s shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.$B$BPlease have a pleasant millennium.]', '[Recover Norgannon\'s Shell from Archivist Mechaton.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12873, 'zhTW', '', '', '[Speak to Yorg Stormheart in Frosthold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12874, 'zhTW', '霜誕的熱情', '我很樂意提供我的居所與家園給需要幫助的旅行者，但是我不願強迫我的人民加入你們的行動。$B$B這樣吧…我的子民都是貨真價實的戰士。在霜誕矮人成年的時候，他必須在戰鬥中證明自己的本事。他必須向我們證明他不會被體型的差距給打敗。$B$B向我證明你跟我的子民一樣強悍勇猛，我就會讓他們聽你說話或是為你作戰。跟南邊懸崖的弗尤林談談，他會讓你進行測驗。', '霜堡的約格·風暴之心要求你與弗尤林·霜眉交談，取得坐騎，並進行你的挑戰。', '', '去找風暴峭壁的約格·風暴之心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12875 AND `locale` = 'zhTW';
