DELETE FROM `quest_template_locale` WHERE `ID` = 12948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12948, 'zhTW', '苦痛勇士', '這是最後了，我的朋友!你的最後一個對手將會是你一生中最大的挑戰。他是來自寒冰皇冠的維酷鬥士，為了尋求血腥而來!擊敗他，你就會被加冕成為苦痛露天競技場的勇士!這場打鬥將會讓我們兩個都賺大錢!$B$B準備好了跟我說一聲，咱們就開始吧。', '進入苦痛露天競技場並且擊敗『屠夫』伏雷多弗!然後去找『食人妖僕從』烏丁領賞。', '已擊敗屠夫弗拉多夫', '去找祖爾德拉克的食人妖僕人伍德林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12949, 'zhTW', '[Get the Key]', '[$C, the key to my shackles is hanging around the neck of Instructor Hroegar outside.$B$BPerhaps you could retrieve it by separating his head from his shoulders?]', '[Vaelen the Flayed at Ufrang\'s Hall has asked you to retrieve the Key to Vaelen\'s Chains.]', '', '去找冰冠冰川的被搶劫的維倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12950, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12951, 'zhTW', '', '', '[Speak with Baron Sliver at The Shadow Vault.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12952, 'zhTW', '[Gem Perfection]', '[My skills are going to waste in this wretched place.   I spent many years learning to cut gems into their perfect form and have nothing to work on!   You look like the type who may be able to find me some gems and if you do I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.]', '[Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Carter Tiffens in Vengeance Landing.]', '', '去找嚎風峽灣的卡特‧提芬斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12953, 'zhTW', '[Valkyrion Must Burn]', '[The crate is filled with incendiary harpoons.  You recall seeing harpoon guns and dry stacks of hay outside.$B$BPerhaps Iva will appreciate the extra effort and reward you appropriately.]', '[Use the Valkyrion Harpoon Guns to burn 6 Dry Haystacks.]', '', '去找風暴峭壁的『復仇』伊娃。', '已縱火', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12954, 'zhTW', '苦痛露天競技場:伊格卓斯!', '我還在想你什麼時候才會出現呢，$N!過去的血色競技場勇士會吸引超多人來看比賽!我們會賺大錢的，老兄!好多好多錢!$B$B總而言之，這個垃圾場就是祖爾德拉克。這些冰霜食人妖好像都把它當廁所在用。我不知道，不過你問我的話我會說這整個地方都過時啦!但是誰管它呢，對吧?我們是來賺錢的!$B$B你知道規矩，$N。你準備好了就跟我說一聲，咱們就開始表演啦!', '進入苦痛露天競技場並且擊敗伊格卓斯!然後去找『食人妖僕從』烏丁領賞。', '已擊敗尤格德拉斯', '去找祖爾德拉克的食人妖僕人伍德林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12955, 'zhTW', '[Eliminate the Competition]', '[Mrrfrmrfrrmrrr...$B$B<The Leaper clears his throat.>$B$BSorry about that. It can sometimes be hard to understand what I\'m saying. You know how it is.$B$BI wanted to make sure that if you find yourself at the Savage Ledge, over the mountains to the west, that you make sure to eliminate the competition there.$B$BSpecifically, I\'d like you to challenge to duels and humiliate Sigrid Iceborn, Efrem the Faithful, Onu\'zun, and Tinky Wickwhistle in front of the vrykul.]', '[The Leaper at The Shadow Vault wants you to duel and defeat Sigrid Iceborn, Efrem the Faithful, Onu\'zun and Tinky Wickwhistle.]', '', '去找冰冠冰川的跳躍者。', '已擊敗希格麗德·冰生者', '已擊敗忠誠者艾弗倫', '已擊敗歐努宗', '已擊敗汀奇·威克惠斯', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12956, 'zhTW', '[A Spark of Hope]', '[Clearly, this is more than an ordinary hunk of metal.$B$BUnlike any ore you\'re familiar with, it is hard but not brittle, far lighter than it looks, and glows even when cool.$B$BLooking closer, you can make out one of Thorim\'s runes shining beneath the surface....]', '[You are to bring the Refined Gleaming Ore to Thorim in the Temple of Storms.]', '', '去找風暴峭壁的索林姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12957, 'zhTW', '[Slaves of the Stormforged]', '[To the southwest, on the western side of the Snowdrift Plains, the iron dwarves have dug a mine into the hillside. There, they use captive mechagnomes, servants of Keeper Mimir, to mine ore.$B$BI don\'t know where these mechagnomes came from, nor what they would do with their freedom, but perhaps we can win their help.$B$BGo to the Frozen Mine, $N, and set these creatures free from their bondage. Ask if they would fight alongside us against iron dwarf tyranny.]', '[Bouldercrag the Rockshaper at Bouldercrag\'s Refuge wants you to free 6 Captive Mechagnomes and kill 3 Stormforged Taskmasters.]', '', '去找風暴峭壁的『塑岩者』石崖。', '嘗試釋放被俘的機械地精', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12958, 'zhTW', '[Shipment: Blood Jade Amulet ]', '[A wealthy shipping concern has requested a collection of Blood Jade Amulets to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter\'s Token.$B$B]', '[Combine a Vrykul Amulet, a Dark Jade and a Bloodstone to make a Blood Jade Amulet and bring it to Timothy Jones in Dalaran.$B$BYou can find a Vrykul Amulet on any Northrend Vrykul.]', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12959, 'zhTW', '[Shipment: Glowing Ivory Figurine]', '[A wealthy shipping concern has requested a collection of Glowing Ivory Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter\'s Token.$B$B]', '[Combine Northern Ivory, a Chalcedony and a Shadow Crystal to create a Glowing Ivory Figurine and bring it to Timothy Jones in Dalaran.$B$BYou can find a Northern Ivory on any Shoveltusk or Mammoth in Northrend.]', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12960, 'zhTW', '[Shipment: Wicked Sun Brooch]', '[A wealthy shipping concern has requested a collection of Wicked Sun Brooches to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter\'s Token.$B$B]', '[Combine an Iron Dwarf Brooch, a Huge Citrine and a Sun Crystal to create a Wicked Sun Brooch and bring it to Timothy Jones in Dalaran.$B$BYou can find an Iron Dwarf Brooch on any Northrend Iron Dwarf.]', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12961, 'zhTW', '[Shipment: Intricate Bone Figurine]', '[A wealthy shipping concern has requested a collection of Intricate Bone Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter\'s Token.$B$B]', '[Combine a Proto Dragon Bone, a Sun Crystal and a Dark Jade to craft an Intricate Bone Figurine and bring it to Timothy Jones in Dalaran.$B$BYou can find a Proto Dragon Bone on any Northrend Proto Dragon.]', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12962, 'zhTW', '[Shipment: Bright Armor Relic]', '[A wealthy shipping concern has requested a collection of Bright Armor Relics to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter\'s Token.$B$B]', '[Combine an Elemental Armor Scrap, a Bloodstone and a Huge Citrine to craft a Bright Armor Relic and bring it to Timothy Jones in Dalaran.$B$BYou can find an Elemental Armor Scrap on any Northrend Revenant.]', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12963, 'zhTW', '[Shipment: Shifting Sun Curio ]', '[A wealthy shipping concern has requested a collection of Shifting Sun Curios to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter\'s Token.$B$B]', '[Combine a Scourge Curio, a Sun Crystal and a Shadow Crystal to make a Shifting Sun Curio and bring it to Timothy Jones in Dalaran.$B$BYou can find a Scourge Curio on any Northrend Scourge.]', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12964, 'zhTW', '[The Dark Ore]', '[At the Frozen Mine in the western part of the Snowdrift Plains, the stormforged iron dwarves have constructed a mine manned by slaves.$B$BIt\'s well behind the lines, so we haven\'t been able to find out much about what\'s going on there, but my scouts have reported seeing them remove cartloads of dark, sickly looking ore.]', '[Bring 5 Ore Samples to Bouldercrag the Rockshaper at Bouldercrag\'s Refuge.]', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12965, 'zhTW', '[The Gifts of Loken]', '[The one who commands the stormforged iron dwarves is called Runeseer Valduran. Although I have never seen them, it is said that his master, Keeper Loken, who took over Ulduar, has given Valduran powerful titan artifacts.$B$BIt could explain the strength and ferocity my men see in the stormforged warriors.$B$BValduran\'s base, Nidavelir, lies to the southwest, across the Snowdrift Plains. Go there, $N, and neutralize his power. Destroy these gifts of Loken\'s and help us to sap the strength of his followers.]', '[Destroy Loken\'s Fury, Loken\'s Power, and Loken\'s Favor, and return to Bouldercrag the Rockshaper at Bouldercrag\'s Refuge.]', '', '去找風暴峭壁的『塑岩者』石崖。', '洛肯的憤怒已摧毀', '洛肯的力量已摧毀', '洛肯的恩惠已摧毀', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12966, 'zhTW', '', '', '[King Jokkum in Dun Niffelem wants you to find Njormeld at Fjorn\'s Anvil.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12967, 'zhTW', '[Battling the Elements]', '[Snorri was once the pride of our nation. A mighty warrior, many an enemy fell to his club.$B$BWe honor him, though he\'s no longer what he once was. Age has taken its toll, dulling his senses and sapping his strength. Still, he remains as proud as ever, never missing an opportunity to join a battle.$B$BSpeaking of battle, we\'re cooling Fjorn\'s anvil so it can be taken home. The remaining fire revenants are putting up some resistance. Help Snorri relive his glory days, $r. Guide him against this enemy.]', '[Njormeld wants you to accompany Snorri to Fjorn\'s anvil and help him kill 10 Seething Revenants.]', '', '去找風暴峭壁的尼約梅爾德。', '沸騰亡魂已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12968, 'zhTW', '[Yulda\'s Folly]', '[The witch that started it all, Yulda the Stormspeaker came to our very village.  She dared to insult our noble traditions and spouted the Lich King\'s venomous promises of power.$B$BShe ought to have left with a sword through her, but her magic was strong and she managed to escape.$B$BSeek her in Valkyrion inside the largest dwelling and show her that we are not to be trifled with.]', '[Iva the Vengeful at Brunnhildar Village wants you to slay Yulda the Stormspeaker in Valkyrion.]', '', '去找風暴峭壁的『復仇』伊娃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12969, 'zhTW', '[Is That Your Goblin?]', '[I trust that\'s the green little one you\'ve been looking for.  If I were you I\'d step in before that Hyldnir splits him in half.$B$BYou\'ve arrived in the middle of the Hyldsmeet, so all challenges must be accepted by participants.  There\'s nothing to stop you from taking your green friend\'s place.]', '[Challenge Agnetta Tyrsdottar in order to save Zeev Fizzlespark.  Return to Lok\'lira the Crone in Brunnhildar Village after you\'ve succeeded.]', '', '去找風暴峭壁的『巫婆』洛莉拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12970, 'zhTW', '[The Hyldsmeet]', '[Whether you\'ve noticed or not, by defeating your first Hyldnir in hand-to-hand combat, you\'ve entered the Hyldsmeet -- the great competition of Hyldnir against Hyldnir to determine who will rule by Thorim\'s side.$B$BThe Hyldsmeet is the reason why I was imprisoned, for I sought to partake in the competition but was far too old and frail to be a match for the Hyldnir.$B$BIf you\'re willing to listen, I\'ve a proposal for you.]', '[Listen to Lok\'lira the Crone\'s proposal.]', '', '去找風暴峭壁的『巫婆』洛莉拉。', '聆聽洛克莉拉的提議', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12971, 'zhTW', '[Taking on All Challengers]', '[Let\'s get you started.  The good news is that by defeating Agnetta, you\'ve earned yourself a spot in the next round of matches.$B$BThe bad news is that all your opponents will also have defeated someone in the first round.  Do not expect pushovers.]', '[Lok\'lira the Crone in Brunnhildar Village wants you to defeat 6 Victorious Challengers.]', '', '去找風暴峭壁的『巫婆』洛莉拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12972, 'zhTW', '', '', '[Speak to Brijana outside Brunnhildar Village.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12973, 'zhTW', '[The Brothers Bronzebeard]', '[That does it! We finally have the keystone... It\'s beautiful! I\'ve been around the world more than once, but this thing\'s got me all jittery with excitement again. I suppose now\'s not the time to stop and admire though, we need to get the heck out of here.$B$BHop on my flying machine and help keep us covered from those iron dwarves on the way out!]', '[Accompany Brann Bronzebeard and his flying machine to Frosthold.]', '陪同布蘭·青銅鬍前往霜寒堡', '去找風暴峭壁的維洛格‧冰吼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12974, 'zhTW', '勇士的呼喚!', '呼，下面那根本不叫打鬥。只不過是幾個傢伙圍著旗子在跳舞罷了。$B$B你想要來點真正的打鬥嗎?因為我手上可是有最熱門的票。$B$B聽過葛爾薩克和烏丁嗎?在外域經營血之環競技場的那個哥布林與食人妖?他們現在來到了北裂境，而且他們在祖爾德拉克開了全新的鬥技俱樂部。如果你有興趣的話，就去水晶之歌東邊的祖爾德拉克吧。他們在中央的大競技場裡面。告訴他們是維克斯派你去的!', '到祖爾德拉克的苦痛露天競技場找葛爾薩克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12975, 'zhTW', '[In Memoriam]', '[Surely Thorim has told you of the tragedy that divides us.$B$BIt was in Thunderfall, northeast of here, that these events unfolded. The frozen fossils there are a reminder of that dark day, as are the spirits that haunt that place.$B$BIf my people are to forgive Thorim, something must take the place of those images. A memorial must be constructed to bring our hearts peace.$B$BGo there, $r. Collect the fragments of Hodir\'s Horn that was shattered that day.]', '[King Jokkum in Dun Niffelem wants you to collect 8 Horn Fragments from Thunderfall.]', '', '去找風暴峭壁的裘庫姆王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12976, 'zhTW', '[A Monument to the Fallen]', '[Bring these fragments to Njormeld. He will use the pieces of that sacred relic in the construction of a mighty monument.$B$BMay it soothe the pains and heal the scars my people have borne these many years.$B$BMay its presence help to bring about a new age that sees us once again in glorious battle at Thorim\'s side.$B$BGo now, $c. Njormeld awaits you.]', '[King Jokkum wants you to bring Hodir\'s Horn Fragments to Njormeld in Dun Niffelem.]', '', '去找風暴峭壁的尼約梅爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12977 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12977, 'zhTW', '[Hodir\'s Call]', '[You have done a great service to the giants of Dun Niffelem. Without your aid, this monument would not exist.$B$BAs you silently ponder its significance, feelings begin to flood your heart. The feelings fill your mind with thoughts and images... as well as a sense of urgency.$B$BThe sensations fade and leave you with a knowledge of what you must do. The restless spirits at Thunderfall must be put to rest.$B$BAs you set off, you find that your hands have been filled with an ethereal horn.]', '[You are to defeat 5 Niffelem Forefathers and 5 Restless Frostborn at Thunderfall. You are then to blow Hodir\'s Horn over their corpses, then return to Hodir\'s Horn in Dun Niffelem.]', '', '去找風暴峭壁的裘庫姆王。', '尼弗倫始祖已釋放', '不安的寒冰誕生者已釋放', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12978, 'zhTW', '[Facing the Storm]', '[Like Bouldercrag, I once served the keepers as a craftsman in Ulduar, but with Loken\'s betrayal, I turned my hammer toward our new foes.$B$BWhen we could spare the men, I led raids on Nidavelir to relieve the pressure on our defenders, but our lines are near collapse.$B$BYou\'ve proven yourself a capable combatant and a staunch ally. Perhaps you\'d be willing to take up our banner and take the fight to Nidavelir, the iron dwarf stronghold to the southwest, across the Snowdrift Plains.]', '[Bruor Ironbane at Bouldercrag\'s Refuge wants you to kill 10 Nidavelir Stormforged. You may kill Stormforged Champions, Stormforged Magi, or Stormforged War Golems.]', '', '去找風暴峭壁的布魯爾‧鐵禍。', '尼達維里的風暴鍛爐者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12979, 'zhTW', '黑暗護甲', '與其他魔像的防禦裝備比起來，這塊護甲片既厚又大。檢驗了魔像的屍體之後，你發現這個厚甲片，似乎是事後加工裝上的。$B$B為什麼鐵矮人要在他們的魔像上，加裝這種多餘又大小不合的護甲?$B$B也許布魯爾·鐵禍能夠檢驗一些從戰爭魔像上取下的護甲片，他就能夠得到答案。', '把4塊黑暗護甲樣本帶去給石崖避難所的布魯爾·鐵禍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12980, 'zhTW', '[The Armor\'s Secrets]', '[The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran\'s schemes.$B$BHe\'s dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal.$B$BTo the east, along the northern mountain face, is a building called Mimir\'s Workshop. It hasn\'t been used in quite some time, but if we\'re lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.]', '[Take the Dark Armor Plate to Mimir\'s Workshop and ask Attendant Tock to examine it. When you\'re finished, return to Bruor Ironbane at Bouldercrag\'s Refuge.]', '', '去找風暴峭壁的布魯爾‧鐵禍。', '已調查護甲板', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12981, 'zhTW', '[Hot and Cold]', '[As you stare at the anvil you relive your recent accomplishments, particularly those which brought this artifact to rest here.$B$BIt suddenly occurs to you that more remains to be done. To the east, smoldering scraps clutter the landscape--shrapnel from the battle fought there.$B$BIf they could be cooled and gathered somehow, the frost giants would have an abundant supply of metal and the region would be cleared of these remnants of war.]', '[You are to go to Frostfield Lake, kill the Brittle Revenants there and use the Essence of Ice on the Smoldering Scraps at Fjorn\'s Anvil. You are then to collect 6 of the Frozen Iron scraps and return to Fjorn\'s Anvil in Dun Niffelem.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12982, 'zhTW', '[Ebon Blade Prisoners]', '[Now that I\'m back, I\'m certain that the baron will want me to recover my men. I can see that we\'re barely hanging on here. The Lich King\'s forces are about to break through and we won\'t be able to hold without my captured death knights.$B$BCan you assist me once more, $N?$B$BGo back to Jotunheim and let them out of those cages. Break the damn locks, I don\'t care what you have to do. The vrykul likely have the keys.$B$BJust get my men free!]', '[Vaelen the Flayed at The Shadow Vault wants you to free 8 Ebon Blade Prisoners. They can be found in the cages throughout the greater Jotunheim region.]', '', '去找冰冠冰川的被搶劫的維倫。', '黑鴉之刃的囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12983, 'zhTW', '[The Last of Her Kind]', '[For as long as I can remember, we\'ve obtained our best bears from the Hibernal Cave to the east.$B$BThose times might finally be gone.  The cave has been overrun by ravenous jormungar and the wild bears are all but extinct.$B$BIf you were to find a surviving matriarch, however, I would guarantee you that she would fight better than any of these bears born in captivity.$B$BTake this harness to the Hibernal Cave and rescue a surviving matriarch.  Good luck finding one.]', '[Astrid Bjornrittar in Brunnhildar Village wants you to rescue an Icemaw Matriarch in the Hibernal Cavern.]', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '已救出冰顎女王', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12984, 'zhTW', '[Valduran the Stormborn]', '[We have no choice, $N. What you learned in Mimir\'s Workshop means that we must act before Valduran can complete and unleash his new weapon.$B$BEven now, the refuge\'s defenders fight to buy us time to deal with Valduran the Stormborn.$B$BYou must go to Nidavelir, across the Snowdrift Plains to the southwest, and then find and face Valduran. But you will not be alone. Bring this war horn with you and sound it as you prepare to face the leader of our enemies. Bruor and I will aid you in this battle.]', '[Use Bouldercrag\'s War Horn when you have found Valduran the Stormborn. Defeat Valduran the Stormborn and return to Bouldercrag the Rockshaper at Bouldercrag\'s Refuge.]', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12985, 'zhTW', '[Forging a Head]', '[Greetings, $r.$B$BI have a task that King Jokkum felt you would be suited for, assuming you still strive to gain favor with our people.$B$BI have developed plans for another artifact, one that will grant Hodir\'s blessing of protection to our stronghold. I have nearly all that I require for its construction. All that remains to collect are the very eyes of our fallen enemies.$B$BTake this tool, and gather the eyes from the iron giant corpses that litter our fields.]', '[Njormeld in Dun Niffelem needs you to use the Diamond Tipped Pick on the Dead Iron Giants at Frostfield Lake and return to him when you have collected 8 Stormforged Eyes.]', '', '去找風暴峭壁的尼約梅爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12986, 'zhTW', '[Fate of the Titans]', '[Norgannon\'s Core is not at this location. I am not sure why you seek it, $r, and I am equally unsure if you truly know the purpose of that which you seek.$B$BI would like you to aid me before I consider extending my assistance.  I have recently encountered knowledge of the watcher, Thorim. His seat of power is contested, and his fate remains to be seen. This troubles me, for I do not know of the other watchers. Utilize this databank to examine their temples to the northeast and return the knowledge to me.]', '[Creteus in the Foot Steppes has requested that you travel to the Temple of Invention, the Temple of Winter, the Temple of Life, and the Temple of Order and utilize the databank to examine each area.]', '', '去找風暴峭壁的克里圖思。', '已調查發明神殿', '已調查寒冬神殿', '已調查生命神殿', '已調查秩序神殿', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12987, 'zhTW', '[Placing Hodir\'s Helm]', '[The helm is forged.$B$BYour efforts have not gone unnoticed, small one. Though there remains much to do, we sons of Hodir are grateful for your accomplishments.$B$BIn return, I offer you the opportunity to present Hodir\'s helm to our king and our brethren.$B$BFly to the sparkling tip of the small ice spike in front of me and read to our people from this tablet.$B$BEnjoy the privilege, $c. Never before has an outsider been given such an honor!]', '[Njormeld wants you to fly to the tip of the northern ice spike in Dun Niffelem and use the Tablets of Pronouncement.]', '', '去找風暴峭壁的尼約梅爾德。', '霍迪爾之盔已安裝', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12988, 'zhTW', '[Destroy the Forges!]', '[In my folly, I\'d thought Valduran\'s project at Narvir\'s Cradle, a large construction area to the south, no more than a grotesque monument to "Keeper" Loken\'s cruelty.$B$BNow we know the truth, that it was meant to be used as a weapon against us and our allies. We must not allow this iron colossus to reach completion, $N, for it will mean the end of the refuge.$B$BGo to Narvir\'s Cradle, find the lightning forges the stormforged artisans use, and sabotage them.]', '[Destroy the North Lightning Forge, the Central Lightning Forge, and the South Lightning Forge with Bouldercrag\'s Bombs, then return to Bouldercrag the Rockshaper at Bouldercrag\'s Refuge.]', '', '去找風暴峭壁的『塑岩者』石崖。', '北方雷霆熔爐已破壞', '中央雷霆熔爐已破壞', '南方雷霆熔爐已破壞', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12989, 'zhTW', '[The Slithering Darkness]', '[The vile jormungar have taken over most of the Hibernal Cavern.  They are despicable beings... children of Loken, Thorim\'s scumsucker of a brother.$B$BAs Thorim\'s servants we owe it to ourselves to kill these scum where we find them.  You\'ll find the cavern just east of here, outside the village.]', '[Astrid Bjornrittar wants you to slay 8 Ravenous Jormungar in the Hibernal Cavern east of Brunnhildar Village.]', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12991, 'zhTW', '[Hit Them Where it Hurts]', '[Bouldercrag\'s got a good plan to stymie the efforts of the iron dwarves at Narvir\'s Cradle, and I\'ve got an idea of my own. Work on the iron colossus will come to a halt without any artisans.$B$BNarvir\'s Cradle is on the south side of the hill sheltering Bouldercrag\'s Refuge. Go there and slay any stormforged artificers in your path. They may be no different from what we once were, but they build a weapon that threatens us all.]', '[Kill 10 Stormforged Artificers and return to Bruor Ironbane at Bouldercrag\'s Refuge.]', '', '去找風暴峭壁的布魯爾‧鐵禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12992, 'zhTW', '[Crush Dem Vrykuls!]', '[Dem vrykuls at the Jotunheim needs to be crushed!$B$B$N crush dems good!]', '[Vile at The Shadow Vault wants you to slay any 15 vrykul in the greater Jotunheim region.]', '', '去找冰冠冰川的暗邪。', '尤頓海姆的維库人已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12993, 'zhTW', '[A Colossal Threat]', '[You\'ve done an excellent job of delaying the work on the iron colossus, but I fear we\'ve only made the stormforged more determined to complete the weapon.$B$BEven now, they\'re bringing in new laborers and the overseers push them to the limit. We may not be able to keep them from bringing the colossus online, after all. Return to Narvir\'s Cradle, to the south and find the documents detailing the colossus\' offensive and defensive abilities. They should be near the tents and forges on the bottom level.]', '[Retrieve the Colossus Attack Specs and Colossus Defense Specs and bring them to Bouldercrag the Rockshaper at Bouldercrag\'s Refuge.]', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12994, 'zhTW', '[Spy Hunter]', '[The rapport you\'ve developed with the inhabitants of Dun Niffelem has yielded some unexpected discoveries.$B$BFor example, you somehow find yourself able to understand the denmother\'s guttural growls and sharp quips--at least you think you do.$B$BIt would seem that she senses danger outside the stronghold and wants you to do something about it.$B$BWith her forepaw, she removes the chain from around her neck and lets it drop at your feet. As you pick it up you notice an aged fang attached to it...]', '[You must defeat 3 Stormforged Spies in the Valley of Ancient Winters.$B$BUsing the Ethereal Worg\'s Fang at the Corpse of the Fallen Worg will summon an Ethereal Frostworg, which will expose hidden enemies. You are to return to the Frostworg Denmother in Dun Niffelem when the valley has been cleansed of spies.]', '', '去找風暴峭壁的冰霜座狼獸母。', '風暴鍛造滲透者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12995, 'zhTW', '[Leave Our Mark]', '[We must attack the vrykul of Jotunheim on many levels. Brute force, of course, is good, but I prefer a more cerebral approach.$B$BI want you to demoralize them.$B$BMy men here have forged a number of banners for you. I would like for you to take and plant them near the corpses of fallen vrykul.$B$BLet the banners serve as a constant reminder to them that they face a more immediate threat than the wrath of the Lich King.]', '[Baron Sliver at The Shadow Vault wishes you to plant 15 Ebon Blade Banners near the corpses of vrykul found within the greater Jotunheim region.]', '', '去找冰冠冰川的史力弗男爵。', '已在維库人屍體旁插上黑鴉之刃旗幟', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12996, 'zhTW', '[The Warm-Up ]', '[You\'ve been very fortunate, sister.  This is a matriarch the likes of which hasn\'t been seen in years.$B$BA good bear won\'t do you much good without the skill to ride it.$B$BI\'m going to have you practice some moves on Kirgaraak.  He\'s the largest yeti we\'ve ever managed to capture so be careful.  Don\'t be afraid to walk away if he gives you a beating... there\'s a reason why we keep him chained.]', '[Astrid Bjornrittar in Brunnhildar Village wants you to use the Reins of the Warbear Matriarch to defeat Kirgaraak.]', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '已擊敗基爾加拉克', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12997, 'zhTW', '[Into the Pit]', '[Besting a tethered opponent is one thing.  Fighting other bear riders on equal footing is another.$B$BHead into the Pit of the Fang and use what you\'ve learned to defeat your opponents.  Good luck, sister.$B$BGlory awaits, should you succeed.]', '[Astrid Bjornrittar, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.]', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12998, 'zhTW', '[The Heart of the Storm]', '[According to the documents you captured at Narvir\'s Cradle, the iron colossus is complete except for one key component -- the Heart of the Storm.$B$BWithout it, the iron colossus\' weapons would be much weaker than the design predicts. If we can deny Overseer Narvir the heart, we could defeat the colossus!$B$BNotes on the documents you found say that the heart is in Uldis, a titan facility far to the south. Its entrance is on the south side of a tall mountain overlooking the Bor\'s Breath River.]', '[Bouldercrag the Rockshaper at Bouldercrag\'s Refuge wants you to travel to Uldis and try to prevent Overseer Narvir from obtaining the Heart of the Storm.]', '', '去找風暴峭壁的『塑岩者』石崖。', '嘗試取得風暴之心', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12999, 'zhTW', '', '', '[Speak with The Bone Witch within the cave at Njorndar Village.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13000, 'zhTW', '[Emergency Measures]', '[The cold in these mountains is brutal.  We have a day or two before we burn up all the wood from the wreckage.$B$BWe spotted worgs inside a cave directly east of here.  I need you to find the cave and obtain some furs.  It might not sound like much, but it might be the difference between freezing to death and living another day.$B$BWorgs don\'t hunt alone, so I\'m giving you a flare.  It should buy you some time if you find yourself outnumbered.]', '[Bloodguard Lorga wants you to go to the Gimorak\'s Den to the east and obtain 6 Worg Furs.]', '', '去找風暴峭壁的血衛士洛嘉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13001, 'zhTW', '打造霍迪爾之矛', '時候到了，小$c。群星早已預言了這天的到來。$B$B偉大的霍迪爾親自賜給我預示，向我顯現了製造一柄至高神器的秘密，那就是霍迪爾之矛。$B$B我們一定得聽令!如果我們未能收到這項賜禮，末日一定接踵而來。$B$B我召喚你來協助我進行這項神聖的任務。$B$B越過峽谷，進入凜冬洞窟，從冰坑中收集永霜裂片，然後從洞窟外的長毛象身上收集毛皮。', '丹尼弗蘭的博學者蘭德維爾要你從凜冬洞窟的深處收集3個永霜裂片，以及從遠古寒冬山谷的堅忍的長毛象身上取得3個堅忍的長毛象皮革。', '', '去找風暴峭壁的博學者蘭德維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13002, 'zhTW', '[Gem Perfection]', '[Welcome to de cold, mon.  Dis place may not be so good for keepin\' me bones warm, but I have learned how to cut me de perfect gem.  All I be needin\' is some gems to do me work on.$B$BBring me some gems and I be teachin\' you the skill of gem perfection.  Dis will allow you to sometimes cut a perfect gem with increased bonuses when cuttin\' an uncommon quality gem from Northrend.]', '[Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Geba\'li in Warsong Hold.]', '', '去找北風苔原的賈巴利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13003, 'zhTW', '[How To Slay Your Dragon]', '[Hodir\'s Spear is an icon of great prowess in battle.$B$BIts mere presence instills a deep hunger for glory in all who enter Dun Niffelem. In fact, simply being near it has compelled you to test your own abilities.$B$BScanning the horizon, your vision locks on a wild wyrm as it flies nearby.$B$BIt is decided. Of you and he, only one shall see the next sunrise....]', '[You are to use Hodir\'s Spear to challenge a Wild Wyrm in the Valley of Ancient Winters. Once in its grip, you are to fight to the death.]', '', '', '野生巨龍已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13004, 'zhTW', '[Gem Perfection]', '[There\'s a war going on and we each must do our part!  Mine is cutting gems and not only can I cut normal gems but I have the skill to cut perfect gems as well.   If you can bring me several uncut gems to contribute to the cause, I can teach you gem perfection as well.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.]', '[Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Alestros in Valiance Keep.]', '', '去找北風苔原的艾雷斯托思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13005, 'zhTW', '[The Earthen Oath]', '[For years I neglected my duties, giving into defeat and self-pity.$B$BNot the brave earthen, however.  Their oath to protect these grounds with their lives has gone unbroken.$B$BEven now, they fight the corruption of iron with selflessness, waiting for the moment in which the tides turn.$B$BThat moment has arrived.  We must rally what remains of the earthen defenders and lead them into a glorious victory.  Sound the Horn of the Peaks to call them to your side and take back the Terrace of the Makers.]', '[Thorim, at the Terrace of the Makers, wants you to use the Horn of the Peaks and call on the Earthen to defeat 20 Iron Dwarves and 7 Iron Sentinels.]', '', '去找風暴峭壁的索林姆。', '鐵哨兵已擊殺', '鐵矮人攻擊者已擊殺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13006 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13006, 'zhTW', '[A Viscous Cleaning]', '[As you draw near the helm, you notice that the frigid environment is already taking its toll on the artifact\'s surface. What is now just a thin layer of ice will surely grow to envelop it entirely.$B$BNot about to let your hard efforts go to waste, you resolve to scour the region in search of a solution.$B$BJust as you set off, the eyes of the helm flash and an image of the nearby Hibernal Cavern enters your mind.]', '[You are to enter Hibernal Cavern west of Dun Niffelem and collect 5 units of Viscous Oil from the Viscous Oils there.$B$BYou are then to return to Dun Niffelem and apply the oil to Hodir\'s Helm.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13007, 'zhTW', '[The Iron Colossus]', '[We have failed to prevent the completion of the iron colossus, $N, which means we have no choice but to face it in battle.$B$BBruor has devised a plan to exploit the colossus\' only weakness.$B$BNo matter how tough the colossus\' armor is, it is still vulnerable to a jormungar\'s acid. Take control of one using the orbs along the northern edge of the Snowdrift Plains, then use it to fight the Iron Colossus on the Snowdrift Plains. If you need help controlling the creature, speak to one of the nearby handlers.]', '[Use a Tamed Jormungar to defeat the Iron Colossus and return to Bouldercrag the Rockshaper at Bouldercrag\'s Refuge.]', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13008, 'zhTW', '[Scourge Tactics]', '[We had the element of surprise on our side! We blew a hole in the side of the mountain and charged into Scourgeholme. Scourge opposition was fierce and it wasn\'t long until we were overwhelmed. We fell back to the valley and began raining artillery down on the Scourge that followed. This held them back for awhile until... Those monsters began using crusaders as living shields. We had to stop shelling for fear of killing our own soldiers.$B$BFree our crusaders trapped on the field outside the base, $c!]', '[Crusade Commander Entari at the Argent Vanguard in Icecrown has asked that you free 8 Webbed Crusaders.]', '', '去找冰冠冰川的十字軍指揮官恩塔利。', '被蛛網纏繞的十字軍已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13009, 'zhTW', '[A New Beginning]', '[It remains uncertain whether or not our people can ever rekindle the affection we once held for Thorim.$B$BMay this armor, if nothing else, remind him of the days when we stood together in honor, invincible.]', '[Njormeld wants you to take the Reforged Armor to Thorim at the Temple of Storms.]', '', '去找風暴峭壁的索林姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13010 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13010, 'zhTW', '[Krolmir, Hammer of Storms]', '[One task remains before I can reclaim my home at the Terrace of the Makers.$B$BKrolmir must be found.$B$BOn that fateful day, I threw it to the earth with all the power and rage I possessed. A mighty explosion followed.$B$BI\'ve thought it lost for these many years, but now I must be certain.$B$BReturn to King Jokkum and discover what, if anything, he knows of my hammer\'s fate.]', '[Thorim wants you to talk to King Jokkum in Dun Niffelem and discover what he knows of Krolmir.]', '', '', '克羅米爾的命運已發現', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13011 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13011, 'zhTW', '[Culling Jorcuttar]', '[I have an opportunity that will help you to gain approval with my people, provided you prevail.$B$BThe jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire.$B$BThey have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region.$B$BShe cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.]', '[King Jokkum in Dun Niffelem wants you to slay Jorcuttar in Hibernal Cavern.]', '', '去找風暴峭壁的裘庫姆王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13012 AND `locale` = 'zhTW';
