INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13036, 'zhTW', '榮譽至上', '通往救贖之道漫長無盡啊，年輕的$c。我們打遍了各大陸，甚至穿越了世界，來到了此處。現在，我們要面臨最大的挑戰:毀滅巫妖王與他的天譴軍團。哎，我們卻是各自為政地在進行這場戰鬥。部落與聯盟彼此作戰，無法援助我們。我們一定得為了自己奮戰不懈!我們又有什麼別的選擇呢?你願意加入嗎?把你的力量借給我們，$c!我的指揮官，恩塔利，正在等待著你。', '向銀白先鋒駐地的十字軍指揮官恩塔利報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13037 AND `locale` = 'zhTW';
