INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13068, 'zhTW', '', '', '[Highlord Tirion Fordring at Crusaders\' Pinnacle has requested that you locate the hero, Crusader Bridenbrad at the Silent Vigil, in northeast Icecrown. His fire pit will likely be the most obvious indication of his location from the air.]', '', '', '', '', '', '', 0);
