INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13069, 'zhTW', '[Shoot \'Em Up]', '[Jotunheim has aerial defenses, both in terms of proto-drake riders and harpoon guns. They\'ve concentrated these on their northern and western facings where they are most vulnerable.$B$BLet\'s use their defenses against them!$B$B<The Leaper pierces you with his single eye and cackles maniacally.>$B$BTake control of a harpoon gun on the platforms that overhang the cliffs on either side of Valhalas to the southwest. Take out the proto-drakes and their riders. Shoot \'em up!]', '[The Leaper at The Shadow Vault wants you to use a Jotunheim Rapid-Fire Harpoon to shoot down 15 Jotunheim Proto-Drakes and their riders.]', '', '去找冰冠冰川的跳躍者。', '尤頓海姆始祖幼龍與其騎士已擊落', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13070 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13070, 'zhTW', '', '', '[Report to Siegemaster Fezzik at the Argent Vanguard in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13071 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13071, 'zhTW', '[Vile Like Fire!]', '[Vile like fire! Vile like proto-drakes!$B$B<The abomination claps its hands excitedly.>$B$BLittle $N go to Jotunheim and steal a pretty proto-drake in Njorndar Village. Make proto-drake make pretty fires on Jotunheim buildings!]', '[Vile at The Shadow Vault wants you to steal a Njorndar Proto-Drake and use it to set fire to 8 vrykul buildings in the greater Jotunheim region.$B$BBalargarde Fortress, due to its nature, cannot be set ablaze.]', '', '去找冰冠冰川的暗邪。', '維库人建築已點燃', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13072 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13072, 'zhTW', '', '', '[Bring news of Crusader Bridenbrad\'s fate to Highlord Tirion Fordring at Crusaders\' Pinnacle.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13073 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13073, 'zhTW', '', '', '[Highlord Tirion Fordring at Crusaders\' Pinnacle has requested that you secure passage from Arch Druid Lilliandra and speak to Keeper Remulos in Moonglade.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13074 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13074, 'zhTW', '[Hope Within the Emerald Nightmare]', '[What we need exists only in the emerald dream... acorns that are infused with a powerful restorative magic. Many places in this sacred glade are closely tied with the dream, and my shrine is among them.$B$BI will send you into the dream to recover some of these acorns. Be prepared though $c, for this method of entering the dream is dangerous, and it is very likely you will be beset by nightmares.$B$BRecover a few acorns quickly, and then depart from my shrine or pinch yourself to return to our world.]', '[Keeper Remulos at Moonglade has instructed you to enter the emerald dream and recover 3 Emerald Acorns.$B$BLeave the vicinity of the Shrine of Remulos to return to Azeroth.]', '', '去月光林地找月神湖的守護者雷姆洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13075 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13075, 'zhTW', '[The Boon of Remulos]', '[I shall open a portal to take you back to the druid that brought you here. You and your crusader have my well wishes. I hope that this acorn is able to purify your crusader and save him from the wretched fate of the plague.$B$BFarewell, $r.]', '[Return to Crusader Bridenbrad at the Silent Vigil in Icecrown with the Emerald Acorn.]', '', '去找冰冠冰川的十字軍布理登布萊特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13076 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13076, 'zhTW', '', '', '[Return to Highlord Tirion Fordring at Crusaders\' Pinnacle with news of Emerald Acorn\'s effects.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13077, 'zhTW', '', '', '[Request the aid of Alexstrasza the Life-Binder at Wyrmrest Temple.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13078, 'zhTW', '[Dahlia\'s Tears]', '[In this dark time, I\'ll not be the one to abandon a champion of the Light.$B$BWe will need something sacred for this to have a hope of saving your Bridenbrad... a remnant of a devout being that fell victim to this very same plague.$B$BGo now to the sacred soil of the passages outside my Ruby Dragonshrine where the battle is joined. As my Ruby Keepers fly down and set flame to the ground beneath undead feet, you will witness new life grow forth. Among that life are Dahlia\'s Tears - bring them to me.]', '[Alexstrasza the Life-Binder at Wyrmrest Temple has requested that you recover Dahlia\'s Tears from soil freshly cleansed by a Ruby Keeper\'s flames.]', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13079, 'zhTW', '[The Boon of Alexstrasza]', '[You must understand, young $r, that cleansing the body in favor of life anew is something well within my grasp... removing the plague of undeath without affecting the body, however, is beyond the scope of the powers that I control.$B$BIf this Bridenbrad is the beacon of light that you profess him to be, perhaps he will endure such a cleansing and thrive, but I cannot state with confidence that this is the salvation that you seek. Take it and go with all of my blessings.]', '[Bring the Breath of Alexstrasza to Crusader Bridenbrad at the Silent Vigil in Icecrown.]', '', '去找冰冠冰川的十字軍布理登布萊特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13080, 'zhTW', '', '', '[Return to Highlord Tirion Fordring at Crusaders\' Pinnacle with news of the effects of the Breath of Alexstrasza.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13081 AND `locale` = 'zhTW';
