INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13177, 'zhTW', '[No Mercy for the Merciless]', '[Welcome to the Wintergrasp Fortress, $n. Your mission is simple. Defeat ten of the Horde\'s finest. Now, go! Bring victory to the Alliance!]', '[Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde.]', '', '去找冬握堡壘的指揮官桑奈希。', '部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13178, 'zhTW', '[Slay them all!]', '[Welcome to the Wintergrasp Fortress, $n. Warlord Garrosh demands one thing: Slay them all!$B$BReturn to me when ten of the strongest members of the Alliance are dead.]', '[Commander Dardosh in Wintergrasp Fortress wants you to slay 10 members of the Alliance.]', '', '去找冬握堡壘的指揮官達多許。', '聯盟成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13179, 'zhTW', '[No Mercy for the Merciless]', '[Welcome to the Wintergrasp, $n. Your mission is simple. Defeat ten of the Horde\'s finest. Now, go! Bring victory to the Alliance!]', '[Commander Zanneth in Wintergrasp wants you to slay 10 members of the Horde.]', '', '去找冬握堡壘的指揮官桑奈希。', '部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13180, 'zhTW', '[Slay them all!]', '[Welcome to the Wintergrasp, $n. Warlord Garrosh demands one thing: Slay them all!$B$BReturn to me when ten of the strongest members of the Alliance are dead.]', '[Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance.]', '', '去找冬握堡壘的指揮官達多許。', '聯盟成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13182, 'zhTW', '別忘了那些蛋!', '遍佈於阿茲歐-奈幽，天譴奈幽蟲族總是小心翼翼地孵育將孵化的蛋，這是牠們數量迅速滋長的原因。$B$B若能清除掉不死生物玷汙過，用以鳩佔鵲巢的敗壞蟲蛋，對牠們的洞穴而言是件好事。$B$B當你探索那一度是阿茲歐-奈幽的廣袤地帶，一定要清理我們古老家園中，任何你看到的天譴蛋。', '那金之淵裡的『排除者』齊力克斯，要你進入阿茲歐-奈幽並摧毀6個奈幽天譴蛋。', '', '去找龍骨荒野的『排除者』齊力克斯。', '摧毀奈幽天譴蛋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13184, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13185, 'zhTW', '[Stop the Siege]', '[I hears dem! The Alliance come soon. Destroy three Alliance siege devices and come back to Murp.]', '[Lieutenant Murp in Wintergrasp Fortress wants you to destroy 3 Alliance siege machines.]', '', '去找冬握堡壘的莫普中尉。', '聯盟攻城裝置已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13186, 'zhTW', '[Stop the Siege]', '[It is only a matter of time before this castle is besieged by the forces of the Horde. Destroy three of their siege devices and return to me.]', '[Senior Demolitionist Legoso in Wintergrasp Fortress wants you to destroy 3 Horde siege machines.]', '', '去找冬握堡壘的資深爆破兵勒茍索。', '部落攻城裝置已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13187, 'zhTW', '[The Faceless Ones]', '[In my peoples\' struggle against the forces of the undead, they dug deeper as they lost ground. In desperation, they dug too deep.$B$BWe inadvertently exposed a tendril of the old god\'s will, which was made manifest in the creatures known only as the Faceless.$B$BIn the end, we could not fight on two fronts against such powerful enemies. Our misfortune cost us the war against the undead, and ultimately, our home.$B$BEnter Ahn\'kahet, $c, and cleanse our former home of these Faceless atrocities.]', '[Kilix the Unraveler in the Pit of Narjun wants you to kill Herald Volazj and the three Forgotten Ones that accompany him in Ahn\'Kahet.]', '', '去找龍骨荒野的『排除者』齊力克斯。', '被遺忘者已摧毀', '已擊敗傳令官沃拉茲', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13188, 'zhTW', '[Where Kings Walk]', '[You are now, and forever will be, a Knight of the Ebon Blade, $N, but know this: you were once a hero of the Alliance.$B$B<Darion stares at you.>$B$BThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance.$B$BOn the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Varian Wrynn. Use the portal.]', '[Deliver the letter to King Varian Wrynn of the Alliance at Stormwind Keep in Stormwind City.]', '', '去找艾爾文森林的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13189, 'zhTW', '[Warchief\'s Blessing]', '[You are now, and forever will be, a Knight of the Ebon Blade, $N, but know this: you were once a hero of the Horde.$B$B<Darion stares at you.>$B$BThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.$B$BOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to Thrall. Use the portal.]', '[Deliver the letter to Thrall, Warchief of the Horde at Orgrimmar.]', '', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13190, 'zhTW', '[All Things in Good Time]', '[Ahn\'kahet, from whence we came...$B$BOne day, I dream, we shall overcome the death and darkness that hold our ancient home in their grip. To that end, I have a plan to weaken the resolve of our enemies.$B$BTheir precious Watchers must burn!$B$BTake their corpses and place them upon the brazier deep within the city. The scent of their burnt remains will linger in the air, reminding our enemy of their weakness.$B$BBe mindful, $c! Their undead corpses are most fragile and will deteriorate rapidly.]', '[Kilix the Unraveler in the Pit of Narjun wants you to obtain an Ahn\'kahar Watcher\'s Corpse and place it upon the Ahn\'kahet Brazier in Ahn\'kahet.$B$BThis quest can only be completed on Heroic Difficulty.]', '', '去找龍骨荒野的『排除者』齊力克斯。', '安卡哈守望者的屍體已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13191, 'zhTW', '[Fueling the Demolishers]', '[Lok\'tar, $n! While the battle may be over, we must prepare for the Alliance\'s next assault! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. $B$BWe\'ve heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!]', '[Siegesmith Stronghoof at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Alliance players in the Cauldron of Flames.]', '', '去找冬握堡壘的攻城鐵匠猛蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13192, 'zhTW', '[Warding the Walls]', '[Hey \'mon. This place be givin\' me dah heebie jeebies, don\'t cha know?$B$BWay too many spirits haunting dis place. I want ta be placing hoodoo wards up, but I be needin\' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.$B$BThe Glacial Falls in east Wintergrasp be havin\' dem special properties to extract da soul. Slay the Alliance there, mebbe they be havin\' the stuff we need.$B$BBring back da armor of the slain. If there be no Alliance maybe da elementals got \'em, mon.]', '[Hoodoo Master Fu\'jin at Wintergrasp Fortress wants you to retrieve 10 Enchanted Alliance Breastplates at the Glacial Falls.]', '', '去找冬握堡壘的咒毒大師符金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13193, 'zhTW', '[Bones and Arrows]', '[Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. $n, I am in need of dragon bone for our arrowheads.$B$BTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.$B$BIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.]', '[Lieutenant Vieron Blazefeather at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players in the Forest of Shadows.]', '', '去找冬握堡壘的維耶隆‧炎羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13194, 'zhTW', '[Healing with Roses]', '[Between the battles, one might almost believe that there was hope for peace in this land. Sadly, that is not to be our fate.$B$BTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.$B$BSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.$B$BIf that fails, perhaps a lasher or two might have one.]', '[Primalist Mulfort wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.]', '', '去找冬握堡壘的原獵者穆法特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13195, 'zhTW', '[A Rare Herb]', '[My, it is quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.$B$BHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 Horde Herb Pouches. I will grind the herbs into a medicine to protect against the cold.$B$BThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!$B$BYou may also find one on a lasher in the area.]', '[Anchorite Tessa in Wintergrasp wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.]', '', '去找冬握堡壘的隱士泰莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13196, 'zhTW', '[Bones and Arrows]', '[Dragons are incredible! Well, their bones at least! I\'ve been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.$B$BHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.$B$BHead to the Forest of Shadows and bring back any bone splinters you can find!$B$BThe Horde have been seen collecting bone splinters in the area. Slay them!]', '[Bowyer Randolph in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.]', '', '去找冬握堡壘的弓箭商藍道夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13197, 'zhTW', '[Fueling the Demolishers]', '[$n! About time you showed up. While we may have lost the last battle, we should prepare for the next! Travel to the Cauldron of Flames in southeastern Wintergrasp and retrieve several eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. $B$BOh, and if you happen to see some of the Horde in the Cauldron, don\'t hesitate to slay them and take their embers. We must prevent them from holding the keep!]', '[Siegesmith Stouthandle in Wintergrasp wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.]', '', '去找冬握堡壘的攻城大師斯托哈德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13198, 'zhTW', '[Warding the Warriors]', '[$n, good to see you. We must prepare for our next assault on the fortress. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been collecting armor in the area.$B$BHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.$B$BIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.]', '[Sorceress Kaylana in Wintergrasp wants you to retrieve 10 sets of Imbued Horde Armor at the Glacial Falls.]', '', '去找冬握堡壘的巫女凱拉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13199, 'zhTW', '[Bones and Arrows]', '[Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. $n, I am in need of dragon bone for our arrowheads.$B$BTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.$B$BIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.]', '[Lieutenant Vieron Blazefeather in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players at the Forest of Shadows.]', '', '去找冬握堡壘的維耶隆‧炎羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13200, 'zhTW', '[Fueling the Demolishers]', '[Lok\'tar, $n! While the battle may have subsided, we must prepare to retake the fortress! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. $B$BWe\'ve heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!]', '[Siegesmith Stronghoof in Wintergrasp wants you to retrieve 10 Eternal Embers from Alliance players at the Cauldron of Flames.]', '', '去找冬握堡壘的攻城鐵匠猛蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13201, 'zhTW', '[Healing with Roses]', '[So many of our braves were lost during the battle, but even more shall die if left untreated. $B$BTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.$B$BSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.$B$BIf that fails, perhaps a lasher or two might be in bloom.]', '[Primalist Mulfort in Wintergrasp wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.]', '', '去找冬握堡壘的原獵者穆法特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13202, 'zhTW', '[Jinxing the Walls]', '[Hey \'mon. See dem Alliance sitting comfy in their keep?$B$BI think they be a bit too comfy, ya? I want ta be jinxing the place, but I be needin\' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.$B$BThe Glacial Falls in east Wintergrasp be havin\' dem special properties to extract da soul. Slay the Alliance there, they be havin\' the stuff we need.$B$BBring back da armor of the slain. If there be no Alliance maybe da elementals got \'em, mon.]', '[Hoodoo Master Fu\'jin in Wintergrasp wants you to retrieve 10 Enchanted Alliance Breastplates from Alliance players at the Glacial Falls.]', '', '去找冬握堡壘的咒毒大師符金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13203, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13204, 'zhTW', '惡臭磨菇', '一朵畸形的磨菇-似乎是剛從蠻穴野獸惡臭又滿佈分泌物的屍塊上掉下來的磨菇。檢視它時，你被中人欲嘔的惡臭薰得差點昏過去。$B$B你想知道，是否這是奈幽蟲族的盤中美味。將這黏涕涕的噁心玩意放進你的背包，你決定要找出真相……', '你必須在安卡罕特的蠻穴野獸身上，採集6朵怪誕菌菇，並送去給那金之淵裡的『排除者』齊力克斯。', '', '去找龍骨荒野的『排除者』齊力克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13205, 'zhTW', '[Disarmament]', '[Take it from me, $g小夥子：小姑娘;, them vrykul weapons be downright nasty!$B$BI\'ve felt their edge personally, and there be somethin\' unnatural about \'em. Deceptively well-balanced, wickedly sharp - just plain deadly.$B$BGet into their stronghold and if nuthin\' else, pilfer some o\' them weapons! Mebbe we can learn us a thing \'er two about \'em, mebbe not.$B$BBottom line - the fewer axes they be swingin\' around, the better.]', '[Defender Mordun wants you to enter Utgarde Keep and steal 5 Vrykul Weapons]', '', '去找嚎風峽灣的防衛者摩丹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13206, 'zhTW', '[Disarmament]', '[We must discover the secret to these savages\' weapons!$B$BIf you\'d have seen how easily they cut through my companions, you\'d understand my sense of urgency. Just have a look at their forge if you doubt my words.$B$BScour the place. Gather all of their arms that you can carry and bring them to Anselm for his inspection.$B$BDo not fail us, $c. Every weapon you are able to bring out of this place is one less that we must face in the field.]', '[Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to High Executor Anselm in Vengeance Landing.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13207, 'zhTW', '[Halls of Stone]', '[Well now, I\'m surprised to see other adventurers in a place such as this! It so happens that I could use a bit o\' company for what lies ahead.$B$BIf my research on these halls is accurate, there be monumental discoveries to be made here!$B$BAssumin\' I can count on ya to watch my back, you\'re welcome to tag along. So, what\'dya say, $c? Care ta join me?]', '[Brann Bronzebeard wants you to accompany him as he uncovers the secrets that lie in the Halls of Stone.]', '', '去找岩石大廳的布萊恩·銅鬚。', '布蘭恩的探索已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13211, 'zhTW', '[By Fire Be Purged]', '[The Scourge uses our own fallen against us, by raising them as ghouls or skeletons, or by dismembering their corpses and using the parts to make abominations. This must stop!$B$BThe dead are heroes who fell in defense of all the living, and they cannot be confined to so grisly a fate. Moreover, we cannot afford to face them again on the field, used as weapons against us. Take this torch with you to the Fleshwerks, and burn any of the corpses you find in the Sanctum of Reanimation or the abomination lab.]', '[Crusader Olakin Sainrith at Blackwatch wants you to burn 7 Festering Corpses using Olakin\'s Torch.]', '', '去找冰冠冰川的十字軍歐拉金·山瑞斯。', '腐爛屍體已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13212, 'zhTW', '[He\'s Gone to Pieces]', '[With the abduction of Crusader Olakin, the Argent Crusade\'s forces will have no commander in the final assault on the Fleshwerks. While one crusader is the same as any other to me, the argents won\'t see it that way.$B$BI hate to see us waste time chasing after this, but I have no choice. Our gallant crusader has likely been dismembered by now, and his remains used to construct abominations. Go down into the Fleshwerks, kill the corpulent horrors fighting our forces, and recover Olakin\'s body parts.]', '[Recover Olakin\'s Torso, Olakin\'s Legs, Olakin\'s Left Arm, and Olakin\'s Right Arm and bring them to Darkrider Arly at Blackwatch.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13213, 'zhTW', '', '', '[Speak with Geirrvif in Valhalas.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13214, 'zhTW', '[Battle at Valhalas: Fallen Heroes]', '[If you believe yourself ready to begin then I have just the match for you to cut your teeth on.$B$BAnother group of outsiders thought themselves prepared for the rigors of Valhalas. They had much hubris, but in the end they fell like all of the others.$B$BIf you think yourselves so different -- if you think that you have the skill and experience to fight here amongst such storied warriors -- then please accept the challenge.]', '[Geirrvif at Valhalas has challenged you to, in a single combat, defeat all six of the fallen heroes: Eldreth, Geness Half-Soul, Jhadras, Masud, Rith, and Talla.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗陣亡英雄', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13215, 'zhTW', '[Battle at Valhalas: Khit\'rix the Dark Master]', '[A variety of beings travel the world to prove themselves within Valhalas. Some even come from under the world.$B$BKhit\'rix the Dark Master is one such.$B$BHailing from deep within the ground where insanity reigns, Khit\'rix has asked for someone exotic to face in the ring. You will do.$B$BDare you face this Nerubian nightmare, $r?]', '[Geirrvif at Valhalas has challenged you to defeat Khit\'rix the Dark Master.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗黑暗宗師基特里克斯', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13216, 'zhTW', '[Battle at Valhalas: The Return of Sigrid Iceborn]', '[An old foe of yours has returned: Sigrid Iceborn. Perhaps you remember besting her in a duel upon the Savage Ledge?$B$BNo matter, she certainly remembers you. She\'s insisting upon a chance to prove herself once more.$B$BPersonally, I think it\'s more a chance for revenge, but that too can be useful in this place.$B$BI leave it up to you, $N. Will you face Sigrid Iceborn once more?]', '[Geirrvif at Valhalas has challenged you to defeat Sigrid Iceborn.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗希格麗德·冰生者', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13217, 'zhTW', '[Battle at Valhalas: Carnage!]', '[You\'ve been successful up to this point, $N, but what you must face to continue to battle within Valhalas is a gigantic horror beyond imagining.$B$BI must warn you to turn away now. Carnage is a mountain of flesh constructed by the Lich King\'s most fiendish minds.$B$BI do not see how you and your friends will defeat it. However, the choice is yours.]', '[Geirrvif at Valhalas has challenged you to defeat Carnage.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗卡奈奇', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13218, 'zhTW', '[Battle at Valhalas: Thane Deathblow]', '[Your skills have not gone unnoticed by the vrykul of Jotunheim, $N. Thane Banahogg has taken a personal interest in you and has insisted that he be your next match.$B$BIf you thought Carnage was bad, then you might want to go home now. Thane Banahogg\'s nickname is The Deathblow. I think you can guess how he earned it.$B$BDo you accept the thane\'s challenge?]', '[Geirrvif at Valhalas has challenged you to defeat Thane Banahogg, the Deathblow.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗酋長巴納霍格', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13219, 'zhTW', '[Battle at Valhalas: Final Challenge]', '[I\'m afraid that your success is going to be your undoing, $N.$B$B<If the val\'kyr could turn more white, she would.>$B$BWord of your success in Valhalas has reached deep into Icecrown Citadel, stirring one whom you have no desire to meet.$B$BPrince Sandoval himself is on his way at this very moment. Gjonner warned you that you should run and I cannot disagree.$B$BWhat will you do? He\'s on his way. Will you face the blood prince in final battle?]', '[Geirrvif at Valhalas has challenged you to defeat Prince Sandoval.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗桑多瓦爾王子', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13220, 'zhTW', '[Putting Olakin Back Together Again]', '[We can\'t afford to waste any time putting Olakin back together. Fortunately, the Scourge has provided a perfect place for you to stitch him back together.$B$BNear the Fleshwerks\' flesh giant lab is the Sanctum of Reanimation. Search the area for a spool of thread and the doctor\'s cleaver. Then, take Olakin\'s remains to the large slab in the middle of the sanctum and get to work.]', '[Obtain a Spool of Thread and the Doctor\'s Cleaver, then take them to the Sanctum of Reanimation Slab and use Olakin\'s remains to attempt to reanimate the crusader. Return to Darkrider Arly at Blackwatch when this task is complete.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '已復活十字軍奧拉金·聖萊斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13221, 'zhTW', '[I\'m Not Dead Yet!]', '[The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their \'work\' here if I cannot escape.$B$BI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.$B$BWill you help me make my escape before the Scourge\'s butchers come to finish me off?]', '[Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.]', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13222, 'zhTW', '[Defend the Siege]', '[Front and center, $n! We\'re beginning our assault on Wintergrasp Fortress. Those Horde animals think they can hide cowardly behind their walls? Well, I think not! We\'ll show them the power of Gnomish technology and smash their walls to bits!$B$BHowever, even the most powerful siege device is helpless without a crew. Pilot or protect one of our siege vehicles as it destroys three of the Horde structures.]', '[Senior Demolitionist Legoso in Wintergrasp wants you to pilot or protect a siege device as it destroys three structures.$B$BPlayers of private rank or higher can build siege devices at Goblin Workshops.]', '', '去找冬握堡壘的資深爆破兵勒茍索。', '已防禦攻城載具', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13223, 'zhTW', '[Defend the Siege]', '[Dem Alliance won\'t be long to hold that keep. Murp would smash walls, but Murp has to stay in camp. Murp wish he could smash Alliance who want to hurt Horde demolishers.$B$BYou, $n! You go in Murp\'s place. Protect 3 siege vehicles while they smash Alliance buildings. Alliance not expect you to defend demolisher. Show Alliance how smart Murp is! ]', '[Lieutenant Murp in Wintergrasp wants you to defend or pilot a siege vehicle while they destroy three Alliance structures.$B$BSiege devices can be built by ranked Horde players at the Goblin Workshops.]', '', '去找冬握堡壘的莫普中尉。', '已防禦部落攻城載具', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13224, 'zhTW', '', '', '[Seek out Sky-Reaver Korm Blackscar aboard Orgrim\'s Hammer flying above Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13225, 'zhTW', '', '', '[Seek out High Captain Justin Bartlett aboard the Skybreaker flying above Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13226, 'zhTW', '審判日將臨!', '我們無法獨力擊敗巫妖王。分裂的我們唯有敗亡一途!我懇求你回應我們的呼喚，<兄弟/姐妹>。銀白十字軍接受所有願意為戰爭奉獻心力的志士。大領主提里奧·弗丁在銀白先鋒駐地親自等著你!坐上你的坐騎，飛往寒冰皇冠的東南邊境。你可以在那裡找到大領主弗丁以及銀白十字軍的士兵。去吧，$c，為了審判日將臨!', '在寒冰皇冠的銀白先鋒駐地，向大領主提里奧·弗丁報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13227, 'zhTW', '', '', '[Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13228, 'zhTW', '[The Broken Front]', '[What battle?! Those troops were on a recon mission!$B$BAnd what\'s this talk of Alliance - you\'re sure he said Alliance?$B$BListen to me, $n! I need to know what\'s going on and I need to know NOW!$B$BGet yourself down there and get me some answers! Scour the battlefield and look for survivors - clues - anything!]', '[Korm Blackscar on Orgrim\'s Hammer wants you to go to The Broken Front and question a Dying Berserker to discover what happened there.]', '', '去冰冠冰川找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '已審問垂死的狂戰士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13229, 'zhTW', '[I\'m Not Dead Yet!]', '[The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their \'work\' here if I cannot escape.$B$BI cannot make it on my own, $c, but with your help, I may yet live to fight the Scourge again.$B$BWill you help me make my escape before the Scourge\'s butchers come to finish me off?]', '[Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim\'s Hammer.]', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13230, 'zhTW', '[Avenge Me!]', '[I hear them, $g兄弟：姊妹;....$B$BThe moans of the wounded Alliance... they taunt me...$B$BFinish what we have begun here, $c. Show no mercy... let none of them survive.$B$BFor... the Horde...]', '[A Dying Berserker has asked that you slay 5 Dying Soldiers at the Broken Front. Report to Sky-Reaver Korm Blackscar on Orgrim\'s Hammer when it is done.]', '', '去冰冠冰川找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '垂死的聯盟士兵已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13231, 'zhTW', '破碎前線', '什麼?!不…!我們承受了多少的痛苦，只為了維持這回攻擊的低調。部落怎麼可能知道的?裝備…人力…全軍覆沒了嗎?不可能的!$B$B我們在寒冰皇冠的戰略，其關鍵在於比部落先奪下那道門。我們必須盡快重新整備，然後發動另一波攻勢。$B$B查看戰場，搜尋所有的生還者。檢討從這場悲劇中得到什麼教訓。$B$B還有，為了將臨的戰鬥，你得打點妥當，$n，我們必須兩面作戰…', '破天者號上的提督賈斯汀·巴特勒要求你，去破碎前線訊問一個垂死的士兵，並回報給他。', '', '去找冰冠冰川的提督賈斯汀·巴特勒。', '訊問垂死的士兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13232, 'zhTW', '[Finish Me!]', '[They taunt us - even as they lie dying here...$B$BPlease, $g兄弟：小姐;... Don\'t allow their mocking to be the last sounds I hear...$B$BFinish me... deliver me from this torment... into... the Light.$B$BSeek out  my companions... offer them the same mercy.$B$BLeave nothing for the Scourge to raise!$B$BI beg you...]', '[A Dying Soldier in the Broken Front wants you to kill 5 Dying Soldiers and report to High Captain Justin Bartlett on the Skybreaker.]', '', '去找冰冠冰川的提督賈斯汀·巴特勒。', '垂死的士兵已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13233, 'zhTW', '[No Mercy!]', '[It is as I told you. They were not merely idle words spoken in a fit of anger.$B$BTime and again, the Horde have demonstrated their disdain for everything we hold dear and holy. They must pay with their lives for their transgressions against the light.$B$BAll of them.$B$BJust imagine a world free of their stain, $n. Envision the joy our children will know. Think of the reverence your descendants will have for your memory, knowing they owe their happiness to you.$B$BNow go, and make that vision a reality!]', '[High Captain Justin Bartlett aboard the Skybreaker wants you to kill 15 Horde Players in Icecrown.]', '', '去找冰冠冰川的提督賈斯汀·巴特勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13234, 'zhTW', '[Make Them Pay!]', '[The time has come!$B$BToo long have we suffered the company of the self-righteous Alliance! Too long have we stayed our hand from cleansing our world of the weak and the desperate.$B$BNow, we bring an end to our humiliation! Now, we show them the true meaning of fear! Now, we bring honor to the Horde!$B$BHere, at Icecrown, we break the Alliance!$B$BGo, $c. Hunt them down. Break them. Take their will to live!]', '[Sky-Reaver Korm Blackscar wants you to kill 15 Alliance Players in Icecrown.]', '', '去冰冠冰川找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13235, 'zhTW', '[The Flesh Giant Champion]', '[You\'ve done well in destroying the Fleshwerks and slaughtering the Lich King\'s servants. Now, all that remains is to defeat the Fleshwerks\' greatest accomplishment -- the flesh giant known as Morbidus.$B$BIt will not be an easy fight, but the Shadow Vault has dispatched Margrave Dhakar with some reinforcements. Meet up with him at the highest point at the western end of the Fleshwerks. Tell him when you\'re ready to begin the attack and he\'ll order his forces into battle.]', '[Speak with Margrave Dhakar at the western end of the Fleshworks to engage Morbidus. After you have defeated Morbidus, report to Darkrider Arly at Blackwatch.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13236, 'zhTW', '[Army of the Damned]', '[You probably think you\'re quite strong -- fighting these undead and crushing their bones beneath your war machines.$B$BThat is nothing compared to the strength it took to create them.$B$BI saw the prince do it himself.  I can show you how it happened... if you\'d like.]', '[Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '已喚起食屍鬼爪牙', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13237, 'zhTW', '[Poke and Prod]', '[While your commander has his focus diluted by his loathing of your Alliance rivals, you can depend on me to direct my attention squarely on the real enemy here - the Lich King and his minions.$B$BIn order to hold any hope of conquering him at the citadel, your people must take and hold each gate.$B$BFor now, let us focus on the first. Return to the front and prod their defenses. Look for any sign of weakness that we might exploit.$B$BI\'ll await your report, $c.]', '[Koltira Deathweaver aboard Orgrim\'s Hammer wants you to go the Broken Front and defeat 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '巨大憎惡已擊殺', '邪惡死靈法師已擊殺', '暗影行者已擊殺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13238, 'zhTW', '', '', '[Sky-Reaver Korm Blackscar wants you to speak with Chief Engineer Copperclaw aboard Orgrim\'s Hammer.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13239, 'zhTW', '[Volatility]', '[Where to begin... well, you must know that as chief engineer of this vessel I have access to all of the intelligence reports - yes, yes, it\'s true, and I\'ve recently taken a particular interest in the frostwyrms you reported seeing to the south, and I do believe I\'ve developed a plan that just might work against them... now it\'ll take a little legwork on your part, but essentially, you build a dummy out of armor and coat it with a splash of this solution, then run for cover!$B$B...You still here, $r?]', '[Chief Engineer Copperclaw wants you to use Copperclaw\'s Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.$B$BTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.]', '', '去冰冠冰川找奧格瑞姆之錘的首席工程師銅爪。', '已進行實地測試', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13240, 'zhTW', '[Timear Foresees Centrifuge Constructs in your Future!]', '[It is into the Oculus floating above Coldarra that you must travel, $N.$B$BI have foreseen a situation in which you must destroy the centrifuge constructs therein. I can assure you that if you do not first eliminate these magical creations, you and your friends will fail.$B$BThus I have seen, thus you must do.]', '此任務已經絕版。[Archmage Timear in Dalaran has foreseen that you must destroy 10 Centrifuge Constructs.]', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13241, 'zhTW', '泰彌亞在你的未來預見了依米亞狂戰士!', '依米倫王的戰士就擋在汝與指日可待的勝利之間。$B$B汝將前往凜風峽灣深處，名為俄特加德之巔的要塞。余無法更加強調，汝輩能了結依米亞狂戰士，是如何地重要。$B$B若未能達成，將致汝輩之毀滅。$N!', '此任務已經絕版。達拉然的大法師泰彌亞要求你，殺掉7個依米亞狂戰士。', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13242, 'zhTW', '[Darkness Stirs]', '[Darkness stirs, $N. A tragic event has transpired that none but the Timeless One could have foreseen. Soon your people will be gripped by anger and hatred. War is on the horizon.$B$BThe red dragonflight has done all that it can. What happens next is in the hands of the mortal races of Azeroth.$B$BRegrettably, your journey begins with anguish. A father has lost a child today. You must bear the grim news. Gather the armaments of Saurfang and return them to the elder Saurfang. $B$B]', '[Gather Saurfang\'s Battle Armor from the field of battle and return it to High Overlord Saurfang at Warsong Hold in Borean Tundra.]', '', '去找北風苔原的薩魯法爾霸王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13243, 'zhTW', '[Timear Foresees Infinite Agents in your Future!]', '[The timeline is in danger from the Infinite dragonflight. Without your intervention, all of time will unravel!$B$BYou must travel to a point in time known as the Culling of Stratholme within the Caverns of Time.$B$BIt gives me a migraine just to attempt to see into all of the possible pasts, but I do know that it is crucial for you to kill the Infinite agents.$B$BOnly by slaying them will the true past be preserved and the present and future kept from being undone forever!]', '此任務已經絕版。[Archmage Timear in Dalaran has foreseen that you must slay 4 Infinite Agents.]', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13244, 'zhTW', '[Timear Foresees Titanium Vanguards in your Future!]', '[The entirety of Azeroth is in peril. The mad god Loken has it within his power to put an end to everything!$B$BWithin the Terrestrial Watchtower at the Halls of Lightning, the titanium vanguards stand poised to execute Loken\'s dread will upon countless unknowing victims.$B$BI have looked into the future, $N. You are the one to see that this does not come to pass!]', '此任務已經絕版。[Archmage Timear in Dalaran has foreseen that you must slay 7 Titanium Vanguards.]', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13245, 'zhTW', '[Proof of Demise: Ingvar the Plunderer]', '[I need you to assemble a group and lead them into Utgarde Keep. Therein, you are to find and slay Ingvar the Plunderer before he can lead his vrykul forces to sack the nearby Alliance and Horde towns.$B$BI require his axe as proof that he has been dealt with. It\'s not that I don\'t trust you. It\'s simply prudent to be certain that the deed has been done.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Axe of the Plunderer.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13246, 'zhTW', '[Proof of Demise: Keristrasza]', '[Are you familiar with the story of Keristrasza?$B$BHow she was instrumental in the slaying of Saragosa, the mate of Malygos? How, in turn, he took Keristrasza as his consort, freezing her within a block of ice?$B$BWe have become aware that Malygos has been using his magic to break her will. This has driven her insane.$B$B$N, you must go into the Nexus in Coldarra and put an end to her before she can be fully turned.$B$BThough it saddens me, I must insist that you bring me her heart as proof.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with Keristrasza\'s Broken Heart.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13247, 'zhTW', '[Proof of Demise: Ley-Guardian Eregos]', '[The Nexus War rages on and we must do something to turn the tide! Are you willing to fly into the heart of the battle, $N?$B$BLey-Guardian Eregos is the protector of the conduit through which Malygos is funneling the magical power of Azeroth\'s ley lines. If he can be slain it will be a great blow to the enemy.$B$BPlease bring me one of his ley line tuners so that we might study it.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with a Ley Line Tuner.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13248, 'zhTW', '[Proof of Demise: King Ymiron]', '[King Ymiron of Utgarde Pinnacle is the favored vrykul of the Lich King. That alone is reason enough to put an end to him.$B$BBut should he blow the horns and call for all of the leaders of the ymirjar and mjordin alike, the vrykul will become a force more powerful than any other within the Scourge!$B$BIt is up to you, $N, to see to it that this does not come to pass. Bring me the locket from around his neck so that I will know that Ymiron no longer poses a threat.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Locket of the Deceased Queen.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13249, 'zhTW', '死亡證明:預言者薩隆杰', '德拉克薩隆要塞曾經是德拉克瑞王國的驕傲。如今卻淪為巫妖王的墊腳石，來毀滅祖爾德拉克，以便偷取食人妖眾神之力的力量。$B$B但假使我們能夠擊敗他們的領袖，預言者薩隆杰，或許便能遏止源源不竭的天譴食人妖妖援軍。至少，這能讓祖爾德拉克的銀白十字軍少點負擔。$B$B擊敗預言者後將他的附魔提基像帶回來給我。', '此任務已經絕版。達拉然的大法師朗達拉克要求你，帶回一個預言者的附魔提基像。$B$B這個任務只能在英雄難度下完成。', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13250, 'zhTW', '[Proof of Demise: Gal\'darah]', '[The Drakkari prophets of Zul\'Drak have done the unthinkable: they\'ve slain most of their gods to absorb their powers! The most dangerous of all is the High Prophet of Akali, Gal\'darah.$B$BSequestered within the bowels of Gundrak, Gal\'darah has absorbed almost all of the mojo from slain Akali and now stands poised to erupt with his followers from the city. If we do not kill him now, we will be awash in a sea of madness and unthinkable power!$B$BHurry, $N, bring me what\'s left of Akali\'s mojo.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Mojo Remnant of Akali.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13251, 'zhTW', '[Proof of Demise: Mal\'Ganis]', '[$N, a friend within the bronze dragonflight has given me information that we must exploit.$B$BThe mysterious beings of the Burning Legion called the dreadlords are also known racially as the Nathrezim. Little is known of their homeworld and even that is rumor.$B$BHowever, it is known that Mal\'Ganis of the past has made a critical error: he left behind an artifact from his homeworld!$B$BThrough the Caverns of Time, you must travel back to the time known as the Culling of Stratholme. Recover the artifact.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Artifact from the Nathrezim Homeworld.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13252, 'zhTW', '[Proof of Demise: Sjonnir The Ironshaper]', '[Little is understood about the condition known as the Curse of Flesh. However, there is information to be had within the Halls of Stone.$B$BSjonnir The Ironshaper seems to know a great deal with regard to the curse. We have it on good authority that he is carrying a Titan disc of information upon him that could answer all of our questions.$B$BRetrieve this disc for me, $N, so that we may learn.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Curse of Flesh Disc.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13253, 'zhTW', '[Proof of Demise: Loken]', '[Within the Halls of Lightning, Loken is poised to put an end to our world. Need I say more, $N?$B$BHe sits there listening to the mad whisperings of the Old God trapped beneath Northrend. You and your friends must travel to the Storm Peaks immediately!$B$BConfront Loken within the Terrestrial Watchtower and stop him before it is too late! Bring me his ruby ring so that I will know we are safe once more.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Celestial Ruby Ring.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13254, 'zhTW', '[Proof of Demise: Anub\'arak]', '[The Scourged nerubians are a plague upon our forces.$B$BWhile we are safe from them here, floating above the world, when we set foot upon the land below, it is always with the thought that the undead nerubians could burrow up from the depths of Azjol-Nerub and attack.$B$BIt\'s in the best interests of everyone if they are thrown into a state of disarray. Kill their former king, and major-domo to the Lich King, the crypt lord, Anub\'arak.$B$BPlease bring me his crown... not that he wears it any longer.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Idle Crown of Anub\'arak.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13255, 'zhTW', '[Proof of Demise: Herald Volazj]', '[The nerubians of Ahn\'kahet dug too deep during their attempt to escape the invasion of the Scourge. They got too close to the Old God under Northrend.$B$BRousing its awareness, the Old God sent its insane creatures against them, and the nerubians were caught between the proverbial rock and a hard place.$B$BThe leader of the Old Gods\' forces, Herald Volazj is one of the nightmarish beings known as The Faceless. Put an end to him and bring me his withered brain.$B$BJust please, try to keep your sanity.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Faceless One\'s Withered Brain.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13256, 'zhTW', '[Proof of Demise: Cyanigosa]', '[We\'re being invaded! The blue dragonflight has teleported into the Violet Hold and they\'re planning on breaking out from there into the rest of Dalaran!$B$BThere have already been reports of prisoners inadvertently being freed by their actions. It wouldn\'t surprise me if they\'re purposefully letting some of them free.$B$B$N, can you assemble your team quickly and get in there? Cyanigosa is the leader of their invasion force. Bring me her head!]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Head of Cyanigosa.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13258, 'zhTW', '', '', '[Speak to Sergeant Kregga below Icecrown Citadel.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13260, 'zhTW', '', '', '[Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim\'s Hammer.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13261, 'zhTW', '[Volatility]', '[Wahooo! It works! Not that I had any doubts in my supernatural ingenuity, only that I wasn\'t quite sure what kind of explosion to expect - let\'s just say I\'m glad to see that you didn\'t get your eyebrows singed off. So now I just need to show ol\' Korm how ya thaw out one \'a them wyrms. He\'ll hafta promote me to... to... to whatever comes after Chief Engineer! Here, you take another batch of the stuff and head back out to the front and I\'ll go get Korm...$B$BWell? Move out!]', '[Chief Engineer Copperclaw wants you to use Copperclaw\'s Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.$B$BTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.]', '', '去冰冠冰川找奧格瑞姆之錘的首席工程師銅爪。', '已進行實地測試', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13262, 'zhTW', '', '', '[Go to the nearby Saronite Bomb Stack to light the fuse.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13263, 'zhTW', '', '', '[Look for clues wherever the fall takes you.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13264, 'zhTW', '[That\'s Abominable!]', '[Abominations...$B$BThey can be a very capable enemy. I\'ve seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.$B$BThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.$B$BFortunately for you, I know these secrets.$B$BThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.]', '[Koltira Deathweaver on Orgrim\'s Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '冰霜食屍鬼已引爆', '凶殘幽魂已引爆', '復生的聯盟士兵已引爆', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13265, 'zhTW', '[Cloth Scavenging]', '', '', '', '', '', '', '', '', 0);
