INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13403, 'zhTW', '[Tirion\'s Gambit]', '[Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.$B$BAnd now I learn that it might be Arthas\'s own heart... a thing containing the last bit of his remaining humanity.$B$BThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!$B$BMeet me at the cathedral\'s entrance.  Be sure to bring a cultist\'s hood -- we\'re going incognito.]', '[Tirion Fordring, at the Crusader\'s Pinnacle, wants you to obtain and wear a Cultist Acolyte\'s Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.]', '', '去找冰冠冰川的大領主提里奧‧弗丁。', '', '提里奧的謀略', '', '', 0);
