INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13404, 'zhTW', '[Static Shock Troops: the Bombardment]', '[This is a short-ranged mission, over The Bombardment.  A good warm up.  Ready?]', '[Kibli Killohertz wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.]', '', '去找冰冠冰川的碁伯里‧基羅赫茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13406 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13406, 'zhTW', '[Riding the Wavelength: The Bombardment]', '[Ready to warm up with a short bombing mission?  You have your orders, and we have our bombers stocked and ready.]', '[Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.]', '', '去找冰冠冰川的偏激工程師泰茲菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13415, 'zhTW', '[The Library Console]', '[Norgannon\'s shell is within our reach, $N. Take the inventor\'s disk into the library\'s interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon\'s shell. There are probably enough schematics stored there to keep Ironforge\'s engineers occupied for years!$B$BAnyway, use the disk to recover the shell. Hopefully, Mimir hasn\'t decided to put any more obstacles in our way. ]', '[Take the Inventor\'s Disk to the Inventor\'s Library Console inside the Inventor\'s Library.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13416, 'zhTW', '[The Library Console]', '[Norgannon\'s shell is within our reach, $N. Take the inventor\'s disk into the library\'s interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon\'s shell. There are probably enough schematics stored there to keep Ironforge\'s engineers occupied for years!$B$BAnyway, bring the disk to the console. Hopefully, Mimir hasn\'t decided to put any more obstacles in our way. ]', '[Take the Inventor\'s Disk to the Inventor\'s Library Console inside the Inventor\'s Library.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13418, 'zhTW', '', '', '[Speak to Officer Van Rossem to secure passage to the Skybreaker in Icecrown, and then report to High Captain Justin Bartlett.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13419, 'zhTW', '', '', '[Speak to Sky-Reaver Klum to secure passage to Orgrim\'s Hammer in Icecrown, and then report to Sky-Reaver Korm Blackscar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13420, 'zhTW', '[Everfrost]', '[This piece of ice has been submitted to immense pressures and exposed to natural magics from deep beneath the world\'s surface. In combination, these effects have yielded an ice that will never melt.$B$BKnowing little of these things, you resolve to bring the sample back to Dun Niffelem. Someone there is bound to be familiar with its properties.]', '[You are to return to Dun Niffelem and ask Calder about the piece of Everfrost.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13421, 'zhTW', '[Remember Everfrost!]', '', '', '', '去找祖爾德拉克的考德爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13422, 'zhTW', '[Maintaining Discipline]', '[You\'ve succeeded where others have failed.  Yet you cannot rest on your laurels.$B$BYou must show others what strength and commitment really mean.$B$BThe male insubordinates inside the Forlorn Mine need to be disciplined once again.  Show them sister... show them what it means to disobey us.]', '[Gretta the Arbiter in Brunnhildar Village wants you to use the Disciplining Rod on 6 Exhausted Vrykul inside the Forlorn Mine.]', '', '去找風暴峭壁的『仲裁者』格瑞塔。', '已管教精疲力盡的維库人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13425, 'zhTW', '[The Aberrations Must Die]', '[It is not enough to demonstrate your prowess among your peers.  You must also fight our enemies, dear sister.$B$BThe Valkyrion traitors continue to mock our noble drake-riding traditions by rearing plagued proto-drakes.$B$BSeize the frost oil they wield and use it to freeze their abominable plagued eggs.]', '[Gretta the Arbiter in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants.  Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.]', '', '去找風暴峭壁的『仲裁者』格瑞塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13426, 'zhTW', '', '', '[Speak with Xarantaur at Camp Tunka\'lo.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13429, 'zhTW', '[A Distraction for Akama]', '[<Xi\'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi\'ri\'s army is ready to push Illidan\'s forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>]', '[Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi\'ri\'s forces create a distraction.]', '幫助阿卡瑪與麥維進入黑暗神廟', '去找影月谷的希瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13430, 'zhTW', '[Trial of the Naaru: Magtheridon]', '[Four trials you must pass before you are deemed worthy by the naaru.$B$BOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!]', '[A\'dal in Shattrath City wants you to slay Magtheridon.]', '', '去找沙塔斯城的阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13433 AND `locale` = 'zhTW';
