INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13479, 'zhTW', '[The Great Egg Hunt]', '[Noblegarden, celebration of life and spring! I hope you\'ve been enjoying the egg hunt, friend, because I could use the services of a capable individual like you.$B$BI\'m not certain what form of magic was used in the creation of the eggs, and the druids aren\'t keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.]', '[The Sping Gatherer wants you to get 20 shell fragments.]', '', '去找春日蒐集者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13480, 'zhTW', '[The Great Egg Hunt]', '[Noblegarden, celebration of life and spring! I hope you\'ve been enjoying the egg hunt, friend, because I could use the services of a capable individual like you.$B$BI\'m not certain what form of magic was used in the creation of the eggs, and the druids aren\'t keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.]', '[The Spring Collector wants you to get 20 shell fragments.]', '', '去找春日收集者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13481, 'zhTW', '[Let\'s Get Out of Here!]', '[The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their \'work\' here if I cannot escape.$B$BI cannot make it on my own, $c, but with your help, I may yet live to fight the Scourge again.$B$BWill you help me make my escape before the Scourge\'s butchers come to finish me off?]', '[Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim\'s Hammer.]', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13482, 'zhTW', '[Let\'s Get Out of Here]', '[The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their \'work\' here if I cannot escape.$B$BI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.$B$BWill you help me make my escape before the Scourge\'s butchers come to finish me off?]', '[Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.]', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13483 AND `locale` = 'zhTW';
