INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13749, 'zhTW', '[A Valiant\'s Field Training]', '[The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.$B$BTravel to the area southwest of the Valley of Fallen Heroes and north of Corp\'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.]', '[Tickin Gearspanner at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.]', '', '去找冰冠冰川的提金‧輪扳。', '', '', '', '', 0);
