INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13758, 'zhTW', '[A Worthy Weapon]', '[Of all the times to have such rotten luck!$B$BMy tournament blade has gone missing and I need it for a match this afternoon.$B$BOne of the bards tells me that travelers used to present winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest\'s northwestern border with Icecrown. Gather the flowers and take them to Drak\'Mar lake in northeastern Dragonblight, near its border with Zul\'Drak and Grizzly Hills.]', '[Bring the Blade of Drak\'Mar to Jaelyne Evensong at the Argent Tournament Grounds.]', '', '去找冰冠冰川的潔琳‧晚歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13759, 'zhTW', '[The Edge Of Winter]', '[That\'s the last time I ever spar with a death knight.$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice\'s exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter\'s Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $N.]', '[Jaelyne Evensong at the Argent Tournament Grounds wants you to bring her Winter\'s Edge.]', '', '去找冰冠冰川的潔琳‧晚歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13760, 'zhTW', '[A Valiant\'s Field Training]', '[The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.$B$BTravel to the area southwest of the Valley of Fallen Heroes and north of Corp\'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.]', '[Illestria Bladesinger at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.]', '', '去找冰冠冰川的依蕾絲崔亞‧刃詠。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13761, 'zhTW', '[The Grand Melee]', '[The grand melee is the most important of the tournament\'s competitions. The people of Darnassus are looking forward to seeing us win the melee. To that end, they\'ve been honing their skills against the valiants representing the other Alliance capitals.$B$BI suggest you do the same.$B$BThe Alliance Valiants\' Ring is just outside our tent. Go to the stables on the outside the pavilion, equip your lance, mount the stabled Darnassian mistsaber, and challenge the valiants.]', '[Bring 3 Marks of the Valiant to Airae Starseeker at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]', '', '去找冰冠冰川的愛芮‧尋星者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13762, 'zhTW', '[A Blade Fit For A Champion]', '[I\'ve heard that the Alliance champions are seeking after ancient blades for their warriors. We can\'t afford to let them have that kind of advantage.$B$BThere\'s an old legend from Grizzly Hills about a maiden cursed with a frog\'s form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $N. Otherwise, you\'ll catch warts.]', '[Retrieve the Ashwood Brand and bring it to Mokra the Skullcrusher at the Argent Tournament Grounds.]', '', '去找冰冠冰川的『碎顱者』莫克拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13763, 'zhTW', '[A Worthy Weapon]', '[Of all the times to have such rotten luck!$B$BMy tournament blade has gone missing and I need it for a match this afternoon.$B$BOne of the bards tells me that travelers used to present winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest\'s northwestern border with Icecrown. Gather the flowers and take them to Drak\'Mar lake in northeastern Dragonblight, near its border with Zul\'Drak and Grizzly Hills.]', '[Bring the Blade of Drak\'Mar to Mokra the Skullcrusher at the Argent Tournament Grounds.]', '', '去找冰冠冰川的『碎顱者』莫克拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13764, 'zhTW', '[The Edge Of Winter]', '[Curse that death knight for breaking my sword!$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice\'s exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter\'s Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $N.]', '[Mokra the Skullcrusher at the Argent Tournament Grounds wants you to bring him Winter\'s Edge.]', '', '去找冰冠冰川的『碎顱者』莫克拉。', '', '', '', '', 0);
