INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13765, 'zhTW', '[A Valiant\'s Field Training]', '[The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.$B$BTravel to the area southwest of the Valley of Fallen Heroes and north of Corp\'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.]', '[Akinos at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.]', '', '去找冰冠冰川的阿奇諾斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13767 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13767, 'zhTW', '[The Grand Melee]', '[The grand melee is the most important of the tournament\'s competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.$B$BIt will help prepare you for the rigors of tournament combat.$B$BGo to the stables outside the pavilion, equip your lance, mount the stabled Orgrimmar wolf, and challenge the valiants. They wait in the Horde Valiants\' Ring just outside our tent.$B$B]', '[Bring 3 Marks of the Valiant to Morah Worgsister at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.]', '', '去找冰冠冰川的莫菈‧座狼姊妹。', '', '', '', '', 0);
