INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13917, 'zhTW', '[Gorishi Grub]', '[The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.$B$BThe hatchling\'s drawings seem to resemble various types of large insects, perhaps the gorishi silithids. The hatchling finishes his picture, then gestures at it with one short arm, snaps its jaws, and licks its lips.$B$BIt must want you to go to the Slithering Scar, in center of the southern part of Un\'Goro Crater, and gather silithid meat. When you have the meat, feed it to your hungry hatchling.]', '[Your Venomhide Hatchling wants you to feed it 10 Silithid Meat.]', '', '', '已餵食希利蘇斯蟲肉給劇毒雛龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13952, 'zhTW', '[The Grateful Dead]', '[It\'s good to visit with friends and family again, though I may have overdone it... I\'ve already eaten everything they made for me!$B$BMight I trouble you for some more of that delicious Bread of the Dead? I\'d be most grateful...$B$BChapman there sells the recipe, I think.]', '[Acquire some Bread of the Dead and give it to the Cheerful Human Spirit in Stormwind\'s graveyard.$B$BUse an Orange Marigold to see the otherwise invisible spirit.]', '', '去找艾爾文森林的興奮的人類靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13959, 'zhTW', '[Back To The Orphanage]', '[We had the best time with you, $N. We wish you could be our $g把拔：馬麻; now, but you have to take us back to Orphan Matron Aria in Dalaran.$B$BMaybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One!$B$BWe going to miss you, $N. We promise to write letter sometime, oki? ]', '[Return your ward to the Dalaran orphanage by handing in the Oracle Orphan Whistle to Orphan Matron Aria in Dalaran.]', '', '去找達拉然的孤兒監護員阿瑞雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13960, 'zhTW', '[Back To The Orphanage]', '[Know what? You not so bad after all, $N. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do.$B$BYou, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes.$B$BKekek gotta go back to orphan-lady Aria now, back in purple human city.]', '[Return your ward to the Dalaran orphanage by handing in the Wolvar Orphan Whistle to Orphan Matron Aria in Dalaran.]', '', '去找達拉然的孤兒監護員阿瑞雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13966, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13986, 'zhTW', '[An Injured Colleague]', '[The fight\'s been hard up here, $c, as I\'m sure you know. We\'re holding out, but not everyone has gone unscathed.$B$BA warrior in our band, Aponi Brightmane, was taken ill by an infected wound in her arm. She\'s been taken back to Thunder Bluff for recuperation. It seems she left her shield here at the front in the confusion, however - could you take it to her, along with our well-wishes? Her smile is missed around here.$B$BYou can find her on Elder Rise on the Bluff.]', '[Take the Battered Tribal Shield to Aponi Brightmane on Elder Rise within Thunder Bluff.]', '', '去找莫高雷的阿波尼·亮鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13997, 'zhTW', '[If You\'re Reading This While I\'m In Combat...]', '[Dan is the most awesome programmer in the world... the World of Warcraft!$B$BIsn\'t it weird that you used to not be able to talk with me at all while I was fighting?  No longer, my friend, now that Dan has made significant improvements to one of my creature flags!$B$BCelebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.]', '[ELM Daze Target wants you to kill 5 ELM Attackers for Dan and Great Justice!]', '', 'Return to ELM Daze Target in Designer Island.', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14016, 'zhTW', '[The Black Knight\'s Curse]', '[I wanted to remove the Black Knight\'s remains from the tournament grounds after your victory, but Confessor Paletress insisted that he receive a decent burial. Ever since, a dark presence has lingered in the cemetery and people are afraid to go there to visit the fallen.$B$BWould you visit the cemetery just past the eastern end of the tournament grounds and see if you can discover what\'s happening? ]', '[Crusader Rhydalla at the Argent Tournament Grounds wants you to investigate the Black Knight\'s Grave.]', '調查黑騎士之墓', '去找冰冠冰川的十字軍萊達菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14017, 'zhTW', '[The Black Knight\'s Fate]', '[You said the body was taken by cultists? I can only think of one place they would have gone, Deathspeaker\'s Watch, the encampment on the rise west of the tournament grounds.$B$BWhatever the cultists are doing must be stopped. The rumors I\'ve heard can only be true, then. The infamous Doctor Kohler must be among the cultists, practicing his arts. Look for a rise or an altar overlooking the cultist camp, slay the doctor, and look for proof of his plans. Slow down his work in any other way you can.]', '[Capture Doctor Kolher\'s Orders at Deathspeaker\'s Watch, then return to Crusader Rhydalla at the Argent Tournament Grounds.]', '', '去找冰冠冰川的十字軍萊達菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14022, 'zhTW', '', '', '[Speak with Gregory Tabor just outside the city gates of Stormwind.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14023, 'zhTW', '[Spice Bread Stuffing]', '[Our spice bread stuffing is the cornerstone of the Pilgrim\'s Bounty table. The recipe has always been a favorite in Stormwind and now it has taken its place in the bountiful cookbook.$B$BIf you are already a cook, pay a visit to the Pilgrim\'s Bounty vendor to get your copy of the cookbook and all the local ingredients you\'ll need to prepare holiday fare. And if you\'re not yet a cook, there\'s no better time to start!$B$BOnce you\'ve made the stuffing, bring it to Jasper Moore over near the tables.]', '[Cook 5 servings of Spice Bread Stuffing and then bring them to Jasper Moore at the feasting area just outside Stormwind\'s gates.]', '', '去找艾爾文森林的賈斯伯‧摩爾。', '準備香料麵包填料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14024, 'zhTW', '[Pumpkin Pie]', '[That spice bread stuffing you made smells delicious, but no Pilgrim\'s Bounty feast is complete without a slice of pumpkin pie. It\'s another one of our favorite dishes here in Stormwind, since it uses ripe Elwynn pumpkins that only grow here.$B$BIf you don\'t know how to make pumpkin pie already, there\'s a recipe in your bountiful cookbook.$B$BWould you mind cooking up a few slices and bringing them to Edward Winslow outside Ironforge? He\'s bound to be running low by now.]', '[Make 5 slices of Pumpkin Pie and bring them to Edward Winslow at the feasting area right outside Ironforge.]', '', '去找丹莫羅的愛德華‧溫斯洛。', '準備南瓜派', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14028, 'zhTW', '[Cranberry Chutney]', '[If you haven\'t tried the cranberry chutney yet, you\'re in for a treat. It\'s made with the freshest tangy Wetlands cranberries. Just pick some up from the Pilgrim\'s Bounty vendor if you want to try your hand at making chutney.$B$BThe recipe should be in your bountiful cookbook.$B$BIf you\'ve got some extra time on your hands, would you mind making some of the chutney and bringing it down to Jasper Moore outside Stormwind? I promised him I\'d trade some for the pie you brought.]', '[Make 5 servings of Cranberry Chutney and bring them to Jasper Moore at the feasting area outside Stormwind.]', '', '去找艾爾文森林的賈斯伯‧摩爾。', '準備蔓越莓酸辣醬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14030, 'zhTW', '[They\'re Ravenous In Darnassus]', '[Thanks for bringing the cranberry chutney. There\'s so much cooking to do, I hardly have time to think of anything else. And on top of my responsibilities here, Isaac Allerton in Darnassus is out of almost everything. I don\'t suppose you\'d be willing to step in and whip up some more spice bread stuffing and pumpkin pie? The vendor should have all the ingredients you need$B$BYou should be able to find him near the feasting tables near the entrance to Darnassus just beyond the Warrior\'s Terrace.]', '[Bring 5 servings of Spice Bread Stuffing and 5 Pumpkin Pies to Isaac Allerton near the entrance to Darnassus.]', '', '去達納蘇斯找戰士區的艾薩克‧愛勒頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14032, 'zhTW', '[Kobold Camp Cleanup]', '[Your first task is one of cleansing, $N.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.]', '[Kill 8 Kobold Vermin, then return to Marshal McBride.]', '', '去找治安官瑪克布萊德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14033 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14033, 'zhTW', '[Candied Sweet Potatoes]', '[While you\'re here, you might want to stock up on Teldrassil sweet potatoes. They\'re used to make the most delicious candied sweet potatoes you\'ve ever tasted.$B$BIf you don\'t believe me, look up the recipe in your bountiful cookbook and give it a try. And if there are any extras, you might want to share them with Gregory Tabor at the feasting area just outside Stormwind. They\'re one of his favorites, but to hear him tell it, everything\'s his favorite!]', '[Make 5 servings of Candied Sweet Potatoes and bring them to Gregory Tabor just outside the gates of Stormwind.]', '', '去找艾爾文森林的葛列格里‧塔波。', '準備蜜汁地瓜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14035 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14035, 'zhTW', '[Slow-roasted Turkey]', '[Every Pilgrim\'s Bounty feast requires a magnificent centerpiece, and I\'m not talking about a decorative horn of plenty, either. No, the focus of the meal is a magnificent roast turkey.$B$BThere\'s a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Elwynn Forest, so you shouldn\'t have a problem finding one.$B$BOnce you\'re done roasting them, will you bring them to Isaac Allerton near the gates of Darnassus?]', '[Make 5 Slow-Roasted Turkeys and bring them to Isaac Allerton near the gates of Darnassus.]', '', '去達納蘇斯找戰士區的艾薩克‧愛勒頓。', '準備慢烤火雞', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14036 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14036, 'zhTW', '', '', '[Speak with Miles Standish in the courtyard above Undercity.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14037 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14037, 'zhTW', '[Spice Bread Stuffing]', '[Our spice bread stuffing is the cornerstone of the Pilgrim\'s Bounty table. The recipe dates from better times in Lordaeron and now it has taken its place in the traditional meal.$B$BIf you are already a cook, pay a visit to the Pilgrim\'s Bounty vendor to get your copy of the bountiful cookbook and all the local ingredients you\'ll need to prepare holiday fare. And if you\'re not yet a cook, there\'s no better time to start!$B$BOnce you\'ve made the stuffing, bring it to William Mullins over near the tables.]', '[Cook 5 servings of Spice Bread Stuffing and then bring them to William Mullins at the feasting area in the courtyard above the Undercity.]', '', '去找提裏斯法林地的威廉‧慕林。', '準備香料麵包填料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14040, 'zhTW', '[Pumpkin Pie]', '[That spice bread stuffing you made is a hit, but no Pilgrim\'s Bounty feast is complete without a slice of pumpkin pie. It\'s another traditional local dish, since it uses ripe Tirisfal pumpkins that only grow around here.$B$BIf you don\'t know how to make pumpkin pie already, there\'s a recipe in your bountiful cookbook.$B$BWould you mind cooking up a few slices and bringing them to Francis Eaton outside Orgrimmar? He\'s bound to be running low by now.]', '[Make 5 slices of Pumpkin Pie and bring them to Francis Eaton at the feasting area right outside Orgrimmar.]', '', '去找杜隆塔爾的法蘭西斯‧埃頓。', '準備南瓜派', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14041, 'zhTW', '[Cranberry Chutney]', '[Have you tried the cranberry chutney yet? It\'s made with fresh tangy Southfury cranberries. Just pick some up from the Pilgrim\'s Bounty vendor if you want to try your hand at making chutney.$B$BThe recipe should be in your bountiful cookbook.$B$BIf you\'ve got some extra time on your hands, would you mind making some of the chutney and bringing it to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff.]', '[Make 5 servings of Cranberry Chutney and bring them to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff.]', '', '去找雷霆崖的杜金‧遠野。', '準備蔓越莓酸辣醬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14043, 'zhTW', '[Candied Sweet Potatoes]', '[While you\'re here, you might want to stock up on Mulgore sweet potatoes. They\'re used to make delicious candied sweet potatoes, my favorite part of the Pilgrim\'s Bounty meal.$B$BIf you don\'t believe me, look up the recipe in your bountiful cookbook and give it a try. If you\'re headed back to Orgrimmar, bring them to Francis Eaton at the feasting area just outside the city. I\'ve been trying to keep him supplied, but everything goes so fast over there.]', '[Make 5 servings of Candied Sweet Potatoes and bring them to Francis Eaton just outside of Orgrimmar.]', '', '去找杜隆塔爾的法蘭西斯‧埃頓。', '準備蜜汁地瓜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14044 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14044, 'zhTW', '[Undersupplied in the Undercity]', '[Thanks for bringing the candied sweet potatoes. There\'s so much cooking to do, I can hardly keep up. And then, Miles sends me a note saying he\'s on the verge of running out of stuffing and cranberry chutney. I don\'t suppose you\'d be willing to step in and whip up some more of each? The vendor should have all the ingredients you need.$B$BYou should be able to find Miles Standish near the feasting tables in the courtyard in the ruins above Undercity.]', '[Bring 5 servings of Spice Bread Stuffing and 5 servings of Cranberry Chutney to Miles Standish near the entrance to Undercity.]', '', '去找提裏斯法林地的邁爾斯‧墨壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14047 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14047, 'zhTW', '[Slow-roasted Turkey]', '[Every Pilgrim\'s Bounty feast requires a centerpiece, and for us, that\'s a slow-roasted wild turkey. I can\'t think of anything better to bring the meal together.$B$BThere\'s a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Tirisfal Glades, so you shouldn\'t have a problem finding any.$B$BOnce you\'re done roasting them, will you bring them to Francis Eaton outside Orgrimmar?]', '[Make 5 Slow-Roasted Turkeys and bring them to Francis Eaton near the gates of Orgrimmar.]', '', '去找杜隆塔爾的法蘭西斯‧埃頓。', '準備慢烤火雞', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14048 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14048, 'zhTW', '[Can\'t Get Enough Turkey]', '[I\'ve been cooking nonstop since before the start of the holiday, and I still can\'t keep up with the demand. I don\'t suppose I could persuade you to help with one of the dishes, could I?$B$BTurkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in Elwynn Forest. You should be able to buy everything else you need from any of the Pilgrim\'s Bounty vendors.]', '[Bring 20 Slow-Roasted Turkeys to Caitrin Ironkettle outside Ironforge.]', '', '去找丹莫羅的凱特倫‧鐵壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14051, 'zhTW', '[Don\'t Forget The Stuffing!]', '[Keeping these tables stocked can be overwhelming! I\'ve got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don\'t burn.$B$BI think I\'ve got everything covered. No, wait, I\'m forgetting something. The stuffing! Oh, no. There won\'t be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn\'t take long to buy or make some stuffing and you can buy the ingredients right here.]', '[Bring 20 Spice Bread Stuffing to Caitrin Ironkettle at the feasting area outside Ironforge.]', '', '去找丹莫羅的凱特倫‧鐵壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14053, 'zhTW', '[We\'re Out of Cranberry Chutney Again?]', '[My husband, Jasper, was going to make more cranberry chutney, but it looks like he\'s busy trying to make sure there\'s enough candied sweet potatoes for all the guests. Would you be willing to help? If you\'re a cook, you can get the tangy Wetlands cranberries you\'ll need from the Pilgrim\'s Bounty vendor outside Ironforge.$B$BIf you don\'t feel up to cooking, you could always ask someone else to make the chutney, too.]', '[Bring 20 servings of Cranberry Chutney to Ellen Moore at the feasting area outside Stormwind.]', '', '去找艾爾文森林的愛蓮‧摩爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14054, 'zhTW', '[Easy As Pie]', '[Isaac\'s been hard at work helping celebrants learn about the traditional Pilgrim\'s Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I\'ve been trying to keep the tables stocked with as many of the dishes as I can, but we\'re running out of one of Isaac\'s favorites, pumpkin pie.$B$BWould you be able to get some for us? If you want to make the pies yourself, you\'ll need to buy ripe Elwynn pumpkins from the Pilgrim\'s Bounty vendor outside Stormwind.]', '[Bring 20 pieces of Pumpkin Pie to Mary Allerton at the feasting area near the gates of Darnassus.]', '', '去達納蘇斯找戰士區的瑪麗‧愛勒頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14055, 'zhTW', '[She Says Potato]', '[My wife Ellen has enlisted my help in keeping the tables stocked, but she can\'t make up her mind. First I was making pumpkin pie, but now she\'s changed her mind and she wants candied sweet potatoes.$B$BWell, I\'ve already started on the pie, so maybe you can help me whip up those sweet potatoes. She\'ll be pleasantly surprised if we can get everything she\'s asked for.$B$BIf you\'re going to cook the sweet potatoes yourself, you\'ll have to buy them from the Pilgrim\'s Bounty merchant in Darnassus. Thanks, $N.]', '[Bring 20 Candied Sweet Potatoes to Jasper Moore at the feasting area outside of Stormwind.]', '', '去找艾爾文森林的賈斯伯‧摩爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14058, 'zhTW', '[She Says Potato]', '[Roberta Carter has recruited me to help prepare one of the feast dishes, candied sweet potatoes.  Normally, I\'d love to help, but I\'ve promised the hostess that I\'d help her watch the tables.$B$BI\'d really appreciate it if you would help me come up with those candied sweet potatoes. Roberta would never forgive me if I let her down.$B$BIf you\'re going to cook the sweet potatoes yourself, you\'ll have to buy them from the Pilgrim\'s Bounty merchant in Thunder Bluff. Thanks, $N.]', '[Bring 20 Candied Sweet Potatoes to William Mullins at the feasting area above Undercity.]', '', '去找提裏斯法林地的威廉‧慕林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14059, 'zhTW', '[We\'re Out of Cranberry Chutney Again?]', '[I wish I knew why we\'re going through cranberry chutney so fast. Sometimes, I think they\'re feeding it to the abominations when I\'m not looking. Would you be willing to help me make up a new batch? If you\'re a cook, you can get the tangy Southfury cranberries you\'ll need from the Pilgrim\'s Bounty vendor outside Orgrimmar.$B$BIf you don\'t feel up to cooking, you could always ask someone else to make the chutney, too.]', '[Bring 20 servings of Cranberry Chutney to Roberta Carter at the feasting area in the courtyard above Undercity.]', '', '去找提裏斯法林地的蘿貝塔‧卡特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14060 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14060, 'zhTW', '[Easy As Pie]', '[Dokin and Laha have been hard at work helping celebrants learn about the traditional Pilgrim\'s Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I\'ve been trying to keep the tables stocked with as many of the dishes as I can, but we\'re running low on pumpkin pie.$B$BWould you be able to get some for us? If you want to make the pies yourself, you\'ll need to buy ripe Tirisfal pumpkins from the Pilgrim\'s Bounty vendor outside the Undercity.]', '[Bring 20 pieces of Pumpkin Pie to Marhara Goldwheat at the feasting area outside Thunder Bluff.]', '', '去找莫高雷的瑪哈拉‧金麥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14061, 'zhTW', '[Can\'t Get Enough Turkey]', '[I\'ve been cooking nonstop since before the start of the holiday, and I still can\'t keep up with the demand. I don\'t suppose I could persuade you to help with one of the dishes, could I?$B$BTurkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in the Tirisfal Glades. You should be able to buy everything else you need from any of the Pilgrim\'s Bounty vendors.]', '[Bring 20 Slow-Roasted Turkeys to Ondani Greatmill outside Orgrimmar.]', '', '去找杜隆塔爾的昂達尼‧巨磨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14062, 'zhTW', '[Don\'t Forget The Stuffing!]', '[Keeping these tables stocked can be overwhelming! I\'ve got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don\'t burn.$B$BI think I\'ve got everything covered. No, wait, I\'m forgetting something. The stuffing! Oh, no. There won\'t be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn\'t take long to buy or make some stuffing and you can buy the ingredients right here.]', '[Bring 20 Spice Bread Stuffing to Ondani Greatmill outside Orgrimmar.]', '', '去找杜隆塔爾的昂達尼‧巨磨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14064, 'zhTW', '[Sharing a Bountiful Feast]', '[You\'ve not celebrated Pilgrim\'s Bounty properly until you\'ve eaten your fill at a Bountiful Table.$B$BPlease, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food.$B$BOnce you eat enough of every dish, you\'ll be infused with the Spirit of Sharing.]', '[Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing.]', '', '去找豐年祭餐席女侍。', '分享之靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14065, 'zhTW', '[Sharing a Bountiful Feast]', '[You\'ve not celebrated Pilgrim\'s Bounty properly until you\'ve eaten your fill at a Bountiful Table.$B$BPlease, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food.$B$BOnce you eat enough of every dish, you\'ll be infused with the Spirit of Sharing.]', '[Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing.]', '', '去找豐年祭盛宴女侍。', '分享之靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14074 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14074, 'zhTW', '被劫的腿肉補給', '銀白十字軍派遣了一艘載著陸行鳥肉及其他補給品的快艇來給聯賽場地的我們，但它一直沒有抵達。斥候回報說看見快艇被科瓦迪爾所攻擊，那些可怕的海上維酷劫掠者。$B$B他們屠殺了船員並把貨物帶去一座叫做赫魯斯加臺地的島上。如果你往北方看去，可以看見它籠罩在迷霧之中。你能幫我們取回那些被偷的貨物嗎?沒有那些陸行鳥腿，我們很快就會食物短缺。', '取回10份被偷的陸行鳥腿給銀白聯賽場地的娜拉希·雪曦。', '', '去找冰冠冰川的娜拉希‧雪曦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14076 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14076, 'zhTW', '勇士的早餐', '現在大競技場完成了，銀白十字軍要我們幫忙尋找能與勇士對戰的生物。$B$B巨型蟄猛巨蟲有著最奇怪的進食特性;牠們吃自己同類的蛋會長得特別強壯，而深地蟄猛巨蟲的蛋是最好的。$B$B帶著這個鼓到風暴群山中央的足跡冷原，然後在那邊的雪堆附近敲鼓。引出深地蟄猛巨蟲，殺了牠們，然後收集牠們的卵囊。', '取得4份蟄猛巨蟲卵囊並帶給銀白聯賽場地的莎薇娜·識歌。', '', '去找冰冠冰川的莎薇娜‧識歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14077, 'zhTW', '聖光的憐憫', '我聽從告解者帕爾璀絲的教誨，我必須告訴你，她說的話讓我省思許多。與十字軍並肩作戰是不夠的;我們必須接手他們的任務。$B$B北海岸外就是赫魯斯加臺地，來自海上的科瓦迪爾侵襲了這個古老的巨牙海民聚落，並屠殺了村民。拿著這本書並在村民屍體旁為死者頌禱儀式。這可以讓他們的靈魂脫離迷霧的束縛並獲得安息。', '使用告解者的祈禱書對8個被殺的托利克村民執行最後的儀式，然後回去找銀白聯賽場地的娜拉希·雪曦。', '', '去找冰冠冰川的娜拉希‧雪曦。', '執行最後的儀式', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14079, 'zhTW', '[Learn to Ride in Elwynn Forest]', '[This pamphlet advertising riding training and mount purchases was sent from Randal Hunter.$B$BRandal can be found at Elwynn Forest\'s Eastvale Logging Camp, along the road east out of Stormwind.]', '[Return the pamphlet to Randal Hunter at Eastvale Logging Camp in Elwynn Forest.]', '', '去艾爾文森林找石碑湖的蘭達爾·亨特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14080, 'zhTW', '阻止侵略者', '科瓦迪爾，可怕的維酷劫掠者，攔截了我們的船隻並屠戮了北方一座島上的巨牙海民，把島更名為赫魯斯加臺地。如果他們在那邊打穩基礎，毫無疑問我們將會是他們下一個目標。$B$B十字軍的軍力全都用在對付天譴軍了，所以我們必須保護聯賽場地。從這裡向北飛抵島上並在科瓦迪爾毀滅任何東西之前處理掉他們。', '銀白聯賽場地的娜拉希·雪曦要你去殺掉10個科瓦迪爾。', '', '去找冰冠冰川的娜拉希‧雪曦。', '殺死科瓦迪爾', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14081, 'zhTW', '[Learn to Ride in the Eversong Woods]', '[This pamphlet advertising riding training and mount purchases was sent from Perascamin.$B$BPerascamin can be found at Thuron\'s Livery, southeast of the Shepherd\'s Gate leaving Silvermoon City.]', '[Return the pamphlet to Perascamin at Thuron\'s Livery in Silvermoon City.]', '', '去找永歌森林的珀拉斯坎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14090, 'zhTW', '戈莫克要他的極地狗頭人', '我的兩名部下在試著囚禁猛瑪象人『穿刺者』戈莫克時被殺了，而那隻生物仍舊怒氣沖沖。牠因為最愛的極地狗頭人不在身邊而嚎叫了好幾個小時。$B$B如果銀白十字軍不希望在大競技場使用這隻怪物，我會親手殺掉牠。也許是該帶給這隻野獸一些玩具的時候了。帶著這個網子去風暴群山東南邊的迦姆之禍。就在K3的東北。捕捉一些極地狗頭人並向聖光祈禱你抓到正確的那隻。', '使用加重的網子捕捉8隻雪盲跟隨者，並帶給銀白聯賽場地的莎薇娜·識歌。', '', '去找冰冠冰川的莎薇娜‧識歌。', '', '捕捉雪盲跟隨者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14092, 'zhTW', '[Breakfast Of Champions]', '[Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting.$B$BThe giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar.$B$BTake this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there. The sound will rouse the deep jormungar. Kill them, collect their egg sacs, and return to the tournament grounds.]', '[Acquire 4 Jormungar Egg Sacs and bring them to Tylos Dawnrunner at the Argent Tournament Grounds.]', '', '去找冰冠冰川的提洛斯‧曦奔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14095, 'zhTW', '鑑定屍體', '一顆從死亡的海怪身上找到的完整牙齒相當罕見。十字軍銀曦一定會想看看的。', '把海怪牙交給十字軍銀曦來作為勝利的證明。', '', '去找冰冠冰川的十字軍銀曦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14096, 'zhTW', '庫爾，看看你這次幹的好事', '十字軍庫爾又讓自己陷入麻煩了，不過這次可不只他一個人。當他發現有些教徒在聯賽場地西邊的亡頌者之望紮營時，庫爾召集了一些志士發動一次突襲。$B$B在沒有增援的情況下，庫爾和他的跟隨者輕易的被俘虜了。除非我們進行救援，不然神教一定會將囚犯當作祭品。任何一個教徒都有可能帶著黑色牢籠的鑰匙。找到鑰匙並釋放庫爾及被俘虜的志士們。', '從亡頌者之望救出『魯莽』庫爾和4位被俘虜的志士，然後回去找銀白聯賽場地的娜拉希·雪曦。', '', '去找冰冠冰川的娜拉希‧雪曦。', '拯救『魯莽』庫爾', '拯救被俘虜的志士', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14101, 'zhTW', '多廷·赫魯斯加', '科瓦迪爾，海上的維酷們劫掠了船隻和岸邊的居民，屠戮了北方海峽那端一座巨牙海民的島。他們的首領，多廷·赫魯斯加，打算控制這整片海域。$B$B若他的勢力壯大，我們的船隻和軍艦就永無安寧之日了。我們將被孤立在此而對巫妖王束手就擒。$B$B拿著這個奪來的科瓦迪爾戰爭號角到赫魯斯加臺地東北邊的巨牙海民雕像之環，使用它來挑戰科瓦迪爾的首領。', '銀白聯賽場地的高階十字軍艾德拉要你去擊敗多廷·赫魯斯加。', '', '去找冰冠冰川的高階十字軍艾德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14102, 'zhTW', '喚霧者伊格瓦', '科瓦迪爾回到了北裂境的海岸，若不加以制止，他們將會截斷我們的援軍以及後勤補給。他們的其中一員，喚霧者伊格瓦，居住在赫魯斯加臺地西邊的洞穴中。他在那裡操縱著霧來隱蔽科瓦迪爾及他們操控的海中怪獸。$B$B拿著這個符咒，前往聯賽場地北邊海峽彼端的赫魯斯加臺地。找到喚霧者的洞穴並使用符咒讓他現形。', '銀白聯賽場地的高階十字軍艾德拉要你去殺掉喚霧者伊格瓦。', '', '去找冰冠冰川的高階十字軍艾德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14103, 'zhTW', '泰坦鋼粉末', '', '', '', '去找水晶歌森林的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14104 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14104, 'zhTW', '『刀疤』歐諾夫', '『刀疤』歐諾夫在科瓦迪爾中是以劫掠和俘虜船隻聞名的可怕劫掠者。他和船員駕駛博爾之怒攻擊我們的船隻並竊奪我們的貨物。$B$B歐諾夫和他的部下也是屠戮巨牙海民並把島改名為赫魯斯加臺地的傢伙。他的船停泊在島上港口的東端。將這面旌旗插在船上，宣告你擄獲了他的船，進而挑釁他出來和你一戰。', '銀白聯賽場地的高階十字軍艾德拉要你去殺掉『刀疤』歐諾夫。', '', '去找冰冠冰川的高階十字軍艾德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14105 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14105, 'zhTW', '亡頌者凱洛斯', '詛咒神教為了目睹我們的毀滅而又增強了他們的勢力。他們在聯賽場地西邊山脊的亡頌者之望據點越來越堅強茁壯。$B$B殘忍的亡頌者凱洛斯和他的部下鞏固了他們的所在地並準備釋放所有神教的武器。$B$B我的部下已經準備好與驍士們一同保衛聯賽場地，但我需要一個像你，$N，一樣的勇士來引領我們的行動以減緩攻勢。找到亡頌者凱洛斯並殺了他。', '銀白聯賽場地的高階十字軍艾德拉要你去殺掉亡頌者凱洛斯。', '', '去找冰冠冰川的高階十字軍艾德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14107 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14107, 'zhTW', '逝往者的命運', '銀白十字軍並不是第一個在寒冰皇冠對抗巫妖王的勢力。我們的敵人正在讓那些逝去的靈魂來對抗我們。$B$B他們遊蕩在逝往英雄山谷，聯賽場地的西南方，奧多薩與鐵牆壁壘之間。那個區域散亂著毀棄的靈魂水晶，被天譴軍團用來控制那些靈魂。收集那些靈魂水晶並和這個聖光祝福聖物一起使用來給予那些靈魂安息的祝福。這些英雄們理當早日獲得安息。', '十字軍銀曦要你讓6位陣亡英雄之靈獲得安息。', '', '去找冰冠冰川的十字軍銀曦。', '祝福陣亡英雄之靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14108 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14108, 'zhTW', '逮住海怪!', '奪日者和白銀誓盟派遣船隻前往北邊的赫魯斯加臺地和科瓦迪爾人交戰，但他們被科瓦迪爾的劫掠艦隊中途攔截，且自顧不暇。更糟糕的是，科瓦迪爾人找出了召喚潛伏在北海深海中恐怖海怪的方法。如果我們想保住船上的人，就必須要驅離海怪，並且中斷科瓦迪爾的召喚儀式。$B$B十字軍，拿著這些長矛，銀白角鷹獸將會帶你前往戰場。', '十字軍銀曦要你騎上銀白角鷹獸，對北海海怪投擲6支烈焰之矛並解決3個維酷深海呼喚者。$B$B你可以在聯賽場地的銀白十字軍帳棚外面找到銀白角鷹獸。', '', '去找冰冠冰川的十字軍銀曦。', '對北海海怪投擲矛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14111 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14111, 'zhTW', '[Relic of the Earthen Ring]', '[You have progressed far in your training, $N. Now that you have mastered the four basic elements, you must strive to keep all four in balance. There is a practical benefit to this discipline - with practice, you may carry only a single relic instead of all four totems.$B$BSpeak to Farseer Eannu near the Great Forge in Ironforge. He will help you hone your mastery of the elements.]', '[Bring your four totems to Farseer Eannu in Ironforge.]', '', '去找丹莫羅的先知埃努。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14112 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14112, 'zhTW', '[What Do You Feed a Yeti, Anyway?]', '[The crusaders have captured a yeti that they\'re calling Icehowl. He\'s to be a participant in the coliseum battles and we\'ve been asked to help with his training and upkeep.$B$BThe crusaders weren\'t fond of my suggestion that we feed the beast surplus Sunreavers. The creature has a predilection for shark meat, so I want you to fly down to the Silver Blade, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.]', '[Savinia Loresong at the Argent Tournament Grounds wants you to bring her 3 pieces of North Sea Shark Meat.]', '', '去找冰冠冰川的莎薇娜‧識歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14136, 'zhTW', '[Rescue at Sea]', '[The Kvaldir have set up camp at Hrothgar\'s Landing, the small island to the North.  We sent Captain Aerthas Firehawk to the area, but they ran into a Kvaldir Raiding party heading to the Tournament Grounds!  The Firehawk is now under attack by the raiders and is vastly outnumbered. Get out there and show those Kvaldir why attacking the Sunreavers is a poor plan indeed. $B$BThe Firehawk is between Hrothgar\'s Landing to the north and the Tournament Grounds, on the western side of The Sea Reaver\'s Run.]', '[Girana the Blooded at the Argent Tournament Grounds would like you to kill 8 Kvaldir Berserkers and 3 Kvaldir Harpooners aboard The Firehawk.]', '', '去找冰冠冰川的『血漬』吉拉納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14140, 'zhTW', '[Stop The Aggressors]', '[The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar\'s Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target.$B$BThe crusade\'s forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.]', '[Giranan the Blooded at the Argent Tournament Grounds wants you to kill 10 Kvaldir.]', '', '去找冰冠冰川的『血漬』吉拉納。', '卡瓦迪爾已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14141, 'zhTW', '[Gormok Wants His Snobolds]', '[Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold.$B$BIf the Argent Crusade didn\'t wish to use this monster in the coliseum, I\'d slay it myself. Perhaps it\'s time to bring the beast its playthings. Take this net and travel to Garm\'s Bane in southeast Storm Peaks. It\'s just northeast of K3. Capture some of those snobolds and pray to the Light you\'ve found the right one.]', '[Use the Weighted Net to capture 8 Snowblind Followers and bring them to Tylos Dawnrunner at the Argent Tournament Grounds.]', '', '去找冰冠冰川的提洛斯‧曦奔。', '', '已捕獲雪盲追隨者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14142, 'zhTW', '[You\'ve Really Done It This Time, Kul]', '[Crusader Kul has gone and gotten himself into trouble again, only this time he\'s not alone. When he saw the cultists making camp at Deathspeaker\'s Watch, west of the tourney grounds, Kul gathered the aspirants for an attack.$B$BThey were easily captured, and now Kul languishes in a cage on the platform in the camp. I am sure that the cult will sacrifice the prisoners unless we can rescue them. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants.$B$B]', '[Rescue Kul the Reckless and 4 Captive Aspirants from Deathspeaker\'s Watch and return to Girana the Blooded at the Argent Tournament Grounds.]', '', '去找冰冠冰川的『血漬』吉拉納。', '已救出魯莽者庫爾', '已救出被俘的候選者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14143, 'zhTW', '[A Leg Up]', '[The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the kvaldir, fearsome vrykul raiders who roam the seas.$B$BThey\'ve slain the crew and taken the cargo to an island called Hrothgar\'s Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we\'ll soon be out of food.]', '[Recover 10 Stolen Tallstrider Legs for Girana the Blooded at the Argent Tournament Grounds.]', '', '去找冰冠冰川的『血漬』吉拉納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14144, 'zhTW', '[The Light\'s Mercy]', '[I\'ve been listening to Confessor Paletress speak, and I must tell you, her words have made me think. We fight beside the crusaders, but we can learn from them, too.$B$BOff the north coast is Hrothgar\'s Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.]', '[Use the Confessor\'s Prayer Book to perform last rites for 8 Slain Tualiq Villagers and then return to Girana the Blooded at the Argent Tournament Grounds.]', '', '去找冰冠冰川的『血漬』吉拉納。', '已進行臨終祈禱', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14145, 'zhTW', '[What Do You Feed a Yeti, Anyway?]', '[The crusaders have captured a yeti that they\'re calling Icehowl. He\'s to be a participant in the coliseum battles and we\'ve been asked to help with his training and upkeep.$B$BThe crusaders weren\'t fond of my suggestion that we feed some Silver Covenant members to the beast. The creature prefers shark meat, so I want you to fly down to the Crimson Dawn, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.]', '[Tylos Dawnrunner at the Argent Tournament Grounds wants you to bring him 3 pieces of North Sea Shark Meat.]', '', '去找冰冠冰川的提洛斯‧曦奔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14151, 'zhTW', '[Cardinal Ruby]', '[The Cardinal Ruby is said to be the finest gem in all of Northrend.  It sparkles like a crystal rose under the sun.$B$BBefore I teach you this recipe, I ask that you perform five epic gem transmutes to prepare your mind.  You can do any you like, and even do the same transmute many times.$B$BReturn to me when you are truly ready.]', '[Linzy Blackbolt in Dalaran wants you to successfully transmute 5 epic gems with your alchemy skill.  Acceptable transmutes include Ametrine, Eye of Zul, Dreadstone, King\'s Amber, and Majestic Zircon.]', '', '去找冰冠冰川的琳西·黑栓。', '史詩寶石嬗變', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14152, 'zhTW', '海上救援', '勇士、浪峰船長和她的船被派往北方襲擊赫魯斯加臺地的科瓦迪爾人，卻被朝聯賽場地而來的科瓦迪爾劫掠艦隊給攔截了。不幸的，科瓦迪爾的船員有著數量上的優勢，並逐漸佔領船隻。$B$B我們需要你往北方到海劫者航道上的浪峰號，就在聯賽場地和赫魯斯加臺地之間，幫助船員擊退來襲的敵人。你可以在航道的東邊看見這艘船。', '前往北海殺掉正在攻擊浪峰號的8個科瓦迪爾狂戰士及3個科瓦迪爾魚叉手。', '', '去找冰冠冰川的娜拉希‧雪曦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14160, 'zhTW', '[Writ of Merit]', '[This fine parchment lists a great many accomplishments, achieved by $N, in the tradition of jewelcrafting.$B$BReturn this writ to Timothy Jones in Dalaran for a proper reward.]', '[Deliver the Writ of Merit to Timothy Jones in Dalaran.]', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14166, 'zhTW', '[The Grateful Dead]', '[It\'s good to visit with friends and family again, though I may have overdone it... I\'ve already eaten everything they made for me!$B$BMight I trouble you for some more of that delicious Bread of the Dead? I\'d be most grateful...$B$BChapman there sells the recipe, I think.]', '[Acquire some Bread of the Dead and give it to the Cheerful Dalaran Spirit in Dalaran\'s graveyard.$B$BUse an Orange Marigold to see the otherwise invisible spirit.]', '', '去找水晶歌森林的興奮的達拉然靈魂。', '', '', '', '', 0);
