INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14174, 'zhTW', '[The Grateful Dead]', '[It\'s good to visit with friends and family again, though I may have overdone it... I\'ve already eaten everything they made for me!$B$BMight I trouble you for some more of that delicious Bread of the Dead? I\'d be most grateful...$B$BChapman there sells the recipe, I think.]', '[Acquire some Bread of the Dead and give it to the Cheerful Forsaken Spirit in Undercity\'s graveyard.$B$BUse an Orange Marigold to see the otherwise invisible spirit.]', '', '去找提裏斯法林地的興奮的被遺忘者靈魂。', '', '', '', '', 0);
