INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24650, 'zhTW', '[Crushing the Crown]', '[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.$B$BHere\'s an entry I want you to check out: it\'s in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough \'em up.$B$BOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]', '[Kill 5 Crown Sprinklers and use Snagglebolt\'s Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Detective Snap Snagglebolt in Orgrimmar.]', '', '去找奧格瑪的力量谷的警探史內卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
