INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24652, 'zhTW', '[Crushing the Crown]', '[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.$B$BHere\'s an entry I want you to check out: it looks like it\'s in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough \'em up.$B$BOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]', '[Kill 5 Crown Sprayers and use Snagglebolt\'s Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Detective Snap Snagglebolt in Orgrimmar.]', '', '去找奧格瑪的力量谷的警探史內卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
