DELETE FROM `quest_template_locale` WHERE `ID` = 24796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24796, 'zhTW', '[A Victory For The Silver Covenant]', '[In spite of Queen Lana\'thel\'s boasting, you have restored Quel\'Delar, $N. Long have we dreamt of reclaiming Quel\'Delar.$B$BThe Silver Covenant, and indeed all quel\'dorei owe you a debt of gratitude.$B$BVereesa Windrunner, the leader of the Silver Covenant, asked to see you after you returned from the Sunwell. Take Quel\'Delar with you and go to Dalaran\'s Violet Citadel where she waits, $N.]', '[Bring the Restored Quel\'Delar to Vereesa Windrunner at the Violet Citadel in Dalaran.]', '', '去找達拉然的凡蕾莎·風行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24798, 'zhTW', '[A Victory For The Sunreavers]', '[At last, Quel\'Delar is restored for the glory of the Sunreavers and the sin\'dorei!$B$BAll of Silvermoon will celebrate you as a hero, $N.$B$BAs a $c, the sword seems to know you lack the training to wield it and hasn\'t bonded to you. Where, then, will its next master come from? No worthy sin\'dorei has come forward. Let us seek the Argent Crusade\'s counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.]', '[Bring the Restored Quel\'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24799, 'zhTW', '[A Victory For The Sunreavers]', '[At last, Quel\'Delar is restored for the glory of the Sunreavers!$B$BAll the Horde will celebrate you as a hero, $N.$B$BAs a $c, the sword seems to know you lack the training to wield it and hasn\'t bonded to you. Where, then, will its next master come from? I will not conceal my disappointment; I had hoped it would be a worthy sin\'dorei. Let us seek the Argent Crusade\'s counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.]', '[Bring the Restored Quel\'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24800, 'zhTW', '[A Victory For The Sunreavers]', '[At last, Quel\'Delar is restored for the glory of the Sunreavers and the sin\'dorei! All of Silvermoon will proclaim you a hero, as will all of the Horde.$B$BArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, $N and bring Quel\'Delar with you. The archmage wishes to congratulate you personally!]', '[Bring the Restored Quel\'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24802, 'zhTW', '[Wrath of the Lich King]', '[Uther knew a great deal about how Arthas might be defeated. It\'s hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?$B$BMany questions remain, but the answers that you\'ve uncovered may be critical to ensuring Arthas\' defeat. You need to find Sylvanas and escape the Lich King while there\'s still time.]', '[Find Lady Sylvanas Windrunner and escape the Halls of Reflection]', '', '', '尋找希爾瓦娜斯·風行者', '逃離巫妖王', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24804 AND `locale` = 'zhTW';
