DELETE FROM `quest_template_locale` WHERE `ID` = 24849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24849, 'zhTW', '[Hot On The Trail]', '[I\'d better start from the beginning. It was love at first sight, $N. There was just something about that goblin from the moment I set eyes on him.$B$BAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?$B$BAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I\'m beginning to think he\'s nothing but a big liar!]', '[Look for Snivel Rustrocket in the Stormwind Counting House, the Auction House, and the Barbershop in Stormwind City.]', '', '去找暴風城的瑪莉恩‧蘇頓。', '已搜查暴風城稅務局', '已搜查暴風城拍賣行', '已搜查暴風城理髮店', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24850, 'zhTW', '', '', '[Speak to Roka at the Gotri\'s Travelling Goods in Orgrimmar\'s Drag district.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24851, 'zhTW', '[Hot On The Trail]', '[I\'d better start from the beginning. It was love at first sight, $N. There was just something about that goblin from the moment I set eyes on him.$B$BAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?$B$BAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I\'m beginning to think he\'s nothing but a big liar!]', '[Look for Snivel Rustrocket in the Orgrimmar Bank, the Auction House, and the Barbershop in Orgrimmar.]', '', '去找奧格瑪的蘿卡。', '已搜查奧格瑪銀行', '已搜查奧格瑪拍賣行', '已搜查奧格瑪理髮店', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24857, 'zhTW', '[Attack on Camp Narache]', '[After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.$B$BSurely Chief Hawkwind could use this information!]', '[Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.]', '', '去莫高雷找納拉其營地的鷹風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24869, 'zhTW', '[Deprogramming]', '[We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King\'s machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.$B$BOur man, Darnavan, is one of them now.$B$BIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult\'s brainwashing.]', '[Defeat Lady Deathwhisper while ensuring that Darnavan survives.]', '', '去找滲透者敏加。', '營救達拿凡', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24870, 'zhTW', '[Securing the Ramparts]', '[As if this place weren\'t enough of a madhouse to begin with, we\'re fighting a war on two fronts up here, with the Scourge on one side and those blasted Alliance dogs on our other flank!$B$BWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.$B$BI\'ll be honest -- he\'s a bit much for us to handle, but you and your companions look up to the task.]', '[Slay the Rotting Frost Giant.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24871, 'zhTW', '[Securing the Ramparts]', '[As if this place weren\'t enough of a madhouse to begin with, we\'re fighting a war on two fronts up here, with the Scourge on one side and those blasted Horde dogs on our other flank!$B$BWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.$B$BI\'ll be honest -- he\'s a bit much for us to handle, but you and your companions look up to the task.]', '[Slay the Rotting Frost Giant.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24873, 'zhTW', '[Residue Rendezvous]', '[Professor Putricide has been holed up in his foul laboratory, experimenting and refining increasingly lethal strains of blight to be used against us. If only we could obtain pure samples of the toxins, our researchers could concoct an antidote that would save countless lives.$B$BBut there\'s a catch -- a proper sample will need to mix two active strains within a living host. Should you have the... misfortune... of becoming such a host, please return here immediately so that we can harvest you for study.]', '[Return to Alchemist Adrianna while infected with Orange and Green Blight.]', '帶著兩種枯萎病毒株回歸', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24874, 'zhTW', '[Blood Quickening]', '[These Scourge bloodsuckers -- San\'layn they call themselves - give me the creeps. We\'ve had one of our best men keeping an eye on them. But this morning he got sloppy and got himself taken prisoner. He\'s being interrogated by the Queen herself right now, and his cries echo through the Crimson Halls. Please, save him before it\'s too late!]', '[Rescue Infiltrator Minchar before he is executed.]', '', '', '已救出敏查爾', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24875 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24875, 'zhTW', '[Deprogramming]', '[We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King\'s machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.$B$BOur man, Darnavan, is one of them now.$B$BIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult\'s brainwashing.]', '[Defeat Lady Deathwhisper while ensuring that Darnavan survives.]', '', '去找滲透者敏加。', '營救達拿凡', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24876, 'zhTW', '[Securing the Ramparts]', '[As if this place weren\'t enough of a madhouse to begin with, we\'re fighting a war on two fronts up here, with the Scourge on one side and those blasted Horde dogs on our other flank!$B$BWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.$B$BI\'ll be honest -- he\'s a bit much for us to handle, but you and your companions look up to the task.]', '[Slay the Rotting Frost Giant.]', '', '', '', '', '', '', 0);
