INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24877, 'zhTW', '[Securing the Ramparts]', '[As if this place weren\'t enough of a madhouse to begin with, we\'re fighting a war on two fronts up here, with the Scourge on one side and those blasted Alliance dogs on our other flank!$B$BWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.$B$BI\'ll be honest -- he\'s a bit much for us to handle, but you and your companions look up to the task.]', '[Slay the Rotting Frost Giant.]', '', '', '', '', '', '', 0);
