INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24878, 'zhTW', '[Residue Rendezvous]', '[Professor Putricide has been holed up in his foul laboratory, experimenting and refining increasingly lethal strains of blight to be used against us. If only we could obtain pure samples of the toxins, our researchers could concoct an antidote that would save countless lives.$B$BIf you happen to come across live specimens, please return here immediately so that we can harvest them for study.]', '[Return to Alchemist Adrianna while infected with Orange and Green Blight.]', '帶著兩種枯萎病毒株回歸', '', '', '', '', '', 0);
