INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24879, 'zhTW', '[Blood Quickening]', '[These Scourge bloodsuckers -- San\'layn they call themselves -- give me the creeps. We\'ve had one of our best men keeping an eye on them. But this morning he got sloppy and got himself taken prisoner. He\'s being interrogated by the Queen herself right now, and his cries echo through the Crimson Halls. Please, save him before it\'s too late!]', '[Rescue Infiltrator Minchar before he is executed.]', '', '', '已救出敏查爾', '', '', '', 0);
