INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24914, 'zhTW', '[Personal Property]', '[You can detect no hinges or openings on this box. Were it not for the shifting of items inside, it could easily be mistaken for solid metal.$B$BIf anyone could know the method of its opening, it would be Highlord Mograine.]', '[Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25055 AND `locale` = 'zhTW';
