INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25286, 'zhTW', '[Words for Delivery]', '[Here we go.  This is the speech, $N!$B$BIt has everything to be a great battle starter: It\'s inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!$B$BTurn this in to Captain Tread Sparknozzle and get some transportation to High Tinker Mekkatorque!]', '[Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.]$B$B已提供物品：', '', '', '', '', '', '', 0);
