INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25446, 'zhTW', '[Frogs Away!]', '[Wit de frogs ready to go, I be needin\' ya to help me send \'em out to the isles.$B$BOn de eastern side of Sen\'jin Village, ya can find Handler Marnlek. He be handlin\' all the bats for Vol\'jin\'s scouts and he can loan ya a bat to get ya out to de isles.$B$BTake dis sack\' o frogs with ya. I been askin\' de spirits for guidance. Dey\'ve sent smoke to show ya where I need de eyes most. While ridin\' de bat, reach into de sack and toss de frogs toward de white smoke.]', '[While riding a bat, use the Sack o\' Frogs to place 12 attuned frogs on the markers in the Echo Isles.]$B$B已提供物品：', '', '去找森金村的凡妮拉。', '青蛙袋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25461, 'zhTW', '[Trollin\' For Volunteers]', '[Vol\'jin has given me his war drums and put  me in charge of trainin\' da new recruits here. Only problem is we be short on new recruits.$B$BSupposin\' I loaned ya dis drum, would ya use it to sound de call to war on Vol\'jin\'s behalf in Razor Hill? If ya could even inspire just a few trolls to join da cause, it would make a difference. Once ya\'ve convinced dem to volunteer, bring dem back to me for trainin\'. Go over an\' talk to Handler Marnlek to de south. He can lend you a bat for de ride to Razor Hill.]', '[Use Vol\'jin\'s War Drums to recruit 5 Troll Citizens in Razor Hill.$B$BYou can speak to Handler Marnlek for a bat ride to Razor Hill.]$B$B已提供物品：', '', '去找森金村的勇士烏魯辛。', '沃金的戰鼓', '巨魔志願者已交給勇士烏爾金', '', '', 0);
